-- ============================================================
-- Ozbek3b (2/2): Günə-özəl push bildirişlərinin UZ tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('9fdf76d2-ea34-465e-99e8-537978d670c9'::uuid, '«Qanday?» savollari boshlanadi 🤔', '«Nega?» savollari o‘rnini «Bu qanday ishlaydi?» degan savollar egallaydi. U mexanizmlarni tushunishga harakat qilmoqda. Sabrli bo‘ling va unga qisqa, mantiqiy tushuntirishlar bering.'),
  ('c9428152-a130-431b-ac89-26275023d613', 'Ona uchun tanaffus ☕', 'Bolangiz mustaqil o‘ynayotganida darhol uy ishlariga shoshilmang. Xonadagi tartibsizlik hech qayerga qochmaydi, ammo sizning quvvatingiz tugashi mumkin. O‘tiring va issiq qahvangizni iching.'),
  ('269b7d14-00d0-4c42-84b9-6759e61b0baa', 'Estetik ovqatlanish inqirozi 🥦', 'Nonning chetini yoki bodring bo‘lagini ko‘rinishi xunukligi uchun yemayaptimi? Ovqat tanlash odati g‘alati tus olmoqda. Ovqatlanish rejasida sabzavotlarni pyure qilib yashirishning eng mohirona usullarini kashf eting.'),
  ('3619cb9e-e29f-4149-9f97-e65685c72f61', 'Tonggi konsert boshlandi 🎤', 'Uyg‘onishi bilan ovozini eng yuqori desibelga qo‘yib, nimalarnidir kuylayaptimi? Uning quvvati ertalab soat 7-danoq to‘liq. Ko‘zlaringizni ishqalang va bu kichkina pop-yulduzning tomoshasini tabassum bilan kuzating.'),
  ('4e5a485c-972c-4f14-b15e-6d0c1f1b8961', 'Vannaxonadagi toshqin 🛀', 'Suv bilan o‘ynash tozalanishdan ko‘ra, xonani akvaparkka aylantirish uchun kerak. Mayli, suvlar sachrasin. Iliq suv va o‘yin-kulgi uning kun bo‘yi to‘plangan barcha qaysarligini yuvib ketadi.'),
  ('22cad895-d987-4916-ac97-672fe0a05ac0', '“Yana bittagina” hiylasi 📖', 'Uxlashni istamay, yana bittagina ertak aytib berishingizni so‘rab vaqtni cho‘zayaptimi? Klassik kitoblarni bir chetga qo‘ying. Aqlli ertaklarda u o‘ylab topgan qahramonlar bilan uxlash oldidan qisqa hikoya yarating va jarayonni yakunlang.'),
  ('4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb', 'Yashirin shokolad tanaffusi 🍫', 'Oshxona shkafi ortida yashirincha, tik turgancha shirinlik yeb olayotgan ona, sizni ko‘rib turibmiz! O‘zingizni ayblamang. Shovqin-suronga chidash uchun glyukoza miqdorini biroz oshirib olishga to‘liq haqqingiz bor.'),
  ('c5c0175d-de40-45a7-97f9-43392b324696', 'Uyning kichkina diktatori 👑', 'U yerga emas, bu yerga o‘tir!, Buni siz emas, men qilaman! Uyni o‘zi boshqarishni xohlaydi. Uning irodasini keskin sindirmasdan, Siz bu yerga o‘tiring, men esa u yerga deb muvozanatni saqlang.'),
  ('3af3aa71-d08b-4f87-af96-9527f5f91ec1', 'Ertalabki badantarbiya 🤸‍♂️', 'Siz hali uyg‘onmagansiz, u esa karavotda ustingizga sakraydi. Dunyodagi eng shovqinli, ammo eng yoqimli uyg‘otuvchi qo‘ng‘iroq! Kunni uning cheksiz energiyasidan zavqlanib, kulib boshlang.'),
  ('8c84402b-2c57-4668-ad1d-96d138e6ba29', 'Ro‘yxatsiz bozorlik tashvishi 🛒', 'Do‘konga borib, eng kerakli narsani sotib olmay qaytdingizmi? Onalik xotirasi shunaqa bo‘ladi. Xotirangizga ishonib qolmang, har bir mayda ehtiyojni darhol Xaridlar ro‘yxatiga yozishni odat qiling.'),
  ('90c41ad8-7de7-4c6d-ba3d-cf1aad328939', 'Sham yorug‘ida choy 🕯️', 'Bola uxlab qoldi. Chiroqlarni o‘chirib, stol ustida sham yoqing. Bu romantika uchun emas, shunchaki kun bo‘yi zo‘riqqan asablaringiz va ko‘zlaringizni tinchlantirish uchun.'),
  ('4390f43b-f533-4c56-8aa2-5901fd06c8f5', 'Sun’iy intellekt, haqiqiy yordam 🤖', 'Bolaning hamma narsaga qaysarlik qilishining psixologik sababi nimada? Internetdan qo‘rqinchli maqolalarni qidirmang. Anacan AI-dan 33 oylik bolalardagi inqirozlar haqida ilmiy va qisqa izoh so‘rang.'),
  ('70560836-1d71-42c8-8235-1ad990694b3b', 'Tartibning siljishi ⏱️', 'Kechqurun uxlab qolish 1 soatdan ko‘proq vaqt olyaptimi? Uyqu taymeri grafigiga qarang. Balki kunduzgi uyquni keskin qisqartirish va kechki uyquni ertaroqqa surish vaqti allaqachon kelgandir.'),
  ('dfed41fd-982b-4955-b70f-6d43247a4468', 'Soch tarash qiyomati 🪮', 'Sochini tarash yoki unga tegish dunyodagi eng katta azobdek qichqiradimi? Kurashni to‘xtating. Avval taroqni unga bering, sochingizni tarashiga ruxsat bering, keyin navbat sizga kelsin.'),
  ('71f7d0fb-698f-4308-ad55-a95583a3469b', 'Melatonin vaqti 🌙', 'Uyqu gormoni ishlab chiqishi uchun yotishdan kamida 1 soat oldin televizor, planshet kabi ko‘k yorug‘lik manbalaridan butunlay voz keching. Qorong‘ilik va sukunat — eng yaxshi uyqu dorisi.'),
  ('9d1de334-e45a-491d-8075-45ce379df7ad', 'Men onaman! o‘yini 🎭', 'Qo‘g‘irchog‘iga barmog‘ini bigiz qilib, sizning ohangingizda jahli chiqyaptimi? Xonada go‘yo sizning kichik nusxangiz yuribdi. O‘zingizni chetdan kuzatish ham kulgili, ham xatti-harakatlaringizga e’tibor berish kerakligini bildiruvchi ishoradir.'),
  ('fc7921b2-eab6-4a37-aad0-63611df47ad7', 'Kunduzgi uyqudan bosh tortish 🥱', 'Yotishni istamayapti, ammo ko‘zidan uyqu yog‘ilyaptimi? 3 yoshga yaqin bunday qarshilik odatiy hol. Majburlamang, xonadagi yorug‘likni pasaytirib, jim kitob varaqlash vaqtini e’lon qiling.'),
  ('2a74e43d-d2e3-45ad-8762-627a59c365b2', 'Ertalabki qaysarlik rangi 🔴', 'Ovqatni yashil likopchada so‘ragan edi, olib kelganingizda esa «Men qizil degandim», deb yig‘layapti. Mantiq izlashni bas qiling. Shunchaki qizil likopchaga soling va asab hujayralaringizni asrang.'),
  ('541b84ef-a3ed-43ff-8a33-aa153668c840', 'Tungi bo‘ron 😭', 'Yarim tunda hech qanday sababsiz yig‘lab uyg‘ondimi? Qorni dam bo‘lganmi yoki bu tungi vahimami? Taxmin qilishni bas qiling, Yig‘i tahlili yordamida sababini aniqlang va uni ohista quchoqlab tinchlantiring.'),
  ('60323c41-a0d6-4029-8b71-994315dcb0cf', 'Tuvak bilan bog‘liq ko‘ngilsizliklar 🚽', 'Tuvakka o‘rgatish paytida yana gilamga siyib qo‘ydimi? Chuqur nafas oling. Jahlingiz chiqishi uning ortga qadam tashlashiga sabab bo‘ladi. Tozalasa bo‘ladigan narsa uchun asabingizni qiynamang, bu shunchaki o‘rganish jarayoni.'),
  ('5b72c8ce-753e-4283-9bd2-18995d662a91', 'Temir zaxirasi 🥩', 'Rangi oqarib qolganmi yoki ishtahasi yo‘qmi? Ovqatlanishni kuzatish vositasida temir iste’molini tekshiring. Go‘sht bilan birga, albatta, limonli salat ham bering — bu temirning so‘rilishini tezda yaxshilaydi.'),
  ('b0a26358-dcc7-4a57-8694-6e91e9d4baaa', 'O‘yinchoqlarni bo‘lishish sabog‘i 🧸', 'Bog‘ga borishdan oldin: «Bugun o‘yinchoqlarimizni navbat bilan berib o‘ynaymiz», deb tushuntiring. Ha, u yana bo‘lishishni istamasligi mumkin, ammo bu mavhum qoidani qayta-qayta eshitishi muhim.'),
  ('c1d1533f-3d3f-4fb5-a549-d74668c72b3d', 'Dadaning uxlash taktikasi 👨‍🍼', 'Kechasi pijama kiyishni istamay, qochib yuribdimi? Bu vazifani dadasiga topshiring. U kiyinish jarayonini kurashga yoki kulgili o‘yinga aylantirsa, bola o‘zi sezmagan holda pijamasini kiyib oladi.'),
  ('3aee856b-a30f-48de-84ad-3c91f83ed092', 'Tabiat topishmog‘i 🍁', 'Bog‘da shunchaki sayr qilish o‘rniga o‘yin o‘ynang: «Qani, eng katta sariq bargni topamiz!» Tabiat uning uchun eng katta va interaktiv maktabdir.'),
  ('746f5afe-3705-4073-a3c0-ff69e92f5a25', 'Kir yuvish mashinasiga qiziqish 🧺', 'Kir yuvish mashinasi qarshisida o‘tirib, aylanayotgan kiyimlarni diqqat bilan kuzatyaptimi? Bu mutlaqo bepul va asablarni tinchlantiradigan mashg‘ulot. Unga xalaqit bermang, siz ham fursatdan foydalanib dam oling.'),
  ('8da8a36e-5d67-4dd0-ac14-245b62a8846a', 'Kayfiyat kundaligidagi izhor 📝', 'Telefoningizni qo‘lingizga oling. Ijtimoiy tarmoqlarni varaqlash o‘rniga, Kayfiyat kundaligini oching va bugun sizni jahlingizni chiqargan barcha narsani ko‘nglingiz bo‘shaguncha yozing. Raqamli terapiya yordam beradi.'),
  ('1a8259f8-8cae-4f18-b5c2-ee44aa10346d', 'Parkdagi advokat 🗣️', '«Yana ozgina o‘ynay, atigi 5 daqiqa!» deb vaqtni cho‘zadi. U hali vaqt tushunchasini bilmaydi, ammo savdolashish qobiliyati a’lo darajada. Taymer o‘rnating va qoidalarni buzmasdan, o‘yin tarzida eslatib turing.'),
  ('bf1a9cee-65ab-4eac-ad90-70c1631bbc46', 'Bo‘y o‘sishidagi sakrash 📏', 'Shimlari kalta bo‘lib qoldimi? U juda tez o‘smoqda! Rivojlanish kuzatuvchisiga joriy o‘lchamlarini kiriting va uyqusiz tunlaringiz samarasiga faxr bilan qarang.'),
  ('cff0599d-3a80-4d02-94df-22f42e5f09f2', 'Juftlik uchun tanaffus 🥂', 'Bola uxlab qoldi. Endi telefonlar va uy ishlarini bir chetga qo‘ying. Juftingiz bilan kamida 20 daqiqa davomida bola va to‘lovlardan boshqa istalgan mavzuda suhbatlashing.'),
  ('5130988b-06fa-4ca0-8477-7c4e5105998f', 'Ertaklarning sehrli olami 🪄', 'Bugun kechqurun Aqlli ertaklarda butunlay boshqacha bir narsani sinab ko‘ring: Osmonni kashf etgan mitti bulutcha haqidagi hikoya. Ovoz ohangingizni ertak ritmiga moslashtirib, bolajoningizni uyquga elt­ing.'),
  ('632fc2f4-f865-49e5-8a30-eef5c63d0d4a', '«Menga qarang!» zarbasi 👀', 'Siz telefonga qarayotganingizda yoningizga kelib, qo‘lingizga uradi yoki qurilmani tortib oladi. U mutlaqo haq. U o‘sha zahoti bor e’tiboringiz faqat o‘zida bo‘lishini istaydi. Ko‘zlariga qarab, uni tinglayotganingizni his qildiring.'),
  ('df191a16-4b37-4a90-bbd4-c8972ecc1670', 'Ketmas dog‘lar, erkin kashfiyotlar 🎨', 'Pijamasi ovqat, ust-boshi esa bo‘yoq dog‘larimi? Bolalar ozoda bo‘lib ulg‘ayishi shart emas — ular kashf etib, kir bo‘lishi kerak. Tartibsizlik uning ijodkorligi imzosidir, xavotir olmang.'),
  ('43d613a7-90fe-4d48-880a-a0dadfb94dab', 'Yashirin sabzavot amaliyoti 🥦', 'Sho‘rvadagi sabzavotlarni mikroskop bilan qidirayotgandek chetga ajratib qo‘yadimi? Sog‘lom retseptlar orasidan sabzavotlarni ko‘rinmas qiladigan sous retseptlarini toping. Ijodkorlik — onaning eng kuchli qurolidir.'),
  ('6fd78011-ad7d-48f0-9941-25d07912808e', 'Pastga qarang, u nimani kashf etyapti? 👣', 'Yalangoyoq yurish va turli yuzalarga tegish unga alohida zavq bag‘ishlaydi. Oyoq kaftidagi nervlarning faollashishi uning muvozanati uchun muhim, paypoqsiz yurishiga ruxsat bering.'),
  ('dcc98b1b-6e09-41d3-9be6-78333aecdab4', 'Tun qo‘riqchilari 🧸', 'Qorong‘ilikdan qo‘rqadimi? Eng sevimli ayiqchalari va o‘yinchoqlarini karavotining atrofiga terib, «Ular seni tonggacha himoya qiladi», deb ayting. Bunday ko‘rgazmali xavfsizlik hissi juda yaxshi samara beradi.'),
  ('3d8d4230-c58c-4f55-bb5e-c5c92f713201', 'Sukunat tasdig‘i 🤫', 'Shovqinli kundan so‘ng bola uxlagach, tovush o‘lchagich yordamida xonadagi sukunatni o‘lchang. Hatto nolga yaqinlashayotgan raqamlarni ko‘rish ham ona miyasiga terapiyadek ta’sir qiladi.'),
  ('53046b7a-695e-4d17-9dda-231255060141', 'Ertalabki «Yo‘q!» 🛑', 'Hali ko‘zini ochmasidan unga biror narsa taklif qilsangiz, «Yo‘q!» deydi. 3 yosh ostonasida savol bermang, shunchaki harakatga o‘ting. «Kel, yuz-qo‘limizni yuvamiz» emas, «Yuz-qo‘l yuvish vaqti!» deng.'),
  ('e5f27372-8ce2-40d6-acbc-12281fab28bb', 'O‘zingizga ham vaqt ajrating 🥑', 'Tinimsiz yugur-yugur sizni holdan toydirdi. Oyoq ustida shoshilib tamaddi qilish o‘rniga, Sog‘lom retseptlardan to‘yimli, vitaminlarga boy maxsus likopcha tayyorlab, maza qilib yeng. Energiya sizga, albatta, kerak.'),
  ('096e15b3-74ca-4180-ab20-07ce9b214b2a', 'Pichirlab suhbatlashish 🌙', 'Xona chiroqlarini butunlay o‘chiring. Uning yoniga yotib, kun davomida sodir bo‘lgan voqealarni juda past ovozda, pichirlab aytib bering. Pichirlash miyani uyquga tayyorlashning eng yaxshi usullaridan biridir.'),
  ('41df7f7d-e272-4737-8498-6c866ab9545a', 'Tajriba almashish 💬', 'Bolangizning hamma narsaga qaysarlik qilishi sizni qo‘rqitdimi? Internetdan vahimali maqolalarni qidirmang. Anacan hamjamiyatidagi tajribali onalarning hayotiy tajribalaridan foydalanib, tabassum qiling.'),
  ('8ac94a1b-a693-498b-9e54-d59e3331d567', 'Mohir raqqos 🎶', 'Eshitgan ilk ritmdayoq, reklama ovozi bo‘ladimi yoki avtomobil signali — raqsga tusha boshlaydi. Hayotga u kabi quvnoq nigoh bilan qarang! Xonada unga qo‘shilib, bir necha daqiqa sho‘x raqsga tushing.'),
  ('540ed6cc-ab45-42f3-bbdf-f7d1a37e6094', 'Dadaning maxfiy usuli 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetadi. Kechga yaqin bolani uyquga tayyorlash va tishlarini yuvdirishni dadasining sho‘xliklariga topshiring, o‘zingiz esa chetda xotirjam dam oling.'),
  ('75bb1e03-07ff-448a-b132-6eec4abf1a2d', 'Taxlanadigan va sochib yuboriladigan kiyimlar 👗', 'Siz katta mehnat bilan kiyimlarni taxlaysiz, u esa kelib, bir zumda hammasini sochib yuboradi. Jahlingiz chiqishining o‘rniga, ishni o‘yinga aylantiring: Qani, ko‘raylik-chi, bu ko‘ylakni kim uzoqroqqa ota oladi?'),
  ('ca77a3ff-10f8-4690-8926-270fe161b3d5', 'Mustaqil ovqatlanishga qaysarlik 🥄', 'Qoshiqni olib, hamma joyni iflos qilyaptimi? Ovqatlanish taymerini ishga tushiring. Sochilib ketgan ovqatga emas, u erishayotgan mustaqillikka qarab quvoning.'),
  ('25c4de30-89c3-4f45-952f-3b21fb85b41e', 'Yalangoyoq kashfiyotchi 👣', 'Paypoq kiyishni istamay, qochib yashirinyaptimi? Biroz yalangoyoq yurib, pol, gilam va sovuq kafelni his qilishiga imkon bering. Oyoq kaftidagi nerv uchlarining rivojlanishi uning muvozanatni saqlashi uchun beqiyos ahamiyatga ega.'),
  ('a0e0a012-48a8-4169-b4f6-62857311b266', 'Chiroqlarni o‘chiring, uyqu kelsin 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlar va planshet ekranlarini o‘chiring. Melatonin faqat qorong‘i va texnologiyalarsiz muhitda ishlab chiqariladi.'),
  ('ac0003df-1b37-4e86-98c2-561682149d03', 'Tabiatdagi izlanish 🍁', 'Ob-havoga mos kiyinib, tashqariga chiqing. Parkda turli toshlar va rang-barang barglarni topish o‘yinini o‘ynang. Bu yoshda tabiat uning uchun eng katta va interaktiv o‘yinchoqdir.'),
  ('85540a77-8c0c-40d1-bec5-6ddc93f07354', 'Do‘kondagi unutuvchanlik 🛒', 'Xotirangizga ishonib do‘konga bordingiz-u, eng kerakli narsani unutib qaytdingizmi? Barcha kerakli narsalarni darhol Xaridlar ro‘yxatiga yozib borishni odat qiling, ularni sizga ilova eslatib tursin.'),
  ('bd0902bb-9be1-40b5-8e41-73f85b835f0e', 'Ertalabki yordamchi 🧑‍🍳', 'U nonushta tayyorlashga yordam bermoqchi. Unni to‘kadi, suvni sachratadi, oshxona iflos bo‘ladi... Ammo u mayda motorikani rivojlantiruvchi mana shunday mashg‘ulotlar orqali ulg‘ayadi. Sabrli bo‘ling.'),
  ('c929f83e-5e59-4728-8c79-df0502607758', 'Sehrgar dadaning tomoshasi 🤡', 'Sizning hech bir urinishingiz ish bermay qolganida, dada chiqaradigan g‘alati tovushlar vaziyatni darhol qutqaradi. Kechki injiqlik paytlarida navbatni unga bering va chetdan quvnoq qahqahalarni tomosha qiling.'),
  ('61f1a424-1da9-48ab-b336-92c9137ef39e', 'Iliq vanna terapiyasi 🛀', 'Kun bo‘yi yugurib, bolangiz ham, siz ham charchadingiz. Iliq vanna qabul qilayotganda fonda tinchlantiruvchi tabiat tovushlarini qo‘ying. Suvning uyg‘un shovqini hatto eng qaysar bolani ham uyquga tayyorlaydi.'),
  ('8ae2c146-2d4a-4919-80fe-7f15c41cdc0e', 'O‘zi quyishni xohlaydi 💧', 'Suvni stakanga albatta o‘zi quymoqchi. Artish uchun salfetkalarni tayyorlab qo‘ying, uning mustaqillikka intilishini so‘ndirmang. To‘kib yuboradi, ammo bir necha urinishdan so‘ng stakanni qanchalik ehtiyotkorlik bilan to‘ldirayotganiga qoyil qolasiz.'),
  ('c8458955-5810-4609-a23d-82b155bf6112', 'Holdan toyish hissi 🔋', 'O‘zingizni yetarlicha yaxshi emasdek his qilyapsizmi? Hamma narsani uddalay olmayapman, deb o‘ylayapsizmi? Hamjamiyatdagi postlarni ko‘ring: siz yolg‘iz emassiz va aslo yomon ona emassiz. Siz bu bolaning butun dunyosisiz.'),
  ('87267db7-ab44-41b2-82ed-1d12fea90f71', 'G‘alati grammatika 🗣️', '“Men ochdim”, “U ketayotgandi keldi” kabi mutlaqo yangi, o‘ziga xos grammatik kashfiyotlar qiladi. Uni keskin tuzatmang, shunchaki jumlaning to‘g‘ri shaklini takrorlab javob bering.'),
  ('9a6f7d87-06ae-42b3-a4d0-b7eff2923976', 'Anacan AI maslahati 🤖', 'Bolangizning parkda boshqa bolalar bilan muloqot qilishi haqida savolingiz bormi? Internetda soatlab adashib yurmang, Anacan AI’dan so‘rang va darhol bolaning rivojlanishiga mos, pediatrlar tasdiqlagan maslahatni oling.'),
  ('a3b7ecf2-9668-46df-b331-9c7487819a32', 'Tungi vahima haqida ogohlantirish 😭', 'Bolangiz to‘satdan yig‘lasa yoki ko‘zlari yumuq holda qichqirsa, Yig‘i tahlili yordamida tekshiring. Agar bu tungi vahima bo‘lsa, uni uyg‘otishga urinmay, shunchaki yonida bo‘ling va jimgina o‘zini xavfsiz his qilishiga yordam bering.'),
  ('181a440f-5684-4f29-a861-16adef184628', 'Vaqt uchadi!', 'Ortga nazar solib, qanchalik ko‘p narsani o‘rganganingizni ko‘ring. Bu jajji huquqshunos endi siz bilan istalgan mavzuda savdolasha oladi. U bilan ham, o‘zingiz bilan ham faxrlaning.'),
  ('31d8e844-a068-4aa5-8b2c-23a9d11616c4', 'Ertak qahramoni 🪄', 'Klassik kitoblar ikkingizni ham zeriktirib yubordi. Aqlli ertaklarda uni fazogirga aylantirib, yulduzlar sari uchiring yoki dengiz qa’riga tushiring. Uyqu oldidan tasavvuringizga erkinlik bering.'),
  ('4280853d-50c1-4092-8d31-3279f5e3d68a', 'Tinchlik vaqti shart ☕', 'Agar u kunduzgi uyqudan qat’iyan bosh tortsa, majburlamang. Ammo 30 daqiqalik Tinchlik vaqtini (quiet time) belgilang. U karavotda kitoblari bilan yolg‘iz qolsin, siz esa boshqa xonada biroz nafas rostlang.'),
  ('10fd3d36-ea93-4f52-8bc2-486b88206869', 'Kayfiyat kundaligi 📝', 'Telefoningizni qo‘lga oling. Ijtimoiy tarmoqlarda varaqlash o‘rniga, Kayfiyat kundaligini oching va bugun uning qilgan eng kulgili, sizni eng ko‘p kuldirgan ishini kelajak uchun yozib qo‘ying.'),
  ('502d3376-0322-4c07-aee1-71c209315c6b', 'Yashirin sabzavotlar operatsiyasi 🥦', 'U sho‘rvadagi sabzavotlarni terib olib tashlayaptimi? Kurashmang. Ovqatlanish rejasida sabzavotlarni pyure qilib, souslar ichiga yashirishning eng xilma-xil va ayyorona usullarini kashf eting.'),
  ('ad687f75-6bde-4ad1-8992-78906bd61fd5', '“Onajon, menga qarang!” degan qaysarlik 👀', 'Siz telefonga qarayotganingizda yoki ish bilan band bo‘lganingizda kelib, qo‘lingizga uradimi? U mutlaqo haq — unga bo‘linmas e’tiboringiz kerak. Ko‘zlariga qarab, unga 5 daqiqa sifatli vaqt ajratsangiz, u tinchlanadi.'),
  ('2f5f6f47-30c9-4601-933d-5baa445585db', 'Dadaning massaj seansi 💆‍♂️', 'Bugun ko‘p vaqt oyoqda qoldingiz, bolaning ortidan yugurib belingiz uzilgudek bo‘ldi. Bola uxlashi bilan turmush o‘rtog‘ingizdan yelkangizni 10 daqiqa uqalab qo‘yishini so‘rang. Siz uyning ustunisiz, ustunlar ham dam olishi kerak.'),
  ('22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea', 'Xonadan qochish o‘yini 🏃‍♂️', 'Siz unga pijama yoki ko‘ylak kiydirmoqchi bo‘lganingizda, u kulib xonadan qochib ketadi. Jahlingizni chiqarmay, buni o‘yinga aylantiring. Quvlashmachoq o‘ynab, uni kiyintirish osonroq bo‘ladi.'),
  ('322a385d-8940-4d2a-9d21-4777e2660139', 'Ob-havo haqida ogohlantirish ⛅', 'Sayrga chiqayotganda derazadan qarab, ob-havoga aldanmang. Ob-havo va kiyim yordamchisi orqali tashqaridagi haqiqiy shamol va haroratga eng mos kiyimlar to‘plamini tanlab, so‘ng uydan chiqing.'),
  ('9c87f5af-e2e2-4310-ab2c-98ff6d5521d4', 'Ovozsiz rejimga o‘tish 🤫', 'U uxlab qolayotgan paytda sezgirligi ortadi. Sokinlikni saqlang.'),
  ('af1711a8-2ca3-45c1-ae35-556b3b0e2d67', 'Dada bilan uyqu dueti 📖', 'Bugun kechqurun xonada o‘zgacha muhit yarataylik. Kitob o‘qish o‘rniga, dadasi bilan birga past ovozda ritmik qo‘shiq kuylab, uning uxlab qolishiga yordam bering.'),
  ('b2328024-7846-4b25-a276-980c22ebcd52', 'Onajon, to‘yib ovqatlaning 🥑', 'Kundalik yugur-yugurda tushlikni oyoqda turib yemang. O‘tirib, maza qilib yeyish uchun temir va kalsiyga boy o‘zgacha salat tayyorlang. Sizning energiyangiz — bu uyning harakatlantiruvchi kuchi.'),
  ('e037ab2c-d2a8-49ed-a1df-aac78a584118', 'Do‘stlik qadamlari 👫', 'U parkda ilk bor o‘z xohishi bilan o‘yinchog‘ini boshqa bola bilan bo‘lishdimi? Bu katta rivojlanishdir! Egotsentrizm susayib, empatiya shakllanmoqda. Uni katta quvonch bilan olqishlang.'),
  ('e70841e8-9af5-471e-9ff6-b28774448a7f', 'Aralashmang 🧦', 'Paypog‘ining tovoni ustki tomonda, ammo uni o‘zi kiygani uchun dunyodagi eng mag‘rur insondek yuribdi. Aslo aralashmang. Mustaqillik hissi to‘g‘ri kiyishdan muhimroq.'),
  ('f3fc49f1-990c-4271-ab6c-21a94434e4c2', 'Hamjamiyatda yengil nafas oling 💬', 'Juda charchadingiz va o‘zingizni dunyodagi eng sabrsiz ona deb his qilyapsizmi? Darhol Anacan Hamjamiyatini oching. Boshqa onalar ham xuddi shunday qiyin vaziyatlarni boshdan kechirayotganini o‘qish — eng katta ruhiy yordamdir.'),
  ('3bcabb18-ba8e-4729-bb3a-959b28fdcaeb', 'Bulutlar topishmog‘i ⛅', 'To‘rt devor ichida siqilib qoldingizmi? Ob-havoga mos kiyinib, parkka chiqing. Shunchaki o‘tirib, osmondagi bulutlar nimalarga o‘xshashini toping. Bu sokin o‘yin miyani ham dam oldiradi, ham rivojlantiradi.'),
  ('1f9d373c-817c-4a86-9cb9-a9b3d9fac797', 'Sham yorug‘ida 10 daqiqa 🕯️', 'Bola uxlab qoldi, uydagi tartibsizlik ham tugadi. Chiroqlarni o‘chiring, shunchaki qorong‘ilikka yoki sham yorug‘iga qarab, 10 daqiqa davomida miyangizni va xayollaringizni butunlay bo‘shating.'),
  ('7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8', 'Hamjamiyatdan taskin 💬', '«Men endi hech qachon avvalgi o‘zim bo‘lolmayman», degan o‘y sizni qiynayaptimi? Bu o‘tkinchi, ammo juda og‘ir tuyg‘uni Anacan hamjamiyatidagi onalar bilan bo‘lishib, ulardan yordam oling.'),
  ('d270bdfa-5a84-42b7-8b44-3231febd32b3', 'Qaysar o‘rimlar 🪮', 'Sochini yig‘ish yoki tarashingizga aslo yo‘l qo‘ymayaptimi? Kurashishni bas qiling. Ko‘zgu qarshisiga o‘tib, avval o‘z sochingizni u xohlagandek tarang, keyin navbatni unga bering.'),
  ('b155d377-4b41-487e-b8ee-74a365226635', 'Kunduzgi uyqu uchun kurash 🥱', 'Agar uxlashni istamasa, majburlamang. Uni qayta-qayta uxlatishga urinib, asablaringizni buzish o‘rniga, xonada o‘yinchoqlari bilan tinchgina o‘ynaydigan tartib yarating.'),
  ('b7283d95-1357-4ff9-9423-db4159e19c31', 'Jamoaviy g‘alaba 🥂', 'Yana bir og‘ir kunni ortda qoldirdingiz. Juftingiz bilan yuzma-yuz o‘tirib, bir piyola choy bilan qadah urishtiring: Biz haqiqatan ham afsonaviy jamoamiz va bu ishni a’lo darajada uddalayapmiz!'),
  ('c932a08e-a484-4595-8fa6-e57165ffaf96', 'Bo‘lishish tashvishi 🧸', 'O‘yinchog‘ini hech kimga bermayaptimi? Bu xudbinlik emas, balki rivojlanish bosqichidir. 3 yoshga yaqin davrda bo‘lishishdan ko‘ra, navbat bilan o‘ynash tushunchasi muhimligi haqida Anacan AI’dan bilib oling.'),
  ('8fab2e02-e35e-45f0-a10f-554adfe7c2c6', 'Uydagi tartibsizlik nihoyat tugadi.', 'Derazadan kelayotgan shovqinni to‘sish uchun lofi musiqa qo‘yib, ruhingizga orom bering.'),
  ('23137ca6-6246-4dc7-b692-cdcd36eeac0f', 'Uch g‘ildirakli velosiped 🚴‍♂️', 'Pedallarni bosib, velosiped haydashga urinyaptimi? Oyoq mushaklari va harakatlarni muvofiqlashtirish qobiliyati yangi bosqichga o‘tmoqda! Uni xavfsiz joylarda bunga undang.'),
  ('b44d4b2a-f3eb-4e26-aa50-0105efb5648c', 'Ona uchun vitaminlar 🥑', 'Uni to‘ydirish uchun hamma narsani qilyapsiz. O‘zingiz-chi? Sog‘lom retseptlar bo‘limidan temir va kalsiyga boy yengil tushlikni tanlang.'),
  ('f62c402c-4ba9-489a-b6de-dde4e1aa3aae', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda uyg‘onishlarning barchasini yolg‘iz o‘zingiz zimmangizga olmang. Juftingizni ham uyg‘oting — bir jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir.'),
  ('10872122-03c1-4660-aabc-490c724034c9', 'Cho‘ntak to‘la xazina 🍁', 'Bog‘dan qaytdingiz-u, uning cho‘ntagidan 3 ta tosh, 1 ta qurigan barg va bir cho‘p chiqdimi? Uning uchun bular qimmatli xazina. Siz esa ularni uy bo‘ylab sochib yuborishidan oldin sezdirmay olib qo‘yishga harakat qiling.'),
  ('8f84e032-e8dd-4d1f-b3c6-5d57937006dd', 'Mantiq izlamang 👑', 'Nonushtaga muzqaymoq yoki kechagi yasmiq sho‘rvasini talab qilyaptimi? Uyda yangi hukmdor paydo bo‘libdi. Unga tanlash imkonini berib (Masalan: Olma xohlaysizmi yoki banan?) diqqatini darhol boshqa tomonga qarating.'),
  ('907a5bc5-4a7e-48ec-977c-d9c5440faba0', 'Yotoqdan qochish bahonalari 🏃‍♂️', 'Suv ichgisi keladi, hojatxonaga borgisi keladi, xonadagi pardani o‘pgisi keladi... Uxlamaslik uchun miyasi yangi bahonalarni o‘ylab topmoqda. Chegara qo‘ying: Faqat 1 stakan suv — tamom. Qat’iy turing.'),
  ('9de02d84-1ac6-4478-a817-67045fcd6af5', 'Ilk shirin yolg‘onlar? 🤥', 'Suvni men to‘kmadim, ayiqcham to‘kdi. Diqqat! Tasavvuri shu qadar rivojlanganki, voqealarni o‘z foydasiga to‘qib chiqara oladi. Uni yolg‘onchilikda ayblamang, «Ayiqchangga ayt, boshqa to‘kmasin», deb jilmaying.'),
  ('4ab501ea-956f-4adc-a27e-2e2bc99f59c6', 'Tanadagi tatuirovkalar 🖍️', 'Bir necha soniyalik sukunat ba’zan xavfli bo‘ladi. Xonaga kirib, uning qo‘llariga flomaster bilan tatuirovka chizganini ko‘rdingizmi? Chuqur nafas oling. Mayda motorikasi rivojlanmoqda, teridagi siyoh esa baribir yuvilib ketadi.'),
  ('93712bd1-e114-4739-841f-9d8901785feb', 'Hamkor dada 👨‍👧', 'Kechga yaqin quvvatingiz butunlay tugadimi? «Men bu ssenariydan chiqaman», deng-da, bolani dadasiga topshiring. Ular birgalikda to‘zg‘itgan xonani yig‘ishtirish, bola bilan yolg‘iz kurashishdan osonroq.'),
  ('9a4e49fa-28ce-4422-86d1-9b77699fd24c', 'Kletchatkaga ehtiyoj 💩', 'U ko‘p yuguradi, ammo suv ichishni unutadi. Tuvakdagi najasini kuzating. Ich qotishi xavfi bo‘lsa, menyuga suli yormasi va olxo‘ri qo‘shing.'),
  ('2743b373-11c6-4a72-a371-988483c30fb4', 'Soya bilan adovat 👻', 'Ko‘chada yoki xonada birdan yig‘lay boshladimi? Bunga o‘z soyasi uni kuzatib yurishi sabab bo‘lishi mumkin! 3 yoshga yaqinlashganda tasavvuri g‘aroyib tus oladi. Uni quchoqlab, tabassum bilan soyasi bilan tanishtiring.'),
  ('344cf14d-0511-4f06-86bb-38e1e79297c3', 'Ovqat jarrohi 🥦', 'Ovqatni yemaydi, faqat ichidagi mayda guruch donalari yoki yashil ziravorlarni jarrohga xos aniqlik bilan ajratib oladi. Ovqatlanish rejasiga o‘tib, sabzavotlarni pyure holiga keltirish usullarini o‘rganing.'),
  ('85bf1b2b-8bd2-41a8-8e81-bd414469ff03', 'Hamma narsa bilan xayrlashish 🧸', 'Uxlashdan oldin xonadagi mashinacha, stul va hatto eshik tutqichiga ham xayrli tun tilamoqchi bo‘ladi. Bu uning uyquga o‘tish uchun o‘zlashtirgan yangi odatlaridan biri, uni shoshiltirmang.'),
  ('4699f7a7-a05a-4fb5-bcc3-1031cc990173', 'Xayoliy biznes qo‘ng‘iroqlari 🍌', 'Qo‘liga banan yoki pult olib, o‘zi to‘qigan tilda jiddiy qiyofada telefonda gaplashyaptimi? U sizning tana harakatlaringizni aynan takrorlayapti. Uni videoga olib, kelajak uchun saqlab qo‘ying — hali ko‘p kulasiz.'),
  ('77b18a3d-16c2-454b-9fe4-daea00f5a342', 'Rejim surilyaptimi? ⏱️', 'Kechqurun uxlab qolishi 1 soatdan ko‘proq vaqt olyaptimi? Uyqu taymeridagi jadvalga qarang. Balki kunduzgi uyquni butunlay bekor qilib, kechki uyqu vaqtini ertaroqqa surish payti kelgandir.'),
  ('9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469', 'Tish cho‘tkasi jangi 🪥', 'Tish cho‘tkasini ko‘rishi bilan og‘zini mahkam yumib oladimi? Gigiyenani jangga aylantirmang. Tavsiya etilgan mahsulotlar bo‘limidagi musiqali cho‘tkalarni ko‘rib, bu mashaqqatli odatni qiziqarli o‘yinga aylantiring.'),
  ('3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a', '«Oyoqlarim ishlamayapti» qaysarligi 🛑', 'Parkdan qaytayotganda birdan yerga o‘tirib olib, oyoqlarim ishlamayapti deb, ko‘tarib olishingizni so‘raydimi? Bu charchoq emas, manipulyatsiya. «Qani, ko‘raylik-chi, uygacha quyondek sakrab bora olasizmi?» deb, vaziyatni o‘yinga aylantiring.'),
  ('b948ea64-f471-4d36-958a-85e04a0250f1', 'Tuvak bilan bekinmachoq 🚽', 'Hojati kelganda parda ortiga yoki divan yoniga yashirinadimi? Bloglar bo‘limiga o‘tib, tuvakka o‘rgatishni boshlashning ilmiy asoslangan bosqichlari haqida o‘qishning ayni vaqti.'),
  ('b9e8fff7-f7f2-410b-a103-f4cd6c6231f8', 'Kundalikka dardini to‘kish 📝', 'Kimdir sizga «Uyda bo‘lsangiz, nimadan charchaysiz?» dedimi? Darhol Kayfiyat kundaligini oching va butun jahlingizni barmoqlaringiz orqali ekranga to‘king. Soxta tabassum qilishdan ko‘ra, haqiqiy his-tuyg‘ularingizni yozganingiz yaxshiroq.'),
  ('0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc', 'Dadaning ertak shousi 📖', 'Bu oqshom xonada sizning emas, dadasining ovozi yangrasin. Ertakni u o‘qisin, qahramonlarning ovozini goh yo‘g‘onlashtirib, goh ingichkalashtirib, kulgili muhit yaratsin. Siz esa chetda turib, kulgilarni tinglang.'),
  ('2fc731d4-47df-4b97-8f67-c7df6aabac96', 'Onaning yashirin shokoladi 🍫', 'Bola orqasini o‘girishi bilan og‘zingizga bir bo‘lak shokolad solib, tezda chaynab yuboradigan ona, bu glyukoza sizning eng tabiiy haqqingizdir. Kun bo‘yi uning shiddatiga bardosh berish uchun quvvat yig‘ishingiz kerak.'),
  ('edb08c0a-b151-4f7a-9713-c903f3f5c584', 'G‘alati eng yaqin do‘st 🥄', 'Shuncha qimmat o‘yinchoqlar turganda, u oshxonadan silikon kurakcha topib olib, kun bo‘yi uni ko‘tarib yuribdi, hatto uxlatyaptimi? Bola miyasi hayratlanarli. Xalaqit bermang, kurakchasini yaxshi ko‘raversin.'),
  ('36ebb286-2e4d-4e44-a91d-6c026199737c', 'Tabiat qo‘ynidagi izlanish ⛅', 'To‘rt devor ichida o‘tirish miyangizni karaxt qilib qo‘ydi. Ob-havoga qarab, eng mos kiyimlar uyg‘unligini tanlang. Tashqariga chiqib, faqat sariq barg topish vazifasi bilan uning ham energiyasini chiqaring, o‘zingiz ham toza havodan nafas oling.'),
  ('4b98ee52-d8a1-4d7a-9183-64cdd8482ef0', 'Xavfli so‘zlar 🤐', 'Qayerdandir eshitgan o‘sha yomon so‘zni kulib sizga takrorlayaptimi va munosabatingizni kutyaptimi? Eng kuchli qurolingiz — hech qanday munosabat bildirmaslik. Kulmang, jahlingiz chiqmasin, shunchaki e’tibor bermang. Tez orada unutadi.'),
  ('c2b89303-d5b8-4b81-97cd-3a091f15bb05', 'Oltindek sukunat o‘lchovi 🤫', 'U nihoyat uxlab qoldi! Ovoz o‘lchagichni yoqing va xonadagi mutlaq tovush darajasini (0-10 desibel) ekranda kuzating. Bu raqamlarni ko‘rish charchagan ona miyasi uchun eng yaxshi massajdir.'),
  ('45a51286-f051-4f99-a23c-39a189481dfa', 'O‘jar pijama 👗', 'Ertalabdan kechgacha kir bo‘lib, dog‘ tushgan pijamasini yechishni istamayaptimi? 3 yoshda tashqi ko‘rinish muhim emas. Sovqotmayotgan bo‘lsa, yana bir necha soat shu holatda yurishiga ruxsat bering.'),
  ('4c871abf-c886-4fbd-909f-95e344736fa3', 'Aqlli ertakdagi men 🪄', 'Klassik kitoblarni yodlab bo‘lgansiz. Aqlli ertaklarni ochib, bosh qahramon sifatida farzandingizni, zabt etiladigan joy sifatida esa uning xonasini tanlang va g‘ayrioddiy uyqu mashg‘ulotini yarating.'),
  ('9f3be00e-0091-4500-91da-22dc9ba62d93', 'Multfilm tanqidchisi 📺', 'Ko‘rgan multfilmini sizga o‘z grammatikasi bilan so‘zlab, kim qayerga borganini jiddiy tushuntiradi. Uni diqqat bilan, hayratlangandek tinglang. O‘zini dunyodagi eng aqlli insondek his qilsin.'),
  ('89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8', 'Quyoshdan oldin uyg‘onadiganlar 🌅', 'U soat 6-da oyoqda, siz esa holdan toyganmisiz? Bu tartibni qanday sozlash mumkinligini Anacan AI-dan so‘rang. Unutmang, uyqusizlik abadiy emas, hammasi o‘tib ketadi.'),
  ('e229522e-360b-4392-8cfc-620f6326286c', 'Juftlik shampani 🥂', 'Bola uxlab qoldi. Shampan bo‘lmasa ham, stakanlarga issiq choy quyib, juftingiz bilan «Bu og‘ir kunni ham eson-omon yakunladik», deya stakanlarni urishtiring. Siz ajoyib hamrohsiz.'),
  ('f802a634-da9b-44e2-a965-9f94ea543fd1', 'Ro‘yxatdagi syurpriz 🛒', 'Do‘konga borishdan oldin xaridlar ro‘yxatini ochdingiz va farzandingiz orqadan kelib, telefon ekranini bosib, unga shokolad qo‘shganini ko‘rdingiz. Ha, ular texnologiyani sizdan ham yaxshiroq bilishadi!'),
  ('0d0524d6-a4ad-4051-b779-b554d981748f', 'Vannadan chiqishni istamaslik 🛀', 'Suv bilan o‘ynash shunchalik zavqliki, barmoqlari burishib qolsa ham vannadan chiqishni istamaydi. Uni 5 daqiqa oldin ogohlantirib, taymer qo‘ying. Qo‘ng‘iroq chalinganda chiqamiz degan qoida ko‘pincha ish beradi.'),
  ('1460be31-c5b7-4f0f-9a6b-7ff5c2085c36', 'Soch tarash kurashi 🪮', 'Ertalab uyg‘onganida sochlari xuddi tok urgandek tikka bo‘lib qolgan. Taroqni ko‘rishi bilan esa qochish boshlanadi. Tarash o‘rniga sochlarini qo‘llaringizni namlab bosib qo‘ying va kurashga nuqta qo‘ying.'),
  ('fc5667d9-2c85-42d4-a92c-e90c3b994a0f', 'Sun’iy intellekt fikri 🤖', 'Farzandingizda g‘alati bir odat paydo bo‘ldimi (masalan, tirnoq tishlash) va internetdagi maqolalar sizni qo‘rqitdimi? To‘xtang. Anacan AI’dan buning pediatrlar tasdiqlagan asl sababini so‘rang va xotirjam bo‘ling.'),
  ('01349acb-919c-490a-bfce-f75e04518130', 'Shifokor yoningizda 🩺', 'O‘yinchoq stetoskopini olib, ko‘kragingizga qo‘yadi va nafas oling deydi. Siz bemorsiz, u esa bosh shifokor. Bu o‘yinga qo‘shiling, yoting va hech bo‘lmasa 5 daqiqalik davolanish paytida ko‘zlaringizni yumib, dam oling.'),
  ('d58d064b-a397-425d-9d57-3f6068e31cf1', 'Energiya jo‘shishi 🏃‍♂️', 'Uy ichida devorlarga tirmashib yuribdi. Ob-havo va kiyimini tekshirib, albatta tashqariga chiqing. Kislorodga boy muhitda 30 daqiqa yugurish uning kechqurun yaxshi uxlashining eng katta kafolatidir.'),
  ('d96fbe0f-26f7-4473-9f0b-34109da6a744', 'Shivirlash sehri 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Yoniga yotib, kun davomida sodir bo‘lgan voqealarni unga juda past ovozda, shivirlab aytib bering. Shivirlash miyani uyquga tayyorlaydigan eng tabiiy va tinchlantiruvchi usuldir.'),
  ('2521dffb-415b-4bec-81f4-b18ee93644d8', 'Qorong‘ilikka ko‘nikish 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin gormoni faqat tinch va qorong‘i muhitda tezroq ajraladi.'),
  ('8ca17d8b-45e4-4184-b598-9b59778d5b0c', 'Onaning quvvatlanish vaqti 🔋', 'U o‘zi mustaqil pazl yig‘yapti va 10 daqiqadan beri jim. Siz esa bu fursatni uy yig‘ishtirishga sarflamoqchisiz. Yo‘q! Borib, divanga cho‘ziling. Kechgacha bardosh berishingiz uchun sizning ham quvvatingiz to‘lishi kerak.'),
  ('c145c120-a19a-477b-922c-6f3ffc430787', 'O‘ylab topilgan grammatika 🗣️', '«Men bordimdim», «U kelganmishdi» kabi g‘alati va kulgili zamon shakllarini o‘ylab topyapti. Uning so‘z boyligi rivojlanmoqda! Uning ustidan kulib, xatosini tuzatmang, shunchaki to‘g‘ri jumlani takrorlab tasdiqlang.'),
  ('6e5eaf14-24e1-4f23-8d49-63a035b843ff', 'Kayfiyat kundaligidan taskin topish 📝', 'Qanchalik charchaganingizni hech kim sezmayaptimi? Ilovadagi Kayfiyat kundaligi sizni tinglash uchun doim yoningizda. Bugun asabingizga tekkan barcha mayda-chuydalarni u yerga yozib, miyangizni ortiqcha o‘ylardan xalos qiling.'),
  ('b83f22c8-15c6-43cf-9689-94f8a790e4b9', 'Ovqat bilan bog‘liq sinovlar 🥣', 'Kecha ishtaha bilan yegan narsalarining barchasini bugun tuflab tashlayapti. Agar tishlari bilan bog‘liq muammo bo‘lmasa, bu shunchaki irodangizni sinashdir. Sog‘lom retseptlar bo‘limidagi sabzavotlar yashirilgan mazali va rang-barang kotlet retseptlarini sinab ko‘ring.'),
  ('fe01f44d-664a-4a34-8ce6-39e87f7fdab2', '5 daqiqalik illyuziya ⏱️', '«Yana atigi 5 daqiqa ko‘ray», deydi, ammo uning miyasida 5 daqiqa tushunchasi hali shakllanmagan. Telefon taymerini o‘rnating va signal chalinganda vaqt tugaganini tushuntiring. Aybdor siz emas, texnologiya bo‘lsin.'),
  ('1fc309f5-659f-4b2e-bf6f-e17296d830ff', 'Dadaning belida ot minish 🐴', 'Energiyasini to‘liq sarflay olmay, uxlashga yotmayaptimi? Dadasining beliga minib, uy ichida ot chopish va qah-qahalar energiyasini sarflashning eng tez va qiziqarli yo‘lidir. Endi navbat dadasiga.'),
  ('69846205-68bb-4476-a7e0-45d4e68fae26', 'Onaning tinchlikka ehtiyoji 🩸', 'Har bir tovush asabingizga tegyaptimi? Hayz kuzatuvchisiga qarang. Tanangiz dam olishga muhtoj. Sog‘lom retseptlardan magniyga boy gazak tayyorlab, o‘zingizga vaqt ajrating.'),
  ('c6dcd330-d5df-4d87-b7a0-d8ab33a73063', 'Sababsiz yig‘i 😭', 'Ko‘zini ochishi bilan sababsiz yig‘layaptimi? Bu injiqlik emas, balki hissiy zo‘riqishdir. Bunday paytda qanday yo‘l tutish kerakligini Anacan AI ekspertimiz bilan dardlashib bilib oling.'),
  ('6ac257ab-47ac-4e61-a9e4-2b538df0a8dc', 'Dadaning oshxonadagi navbati 👨‍🍳', 'Bugun tushlik tayyorlash va bolani ovqatlantirish dadasining zimmasida! Siz esa bu vaqtni shunchaki yotib yoki dam olib, o‘zingizga bag‘ishlang.'),
  ('ba525880-dd70-46d8-9c0c-f0fb9b49240c', 'Tabiat tovushlari bilan uyqu 🪄', 'Klassik musiqa yordam bermayaptimi? Aqlli ertaklarda ertakni o‘chirib, faqat yomg‘ir yoki o‘rmon tovushlari eshitiladigan fonga o‘ting. Bir maromdagi tabiat tovushlari bolani xuddi sehrlangandek uxlatadi.'),
  ('ba82984e-ccd6-40f9-b991-bf586ff48b9d', 'Kattalardek xo‘rsinish 😔', 'Divanda o‘tirib, birdan kattalardek chuqur nafas olib xo‘rsinadi. U sizga juda yaxshi taqlid qiladi! Uning bu dramatik mimikalarini chetdan jilmayib kuzating.'),
  ('268f32e3-3ad0-45c0-aef4-aba7ce610179', 'Oshxonadagi ko‘ngilsizliklar 🧑‍🍳', 'Ovqat pishirayotganingizda u albatta yoningizda turib, yordam berishni va tuz solishni xohlaydi. Ruxsat bersangiz, ovqat buziladi, bermasangiz, yig‘laydi. Unga bo‘sh idish bilan suv berib, «Sen o‘z sho‘rvangni pishir», deng.'),
  ('e612b840-bcec-4199-920b-e4d2f37aa7cb', 'Ro‘yxat nazorat ostida 🛒', 'Yubiley kuni uchun kerak bo‘ladigan hamma narsani Xaridlar ro‘yxatiga qo‘shdingizmi? Sharlar va kichik syurprizlar ham ro‘yxatda ekaniga ishonch hosil qiling. Turmush o‘rtog‘ingizga ilova orqali so‘nggi eslatmani yuboring.'),
  ('eb50f918-4009-4323-94a0-e8fd1ccc9f1d', 'Yorug‘lik kuzatuvchisi 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat — miya eng faol bo‘ladigan vaqt. Shovqin o‘lchagich yordamida xonadagi sharoitni sozlang. Derazadan kelayotgan tovushlarni bartaraf etib, mutlaqo sokin va qorong‘i muhit yarating.'),
  ('0cde3d33-fabc-43f7-bcba-b8c6c307e26e', 'Hikoya rejissyori 🪄', 'Aqlli ertaklarni yoqing va bugun kechqurun voqealar rivojini uning o‘zi boshqarishiga imkon bering. «Endi qahramon qayerga borsin?» deb so‘rang, o‘zi o‘ylab topgan g‘aroyib yakun bilan uyquga ketsin.'),
  ('60a51ebc-ca29-4910-bc60-cd0880a0539a', 'Mantiqsiz ko‘z yoshlar 🐶', 'Ko‘chada ko‘rgan it unga qaramagani uchun 15 daqiqa ho‘ngrab yig‘ladimi? Bundan mantiq izlamang. Bu uning uchun chindan ham chuqur qayg‘u. «Bilaman, sen uning senga qarashini xohlaganding», deb, his-tuyg‘usini tushunayotganingizni bildiring.'),
  ('e0a781fd-ff93-41bb-aced-df42a4ca9525', 'Uydagi tartibsizlikni qabul qilish 🌪️', 'Xonaning hamma joyi o‘yinchoqlarga to‘lib ketganmi? Tozalik emas, u bilan o‘tkazayotgan sho‘x-shodon lahzalaringiz muhim. O‘yinchoqlar ertaga ham shu yerda bo‘ladi, o‘zingizni charchatmang. Ba’zan tartibsizlikka ko‘nish — eng yaxshi dam olishdir.'),
  ('37ca7eb9-999f-4245-9a90-94f0e28e6df4', 'Tugamaydigan savollar mashinasi 🤔', '«Nega?», «Qanday?» degan savollar miyangizni charchatyaptimi? Uning bilimga bo‘lgan qiziqishiga zerikmasdan qanday mantiqli javob berishni Anacan AI’dan o‘rganing. Sizning sabringiz — uning rivoji.'),
  ('70e9f70c-b53f-462f-9274-badc9beebd25', 'Sukunat kundaligi 📝', 'Uydagi dovul nihoyat uxlab qoldi. Endi telefoningizni qo‘lga oling va Kayfiyat kundaligiga bugungi kunni omon o‘tkazganingiz uchun o‘zingizga minnatdorchilik xati yozing. Siz buning uddasidan chiqyapsiz.'),
  ('cac1efaa-10e1-4f19-b586-507cb8610102', '«O‘zim qilaman» qarshiligi 🛑', 'Poyabzalining bog‘ichini o‘zi bog‘lamoqchi bo‘lib, 10 daqiqangiz ketyaptimi? Shoshilmang, unga vaqt bering. Uning urinib ko‘rishi va xato qilishi kelajakda muammolarni hal qilish qobiliyatiga poydevor bo‘ladi.'),
  ('078ff563-48f3-4bd6-81ac-93fc21a3bab7', 'Qahva va meditatsiya ☕', 'Xonani ostin-ustun qilib yubordimi? Yig‘ishtirishni qo‘ya turing. Bola o‘zi bilan ovora bo‘lib turganida, divanga o‘tirib, issiq qahvangizni iching va shunchaki devorga qarab, 10 daqiqa miyangizga dam bering.'),
  ('710f54a9-baa0-4889-a361-f7615894b552', 'Kasblarga taqlid 🩺', 'O‘yinchoq ayig‘ini davolayaptimi yoki mashinalarni ta’mirlayaptimi? Ramziy o‘yinlar (rolli o‘yinlar) ayni avjida.'),
  ('9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a', 'Soya o‘yinlari 🐰', 'Uxlashni xohlamayaptimi? Xonani butunlay qorong‘i qiling va qo‘llaringiz yordamida devorda soyalar teatrini yarating. Bu qorong‘ilik qo‘rquvini yengishning eng qiziqarli usulidir.'),
  ('0cd42656-20ce-4f47-aca2-4978ae93880d', 'Tuvak borasida ortga qadam? 🚽', 'Tuvakka borishni o‘rganib olgan edi, endi yana tagiga qilib qo‘yyaptimi? Bu juda tabiiy ortga qaytish holati. Bosim o‘tkazmang, ushbu psixologik to‘siqni injiqliklarsiz yengib o‘tish yo‘llarini Anacan AI’dan so‘rang.'),
  ('3164bc6c-fe7e-4273-94e8-6750bee50d0a', 'Bloglardan ilhom olish 📱', '35 oylikka yaqinlashayotgan bolada rivojlanishning qanday sakrashlari kuzatiladi? U nimalarni bajara olishi kerak? Ilovadagi rivojlanish haqidagi bloglarni ko‘rib chiqing va farzandingiz qanchalik ilgarilab ketganini ko‘rib quvoning.'),
  ('4d45db57-1817-4fc6-ad71-f2aeb4cd1050', 'Muhim sanaga tayyorgarlik 💆‍♂️', 'Bola uxlagach, juftingiz bilan ertangi katta sana munosabati bilan bir-biringizni tabriklab, yelkangizni yengil uqalab qo‘ying. Bayram kunini tetik kutib olish uchun ikkalangiz ham dam olishingiz shart.'),
  ('41e90866-d00f-459e-8936-e28d83f9d539', 'Yotoqxonadagi yugur-yugur 🏃‍♂️', 'Uxlash o‘rniga divanda sakrayaptimi? Yana suv ichish bahonalari ham tugamayaptimi? Uyqu taymerini ishga tushiring va belgilangan chegaralarga qat’iy rioya qiling.'),
  ('4f9eced2-7736-4f35-ad7d-6205edaad1e4', 'Dadaning o‘yin navbati 👨‍👧', 'Onalik tugamaydigan marafon emas. Bugun bolaning kuch-g‘ayratini dadasi parkda sarflatsin, siz esa divanda yolg‘iz qolish gashtini suring.'),
  ('e18107ed-4459-4f40-b466-2d79ae0ff98c', 'Yozda qishki bosh kiyimlar 🧢', 'Ob-havoga mutlaqo mos kelmaydigan kiyimni kiymoqchimi? Mustaqillik uchun kurash davrida unga bir nechta kichik tanlov imkonini bering.'),
  ('3a84b553-313a-486c-95e8-2a799895283c', 'Yig‘lama 🫂', 'Bog‘da yig‘layotgan boshqa bolani ko‘rsa, uning yoniga borib, erkalaydimi? Demak, hamdardlik tuyg‘usi rasman ishga tushgan! Uning bu ajoyib mehribonligini chetdan faxr bilan kuzating.'),
  ('77ff1ffc-86a7-418d-bad4-4d026f199772', 'Katta karavotga o‘tish vaqti keldimi? 🛏️', 'Beshigidan oshib tushishga urinyaptimi? Balki, katta karavotga o‘tkazish haqida o‘ylayotgandirsiz. Anacan AI’dan kattaroq bolalar karavotiga o‘tishdagi xavfsizlik qoidalari va buning uchun eng maqbul vaqt haqida so‘rang.'),
  ('e176efcb-aafc-4480-93eb-e1978282a880', 'Dada bilan kitob o‘qish vaqti 📖', 'Bugun kechqurun ovozingizga dam bering. Bolaning sevimli kitoblarini turli ovozlarda o‘qib berish vazifasini dadasiga topshiring.'),
  ('65edab42-e5b4-4da3-8b99-8e271dd3fc16', 'Shaxsiy chegaralarini belgilayapti ✋', 'Kimdir uni o‘pmoqchi bo‘lsa, uzoqlashadimi yoki «yo‘q» deydimi? Uning tanasiga oid shaxsiy chegaralarini hurmat qiling va boshqalardan ham shuni talab qiling. O‘ziga ishonch aynan shundan boshlanadi.'),
  ('c46434f8-d6b6-4038-89e7-8bc38a5332c2', 'Aqlli ertak sehri 🪄', 'Klassik ertaklardan zerikdingizmi? Aqlli ertaklarga o‘zgacha mavzu bering: sabzavot yeyishni yaxshi ko‘radigan sehrli dinozavrning sarguzashtlari.'),
  ('d941dd67-309a-49cb-833c-78b38c4762e7', 'Kiyinish diplomatiyasi 👗', 'Qishning qoq o‘rtasida yozgi shim kiyishni xohlayaptimi? Darhol Ob-havo va kiyim vositasini oching va ekrandagi tasvirlar yordamida tashqarida havo sovuq ekanini unga mantiqan tushuntiring.'),
  ('0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6', 'Sukunatning qadri 🤫', 'U nihoyat uxlab qoldi. Endi uydagi eng mayda tovush ham asabingizga tegadi. Shovqin o‘lchagich yordamida xona uchun tovush chegarasini belgilang va fonda uzluksiz oq shovqinni yoqing.'),
  ('bf9527d0-d7b0-4cb8-8523-c499e2e95693', 'Sanashni boshlaymiz 🔢', 'Zinadan chiqayotganda yoki o‘yinchoqlarini terayotganda bir, ikki, uch deb aytishga harakat qilyaptimi? Matematik tafakkurning poydevori shakllanmoqda. U bilan birga xonadagi buyumlarni ovoz chiqarib sanang.'),
  ('ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5', 'Hissiy kuyish sindromi 🔋', 'Hamma narsaga baqirgingiz kelyaptimi? Siz hissiy kuyish holatini boshdan kechiryapsiz. Anacan hamjamiyatiga kiring va Men juda charchadim deb yozing. Minglab ayollar ayni damda siz bilan hamfikr ekanini ko‘rasiz.'),
  ('405360f8-7a97-471c-825c-355eafed365d', 'Kunduzgi uyquni rad etish 🥱', 'Kunduzi uxlashni aslo istamay, qarshilik ko‘rsatyaptimi? 3 yoshga yaqin ayrim bolalar kunduzgi uyqudan voz kechadi. Kun tartibidagi uyquni Sokinlik soati (uyqusiz sokin vaqt) bilan almashtirib ko‘ring.'),
  ('6740b19e-f070-42e2-9b6e-76434890c90f', 'Xotiralar uyg‘onmoqda 🧠', 'Kecha buvimiznikiga bordik kabi o‘tmishga oid gaplar tuzyaptimi? Vaqt tushunchasi va uzoq muddatli xotira shakllanmoqda. Uning bu xotiralarini qiziqish bilan tinglab, savollar bering.'),
  ('f0257b2e-d5f4-40d8-9701-488c186af81f', 'Yarim tunda ko‘zlari yumuq holda baqirib yig‘layaptimi?', 'Uni uyg‘otishga urinmang. Ovozini Yig‘i tahliliga eshittirib, bu shunchaki tungi vahima ekaniga ishonch hosil qiling va xotirjam yonida turing.'),
  ('1da71143-b8dd-434a-bf23-b7f16a2d4a80', 'Mustaqillik sharsharasi 🥛', 'Suv yoki sutni stakanga albatta o‘zi quyishni xohlaydi, natijasi-chi? Hamma joy ko‘lmak. Chuqur nafas oling. Bu tartibsizlik — uning qo‘l-ko‘z muvofiqligi va o‘ziga ishonchi rivojlanishining bahosi. Unga ham latta bering va ovozingizni ko‘tarmasdan birga tozalang.'),
  ('7f1b27a1-aff6-4522-ba4e-76bb08fa648e', 'Shovqin-surondan tanaffus 🎧', 'Ona, ona, ona! degan ovozlar miyangizda aks-sado beryaptimi? O‘zingiz uchun kichik tanaffus e’lon qiling. Uni 15 daqiqaga xavfsiz mashg‘ulot bilan yolg‘iz qoldirib, qahvangizni mutlaq sukunatda iching. Sizning ham quvvatingiz tiklanishi kerak.'),
  ('9ebeb631-4aa4-4310-b78e-47bee6920a4e', 'Cho‘milish injiqligini yengish 🛁', 'Cho‘milishni istamay, yerda yumalab norozilik bildiryaptimi? Kel, seni yuvintiraman deyish o‘rniga, Yur, sevimli mashinalaringni (yoki qo‘g‘irchoqlaringni) cho‘miltiramiz, deng. Majburiyatni o‘yinga aylantirish — bolaning qarshiligini yengishning eng oson yo‘li.'),
  ('5188ae48-9680-4372-a0c2-b6a14d87d513', 'Uydagi poyabzal mojarosi 👟', 'Ko‘cha poyabzalini uyda kiyib yurish va aslo yechmaslik uchun yig‘layaptimi? Buning uchun urushishga arzimaydi. Tagini nam latta bilan arting va bir necha soat xona bo‘ylab faxr bilan yurishiga ruxsat bering. Ba’zi janglarda ataylab yon berish aslida onaning eng katta g‘alabasidir.'),
  ('a80b1c35-a6ce-48dc-a430-2268378d43f5', 'Navbat dadasiga 👨‍🍼', 'Kun bo‘yi yo‘q deyishdan va qoidalar o‘rnatishdan charchadingiz. Bugun kechqurun pijama kiyish va tish yuvish jangini dadasiga topshiring. Xona eshigini yopib, Kayfiyat kundaligiga bugungi his-tuyg‘ularingizni yozing va bu vaqtni butunlay o‘zingizga ajrating.'),
  ('f6d030df-f5ef-4ef7-84fc-04dd7126bef2', 'Hamjamiyatdagi tabassum 💬', 'Bugun uning injiqliklari sizni rostdan ham holdan toydirdimi? Darhol Anacan hamjamiyatini oching va boshqa onalarning uyida yuz bergan shunga o‘xshash, hatto yanada kulgili injiqliklar haqidagi hikoyalarni o‘qing. Bir xil yo‘llardan o‘tayotganingizni va yolg‘iz emasligingizni bilish — eng yaxshi ruhiy ko‘makdir.'),
  ('16b69d4c-feb3-42d5-b458-329c2a13a823', 'Yangi do‘stlar izlash 👫', 'Bog‘da tengdoshlari bilan yugurishga, ularning o‘yinlariga qo‘shilishga harakat qilyaptimi? Ijtimoiylashuv rasman boshlanmoqda! Uni ruhlantiring va bolalar bilan qanday salomlashishni o‘rgating.'),
  ('db813abc-1129-479f-a1e4-e6beaeb2ec95', 'Ona uchun tabiat terapiyasi 🌳', 'Uy devorlari sizni siqib qo‘ydimi? Bolani ham olib, eng yaqin bog‘ga shoshiling. Toza havo nafaqat bolaning, balki sizning ham charchagan asablaringiz uchun eng yaxshi malhamdir.'),
  ('f7c61cc4-7a2d-48d0-bf89-ec947a89cd75', 'Otaning mas’uliyati 👨‍🍼', 'Hamma ishni o‘zingiz qilishingiz shart emas. Bugun kechqurun bolaning tishlarini yuvish va pijamasini kiydirishni butunlay otasiga topshirib, chetdan kuzating.'),
  ('07c7c2cb-58bb-47db-ac0e-f81bd01e602b', 'Ona ovozining qudrati 🎶', 'Bugun kechqurun hech qanday vositadan foydalanmang. Shunchaki uni bag‘ringizga bosing va eng sevimli allasini qulog‘iga pichirlab ayting. Sizning ovozingiz uning eng ishonchli panohidir.'),
  ('1acb826a-9b73-413f-b0af-4614a74084bd', 'Tezkor pediatr yordami 🤖', '3 yoshga yaqinlashayotgan bolaning bo‘y-vazn grafigi sizni tashvishga solyaptimi? Internetda soatlab izlamang, Anacan AI orqali aniq va pediatrlar tasdiqlagan me’yorlarni darhol bilib oling.'),
  ('5bb344ff-e859-413b-93f7-4f25386f0835', 'Ismi va yoshini biladi 🎂', '“Necha yoshdasan?” deb so‘raganingizda, barmoqlari bilan ko‘rsatishga harakat qiladimi? O‘zligini anglash qobiliyati a’lo darajada. Rivojlanish kuzatuvchisida bu intellektual sakrashni qayd eting.'),
  ('2c139fbd-2360-47be-8201-67957bcf1684', 'Ko‘zgu qarshisidagi rejissyor 🎭', 'Ko‘zgu qarshisida turib, turli mimikalar qilayaptimi, o‘zi bilan o‘zi gaplashayaptimi? U turli rollarni sinab ko‘rmoqda. Uni sezdirmay kuzating va bu kulgili lahzalardan zavqlaning.'),
  ('42026a5f-2788-45b9-acb9-1e97ccc1366b', 'Quvvat zaxirasi kerak 🍲', 'Tinimsiz yugur-yugurlar sizni holdan toydirdi. Sog‘lom retseptlar bo‘limidan sizga ham, bolangizga ham yoqadigan, temir va oqsilga boy noodatiy tushlikni tanlang.'),
  ('f413f7f2-f85e-4bd1-a054-6b9d46b4d341', 'Kun tahlili 📝', 'Bolangiz uxlashi bilan turmush o‘rtog‘ingiz bilan Kayfiyat kundaligini oching. Bugun bolangiz qilgan eng kulgili ishni yozib, birgalikda kuling va stressdan xalos bo‘ling.'),
  ('59d23d62-6dca-4962-aec7-eb093810797b', 'Musiqa bilan uyquga o‘tish 🛀', 'Kechki tartib qiyinlashdimi? Iliq vanna qabul qilayotganda fonda tinchlantiruvchi mumtoz musiqani qo‘ying. Suv va musiqa uyg‘unligi hatto eng qaysar bolani ham tinchlantiradi.'),
  ('605d2ada-99ba-4138-bd88-c091a6c53e2b', 'Sizni topdim! 🙈', 'Bekinmachoq endi eng sevimli o‘yinga aylandi. U parda ortiga yashirinib, uni topishingizni kutadi. Obyekt ko‘rinmasa ham mavjud bo‘lishi haqidagi tushuncha bu yoshda o‘yinlar orqali yanada mustahkamlanadi.'),
  ('c0738cb9-5d1f-47d6-821c-55b543c58b28', 'Jazavani boshqarish 🛑', 'Do‘konda yoki bog‘da boshlangan jazava sizni xijolatga soladimi? Unutmang, atrofdagilar nima deb o‘ylashi emas, bolangizning ayni paytdagi hissiyoti muhim. Uni xotirjam quchoqlang.'),
  ('244e81e4-ef8a-4010-a428-229aabe2c4b0', 'Turmush o‘rtog‘ingizdan yordam so‘rang 🛒', 'Xarid qilishga vaqtingiz yo‘qmi? Xaridlar ro‘yxatini oching, uyda yetishmayotgan barcha narsalarni belgilang va bir marta bosish orqali turmush o‘rtog‘ingizga yuboring. Vazifalarni bo‘lib olish muhim.'),
  ('e5509d0f-428a-4a25-9b61-f825746504ad', 'Jimlikda kitob o‘qish 📖', 'Bugun kechqurun xonada faqat kitob varaqlarining shitirlashi eshitilsin. Ikkovingiz ham karavotga yoting: u o‘zining rasmli kitobini tomosha qilsin, siz esa jimlikda dam oling.'),
  ('f568dd40-0374-40d2-8f34-9a863c9b7158', 'Xavfli sakrashlar 🧗‍♂️', 'Divan ustidan polga sakramoqchimi? Demak, u o‘z harakat ko‘nikmalariga juda ishonadi. Taqiqlash o‘rniga, polga yumshoq yostiqlar qo‘yib, xavfsiz sakrash joyini yarating.'),
  ('1222929d-ba35-40ba-92f4-2c3b29988e2e', 'Qoidalarni buzib ko‘rish ⚠️', 'Bunday qilma deganingizga qaramay, ko‘zingizga tik qarab o‘sha ishni qilyaptimi? U sizni jahlingizni chiqarishni emas, chegaralaringiz qanchalik qat’iy ekanini sinab ko‘rishni istaydi. Qoidalaringizda qat’iy turing.'),
  ('60d686a6-8001-479b-9d53-bcd85bcdffdb', 'Uy tartibsiz qolaversin 🌪️', 'Har kuni bir xil o‘yinchoqlarni yig‘ishtirishdan charchadingizmi? Bugun yig‘ishtirmang! Uyning tartibsizligi dunyoning oxiri emas, ammo onaning ruhiy holdan toyishi jiddiy masala.'),
  ('e7bfaacc-c0cc-4b36-8687-477371b3bc3d', 'Bugun aqlli ertakda 🪄', 'Aqlli ertaklar uchun alohida mavzu bering: o‘yinchoqlarini yig‘ishtirishni yaxshi ko‘radigan sehrli ayiqcha. Balki bu hikoya ertangi yig‘ishtirishda sizga yordam berar!'),
  ('895f4348-4fb2-4124-9532-acf7d07409f6', 'Dadaning usullari 👨‍🍼', 'Bolalarning dadasi bilan o‘ziga xos odatlari bo‘ladi. Bugun kechqurun uxlatish jarayonini dadasining kulgili qoidalariga topshiring va xonadan tashqarida osoyishta choyingizni iching.'),
  ('aca7ae85-535e-4175-ab27-d1ca390e78cb', 'Ranglarni kashf etish 🎨', '«Bu qizil, bu ko‘k», deb ranglarni to‘g‘ri guruhlayaptimi? Bu kognitiv rivojlanishdagi katta yutuq! Rivojlanish kuzatuvchisida bu ko‘nikmani faxr bilan belgilang.'),
  ('b6ee83b4-0d5f-4791-8483-ed7d1d3aa649', 'Oshxonada birga 🧑‍🍳', 'Siz bilan birga biror ish qilishni xohlayaptimi? Foydali retseptlardan oson pirogni tanlang va un yoki suv solishda sizga yordam berishiga ruxsat bering. Atrof kir bo‘lsa ham, maroqli vaqt o‘tkazishingiz aniq.'),
  ('2009290a-99c2-4bf0-a2b6-174daa69d49d', 'Tungi detsibellar 🤫', 'Ko‘chadan kelayotgan tovushlar uning chuqur uyquga ketishiga xalaqit beryaptimi? Xonadagi shovqin darajasini tovush o‘lchagich yordamida tahlil qiling.'),
  ('2a0f6e31-8cdc-436b-8432-73cf4dad5b5c', 'Ijodkor ish ustida 🖍️', 'Devorlar va eshiklar ba’zan uning rasm taxtasiga aylanadi. Jahlingiz chiqishi o‘rniga, katta karton topib polga yoying va «Bu seniki», deb ayting. Uning ishtiyoqini to‘g‘ri yo‘naltiring.'),
  ('7750d70c-df5b-48b0-9b2f-522c15391059', 'Savollar yomg‘iri 🤖', 'Farzandingiz 3 yoshga yaqinlashar ekan, uning xulq-atvori haqidagi savollaringiz tugamayaptimi? Anacan AI siz uchun 7/24 uyg‘oq bo‘lgan raqamli pediatr va psixologdir. Yozing va darhol javob oling.'),
  ('2859fc00-366b-44b7-ba24-815b9b659125', 'Tuyg‘ularingizni erkin qo‘yib yuboring 📝', 'O‘zingizni juda yolg‘iz va hech kim tushunmayotgandek his qilyapsizmi? Bu mutlaqo tabiiy tuyg‘u. Kayfiyat kundaligiga his-tuyg‘ularingizni samimiy yozing.'),
  ('4f59cf22-ccfa-43b9-8a30-62365a911312', 'O‘zligini kashf etmoqda 👑', '«Men!», «Meniki!» degan so‘zlar tilidan tushmaydi. Bu egotsentrizm davrining eng yaqqol bosqichidir. Uning bu o‘ziga xosligini hurmat bilan qabul qiling — bu rivojlanish bosqichidir.'),
  ('eddd6a67-3ce9-4446-ba23-dba7c167dca2', 'Havo o‘zgaruvchan ⛅', 'Sayrga chiqmoqchisiz-u, lekin tashqaridagi havo aldamchimi? Ob-havo va kiyim vositasiga kirib, uni terlatmaydigan, ayni paytda himoya qiladigan eng mos kiyimlar to‘plamini tanlang.'),
  ('009a8d5c-9bba-4789-a6ee-e59d4c647832', 'Jamoaviy faxr 🥂', 'Og‘ir bir haftani ortda qoldirdingiz. Turmush o‘rtog‘ingiz bilan yuzma-yuz o‘tirib, «Biz bu bolani chindan ham yaxshi tarbiyalayapmiz», deya bir-biringizga dalda bering.'),
  ('d0adf273-d83c-415a-88b8-6fa5f74c5f51', 'Gaplar tuzib ertak aytmoqda 🗣️', 'Rasmli kitobni tomosha qilib, o‘zicha gaplar tuzgan holda ertak to‘qiyaptimi? Tasavvuri va nutqi bir paytning o‘zida jadal rivojlanmoqda! Uni diqqat bilan tinglab, olqishlang.'),
  ('ff22b088-7f8b-4366-a32b-7bd8cd1aa92f', 'Onalar birdamligi 💬', 'Potty training (tuvakka o‘rgatish) sizni tushkunlikka tushirdimi? Darhol Anacan hamjamiyatiga kiring. U yerdagi boshqa onalarning muvaffaqiyat va muvaffaqiyatsizlik haqidagi hikoyalari sizga kuch beradi.'),
  ('1c47434b-8f04-4342-a73a-e77c7a63eb48', 'Qorong‘ilikdan qo‘rqmasin 🌙', 'Xonasining qorong‘iligidan qo‘rqadimi? Karavoti yoniga kichik tungi chiroq qo‘ying, ammo xona melatonin ajralishi uchun yetarlicha qorong‘i ekaniga ishonch hosil qiling.'),
  ('77a1ab3f-8086-4334-93ed-03dab08fb152', 'Kiyimlarini o‘zi tanlamoqchi 👗', 'Shkafni ochib, bir-biriga mos kelmaydigan ranglar va turli fasllarga mo‘ljallangan kiyimlarni birga kiyishni xohlayaptimi? Mustaqilligini qo‘llab-quvvatlang, ammo vaziyatni nazoratda saqlash uchun unga atigi 2 ta variant taklif qiling.'),
  ('b22d0c31-c528-4596-b176-4f64d3f5be5d', 'Qahva quvvati ☕', 'Endi kunduzi uxlamaydimi va siz kun bo‘yi bir zum ham dam ololmayapsizmi? Uni 15 daqiqaga xavfsiz mashg‘ulot bilan band qilib, o‘zingiz ham bir piyola qahva bilan quvvatlanib oling.'),
  ('9787e3a9-8592-4bb2-8463-c4e695682c99', 'Og‘ir yuk, o‘jar yurak 🛒', 'Sayrdan qaytayotganda eng og‘ir buyum yoki xaltani albatta o‘zi ko‘tarishni xohlayaptimi? Uni joyidan siljita olmasa ham, yordamingizni qat’iyan rad etadi. Mayli, biroz urinib ko‘rsin, kuchini sinasin.'),
  ('bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001', 'Kichkina faylasuf 🤔', 'Ko‘zlari endigina yumilayotganda birdan boshini ko‘tarib: «Onajon, quyosh uxlash uchun qayerga ketadi?» kabi falsafiy savol berdimi? Uning miyasi hatto uyquga ketish paytida ham dunyoni anglashda davom etadi. Juda chuqurlashmasdan, qisqa va ertaknamo javob bering.'),
  ('c2525bad-5158-49a7-81ce-247259a08d2e', 'Mo‘jizaviy talablar 🪄', 'Bugun ertalab uyg‘onishi bilan baqirib, tilimlangan olmani yana butun qilib berishingizni talab qildimi? Ha, 3 yoshga yaqinlashganda ularning mantig‘i fizika qonunlariga qarshi chiqadi.'),
  ('1e3f3fa1-dbbc-4651-aa40-6590038f46b0', 'Hayvonlarga taqlid 🐶', 'U nafaqat hayvonlarning ovozini chiqaradi, balki it kabi emaklab, mushuk kabi suykalanadimi? Tana harakatlari va tasavvur birlashmoqda. Siz ham u bilan gilam ustida bu o‘yinga qo‘shiling.'),
  ('4ac97d09-8bce-44ef-922e-5286afc49815', 'Ovqat tanlash 2.0 🥣', 'Kecha yaxshi ko‘rgan sho‘rvasini bugun yemayaptimi? Majburlamang. Sog‘lom retseptlar bo‘limidan sabzavotlarni sezdirmay qo‘shishingiz mumkin bo‘lgan muqobil va noodatiy retseptlarni toping.'),
  ('d8f03ef9-1ea4-48a4-a43d-dc4f633f2d60', 'Sehrli uyqu ertagi 🪄', 'Aqlli ertaklarda uch yoshga to‘layotgan jasur qahramon haqida hikoya yarating va unga ulg‘ayib, kuchli bo‘lib borayotganini his qildiring.'),
  ('2a9575e0-ee4f-4f27-86a9-25def022748e', 'Sizni izlayapman! 👀', 'Xonadan chiqishingiz bilan yana yig‘lay boshlaydimi? Ayriliq xavotiri ba’zan qaytishi mumkin. Ovozingiz bilan unga uzoqdan dalda bering, ammo har doim ko‘z o‘ngida bo‘lishingiz shart emas.'),
  ('89de8241-ec59-4180-ba30-e03291e0f208', 'Ertakning oxirini u aytsin 📖', 'Bugun kechqurun ertak o‘qiyotganda gaplarni tugatmay qoldiring, davomini u aytsin! Tasavvurning ajoyib rivojlanishini qo‘llab-quvvatlaydigan muloqot usullarini Anacan AI’dan so‘rang.'),
  ('ca321f21-1031-4b14-96c8-69fa4c4201da', 'Ro‘yxat bo‘lishi shart 🛒', 'Tug‘ilgan kun uchun kerakli buyumlar esdan chiqmasin! Miyangizni ortiqcha band qilmang, hammasini darhol Xaridlar ro‘yxatiga yozing va turmush o‘rtog‘ingiz bilan sinxronlashtiring.'),
  ('565fda98-0d2c-40b4-8230-13c64e585700', 'Paypoq choki fojiasi 🧦', 'Bugun ertalab katta bir inqiroz bilan uyg‘ondik: paypoq ichidagi chok uning barmog‘iga tegmoqda! 3 yoshga yaqinlashganda hissiy ta’sirchanlik eng yuqori darajaga chiqadi. Mantiq izlamang, paypoqni teskarisiga kiydiring va bu bema’ni inqiroz 10 soniyada qanday tugashini kuzating.'),
  ('acd26d8c-d24f-4082-9973-a1110aefb638', 'Ko‘lmak ovchisi 🌧️', 'Yomg‘irdan keyin tashqariga chiqdingiz-u, u to‘g‘ri loyqa ko‘lmakka sakradimi? Ust-boshi kir bo‘ldi, ammo ko‘zlaridagi o‘sha kashfiyot zavqiga qarang. Ob-havoni hisobga olib, unga oldindan rezina etik kiydirishni rejalashtiring, bolaligini maza qilib yashasin.'),
  ('b17158eb-f894-42c6-8d84-cab6d30d297a', 'O‘yinchoqlarga xayrli tun 🧸', 'Uxlash vaqti bo‘ldi, ammo u xonadagi har bir mashinacha va ayiqcha bilan bittalab xayrlashmoqda. Bu uyquni kechiktirish san’atining chinakam durdonasi. Taymerni o‘rnating va 3 daqiqadan keyin hammasi bilan bir vaqtning o‘zida xayrlashamiz degan qoidani qo‘llang.'),
  ('3b1d044a-5917-48bd-b4f3-847b5ba6d5db', 'Eng g‘alati buyum 🥄', 'Shuncha qimmat o‘yinchog‘i bor, ammo u oshxonadan bir cho‘mich topib olib, butun oqshom uni ko‘tarib yuradi, hatto uxlatadi. Bola miyasining bunday qiziqishlarini tushuntirib bo‘lmaydi. To‘sqinlik qilmang, o‘sha cho‘michni yaxshi ko‘rishiga imkon bering.'),
  ('498b3498-4fee-4a00-9b62-ebe43844ae53', 'Sho‘rva ichidagi jarroh 🥣', 'Ovqatni yemaydi, shunchaki ichidagi mayda piyoz yoki guruch donalarini jarrohdek aniqlik bilan chetga ajratadi. Sabzavotlarni pyure qilib, ko‘rinmas qilish vaqti keldi. Sog‘lom retseptlar orasida onalarning eng ijodkorona, sabzavotlar yashirilgan retseptlarini ko‘rib chiqing.'),
  ('a13e9959-a476-4e99-9da8-13f5bff68864', 'Shkafni o‘zim ochaman! 🚪', 'Ertalab shkaf eshigini siz ochganingiz uchun yig‘lab, uni qayta yopdirib, keyin o‘zi ochdimi? Ha, hammasi uning nazoratida bo‘lishi kerak. Bu beg‘ubor «o‘zim qilaman» urinishlariga tabassum bilan qarang, u o‘z irodasini sinab ko‘rmoqda.'),
  ('3b9f5253-06a7-4aef-bfdf-bb0daf30818e', 'Chiroqlar sehri 🌙', 'Qorong‘ilikdan qo‘rqa boshladimi? Xonani butunlay qorong‘i qiling va kichkina fonar bilan shiftda yorug‘lik o‘yinlarini o‘ynang. U qo‘rqadigan qorong‘ilikni qiziqarli mashg‘ulotga, uyqu oldidan esa kichik bir kashfiyotga aylantiring.'),
  ('5d1a2a49-e134-453a-a974-f4cff4de0952', 'Pijamaga muhabbat 👗', 'Ertalab uyg‘onib, ustidagi dog‘ tushgan pijamasini yechishdan qat’iyan bosh tortyaptimi? Agar uydan chiqmasangiz, bu kurashni to‘xtating. Ba’zan onaning ruhiy xotirjamligi bolaning ozoda ko‘rinishidan ancha muhimroq.'),
  ('c8ffca51-c2fa-4f5a-8090-6c144b596f9c', 'Cho‘ntakdan chiqqan xazinalar 🍁', 'Parkdan qaytdingiz, cho‘ntagidan 3 ta tosh, 1 ta qurigan barg va bir dona cho‘p chiqdi. Siz uchun chiqindi, u uchun esa xazina. Ular uyga sochilib ketmasligi uchun maxsus quti tayyorlab, topilmalarini o‘sha yerga yig‘ishiga ruxsat bering.'),
  ('176265d3-ef2f-4ec4-923c-4308870e611f', 'Hissiy yukdan xalos bo‘lish 📝', 'Uyda hech kim qanchalik charchaganingizni sezmayaptimi? Kayfiyat kundaligi — eng sokin sirdoshingiz. Bugun sizni asabiylashtirgan barcha mayda-chuydalarni unga yozing va miyangiz qanday yengillashganini his qiling.'),
  ('94fce04c-73e9-47bd-8d9d-3bd3da19122a', 'O‘zim yuraman! 🚶‍♂️', 'Ko‘chada qo‘lingizdan ushlashdan qat’iyan bosh tortib, erkinlik talab qilyaptimi? Xavfsiz joylarda unga shunday erkinlik bering. Uni ko‘zdan qochirmang, dunyoni o‘z qadamlari bilan kashf etsin.'),
  ('b24a452c-9588-4b0c-923f-9c455be6d1e2', 'Oshxonaning kichik oshpazi 🧑‍🍳', 'Siz xamir yoyayotganingizda, yoningizga stul qo‘yib, albatta jarayonga aralashadimi? Qo‘liga kichkina xamir bo‘lagini bering. Hamma joy un bo‘ladi, ammo uning jiddiy va ishchan qiyofasi keyingi tozalashga arziydi.'),
  ('0a4a5638-968e-4cce-9213-12c0072354c4', 'Sukunatning raqamli o‘lchovi 🤫', 'U nihoyat uxlab qoldi! Uyga cho‘kkan sukunatga ishongingiz kelmaydi. Ovoz o‘lchagichni ishga tushiring va ekrandagi 0-10 detsibel ko‘rsatkichiga qarab, miyangiz asta-sekin dam olayotganini va quvvatga to‘layotganini his qiling.'),
  ('b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a', 'Sen yomon onasan! zarbasi 💔', 'U xohlagan konfetni bermaganingiz uchun sizga sen yomonsan dedimi? Ko‘nglingizni og‘ritmang. U hali his-tuyg‘ularini to‘g‘ri so‘zlar bilan ifodalay olmaydi, aslida esa men juda jahlim chiqyapti demoqchi. Ko‘z bilan aloqa o‘rnating va uning his-tuyg‘usini qabul qiling.'),
  ('fabd170d-dc89-4100-b9c1-3acf59e32a5c', 'Ko‘rinmas chumoli bilan suhbat 🐜', 'Ayvonda yoki bog‘da yerdagi chumoliga egilib, unga jiddiy ohangda nimalarnidir gapiryaptimi? Ayni paytda uning tasavvuri ham, mehr-shafqat tuyg‘usi ham ishlayapti. Bu ajoyib lahzani darhol Chaqaloq fotosessiyasi yordamida suratga olib, arxivingizning eng yoqimli burchagiga joylang.'),
  ('a860534c-7167-4781-b298-8321127fd089', 'Dadaning parvoz rejimi ✈️', 'U uyda energiyasini sarflay olmay, yotishga qarshilik qilyapti. Dadani yordamga chaqiring. Dadasi bolani havoga ko‘tarib, samolyot qilib o‘ynatganida, xona qahqahaga to‘ladi va yig‘ilib qolgan barcha jismoniy zo‘riqish soniyalar ichida yo‘qoladi.'),
  ('e0e56f8d-3c51-4c46-90f2-dbfa90060519', 'Yerda dumalash erkinligi 🌪️', 'Do‘konning o‘rtasida o‘zini yerga tashladimi? Uni ko‘tarishga yoki atrofdagilarga izoh berishga urinmang. Chuqur nafas oling. Anacan hamjamiyatiga kirganingizda, minglab onalar ham xuddi shunday noqulay, ammo tabiiy vaziyatni boshdan kechirayotganini ko‘rasiz.'),
  ('e9ba4911-0212-43aa-9a51-c6bf942facb9', 'Menga qarama! qaysarligi 🙈', 'Siz unga qarab jilmayganingiz uchun Menga qarama! deb yig‘layaptimi? Bema’ni mantiqning cho‘qqisi! Yuzingizni chetga burib, bu kulgili injiqlik o‘tib ketishini kuting, ba’zan bolalarning o‘zi ham nima istayotganini bilmaydi.'),
  ('33979ce6-ea09-4adc-ab85-0cf386a73156', 'Qutining sehrli jozibasi 📦', 'Unga shuncha qimmat, ovozli o‘yinchoq sotib oldingiz, ammo u o‘yinchoqning qutisi bilan bir soatdan beri o‘ynayapti. Bola miyasi tayyor tuzilmalarni emas, tasavvur qilish imkonini beradigan oddiy buyumlarni yoqtiradi. Kuzating va o‘rganing.'),
  ('5b89452a-e411-4130-87b7-6e1e33b0701e', 'Tabiiy oq shovqinlar 🤫', 'Uyquga ketayotgan paytda sezgirlik ortadi. Ko‘chadan kelayotgan tovushlarni neytrallashtirish uchun xonada Ovoz o‘lchagichning fon shovqinini yoqing va xonada osoyishta muhit yarating.'),
  ('a09d0a7b-0632-4bcf-8833-28f5ef0f9d93', 'Yolg‘ondakam yig‘i 🎭', 'Istagan narsasiga erishish uchun ko‘z yosh to‘kmasdan, ovozini titratib, yolg‘ondakam yig‘layaptimi? U sizni manipulyatsiya qilishni o‘rganyapti. Kulib yubormaslikka harakat qiling, ammo yon bermang. Chegaralaringiz aniq bo‘lsin.'),
  ('20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce', 'Kutilmagan «Sizni sevaman» 💖', 'Xonaning o‘rtasida o‘ynab turib, kutilmaganda sizga qaradi-da: «Sizni judayam sevaman», dedimi? Barcha uyqusiz tunlar va charchoqlarga arziydi! Bu lahza olib kelgan chuqur va betakror huzurdan zavqlaning.'),
  ('22b5d836-6305-422c-8cf7-c30a523392f2', 'Dadaning sho‘x raqsi 🕺', 'Kechga yaqin boshlanadigan injiqlikni faqat dada bartaraf eta oladi. Musiqani baland qo‘yib, bola bilan xonada sakrab raqsga tushsin. Siz esa bu quvnoq energiyani chetdan faxr bilan kuzating.'),
  ('909bc50f-85b7-40ab-a524-0abbcb0fac9f', 'Faqat o‘zingiz uchun 10 daqiqa ☕', 'U multfilmga berilib turganida idish yuvish mashinasini bo‘shatishga shoshilmang! Divanga cho‘ziling. Nihoyat qahvangizni issiqligicha iching va 10 daqiqaga onalik rolidan chiqib, shunchaki o‘zingiz bo‘ling.'),
  ('15f19421-c415-4b7b-ad4d-54211e4ccb3a', 'Suv, hamma joyda suv! 💧', 'Suvni stakanga albatta o‘zi quymoqchi bo‘ldi. To‘kib yubordi, hamma joy ho‘l bo‘ldi. Ammo uning latta olib, o‘sha mitti qo‘llari bilan joyni tozalashga urinayotganiga qarang. U xato qilish orqali mas’uliyatni o‘rganmoqda, jahlingiz chiqmasin.'),
  ('6d2f1d1e-d7d7-41c3-b906-1e286aab1a51', 'Dadasining navbati 👨‍👧', 'Onalik tugamaydigan marafon emas. Bugun parkdagi yugur-yugurlarni dadasi o‘z zimmasiga olsin, siz esa divanda yolg‘iz qolishning huzurini his qiling.'),
  ('cf9e0ee2-2f17-4a55-933b-735bc0754d7e', 'Jamoaviy massaj 💆‍♂️', 'Bola uxlagach, kun davomida to‘plangan stressdan xalos bo‘lish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Siz shunchaki ota-ona emassiz, bu xonadonning ham, bir-biringizning ham eng katta tayanchisiz.'),
  ('2caa3c21-d2d3-4566-921a-e08cdbce1397', 'Men charchadim... 🔋', 'Hamma sizdan kuch-g‘ayrat kutadi, ammo quvvatingiz tugagan. Bugun hech narsa pishirmang: tashqaridan buyurtma bering yoki eng oddiy makaronni qaynatib oling. Super Qahramon bo‘lish hamma ishni yolg‘iz bajarishingiz shart degani emas.'),
  ('48299b62-1108-44e9-af43-b48460ffdfa2', 'Vannadagi osoyishtalik 🛀', 'Butun kun “xohlamayman” degan gaplar bilan o‘tdi. Iliq vanna shunchaki gigiyena uchun emas, balki uning taranglashgan asab tizimini tinchlantirish uchun ham kerak. Suvning ovozini tinglang, xonadagi muhit bir zumda o‘zgaradi.'),
  ('ab5bd705-a57d-40d7-b0a0-86107e824b4d', 'Zinadan mustaqil chiqish 🧗', 'Zinadan yordamsiz chiqishga urinayaptimi? Harakat ko‘nikmalari ayni cho‘qqisida! Chetdan kuzating, aralashmang. Ushbu mustaqil onni chaqaloq fotosessiyasi bilan abadiylashtiring.'),
  ('09711673-d0fa-42b5-be98-012bd4b1ed8b', 'Ekransiz tanaffus qiyinligi 📺', 'Bugun ishlaringiz tufayli unga ko‘proq multfilm qo‘yib berdingiz va endi vijdoningiz qiynalyaptimi? O‘zingizni ayblamang. Har kuni mukammal ona bo‘la olmaysiz. Ba’zan raqamli enaga sizni ruhiy tushkunlikdan asraydi.'),
  ('8649e4ca-170c-4117-8af8-b0d7e819e84f', 'Jonli diktofon 🎙️', 'Kecha turmush o‘rtog‘ingiz bilan gaplashayotganda tasodifan ishlatgan so‘zingizni bugun ertalab u o‘yinchog‘iga aytyapti! Uning so‘z boyligi hayratlanarli tezlikda kengaymoqda va u sizga to‘liq taqlid qilmoqda. Unga o‘rnak ekaningizni unutmang.'),
  ('c0faa467-b596-4471-bbba-6d91e0e37db1', 'Shivirlash usuli 🤫', 'U yotoqda shunchalik faolki, uxlamayapti. Ovozingizni ko‘tarish o‘rniga, birdan ohangingizni pasaytirib, shivirlab gapiring. Bola sizni eshitish uchun diqqatini jamlaganida, uning miyasi avtomatik ravishda uyqu rejimiga o‘tadi.'),
  ('48263ed0-f236-440c-a83e-807da51bd86f', 'Kislorodga ehtiyoj ⛅', 'To‘rt devor ichida qolish miyangizni karaxt qilib, uyda injiqlik xurujlarini ko‘paytirdi. Ob-havoni hisobga olib, eng mos kiyimlarni tanlang. Tashqariga chiqib, shunchaki yugurish uning ortiqcha energiyasini chiqaradi, sizga esa yangi nafas bag‘ishlaydi.'),
  ('8fed0a18-52ae-4688-8137-532b6b55726c', 'Ertak boshqaruvi uning qo‘lida 🪄', 'Klassik kitoblardan ikkalangiz ham zerikdingiz. Aqlli ertaklarni yoqing: bosh qahramon sifatida bolangizni, qutqarilishi kerak bo‘lgan joy sifatida esa uning xonasini tanlab, noodatiy, shovqinsiz va erkin uyqu mashg‘ulotini yarating.'),
  ('c7c388a1-a255-4a7c-a615-22236406e4e2', 'Avangard ijodkorlik 🖍️', 'Bir necha soniyalik jimlik xavfli tus oldi. Xonaga kirib, u qo‘llari yoki qorniga flomaster bilan tatuirovka chizganini ko‘rdingiz. Chuqur nafas oling. Uning mayda motorikasi rivojlanmoqda, terisidagi izlar esa baribir yuvilib ketadi.'),
  ('028ed2b5-737d-4edf-81c1-5a9151e5fbf0', 'Do‘kondagi shokoladli syurpriz 🛒', 'Do‘konga borishdan oldin Xaridlar ro‘yxatini ochdingiz va u orqangizdan kelib, telefon ekranini bosib, ro‘yxatga allanimalarni yozib qo‘yganini ko‘rdingiz. Ha, u sizning raqamli hayotingizga ham taqlid qilmoqda!'),
  ('098cd94b-6989-48a8-9fdc-160a2f819cb0', 'To‘qima grammatikaning zavqi 🗣️', '«Men bordimdim», «U kelarmishdi» kabi g‘alati, ammo juda yoqimli zamon shakllarini kashf etdi. Uning lug‘at boyligi bo‘rondek tez rivojlanmoqda! Rivojlanish kuzatuvchisiga uning o‘ziga xos tilini esdalik sifatida yozib qo‘ying.'),
  ('50dce5d9-294a-44b8-b1c9-316b84d5df14', 'Karavot tagida nima bor? 👻', 'U qorong‘ida maxluqlar borligiga ishonadimi? Ichiga oddiy suv solingan purkagichli idishni oling va uni «Qo‘rquvni haydovchi sprey» deb xonaga seping. Tasavvurni tasavvur bilan yenging.'),
  ('2cd29d0d-0cf1-403e-806d-35f84215b2df', 'Ertalab soat 5 da bazm boshlandi! ⏰', 'Quyosh hali chiqmagan, ammo u karavotda sakrab, kunni boshlab yubordi. Siz hali uyqusirayotgan bo‘lsangiz ham, u dunyoni zabt etishga tayyor. Unga qo‘shiling va bu jo‘shqin energiya sizni ham uyg‘otishiga imkon bering.'),
  ('48550c10-c030-428e-9c25-ccd73ca09c55', 'Bog‘cha izlayapsizmi? 🏫', '3 yoshga yaqinlashar ekan, bog‘cha haqidagi fikr xayolingizdan ketmayapti, ammo qaror qila olmayapsizmi? Yolg‘iz o‘ylashdan charchagan bo‘lsangiz, Anacan hamjamiyatiga qo‘shilib, boshqa onalarning bog‘cha haqidagi haqiqiy tajribalarini o‘qing.'),
  ('df1cf1ea-2772-44a6-8cb7-33857989fedf', 'His-tuyg‘ular kundaligi 📝', 'Kimdir sizga «Uyda o‘tirasiz-ku, nimadan charchaysiz?» dedimi? Darhol Kayfiyat kundaligini oching va bor jahlingizni barmoqlaringiz orqali ekranga to‘king. Soxta tabassum qilishdan ko‘ra, haqiqiy his-tuyg‘ularingizni yozish — terapiyadir.'),
  ('3deb7e49-2093-4c39-a51d-8dd6fd44d138', 'Sabzavotlarga qarshilik davom etmoqda 🥦', 'Sho‘rvadagi o‘sha kichkina sabzi bo‘lagini yana ko‘rib, ovqatlanishdan bosh tortdimi? Ovqatlanish rejasi yordamida sabzavotlarni pyure qilib, kotlet ichiga yashirish — onalarning eng qadimiy va foydali hiylalaridan biri. Sinab ko‘ring!'),
  ('9dd6923c-7dc5-4341-8507-b21e0f3c9ee4', 'Kichkina shifokor sizni tekshirmoqda 🩺', 'O‘yinchoq stetoskopini olib, ko‘ksingizga qo‘yadi va nafas olishingizni aytadi. Siz bemorsiz, u esa bosh shifokor. Bu o‘yinga qo‘shiling, yotib oling va davolanish paytida hech bo‘lmasa 5 daqiqaga ko‘zingizni yumib, dam oling.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('ebf71c8a-d8a3-4875-8021-e3145bf8ae06'::uuid, 'Tovushlar cheklovi 🌙', 'U nihoyat uxlab qoldi. Endi uydagi eng past tovush ham sizni bezovta qiladi. Chiroqlarni xiralashtiring, televizorni o‘chiring va qorong‘ilik bag‘ridagi o‘sha noyob sukunatning huzurini suring.'),
  ('19419b9a-b627-43ae-9610-e43b875264b1', 'Maqsadli emaklash va yugurish 🐢', 'Endi u shunchaki yurish bilan kifoyalanmaydi: tez yugurib, sizdan yashirinadi va eshiklar ortidan mo‘ralaydi. Xonadagi to‘siqlarni olib tashlang va siz ham bolalarga xos jo‘shqinlik bilan bu quvlashmachoq o‘yiniga qo‘shiling.'),
  ('20d0afb1-a487-43f5-b6f3-0f8cd2bca864', 'Chiroqlarni o‘chiring, uyqu kelsin 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlar va ko‘k nurli ekranlarni o‘chiring. Uyqu gormoni (melatonin) faqat qorong‘i va texnologiyalarsiz muhitda tez ajraladi.'),
  ('c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33', 'Sun’iy intellekt, aniq javob 🤖', 'Farzandingizda g‘alati bir odat paydo bo‘ldimi (masalan, tirnoq tishlash) va internetdagi forumlar sizni qo‘rqitib yubordimi? Shoshilmang. Anacan AI’dan buning pediatrlar tasdiqlagan asl sababini so‘rang va ko‘nglingizni tinchlantiring.'),
  ('1bbd92c6-a12a-4c26-a63f-0946e226b656', 'O‘zingizni unutish mumkin emas! 🥗', 'Uni to‘ydirish uchun 3 xil menyu o‘ylab topdingiz-u, o‘zingiz yana och qoldingizmi? Sog‘lom retseptlar orasidan 10 daqiqada tayyorlanadigan, temir va kalsiyga boy tushlikni tanlab, o‘zingizni qadrlang.'),
  ('31e8c246-42c7-4bad-8ff1-c08af53874b1', 'To‘satdan jahl chiqishi 💥', 'O‘ynab turganida birdan jahli chiqib, o‘yinchoqlarini uloqtirdimi? U hali his-tuyg‘ularini boshqara olmaydi. Baqirish o‘rniga, Jahling chiqqanini ko‘ryapman, kel, birga chuqur nafas olamiz, deb unga hamdardlik bildiring.'),
  ('96327d67-c216-46e6-b768-6cd8fce23852', 'Juftlik shampani 🥂', 'Bola uxladi. Shampan bo‘lmasa ham, piyolalarga issiq choy quying va turmush o‘rtog‘ingiz bilan Bu og‘ir kunni ham sog‘-omon yakunladik, deb piyolalarni urishtiring. Sizlar bu uyning eng kuchli sarkardalarisiz.'),
  ('3b764723-4ccb-4ab8-a1ed-3b072c5f8a25', '3 yoshga to‘lishiga atigi 5 kun! 🚀', 'Ishonish qiyin! Mana shu katta 3 yoshga to‘lishiga bor-yo‘g‘i 5 kun qoldi. Uyda o‘z qoidalarini o‘rnatadigan bu mitti shaxsni siz ulg‘aytirdingiz. Anacan orqali tortga hoziroq buyurtma bering va tayyorgarlikni boshlang.'),
  ('b8850dac-f142-4e24-bc24-56bb7962ebf6', 'Dadaning parvoz rejimi ✈️', 'U uyda kuchini sarflay olmay, uxlashga qarshilik qilyapti. Dadasini yordamga chaqiring. Dadasi uni havoga ko‘tarib, samolyot qilib o‘ynatganida, xona qahqahaga to‘ladi va jismoniy zo‘riqish bir necha soniyada yo‘qoladi.'),
  ('ee7e813c-5a12-4710-b655-7b294f1ff478', 'Onaning tanaffusi ☕', 'Bola tilida gapirishdan charchadingizmi? Onalar uchun qulay joylar orasidan bolalar burchagi bor kafeni toping, qahvangizni iching va boshqa onalar bilan dardlashib, biroz nafas rostlang.'),
  ('20794d75-b46f-481d-baa5-2b85b8516d4e', 'Parkdagi erkinlik 🌳', 'To‘rt devor orasida qolish uni tajovuzkor qilib qo‘yadi. Uni parkka olib chiqing, qumga belansin, yugurib yiqilsin, toshlar yig‘sin. Tabiatdagi bu erkinlik uning miyasi rivojiga eng yaxshi ta’sir qiladigan vositadir.'),
  ('3d4fe78e-9d18-4fa4-b11f-ee7836615ee7', 'Melatonin fabrikasi 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin faqat tinch, xira yoritilgan va ekranlarsiz muhitda tez ajraladi.'),
  ('5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11', 'Xayoliy mehmonlar keldi ☕', 'Xonada yolg‘iz o‘zi ko‘rinmas do‘stlari bilan gaplashib, ularga choy quyayaptimi? Bu tasavvur rivojining eng yuqori cho‘qqisi! Bu ajoyib ssenariynavisni chetdan faxr bilan kuzating — u allaqachon o‘z olamini yaratmoqda.'),
  ('19c93357-3662-4a7d-bd13-a71d938dc00a', 'Sizga tushuntirib beraman! ☝️', 'U siz biladigan narsani kelib, juda jiddiy va dono qiyofada sizga tushuntiradi. Shu tariqa u o‘z bilimini sinab ko‘radi. Kulmaslik uchun o‘zingizni zo‘rg‘a tiyib tursangiz ham, uni juda jiddiy tinglang.'),
  ('6ab81ee1-daa9-4300-97cb-c7dad69d9baf', 'Kayfiyat kundaligidagi e’tirof 📝', 'Telefoningizni qo‘lingizga oling. Ijtimoiy tarmoqlarda boshqalarning hayotini tomosha qilish o‘rniga, Kayfiyat kundaligini oching va bugun uning qilgan eng kulgili ishini kelajak uchun yozib qo‘ying. Raqamli terapiya yordam beradi.'),
  ('ee467fcc-7c51-4e6a-ba68-1e6466be7d10', 'Kunduzgi uyquga qarshi isyon 🥱', 'Yotishni mutlaqo istamayaptimi? 3 yoshga yaqinlashganda bunday qarshilik juda odatiy hol. Majburlamang, yig‘latmang. Xonadagi yorug‘likni pasaytirib, «Jim kitob varaqlash vaqti»ni e’lon qiling va odatiy tartibni o‘zgartiring.'),
  ('3a35865f-054d-413c-b3ad-81c68c171c47', 'Ayriliq xavotiri yana qaytdimi? 🥺', 'Xonadan bir necha soniyaga chiqib ketsangiz ham, ortingizdan yig‘laydi. Ayriliq xavotiri 3 yosh arafasida ba’zan yana qaytishi mumkin. Har safar unga ovoz berib, shu yerda ekaningizni ayting: «Oshxonadaman, hozir boraman». Shu tariqa uzoqdan bo‘lsa ham unga xotirjamlik bering.'),
  ('96b4e611-59a4-4d8b-a157-87f9d477e265', 'Sukunat tasdig‘i 🤫', 'Shovqinli kundan keyin bola uxlagach, Ovoz o‘lchagich yordamida xonadagi sukunatni o‘lchang. Nolga yaqinlashayotgan raqamlarni ko‘rishning o‘zi ham ona miyasi uchun eng yaxshi vizual massajdek ta’sir qiladi.'),
  ('c1d1539d-38e2-40da-9e66-eb22e0cbbd09', 'Mukammallik bosimi 🛑', 'Boshqa bolalar allaqachon ranglarni sanayapti, sizning bolangiz esa buni istamayaptimi? Taqqoslashni darhol to‘xtating! Har bir bolaning rivojlanish sur’ati turlicha. Farzandingiz o‘z sur’atida rivojlanmoqda va bu mutlaqo normal.'),
  ('08d5ac7d-b540-46e7-9f43-7f771edfd887', 'Bayramga tayyorgarlik 💆‍♂️', 'Bola uxlagach, kun davomida yig‘ilgan stressni chiqarish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Ertangi 3 yosh bayrami va yugur-yugurlar uchun ikkalangiz ham, albatta, tetik bo‘lishingiz kerak!'),
  ('2d61ffa4-9df3-4b29-acca-6b87ebc82745', 'Onalarni qo‘llab-quvvatlash guruhi 💬', 'Kun og‘ir o‘tyaptimi va hamma narsa ko‘zingizga kattalashib ko‘rinyaptimi? Anacan hamjamiyatidagi tajribali onalarning maslahatlari hech bir kitobda yozilmagan, hayotiy va eng amaliy yechimlardir. Ulardan ilhom oling.'),
  ('dd4c2432-4936-49e7-844c-aec9116027b4', '3 yosh arafasi! 🎂', 'Ertaga juda katta kun! Qorningizda ilk bor tepgan kundan buyon qanchalik uzoq yo‘lni bosib o‘tdingiz. Bugun unga uzoq-uzoq termiling, kiyimlarini tanlang va ertangi chaqaloq fotosessiyasi uchun telefon xotirasini bo‘shatib qo‘ying.'),
  ('36c78cd2-37d5-4665-84a1-551e9c9c2557', 'Juftingiz bilan nishonlang 🥂', '3 yillik charchoq, ko‘z yoshlar va quvonchni bugun kechqurun juftingiz bilan birga nishonlang. Dasturxonga sham qo‘yib, mustahkam jamoangiz g‘alabasini katta quvonch va tabassum bilan olqishlang!'),
  ('6148534d-dac4-4ca6-9b42-87f0242f8cdb', 'Ajoyib 3 yosh! 👑🎉', 'Tabriklaymiz! U allaqachon 3 yoshda! Mana, roppa-rosa 1095 kundirki, siz ushbu jo‘shqin, mashaqqatli, ammo dunyodagi eng zavqli yo‘ldan boryapsiz! Bu alohida kunni hoziroq bayramga aylantiring va quvonchingizni barcha bilan baham ko‘ring!'),
  ('94dba968-6bd5-4b01-b8ef-b33b80729320', 'Siz mukammalsiz! 📈', 'Farzandingiz qanchalik katta yo‘lni bosib o‘tdi! Ilk kunlardagi o‘sha nozik xavotir endi ulkan ishonch va bilimga aylandi. Siz bu 3 yilni katta faxr bilan bosib o‘tdingiz! Siz haqiqatan ham ajoyib onasiz!'),
  ('278a6dcf-b4d5-435f-bebd-984362b1ec54', 'Bayramdan keyingi haqiqat 🚀', 'Kechagi katta yubileydan so‘ng bugun ertalab yana sochilib yotgan o‘yinchoqlar va “Men kiyinishni xohlamayman!” degan gaplar bilan uyg‘ondik. Hayot o‘z maromiga qaytdi. Chuqur nafas oling, siz bu tartibsizlikning eng mohir boshqaruvchisisiz.'),
  ('5242afc1-567f-496d-81cf-522c0271690e', 'Ertak boshqaruvi uning qo‘lida 🪄', 'Klassik kitoblardan ikkalangiz ham zerikdingiz. Aqlli ertaklarni oching, bosh qahramon sifatida farzandingizni, qutqariladigan joy sifatida esa uning xonasini tanlab, noodatiy, shovqinsiz va erkin uyqu marosimini yarating.'),
  ('d5e65c0a-6f82-4fee-945e-ee1f72e84c4a', '“Men o‘zim” qarshiligi 🛑', 'U oyoq kiyimining bog‘ichini o‘zi bog‘lamoqchi bo‘lib, bunga 10 daqiqangiz ketyaptimi? Shoshilmang, unga vaqt bering. Uning urinib ko‘rishi va xato qilishi kelajakdagi muammolarni hal etish ko‘nikmasining poydevoridir.'),
  ('58d0ef6e-2eed-490f-85f9-8fd8f899a9bd', 'Uydagi tartibsizlik bilan murosa qilish 🌪️', 'Xonaning hamma joyi o‘yinchoqmi? Tozalik emas, u bilan o‘tkazgan sho‘x-shodon onlaringiz muhim. O‘yinchoqlar ertaga ham o‘sha yerda bo‘ladi, o‘zingizni charchatmang. Ba’zan tartibsizlikka ko‘nikish — eng yaxshi dam olishdir.'),
  ('d52a333c-1a4b-40fd-a11c-b3544628c6df', 'Dadaning yashirin taktikasi 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetadi. Kechga yaqin bolani uyquga tayyorlash va tishlarini yuvdirishni dadasining sho‘xliklariga topshirib, siz chetda sokin dam oling.'),
  ('dbff772c-4b84-4bcd-8132-9e03a5a6d600', 'G‘aroyib eng yaqin do‘st 🥄', 'Shuncha qimmat o‘yinchoqlari bo‘la turib, u oshxonadan silikon kurakcha topib olib, kun bo‘yi uni ko‘tarib yuribdimi, hatto uxlatyaptimi? Bola miyasi hayratlanarli. To‘sqinlik qilmang, kurakchasini yaxshi ko‘raversin.'),
  ('5e23814c-ef4e-4708-8223-e1ab2ac7daa9', 'Pichirlab uxlatish 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Yoniga yotib, kun davomida sodir bo‘lgan voqealarni juda past ovozda qulog‘iga pichirlab ayting. Pichirlash miyani uyquga tayyorlaydigan va shovqinni unuttiradigan eng tabiiy hamda samarali usullardan biridir.'),
  ('e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c', 'Ro‘yxatdagi kutilmagan sovg‘a 🛒', 'Do‘konga borishdan oldin Xaridlar ro‘yxatini ochdingiz va u orqangizdan kelib, telefon ekranini bosib, ro‘yxatga shokolad qo‘shganini ko‘rdingiz. Ha, ular texnologiyani sizdan ham yaxshiroq bilishadi!'),
  ('fc07a24b-5d02-4f37-9d95-b46ab5b5f190', 'Maqsadli buzish 🧱', 'Katta mehnat bilan minora quradi, keyin esa kulib, uni bir urinishda buzib tashlaydi. U fizika va sabab-oqibat bog‘liqligini o‘rganmoqda. Jahlingiz chiqmasin, qulagan minoralar uning miyasida yangi neyron aloqalar shakllanayotganidan darak beradi.'),
  ('00481a1e-da97-4621-84c5-0bde2c4df340', 'Ko‘rinmas ta’qibchi 👻', 'Devordagi soyasidan qo‘rqib, yig‘lay boshladimi? Soya bilan kurashish — 3 yosh davrining eng kulgili klassik holatlaridan biri. Chiroqlarni o‘chiring, fonarni yoqing va soyalarni raqsga tushirib, bu qo‘rquvni qiziqarli uyqu marosimiga aylantiring.'),
  ('81f8ee8c-8ca4-4260-b2ea-e74f425fe201', 'Kiyimlar uyumidan chodir ⛺', 'Hozirgina taxlagan toza kiyimlaringizni sochib, o‘ziga chodir qurdimi? Jahlingiz chiqishidan oldin chodir ichiga bir qarang. U yerdagi xayolot olami va bolaning quvonchi kiyim taxlash uchun sarflagan mehnatingizdan qadrliroqdir.'),
  ('c4bb77ab-6874-45a4-8118-c089a7246538', 'Yorliq inqirozi 🏷️', 'Bo‘ynimni qichishtiryapti! Ko‘ylak orqasidagi o‘sha kichkina yorliq bugungi tongning eng katta dushmaniga aylandi. 3 yoshda sensor sezgirlik eng yuqori darajaga chiqadi. Bahslashmang, shunchaki yorliqni kesib tashlang va kunni osoyishta boshlashga imkon bering.'),
  ('04cb5d8f-0591-4ccc-8e31-0cf6555eb83a', 'Vannada cho‘kayotgan kemalar 🛀', 'Suv bilan o‘ynash uchun hammomga kirdingiz, u esa cho‘kmaydigan o‘yinchoqlarni suvga botirishga urinmoqda. U fizikani kashf etyapti! Mayli, suv atrofga sachrasin — uning quvvati bolada kun bo‘yi to‘plangan qarshilikni ham o‘zi bilan olib ketadi.'),
  ('123c0368-cc37-47f7-bb36-f227dd4d9131', 'Xayoliy uy hayvoni 🐕', 'U xonada yo‘q kuchuk yoki mushukni silab, unga ism qo‘yyaptimi? Uning tasavvur kuchi endi jismoniy chegaralardan ham oshib ketdi. Xonaning bir burchagiga ko‘rinmas suv idishini qo‘ying va bu yoqimli xayoliy o‘yinga siz ham qo‘shiling.'),
  ('ecca6ba2-c00d-4fde-a20b-1268d23c90e0', 'Muz qolipidagi ziyofat 🧊', 'Nima qilsangiz ham, u sabzavotlarni yemayaptimi? Taqdim etish usulini tubdan o‘zgartiring. Foydali yeguliklarni muz qolipining (ice cube tray) kichik bo‘lmalariga joylang. G‘ayrioddiy taqdimot har doim ishtahani ochadi.'),
  ('aa798243-c44e-4178-957c-647030916048', 'Ob-havo ogohlantirishi ⛅', 'Sayrga chiqayotganda derazadan qarab aldanmang. Ob-havo va kiyim yordamchisi orqali tashqaridagi haqiqiy shamol va haroratga eng mos kiyimlar uyg‘unligini tanlab, uydan xotirjam va tayyor holda chiqing.'),
  ('b3ff48b4-aa5c-406e-999b-73655dca1c90', 'Multfilm tanqidchisi 📺', 'Ko‘rgan multfilmini sizga o‘ziga xos grammatikasi bilan aytib beradi, kim qayerga ketganini jiddiy tushuntiradi. Uni diqqat bilan, hayratlangandek tinglang. O‘zini dunyodagi eng aqlli insondek his qilsin.'),
  ('c83099cc-b126-47d8-b334-d8faf9b45dde', 'Qorong‘ilik kuchi 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlar va planshet ekranlarini o‘chiring. Melatonin faqat qorong‘i va texnologiyalarsiz muhitda tez ajralib chiqadi.'),
  ('9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b', 'Taom tanlaydigan xo‘randalar 🥦', 'Kecha yoqtirgan taomiga bugun yo‘q deyaptimi? 3 yoshda ovqat tanlash bilan bog‘liq injiqliklar odatiy hol. Sog‘lom retseptlar orasidan uni qiziqtiradigan rang-barang va noodatiy taqdimot usullarini toping.'),
  ('b755d54c-d2cb-47a2-92bb-44a36d855874', 'Tasavvur parvozda 🚀', 'Endi u shunchaki o‘ynamayapti, balki ssenariylar tuzyapti! Karton quti bir zumda kosmik kemaga aylanadi. Rivojlanish kuzatuvchisida ushbu kognitiv sakrashni faxr bilan qayd eting va uning o‘yiniga qo‘shiling.'),
  ('ef6fe3c1-b830-477f-93ee-842f8b450ab9', 'Kun hisoboti 🌙', 'Uxlashdan oldin chiroqlarni xiralashtiring va bugun eng ko‘p nimaga kulganingizni muhokama qiling. Uyqu oldidan bo‘ladigan bu kichik suhbatlar uning fikrini ifodalash qobiliyatini rivojlantiradi.'),
  ('56159a04-f4fe-4e35-a3dd-8bcc4853f3c9', 'Dadaning parvoz rejimi ✈️', 'U uyda yugurib yuribdi va yotishni istamayapti. Dadasini yordamga chaqiring. Dadasi uni havoga ko‘tarib, samolyotdek uchirganda, xona qahqahaga to‘ladi va yig‘ilib qolgan barcha jismoniy tajovuzkorlik bir necha soniya ichida ter bilan birga chiqib ketadi.'),
  ('69ac9098-fc9c-4474-aa9d-090c0c3f7cdf', 'Ertalab soat 6 dagi rejissyorlik 🎬', 'Siz hali uyqudasiz, ammo u boshingiz tepasida turibdi: Sen ayiq bo‘l, men quyon! Yarim uyquda g‘urr-g‘urr ovozlar chiqarib, bu g‘aroyib teatrda rolingizni ijro eting. Onalik ba’zan eng zo‘r aktyorlik mahoratini talab qiladi.'),
  ('aa6e4c45-6848-4e91-8836-f55617de9313', 'Hamjamiyatdagi hamdardlik 💬', 'Siz juda charchagansiz va hech kimga hech narsani tushuntirishni istamayapsiz. Anacan Hamjamiyatiga kirib, shunchaki o‘quvchi bo‘lib qoling. Boshqa onalarning ham xuddi shunday charchaganini ko‘rish «men yolg‘iz emasman» degan tuyg‘uni uyg‘otib, eng yaxshi terapiyaga aylanadi.'),
  ('7b3c2751-f23f-4467-abdf-9463831a86cb', 'Sukunatning raqamli zavqi 🤫', 'U nihoyat uxlab qoldi! Uyni qoplagan sukunat shu qadar chuqurki, hatto quloqlaringiz tin oladi. Ovoz o‘lchagichni yoqing va ekrandagi 0-10 detsibel ko‘rsatkichiga qarab, miyangiz asta-sekin qanday tiklanayotganini ko‘z bilan his qiling.'),
  ('7d093b24-909b-4f92-b3df-fe627f2322c0', 'Do‘konda «Men haydayman!» 🛒', 'U do‘kon aravachasini albatta o‘zi haydamoqchi bo‘ladi va natijada siz javonlarga urilib ketasiz. Uning irodasini sindirmaslik uchun aravachani birga boshqaring. Biror narsani unutmaslik uchun esa ilovadagi Xaridlar ro‘yxatini ochiq qoldiring.'),
  ('803c4a83-8bb9-4a65-a6e0-a757e4e816cf', 'Yarimta gaplarni to‘ldiring 🗣️', 'Biror so‘zni unutib qolsa, qo‘li bilan ishora qilib, uni topishingizni kutadimi? «Ha-a, to‘pni aytyapsanmi?» deganingizdagi o‘sha yengillik lahzasini kuzating. Uning lug‘at boyligi oshib bormoqda, shunchaki miyasi tilidan tezroq ishlayapti.'),
  ('1f94fede-7afb-4d0a-8e39-07ab7d2da0c4', 'Siz bola bo‘ling, men esa ona 👩‍👧', 'Rollar almashinuvi o‘yini boshlandi! U sizga «bu yerga keling, ovqatingizni yeng» deb ko‘rsatmalar beradi. Uning yetakchilik tajribasini mamnuniyat bilan qabul qiling va indamay uning bolasi rolini o‘ynang.'),
  ('77330b1b-94b4-4438-9dd4-9ea117490b54', 'Sun’iy intellekt, haqiqiy yechim 🤖', 'Nega 3 yoshli bola birdan tirnog‘ini tishlay boshlaydi? Internetdagi qo‘rqinchli, ruhiy jarohat yetkazadigan maqolalarni unuting. Anacan AI’dan bu shunchaki vaqtinchalik stress reaksiyasi bo‘lishi mumkinmi, deb so‘rang va ilmiy asoslangan javob oling.'),
  ('e7437e5e-38bf-45b1-8db0-74786f20b535', 'Juftlik uchun tanaffus 🥂', 'Bola uxlab qoldi. Endi telefonlar va uy ishlarini bir chetga qo‘ying. Juftingiz bilan yuzma-yuz o‘tirib, atigi 20 daqiqa davomida to‘lovlar va boladan boshqa mavzuda suhbatlashing. Siz nafaqat ota-ona, balki juftlik ham ekansiz!'),
  ('3a4c5cc8-5f54-4aef-b016-9394a079ec83', 'Cho‘ntakdan chiqqanlar 🪨', 'Shimini yuvayotganda cho‘ntagidan 3 xil kattalikdagi tosh va bitta kashtan po‘chog‘i chiqdimi? Uning uchun bular dunyodagi eng qimmatli kolleksiyadir. Ularni tashlab yuborish o‘rniga kichik qutiga yig‘ib, xazina sandig‘i yarating.'),
  ('68c1a1ff-c119-4521-aae1-9a7a984caad7', 'Chiroqlarni o‘chiring, uyqu kelsin 🌙', 'Tezroq uxlab qolishi uchun yotishdan 1 soat oldin xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin (uyqu gormoni) faqat qorong‘i va texnologiyalarsiz muhitda tez ajraladi.'),
  ('9021ef15-5cf5-4f9d-8592-aab7e32c65a0', 'Hissiy holdan toyish 🔋', 'Hamma narsaga baqirgingiz kelyaptimi? Shovqin miyangizni teshib yuborayotgandekmi? Bu — haqiqiy hissiy kuyish. Uni darhol xavfsiz joyga qo‘ying (yoki otasiga bering), boshqa xonaga o‘ting va Kayfiyat kundaligiga barcha stressingizni hech narsani yashirmay yozing.'),
  ('5625eb93-64b3-45e9-9346-29a2c6af885f', 'Tabiat detoksi shart 🌳', 'To‘rt devor orasida uning energiyasi tajovuzkorlikka aylanadi. Ob-havo qanday bo‘lishidan qat’i nazar, mos kiyintirib, uni albatta tashqariga olib chiqing. Tuproqqa tegish, barglarni yig‘ish uning asab tizimini darhol tinchlantiradi.'),
  ('d33d70dc-19c8-4087-8ed8-270685911bfd', 'Shivirlashning sehrli kuchi 🌙', 'Ertak o‘qishdan ovoz paylaringiz charchadi. Xonadagi chiroqlarni butunlay o‘chiring. Uning yoniga yotib, kun davomida sodir bo‘lgan voqealarni juda past ovozda qulog‘iga shivirlang. Shivirlash — miyani uyquga tayyorlashning eng tinchlantiruvchi usuli.'),
  ('e578603f-02ec-4734-b19f-2d0ca949a8e2', 'Hayratlanarli jajji inson 🎈', 'Bu uzoq yo‘lda hayratlanadigan narsalar juda ko‘p. Masalan, kecha o‘rgangan so‘zini bugun falsafiy bir jumlada ishlatishi! Bu kunlar boshqa qaytmaydi.'),
  ('0cdb7f22-d990-414a-b36e-54d6d47e1b4f', 'Yashirin shokolad tanaffusi 🍫', 'Oshxona shkafi ortida undan yashirincha shokolad yeyayotgan ona, bu glyukozaga siz haqlisiz. O‘zingizni ayblamang! Uning telbalarcha energiyasiga bardosh berish uchun siz ham quvvat olishingiz shart. Nafas oling va chaynashda davom eting.'),
  ('62a2e4b7-b7ef-4d46-a134-22e1f4da5625', 'Aqlli ertakdagi qahramon — uning o‘zi 🪄', 'Bugun kechqurun Aqlli ertaklardagi qahramonga bevosita farzandingizning ismini bering. Ertak qahramoni ham tishlarini yuvmagani va keyin afsuslanganini aytib, muhim qadriyatlarni bilvosita singdiring.'),
  ('ce8759a7-ff69-4b27-a788-668b48e71999', 'Hojatxona qog‘ozi muhandisi 🧻', 'Bir necha daqiqalik sukunat... Xonaga kirganingizda esa hojatxona qog‘ozining hammasi yechilib, butun uyga yoyilganini ko‘rasiz! Jahlingiz chiqishi o‘rniga, qog‘ozlarni yig‘ib, birgalikda qor odam yasang. Tartibsizlikni ijodkorlik bilan yengib chiqing.'),
  ('a5815a11-4b6f-4f3d-a6ff-4d587c286a65', 'Musiqa bilan uyg‘onish 🎶', 'Quyosh hali to‘liq chiqmagan, ammo u karavotda sakrab, ritmik tovushlar chiqarmoqda. Dunyodagi eng shovqinli, lekin eng yoqimli uyg‘otuvchi! Kunni uning cheksiz energiyasiga tabassum qilib boshlang.'),
  ('afb9fd4f-60e2-4547-87e2-d867963a1345', 'Tuyg‘ularni qayd etish 📝', 'Bola uxlagach, Kayfiyat kundaligini oching. Bugun u qilgan eng kulgili, sizni hammadan ko‘p kuldirgan o‘sha bema’ni lahzani kelajak uchun yozib qo‘ying. Yillar o‘tib o‘qiganingizda ko‘zlaringizga yosh keladi.'),
  ('db2d884d-1367-4ebc-a61b-9a450673d64d', 'Sokin vaqt tajribasi 🥱', 'Kunduzgi uyquga yotishni istamayapti, ammo ko‘zlari yumilib ketyaptimi? 3 yoshdagi qarshilik — odatiy hol. Majburlamang, xonadagi yorug‘likni pasaytirib, Jimlikda kitob varaqlash vaqtini e’lon qiling va yangi odat yarating.'),
  ('0f647bd8-9749-4a55-969b-bfc85ddb7152', 'Dadaning maxfiy quroli 🤡', 'Siz qilayotgan hech narsa yordam bermay qolganda, dadaning g‘alati tovushlari va kulgili yuz ifodalari vaziyatni darhol qutqaradi. Kechki injiqlik paytida navbatni darhol unga bering, o‘zingiz esa chetdan dam olib kuzating.'),
  ('c30ee50d-9665-4368-af0d-6578c2cc302b', 'Tanangizga quloq tuting 🩸', 'Sababsiz charchoq va yig‘lash istagi bormi? Hayz kuzatuvchisini oching. Tanangiz sizga ishora bermoqda. Sog‘lom retseptlardan magniyga boy yegulik tanlab, o‘zingizga mehr ko‘rsating.'),
  ('c49b057e-0774-42da-aec0-ee5fcc238471', 'Tanlab ovqatlanish 🍝', 'Faqat o‘zi yoqtirgan 2-3 xil taomni yeyaptimi? Xavotir olmang. Ovqatlanishni nazorat qilish vositasi yordamida haftalik muvozanatni tekshiring va dasturxon atrofida bosim o‘tkazishdan saqlaning.'),
  ('462a51f8-d8f0-4c41-8551-81fbd18e8c62', 'Ertakning oxirini u topadi 🪄', 'Klassik kitoblardan ikkalangiz ham zerikdingiz. Aqlli ertaklarni oching va bu oqshom voqealar rivojini u boshqarishiga imkon bering. “Endi mashina qayerga borsin?” deb so‘rang va u o‘ylab topgan kulgili yakun bilan uyquga ketsin.'),
  ('a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb', 'Mukammal ona haqidagi afsonalar 🛑', 'Ijtimoiy tarmoqlardagi bolalar allaqachon she’r aytyapti, sizning bolangiz esa hali ham so‘zlarni chalkashtiryaptimi? Darhol taqqoslashni bas qiling! Har bir bolaning rivojlanish sur’ati o‘ziga xos va turlicha. U o‘z sur’atida mukammal rivojlanmoqda.'),
  ('fca7853a-0c3e-4553-8c15-c32fa7564774', 'Poyabzal kiyish olimpiadasi 👟', 'O‘ng poyabzalini chap oyog‘iga kiyib oldi va uni aslo yechishni istamayaptimi? Mayli, shunday qolsin. Erkinlik hissi va “o‘zim qildim” degan faxr poyabzalni to‘g‘ri kiyishdan muhimroq. Bu kelajakda muammolarni hal qilish qobiliyatining ham poydevoridir.'),
  ('344d14b0-cfc9-4ff3-af6f-44e0148ab198', 'Ko‘rinmas chiqindi fojiasi 🗑️', 'O‘zi tashlab yuborgan, siz esa chiqindiga solgan o‘sha keraksiz qog‘oz parchasini qidirib yig‘layaptimi? 3 yoshli bolaning mantig‘i aynan shunday. Uni qaytarib bera olmaganingiz uchun bolaning diqqatini darhol yorqinroq biror narsaga qarating.'),
  ('be71bad2-041d-4cb4-a658-89cb36e8a738', 'Onaning quvvat olish vaqti 🔋', 'U 10 daqiqadan beri jim o‘tirib, mustaqil ravishda pazl yig‘yapti. Siz esa bu fursatda uyni yig‘ishtirmoqchisiz. Yo‘q! Divanga cho‘ziling. Kechgacha shu sur’atga bardosh berishingiz uchun sizning ham quvvatingiz to‘lishi kerak.'),
  ('d2f93631-6ef4-4ba4-9cac-259dafd2fb22', 'Qorong‘ilikka ko‘nikish 🌙', 'Yotoqxonadagi chiroqlar o‘chirilganda bezovta bo‘ladimi? Xonaning bir burchagiga iliq rangli (sariq yoki to‘q sariq) kichik tungi chiroq qo‘ying. Xonaning qolgan qismi esa chuqur uyqu uchun butunlay qorong‘i bo‘lib qolishi kerak.'),
  ('5407f02f-f40a-48e1-b4f8-80cd1fc9345c', 'Ertalabki diktator ish boshida 👑', 'U yerga siz o‘tirmang, ayiqcham o‘tiradi! Nonushta paytida butun stolni u boshqaradi. Uning irodasini keskin sindirmasdan, «Mayli, ayiqchang u yerda o‘tirsin, men esa bu yerda o‘tiraman», deb muvozanatni saqlang.'),
  ('a1a50d57-7314-4042-848d-a89f6c8fc209', 'Tabiat qo‘yniga qochish ⛅', 'To‘rt devor orasida qolish uning ham, sizning ham jahlingizni chiqardi. Ob-havo va kiyim vositasini tekshirib, darhol parkka yo‘l oling. Ochiq havoda yugurish va erkinlik hatto kichkintoyning eng kuchli injiqlik xurujlarini ham bir zumda to‘xtatadi.'),
  ('e61af62b-257c-41ec-8846-9d470f2646d9', 'Tunning huzurbaxsh onlari 🛀', 'Butun kun «xohlamayman» degan gaplar bilan o‘tdi. Iliq vanna nafaqat gigiyena, balki uning zo‘riqqan asab tizimini tinchlantirish uchun ham kerak. Suvning shovullashi va iliqligi barcha qaysarlikni yuvib ketadi.'),
  ('8169372c-8d17-46fc-bfc3-eda3a929eaa6', 'Do‘kondagi unutuvchanlik 🛒', 'Xotirangizga ishonib do‘konga bordingiz-u, taglikni unutib qaytdingizmi? Bunday holatlar bo‘lib turadi. Barcha kerakli narsalarni darhol Xaridlar ro‘yxatiga yozishni odat qiling, ilova sizning raqamli xotirangiz bo‘lsin.'),
  ('a15765ea-b7ce-42a7-91ae-209256ee1beb', 'Ona, menga qarang! 👀', 'Siz telefonga qarayotganingizda yoki biror ish qilayotganingizda, u kelib qo‘lingizga uradi yoki oldingizni to‘sadi. U mutlaqo haq: u sizning butun e’tiboringizni xohlaydi. Atigi 5 daqiqa davomida chalg‘imasdan ko‘zlariga qarab o‘ynashingiz uni tinchlantiradi.'),
  ('de1347cd-769b-44d4-8aff-75ce2b7d2f0c', 'Sukunat tasdig‘i 🤫', 'Shovqinli kundan keyin, bola uxlagach, Ovoz o‘lchagich yordamida xonadagi sukunat darajasini o‘lchang. Nolga yaqinlashayotgan raqamlarni ko‘rish — bu vizual osoyishtalik ona miyasi uchun eng yoqimli massajdek ta’sir qiladi.'),
  ('0ff315d9-2ad1-4c8c-9187-ea4c26042a66', 'Vaqt naqadar tez o''tadi!', 'U endi o''z qarorlariga ega bo''lgan mustaqil inson. Uning bu kuchli xarakteri kelajakda sizga katta faxr bag''ishlaydi. Bu kunlar qaytib kelmaydi, uni mehr bilan bag''ringizga bosing.'),
  ('e4430813-5ad7-446e-9502-6e658d83eddd', 'Sabzavot jarrohi 🥦', 'U sho''rvadagi sabzavotlarni xuddi mikroskop bilan qidirayotgandek chetga ajratib qo''yadimi? U bilan kurashmang. Foydali retseptlarda sabzavotlarni pyure qilib, souslar ichiga yashirishning turli va mazali usullarini kashf eting.'),
  ('e44cdd54-2858-49fa-8fd7-06dc369d29b6', 'Dadaning massaj seansi 💆‍♂️', 'Bugun ko''p vaqt oyoqda turdingiz, uning ortidan yugurib, belingiz ham og''rib ketdi. Bola uxlagach, turmush o''rtog''ingizdan yelkangizni 10 daqiqa uqalab qo''yishini so''rang. Siz uyning ustunisiz, ustunlar ham albatta tiklanishi kerak.'),
  ('9c8523f0-548b-4581-bde4-2a8295db3639', 'Qorong''ilikka chorlov 🌙', 'Uning tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o''chiring. Melatonin faqat qorong''i va texnologiyalarsiz muhitda tez ajralib chiqib, uyquga ketishni osonlashtiradi.'),
  ('b7c3f40e-e406-412b-86a2-1c33a12692d8', 'Bog''cha haqidagi o''ylar 🏫', 'Endi uning ijtimoiylashishga ko''proq ehtiyoji borligini sezyapsizmi? Bog''chaga borish uchun ayni vaqtmi? Anacan hamjamiyatiga qo''shilib, boshqa onalarning moslashuv bo''yicha haqiqiy tajribalarini o''qing va qaror qabul qilishni osonlashtiring.'),
  ('d8d022ce-8e44-42aa-972f-aa293c4341c8', 'Sizga yordam beray! 🧽', 'Siz idish yuvayotganingizda u albatta yoningizga stul qo''yib, suv bilan o''ynashni xohlaydimi? Aslida u yordam berishni emas, jarayonning markazida bo''lishni istaydi. Unga kichik plastik idish bering, u ham sovunlasin.'),
  ('63dc600c-4255-41f7-8695-78dd689a1998', 'Shivirlab aytiladigan ertaklar 🪄', 'Xona chiroqlarini butunlay o‘chiring. Uning yoniga yotib, Aqlli ertaklardan qisqa bir voqeani juda past ovozda qulog‘iga shivirlab aytib bering. Shivirlash miyani uyquga tayyorlaydigan eng tabiiy va tinchlantiruvchi usuldir.'),
  ('76d2443b-1074-45cd-a82d-59ba223792bb', 'Jonli diktofon 🎙️', 'Kecha telefonda dugonangizga aytgan o‘sha hayajonli yoki g‘alati jumlangizni bugun u o‘yinchog‘iga aytyapti! Uning so‘z boyligi nihoyatda tez kengaymoqda va u sizga taqlid qilyapti. Endi so‘zlaringizga ikki karra e’tiborli bo‘lishingiz kerak.'),
  ('a624ef08-9c66-462b-82e4-a4aa90f5b17b', 'O‘zingizni qadrlang 🥗', 'Uni ovqatlantirish uchun tuxumni 4 xil usulda pishirdingiz, ammo o‘zingiz nima yedingiz? Sog‘lom retseptlardan 5 daqiqada tayyor bo‘ladigan, temir va kalsiyga boy maxsus taom tayyorlab, o‘zingizni siylang.'),
  ('0f7458af-fb58-4fe6-9907-6a5b773bca96', 'Oq shovqin yordami 🤫', 'U uyquga ketayotgan paytda sezgirligi ortadi. Derazadan kelayotgan tovushlarni neytrallash uchun xonada Ovoz o‘lchagichning fon shovqinini yoqing va xonada doimiy osoyishtalik yarating.'),
  ('143f9431-42d8-41e6-9983-ce9dde347219', 'Kiyimlar dog‘ bo‘lib ketdi 🎨', 'Pijamasi ovqat, ust-boshi esa bo‘yoq dog‘lari bilan qoplanganmi? Bolalar hamisha toza bo‘lib ulg‘ayishi shart emas, ular atrofni o‘rganib, kir bo‘lishi tabiiy. Silikon ko‘krakpechlardan foydalaning, qolganini esa kir yuvish mashinasiga qo‘yib bering.'),
  ('6aecb8fd-7228-4ba7-9f34-65a8f0cda801', 'Mebellarga tirmashish 🧗‍♂️', 'Divan yoki kresloga yopishib, tepaga tirmashishga urinyaptimi? Uning muvozanati va mushak kuchi rivojlanmoqda. Uni ehtiyot qiling, ammo bu kichik alpinistning urinishlariga va fizika qonunlarini kashf etishiga aslo to‘sqinlik qilmang.'),
  ('135b57f3-06e7-4fc4-b590-bec1151ee33b', 'Iliq suv sehri 🛀', 'Butun kun “xohlamayman”lar bilan o''tdi. Iliq vanna nafaqat gigiyena, balki uning zo''riqqan asab tizimini tinchlantirish uchun ham kerak. Suvning shovullashi va iliqligi barcha qaysarlikni yuvib ketadi.'),
  ('57cfce2e-d64c-49cb-9f8b-295055620f21', 'Tabiat topishmog''i 🍁', 'Uydagi zerikarli muhit ikkingizni ham siqadi. Parkka borib, eng g''alati shakldagi toshni topish vazifasini bajaring. Tabiat uning uchun eng katta laboratoriya bo''lib, barcha zo''riqishini ketkazadi.'),
  ('682b0a2a-83c6-46cb-a100-02da150309f7', 'Hayvonlarga taqlid 🐶', 'U nafaqat ovoz chiqaradi, balki it kabi emaklab, mushuk kabi ishqalanadimi? Tana tili va tasavvur hayratlanarli tarzda uyg''unlashmoqda. Siz ham u bilan birga gilam ustida bu o''yinga qo''shilib, stressingizni chiqaring.'),
  ('01a8a883-66ea-4e90-9796-1cd4c7aa4386', 'Ona uchun oflayn vaqt ☕', 'Bola o''z olamiga sho''ng''ib o''ynayotganida, darhol uyni yig''ishtirishga shoshilmang. O''zingizga bir piyola issiq choy quying, telefonni chetga qo''ying va 15 daqiqa hech narsani o''ylamasdan, shunchaki o''tiring.'),
  ('7fc36514-28e6-4738-b9f6-f0c9cd9fa57d', 'Juftlik uchun tanaffus 🥂', 'Bola uxlab qoldi. Endi uy ishlarini bir chetga qo''ying. Juftingiz bilan kamida 20 daqiqa davomida bola va xarajatlardan boshqa istalgan mavzuda suhbatlashing. Siz ayni paytda bir juftlik ham ekansiz!'),
  ('8b2d61db-8be9-4916-a184-f14d02885b17', '“Bu nima?” mashinasi ☝️', 'U hamma narsani barmog''i bilan ko''rsatib, nomini so''rayaptimi? U sizdan dunyodagi narsalarga nom berishingizni istaydi. Bu muloqotdagi katta sakrash! Charchasangiz ham, o''sha buyumlarning nomini sabr bilan takrorlashda davom eting.'),
  ('0db41c26-c87d-4bd7-8650-e9fd07449904', 'Onalar dardlashuvi 💬', '«Bu bola hech qachon tinchlanmaydi», degan o‘y sizni charchatyaptimi? Anacan Hamjamiyatiga qo‘shiling — har bir bola 3 yoshga yaqinlashganda shunday jo‘shqin inqirozli davrlarni boshdan kechirishini ko‘rib, chuqur nafas olasiz.'),
  ('448fd3b8-143f-4fee-a40b-1b20e42ebbba', 'Bir, ikki, uch... o‘n! 🔢', 'Barmoqlarini yoki o‘yinchoqlarini sanashga urinyaptimi? Matematik tafakkuri uyg‘onmoqda. Hayratlanarli tezlikda rivojlanayotgan bu kichik urinishlarni e’tibordan chetda qoldirmang.'),
  ('5a020277-4aac-4623-8f46-93168c2f54e5', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda uyg‘onishlar va uxlatish jarayonining barcha yukini yolg‘iz o‘zingiz ko‘tarmang. Juftingizni ham uyg‘oting: jamoa bo‘lish — mas’uliyatni teng bo‘lishish demakdir. Bu kecha bolani uxlatish navbati butunlay uniki.'),
  ('026f00f3-6e56-4ac5-a91b-bd5bd82cd187', 'Sokinlik soati tajribasi 🥱', 'Kunduzi uxlashni istamay, yig‘layaptimi? Majburlamang. Xonadagi yorug‘likni pasaytirib, «Jim kitob varaqlash soati»ni e’lon qiling va ikkalangizga ham xotirjamlik beradigan yangi odat yarating.'),
  ('53b445aa-e1d7-4c46-9d5a-07132c91031c', 'Qorong‘ilikdagi xayollar 🌌', 'Chiroqlar o‘chganida xonadagi buyumlar maxluqqa aylanayotgandek tuyuladimi? Oq shovqinlar orasidan ona qornidagi tovushni yoqib, unga o‘sha azaliy va mukammal xavfsizlik hissini qaytaring.'),
  ('f4eb03a9-f74f-423a-ab2a-59d54da2db98', 'Mantiq izlab 🧩', 'Endi oddiy o‘yinchoqlar uni qiziqtirmaydi, u murakkabroq o‘yinlar o‘ylab topmoqda. Aqlini yanada charxlaydigan va mantiqiy fikrlashni rivojlantiradigan o‘yinlarni Tavsiya etilgan mahsulotlar bo‘limidan izlang.'),
  ('6716e6c0-2c87-4096-9dc2-661b570d83da', 'Muzlatkichdagi pult 📺', 'Televizor pultini topolmayapsizmi? Muzlatkich yoki poyabzal javoniga qarang. U buyumlarni o‘zi o‘ylab topgan mantiq asosida joylashtirib, dunyoni kashf etmoqda. Jahlingiz chiqishi o‘rniga, bu bema’ni detektiv o‘yinga kulib qarang.'),
  ('7e1b9939-5806-440f-9214-8ee42a76c83e', 'Xayoliy yarani izlash 🩹', 'Uyg‘onishi bilan tanasidan ko‘rinmas yara topib, vahima ichida unga plastir yopishtirishingizni talab qiladi. Bu jismoniy og‘riq emas, shunchaki e’tibor va mehrga bo‘lgan ehtiyojdir. Bahslashmang, kichkina plastirni yopishtirib, o‘pib qo‘ying — kuningiz qutqariladi.'),
  ('ce6bc378-f040-49dc-a292-ef6ffa4a4247', 'To‘satdan och qolish sindromi 🥱', 'Aynan yotishga kirganida ona, qornim ochdi deb, oshxonaga yugurmoqchi bo‘ladi. Uyquni kechiktirishning ajoyib usuli! Ovqatlanish rejasida kechki payt uchun uyqu keltiradigan kichik tamaddi (masalan, banan) tanlab, bu bahonaga oldindan barham bering.'),
  ('7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f', 'Sukunatdan xavotirlanish 🤫', 'U xonada yolg‘iz o‘zi rasmlarni tomosha qilmoqda, uy esa suv quygandek jimjit. Siz esa bu sukunatdan shubhalanib, har lahzada biror falokat yuz berishini kutasiz. Xotirjam bo‘ling. Ba’zan ular ham yolg‘iz qolishni xohlaydi. Orqaga suyanib, bu kamyob oflayn lahzadan zavqlaning.'),
  ('7dcdfa61-d4a7-4888-bf22-0453312c6bae', 'Ovoz chiqarib o‘ylash 💭', 'U karavotda yotib, kun davomida sodir bo‘lgan voqealarni o‘zicha, ammo baland ovozda gapirib beradi. U ma’lumotlar va xotiralarni shu tarzda qayta ishlaydi. Rivojlanish kuzatuvchisini oching va uning mustaqil hikoya tuzish qobiliyati naqadar tez rivojlanayotganini faxr bilan qayd eting.'),
  ('dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39', 'Gilamdagi chiziqlar 📏', 'U gilamdagi chiziqlarni bosmasdan yurishga harakat qiladi va sizdan ham shuni talab etadi. Yirik motorika va diqqatni muvofiqlashtirish ajoyib tarzda uyg‘unlashgan. O‘yinni buzmang, siz ham bir necha qadam davomida u bilan birga chiziqlar ustidan sakrab o‘ting.'),
  ('80fe5b22-0f4c-4f31-ac99-30418e5a6c6a', 'Ona uchun bir nafas 🌬️', 'Uydagi tartibsizlikdan quloqlaringiz shang‘illayapti. Ob-havoni tekshiring, mos kiyim kiying va qalin kiyinishga to‘g‘ri kelsa ham, atigi 15 daqiqaga tashqariga chiqing. U yerdagi toshlarni yig‘sin, siz esa yuzingizga urilayotgan sovuq va toza havodan shunchaki chuqur-chuqur nafas oling.'),
  ('93c26bc0-b2a6-4580-91d3-d91792e077a2', 'Dinozavr tili 🦖', 'Bugun ertalab u inson emas, dinozavr va barcha savollaringizga faqat o‘kirib javob beradi. Rolli o‘yinlar shaxsiyat rivoji uchun ajoyib vositadir. Siz ham bir zumga ona emas, boshqa bir dinozavr bo‘lib, unga o‘z tilida javob bering.'),
  ('b992124a-a4ae-4e30-a81b-b79de4b95a68', 'Charchoqni tan olish 📝', 'Hech kim sizni tushunmayotgandek, mehnatingiz esa ko‘rinmayotgandek tuyulyaptimi? Soxta tabassumlarni bir chetga suring. Kayfiyat kundaligiga bugun aslida qanchalik holdan toyganingizni yozing. Ekranga tushgan har bir so‘z yelkangizdagi og‘ir yukni yengillashtiradi.'),
  ('075e0950-03bc-496b-a1a2-1172377fb523', 'Sun’iy intellekt va xavotirlar 🤖', 'Bolangiz ayrim harflarni talaffuz qila olmayotgani sizni birdan xavotirga soldimi? Internetdagi noprofessional va vahima uyg‘otadigan forumlarni yoping. Anacan AI-dan 3 yosh arafasidagi nutq rivoji me’yorlari haqida so‘rab, ilmiy asoslangan va ko‘nglingizni tinchlantiradigan javob oling.'),
  ('9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9', 'Karavotdagi sirk 🎪', 'Uxlash vaqti kelishi bilan karavot birdan sirk arenasiga aylanadi. U sakraydi, emaklaydi, qichqiradi. Ovozingizni ko‘tarmasdan chiroqlarni xiralashtiring. U qolgan so‘nggi quvvatini sarflayapti. Aqlli ertaklardan juda sokin ritmdagi hikoyani tanlab, bu bo‘ronni asta-sekin tinchlantiring.'),
  ('c4897803-48e7-46f1-aca1-db692fe7b9f1', 'Hech kimga berilmaydigan eshik tutqichi 🚪', '«Eshikni men ochaman!» deb sizdan oldin yuguradi. Agar uni siz ochib qo‘ysangiz, yig‘lab eshikni qayta yopdiradi va o‘zi ochadi. Bu yoshda vaziyatni nazorat qilish hissi juda muhim. Eshikni o‘zi ochishiga ruxsat bering — bu kichik g‘alabalar uning hali juda nozik bo‘lgan o‘ziga ishonchini mustahkamlaydi.'),
  ('2b40e6c9-46bc-4fb2-8d09-1e690e1a478c', 'Hamjihatlik hamjamiyati 💬', 'Bugun u shunchalik qarshilik qildiki, o‘zingizni yomon ona kabi his qilyapsiz. Darhol Anacan hamjamiyatiga kiring. Boshqa onalarning farzandlari bugun qanday isyon qilgani haqida o‘qib, yolg‘iz emasligingizni va aslida juda yaxshi ish qilayotganingizni tushunasiz.'),
  ('4f85a7f5-323c-4830-b901-61f69a9b8176', 'Yashirin ikkilanish 🤔', 'U oldingizga kelib, “Menga suv bering, lekin bermang” kabi mutlaqo ziddiyatli gaplarni aytadi. Uning miyasida bir vaqtning o‘zida bir-biriga zid ikkita istak mavjud. Bunda ortiqcha mantiq izlamay, shunchaki suvni stol ustiga qo‘ying va qarorni uning ichki kurashiga qoldiring.'),
  ('fb64f95e-ceac-49e1-96ee-95e171273ead', 'Bolg‘a va shurup bilan urinishlar 🛠️', 'Qo‘liga tushgan har qanday qattiq o‘yinchoq bilan mebelni urib, uni ta’mirlaydi. Bu tovushlar miyangizni teshib yuborgudek bo‘lsa-da, aslida u sabab-oqibat bog‘liqligini o‘rganmoqda. Unga bo‘sh karton quti va yog‘och qoshiq bering, shovqinli ta’mirlash ishlarini o‘sha yerda davom ettirsin.'),
  ('0b8c858b-4b69-4199-b627-a7a497686efd', 'Chiqindi emas, san’at 🎨', 'U xonaning o‘rtasida mayda qog‘oz parchalari va kesilgan iplardan ulkan san’at asari yaratibdi va uni tashlab yuborishingizga yo‘l qo‘ymayapti. Ozodalikka bo‘lgan ortiqcha talabchanligingizni bir chetga suring. U yaratgan betartiblikni hurmat qiling, tozalash ertagacha kutishi mumkin.'),
  ('5f97fec7-d72f-4377-af18-4420a1663ca4', 'Shovqin o‘lchagich terapiyasi 🤫', 'Uydagi tuganmas shovqin nihoyat tindi. U uxlayapti. Shovqin o‘lchagichni yoqing va ekrandagi raqamlar 0 desibelgacha pasayishini kuzating. Xonadagi mutlaq sukunat miyangizni vizual tarzda qanday massaj qilayotganini his eting.'),
  ('63b3f3e0-ceca-4b44-a2ea-ae171ce3413f', 'Ko‘zgu qarshisidagi teatr 🎭', 'U erta tongdanoq ko‘zgu qarshisiga turib, yig‘lash, kulish va hayratlanish kabi turli mimikalarni mashq qiladi. U o‘z his-tuyg‘ularini qanday ifodalashni va bunda yuzi qanday tus olishini o‘rganmoqda! Bu daho aktyorning chiqishini uzoqdan faxr bilan tomosha qiling.'),
  ('14f4e22b-ebcd-4b44-af1e-7caf9bc49874', 'Dadaning sehrli qo‘llari 🫂', 'Kun bo‘yi ko‘tarib yurishdan qo‘llaringiz uzilib tushay deydi, ammo u yana quchoqqa olishingizni xohlaydi. Dadasini chaqiring. Dadasining qo‘llarida uchish bolaning e’tiborga bo‘lgan ehtiyojini qondiradi, sizning qo‘llaringiz va belingizga esa juda zarur bo‘lgan damni beradi.'),
  ('8e97dc44-4076-463e-90aa-e9a38f43a406', 'Savol ortidagi mantiq 🧐', 'Baliqlar nega yurmaydi? Erta tongdanoq uning miyasi falsafiy savollar bilan uyg‘onadi. Savollari sizni boshi berk ko‘chaga olib kirsa ham, erinmay tushuntirishga harakat qiling. Sizning ovozingiz uning uchun olamni anglashning eng ishonchli va eng go‘zal yo‘lidir.'),
  ('d78d5945-d2b9-4d6b-be69-c36a9e85a337', 'Xaridlar ro‘yxatidagi tartibsizlik 🛒', 'Do‘konda kassa oldida turibsiz va yana eng kerakli narsani unutganingizni payqadingiz. Miyangiz shundoq ham ming xil ish bilan band. Bundan buyon biror narsa kerak bo‘lgan zahoti uni ilovadagi Xaridlar ro‘yxatiga yozib qo‘yishni odat qiling va o‘zingizga yordam bering.'),
  ('62d4901b-19ff-4b33-a0e0-89d727535d96', 'Teskari kiyinishdan faxrlanish 🧦', 'Paypoqning tovoni oyog‘ining ustida turibdi, ammo uni o‘zi kiygani uchun faxrlanib yuribdi. Aslo aralashmang. Undagi bu «men uddaladim» hissi chiroyli yoki to‘g‘ri kiyinishdan million marta qadrliroq psixologik poydevordir.'),
  ('79c5f477-357d-4a5a-a226-aa71c2153c6a', 'Shivirlab aytilgan hikoyalar 🌙', 'Bugun juda ko‘p gapirdingiz, ovozingiz ham, o‘pkangiz ham charchadi. Chiroqlarni o‘chiring, yoniga yoting va kun davomida yuz bergan voqealarni qulog‘iga shivirlab aytib bering. Shivirlash uning diqqatini jamlaydi va miyasini go‘yo gipnoz qilgandek chuqur uyquga tayyorlaydi.'),
  ('b3b80c54-4891-4e55-9e0b-d88a4a322bdd', 'Oshxonadagi konsert 🥄', 'U qozonlar va yog‘och qoshiqlarni olib, oshxonaning o‘rtasida shovqinli konsert uyushtiryapti. Boshingiz og‘risa ham, bu uning ritmni his qilishi va harakat ko‘nikmalari rivojlanayotganidan darak. Unga «barakalla» deng va bu jarayon tezroq tugashiga umid qiling.'),
  ('26929739-4514-47f4-b2ff-3f79743e2a52', 'Oltindek sukunat o‘lchovi 🤫', 'Uydagi tartibsizlik nihoyat tugadi va u uxlab qoldi. Idishlarni yuvishga shoshilmang! Shovqin o‘lchagichni yoqing va xonadagi mutlaq sukunatni (0-10 detsibel) kuzatib, 15 daqiqa ichida miyangiz qanday dam olayotganini ko‘z bilan his qiling.'),
  ('691e79df-4ad4-4dc1-80d2-9bb367dfc70e', 'Banan archish fojiasi 🍌', 'Bananini uning o‘rniga siz archib qo‘yganingiz uchun ertalab soat 8-da xonada inqilob boshlandimi? Bu yoshning oltin qoidasi: Hamma narsani uning o‘zi hal qilishi kerak. Bananni qayta yopishtira olmaysiz, shuning uchun diqqatini darhol boshqa bir bema’ni narsaga qarating va inqirozni bartaraf eting.'),
  ('cfe53a47-5049-4180-8a26-333de41ec18f', 'Tanlab eshitish sindromi 🙉', 'O‘yinchoqlaringni yig‘ishtir desangiz eshitmaydi-yu, qo‘shni xonadagi shokolad o‘ramining shitirlashini darhol sezadimi? Eshitishida muammo yo‘q, shunchaki o‘ziga keraklisini eshitadi. Qoidalarni pichirlab aytib ko‘ring — qiziqishi uyg‘onadi.'),
  ('46cb3019-8e96-4dd4-93b2-6c2a4bab0f53', 'Cho‘ntakdan chiqqan xazinalar 🪨', 'Shimini yuvayotganda cho‘ntagidan 2 ta tosh, bitta qurigan barg va yarimta cho‘p chiqdimi? Siz uchun chiqindi bo‘lgan bu buyumlar uning olamni kashf etish jarayonida to‘plagan qimmatli kolleksiyasidir. Ularni tashlab yuborish o‘rniga kichik xazina qutisiga yig‘ing.'),
  ('4c758b24-b5bb-4fba-9fae-76aff0e5119d', 'Brokkoli kamuflyaji 🥦', 'Sho‘rvadagi yashil sabzavotlarni jarroh aniqligi bilan chetga ajratadimi? Ovqat tanlash odati avjiga chiqqan. Ovqatlanish rejasida sabzavotlarni ko‘rinmas qilib, rang-barang kotletlarga aylantiradigan maxsus va ayyorona retseptlarni kashf etish vaqti keldi.'),
  ('56a63f2b-c314-4614-a2a4-36e4a75775f5', 'Ertak rejissyori — uning o‘zi 🪄', 'Klassik kitoblardan ikkalangiz ham zerikdingiz. Aqlli ertaklarni oching va bu oqshom voqealar rivojini u boshqarishiga imkon bering. «Endi uchadigan mashina qayerga borsin?» deb so‘rang, o‘zi to‘qigan bema’ni yakun bilan uxlab qolsin.'),
  ('4cbe2cb0-5188-4114-8447-b099245e7121', 'Dadaning parvoz rejimi ✈️', 'Uyda energiyasini chiqarolmay, yotishga qarshilik qilyapti. Dadasini yordamga chaqiring. U bolani havoga ko‘tarib, samolyot qilib o‘ynatganda, xona qahqahaga to‘ladi va to‘planib qolgan barcha jismoniy zo‘riqish bir necha soniyada yo‘qoladi.'),
  ('9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a', 'Hamjamiyatda yengil nafas olish 💬', 'Juda charchadingiz va o‘zingizni dunyodagi eng sabrsiz ona deb his qilyapsizmi? Darhol Anacan hamjamiyatini oching. Boshqa onalar ham xuddi shunday bema’ni injiqlik xurujlarini boshdan kechirayotganini o‘qish — eng katta ruhiy tayanchdir.'),
  ('bd33d5a6-7358-4409-91cf-48f9ce76cb44', 'Cheksiz «Nega?»lar girdobi 🌪️', 'Qushlar nega uchadi?, Suv nega ho‘l qiladi?, Nega — nega?... Savollar poyezdi shiddat bilan ustingizga bostirib keladi. Charchasangiz ham, unga mantiqli va qisqa javoblar bering. U koinot sirlarini sizning ovoz ohangingiz orqali o‘rganadi.'),
  ('5940af77-4cae-40d5-a543-2bf3a6668855', 'Tabiat qo‘yniga qochish ⛅', 'To‘rt devor orasida qolish uning ham, sizning ham jahlingizni chiqardi. Uydagi tartibsizlikdan charchadingiz. Ob-havo va kiyim vositasini tekshirib, darhol parkka yo‘l oling. Ochiq havoda erkin yugurish kichkintoyning eng kuchli injiqlik xurujlarini ham bir zumda to‘xtatadi.'),
  ('7886ad64-9846-4990-9753-652093d6bac5', 'Noto‘g‘ri rang fojiasi 🔴', 'Suvni ko‘k emas, qizil stakanda berganingiz uchun qiyomat qo‘pdimi? Bu injiqlik emas, u shunchaki siz qo‘ygan chegaralarni va dunyoni boshqara oladimi-yo‘qmi, sinab ko‘rmoqda. Qaysarlik qilmay, stakanni almashtiring va kuchingizni asrang.'),
  ('bfa1d504-f493-414c-a978-4ad885726ef7', 'His-tuyg‘ularingizni erkin qo‘yib yuboring 📝', 'Uyda qanchalik charchayotganingizni hech kim ko‘rmayaptimi? Kayfiyat kundaligi — eng sokin sirdoshingiz. Bugun sizni aqldan ozdirgan barcha tafsilotlarni unga yozing va miyangiz qanday yengillashganini his qiling.'),
  ('1800a436-63cf-4ef5-8469-ebb0dffa942d', 'Sun’iy intellekt, haqiqiy yechim 🤖', 'Farzandingizda g‘alati bir odat paydo bo‘ldi (masalan, sochini barmog‘iga o‘rash) va internetdagi maqolalar sizni qo‘rqitib yubordimi? Shoshilmang. Anacan AI’dan buning pediatrlar tasdiqlagan asl sababini so‘rang va ortiqcha vahimadan xalos bo‘ling.'),
  ('3f147988-5fe0-4104-b53b-bcd1de9eb553', 'Bekinmachoq mantig‘i 🙈', 'U xona o‘rtasida ko‘zlarini qo‘llari bilan berkitib, uni topishingizni kutyapti! 3 yoshli bolaning mantig‘i: men sizni ko‘rmasam, siz ham meni ko‘rmaysiz. Uning bu beg‘ubor tasavvuriga ishongandek bo‘lib, xona bo‘ylab shovqin bilan uni qidiring.'),
  ('e71a10b9-dee7-4968-a1f7-387196804ef0', 'Chiroqlarni o‘chiring, uyqu kelsin 🌙', 'Tezroq uxlab qolishi uchun yotishdan 1 soat oldin xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin (uyqu gormoni) faqat qorong‘i va texnologiyalarsiz muhitda tez ajraladi.'),
  ('2cc2d175-4d74-4e12-832a-3885acc3e55b', 'Raqamli xotira 🛒', 'Do‘konga borganingizda doim nimanidir unutib qoldirasizmi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni darhol o‘sha yerga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda hammasini aniq ro‘yxat bo‘yicha olib kelsin — miyangizni ortiqcha band qilmang.'),
  ('8949a363-0fca-4998-bc28-ec5b3f0fc9b2', '«O‘zim qilaman!» qoidasi 👟', 'U oyoq kiyimining bog‘ichini o‘zi bog‘lamoqchi, siz esa uydan chiqishga allaqachon 10 daqiqa kechikyapsiz. Shoshirmang. Uning rivojlanishi uchun buzilgan jadvaldan ko‘ra, zarar ko‘rmagan o‘ziga bo‘lgan ishonch muhimroq.'),
  ('b6dabad1-9ff8-435e-b107-865df601701d', 'Shivirlashning sehrli kuchi 🤫', 'U yotoqda shunchalik faolki, hech uxlamayapti. Ovozingizni ko‘tarish o‘rniga, birdan ohangingizni pasaytirib, shivirlab gapiring. Bola sizni eshitish uchun diqqatini jamlaganda, uning miyasi avtomatik ravishda uyqu rejimiga o‘tadi.'),
  ('222c5b3e-e10d-4be3-be74-5b7c060039a8', 'Tungi osoyishtalik 🛁', 'Kun bo‘yi yugurib, siz ham, u ham holdan toydingiz. Iliq vanna qabul qilayotganda fonda tinchlantiruvchi tabiat tovushlarini qo‘ying. Suvning uyg‘unligi hatto eng qaysar bolani ham chuqur uyquga tayyorlaydi.'),
  ('658a0f7f-5501-4d36-97c8-25ebf4c2bf93', 'Teginishlardan charchash 🔋', 'U kun bo‘yi ustingizga chiqadi, quchoqlashingizni xohlaydi va sochingiz bilan o‘ynaydi. Siz esa shunchaki biroz jismoniy bo‘shliq istaysiz. Teginishlardan charchash (touched out) — haqiqiy holat. Hech bo‘lmasa 15 daqiqaga bir xonada yolg‘iz qolishga haqqingiz bor.'),
  ('fd872988-ca1c-4392-86ef-3fa893d01f3e', 'Vanna oqova teshigidan qo‘rqish 🛀', 'Ilgari suvdan chiqishni istamaydigan bola to‘satdan vannadagi suv oqib ketadigan teshikdan qo‘rqib, yig‘lay boshladimi? Tasavvur rivojlangani sari asossiz qo‘rquvlar paydo bo‘lishi mumkin. Teshik ustini plastik o‘yinchoq bilan yopib, unga xotirjamlik va ishonch bering.'),
  ('380c78ab-6c26-4edf-8c80-e7615f9b4b80', 'Juftlik uchun tanaffus 🥂', 'Bola uxlab qoldi. Endi uy ishlarini bir chetga suring. Juftingiz bilan kamida 20 daqiqa davomida bola, muammolar va xarajatlardan boshqa istalgan mavzuda suhbatlashing. Siz ota-ona bo‘lishdan avval bir juftliksiz!'),
  ('752bc100-4fdb-4f78-84aa-dd9676151255', 'Jonsiz buyumlar bilan suhbat 🗣️', 'U bog‘dagi toshga yoki uydagi stulga jiddiy ohangda nimalarnidir gapiradi, hatto ularni koyiydi. Ramziy o‘yinlar orqali u atrofidagi dunyoni anglaydi. Rivojlanish kuzatuvchisida uning bu o‘ziga xos ssenariylarini albatta belgilang.'),
  ('7bfbea7d-ee3e-4b33-88e0-e90f78f2538d', 'Dadaning massaj seansi 💆‍♂️', 'Bugun ko‘p vaqt oyoqda qoldingiz, uning ortidan yugurib belingiz og‘rib ketdi. Bola uxlashi bilanoq juftingizdan yelkangizni 10 daqiqa massaj qilib berishini so‘rang. Siz uyning ustunisiz, ustunlar ham albatta tiklanishi kerak.'),
  ('14bae514-5bcb-45ca-923d-75a7333cefe5', 'Uyquni kechiktirish taktikasi ⏱️', 'Uxlash vaqti kelganida birdan chanqab qoladimi, hojatxonaga borgisi keladimi yoki devor bilan xayrlashadimi? Taymer o‘rnating. Qo‘ng‘iroq chalinganda hamma uxlaydi qoidasini qo‘llab, bu tuganmas xayrlashuvlardan sabr bilan xalos bo‘ling.'),
  ('4ec63d29-5d5a-4c61-aeca-3683d2926fad', 'Onaning oziq-ovqat zaxirasi 🥗', 'Uni to‘ydirish uchun turli taomlar o‘ylab topdingiz, ammo o‘zingiz yana och qoldingizmi? Sog‘lom retseptlar orasidan 10 daqiqada tayyorlanadigan, temir va kalsiyga boy tushlikni tanlang va o‘zingizga ham g‘amxo‘rlik qiling.'),
  ('d6b3a2c2-7743-47f8-927a-59220b3461a1', 'Kir yuvish yordamchisi 🧺', 'Siz kiyimlarni katta mehnat bilan taxlaysiz, u esa yordam beraman deb hammasini yana xonaga sochib tashlaydi. Jahlingiz chiqishi o‘rniga, ishni o‘yinga aylantiring: Qani, bu paypoqlarni savatga kim tezroq tashlar ekan?'),
  ('95036444-eb4a-4cd7-a33d-678f3daaa180', 'Avangard moda tushunchasi 👗', 'Qishki sviter ustidan yozgi shortik kiyib olib, yechishni istamayaptimi? Hechqisi yo‘q. Odamlar orasiga bir-biriga mos kelmaydigan kiyimda chiqqan bola, aslida, o‘z qarorini jasorat bilan himoya qilayotgan boladir. Uning irodasini sindirmang.'),
  ('98f4059e-feba-4e5c-88c8-f44ceadd630c', 'Tungi vahima siri 😭', 'Yarim tunda ko‘zlari yumuq holda yig‘lab uyg‘ondimi va hech kimni eshitmayaptimi? Yig‘i tahlili orqali aniqlang; agar bu tungi vahima bo‘lsa, uni uyg‘otishga urinmang. Shunchaki yonida bo‘lib, jimgina o‘zini xavfsiz his qilishiga yordam bering.'),
  ('bfca2126-084c-4371-a225-6bbeaa8fe2d1', 'Ob-havo ogohlantirishi ⛅', 'Sayrga chiqayotganda derazadan qarab aldanmang. Ob-havo va kiyim yordamchisi orqali tashqaridagi haqiqiy shamol va haroratga eng mos kiyimlar to‘plamini tanlab, uydan xotirjam va tayyor holda chiqing.'),
  ('25567149-e2e9-4c4d-aaff-501c9547f638', 'Hamjamiyat ko‘magi 💬', 'Siz juda charchagansiz va hech kimga hech narsani tushuntirishni istamayapsiz. Anacan Hamjamiyatiga kirib, shunchaki kuzatuvchi bo‘ling. Boshqa onalar ham xuddi shunday charchayotganini ko‘rib, yolg‘iz emasligingizni his qilish eng yaxshi terapiyaga aylanadi.'),
  ('3df12920-0213-48db-ae96-b67ec62ae28a', 'Jonli konsert va qo‘shnilar 🎤', 'U qo‘liga qoshiq olib, xonaning o‘rtasida bor ovozi bilan baqirib qo‘shiq aytadi. Qo‘shnilar nima deb o‘ylashi sizni tashvishga solmasin. Uyingizda bir yulduz ulg‘aymoqda, siz esa shunchaki olqishlang.'),
  ('3f3676c6-cf62-4752-a389-70e0f348c529', 'Musiqa bilan uyquga ketish 🎶', 'Kechga yaqin hech qanday sababsiz boshlanadigan injiqliklarni mayin klassik musiqa bilan tinchlantirib ko‘ring. Ko‘pincha bu oddiy, ammo samarali usul uyda mo‘jiza yaratib, xonaga osoyishtalik olib kiradi.'),
  ('3e411b4b-9fe8-4f71-93e2-682182a18dba', 'Ekran vaqti uchun aybdorlik hissi 📺', 'Bugun ishlaringiz sababli unga odatdagidan ko‘proq multfilm ko‘rishga ruxsat berdingiz va endi vijdoningiz qiynalyaptimi? O‘zingizni ayblamang. Ba’zan raqamli enaga sizni ruhiy tushkunlikdan asraydigan yagona yechim bo‘lishi mumkin.'),
  ('66770f83-ef83-4481-9f8c-e9788791f68a', 'Telefonni yashirish operatsiyasi 📱', 'Telefoningizni qayerga qo‘yganingizni topa olmaysiz, birozdan keyin esa u o‘yinchoqlar qutisidan chiqadi. Chaqalog‘ingiz diqqatingizni telefon bilan bo‘lishishni istamaydi. Qurilmani chetga qo‘yib, unga 15 daqiqa davomida chalg‘imasdan e’tibor qarating.'),
  ('b18d81af-044b-40e7-b55d-b23baee972a4', 'Sukunatning raqamli o‘lchovi 🤫', 'U nihoyat uxlab qoldi! Uyni qamrab olgan sukunatga ishonolmaysiz. Ovoz o‘lchagichni yoqing va ekrandagi 0-10 desibel ko‘rsatkichiga qarab, miyangiz asta-sekin dam olayotganini ko‘z bilan his qiling.'),
  ('09d17b10-a60b-4930-b773-b0f5bb7e0366', 'O‘yinchog‘imni bermayman! 🧸', 'Bog‘dagi sirpanchiqda yoki qum maydonchasida hech kimga joy berishni istamaydi, o‘yinchoqlarini mahkam quchoqlab oladi. Bu xudbinlik emas, balki o‘z chegaralarini himoya qilishdir. Uni bo‘lishishga majburlamang, aksincha, navbat bilan o‘ynashni o‘yin tarzida o‘rgating.'),
  ('0a13d571-0f47-4b38-ba09-6279a4e6c3b5', 'Qorong‘ilikka chorlov 🌙', 'Yotoqxonadagi chiroqlar o‘chirilganda bezovta bo‘ladimi? Xonaning bir burchagiga iliq rangli kichik tungi chiroq qo‘ying. Xonaning qolgan qismi esa chuqur uyqu uchun butunlay qorong‘i bo‘lishi kerak.'),
  ('f1a7ace3-b71a-47a5-8150-e29d91b1d2f6', 'Ona charchaganida 🛑', 'Siz robot emassiz. Agar bugun ovqat pishirishga kuchingiz bo‘lmasa, tayyor ovqat buyurtma qiling yoki shunchaki makaron qaynatib oling. Mukammal ona bo‘lish hamma ishni yolg‘iz bajarish degani emas. O‘zingizga bunga ruxsat bering.'),
  ('012a4a46-c01f-4202-b7ec-b6dfb922b323', 'Ro‘yxatdagi syurpriz 🛒', 'Do‘konga borishdan oldin Xaridlar ro‘yxatini ochdingiz va u ortingizdan kelib, telefon ekranini bosib, ro‘yxatga nimalarnidir yozib qo‘yganini ko‘rdingiz. Ha, u sizning raqamli hayotingizdan ham nusxa olyapti!'),
  ('0f7001d8-21ca-493f-95e3-7b29b5f52d2b', 'Kayfiyat kundaligidagi e’tirof 📝', 'Telefoningizni qo‘lingizga oling. Ijtimoiy tarmoqlarda boshqalarning hayotini tomosha qilib o‘tirish o‘rniga, Kayfiyat kundaligini oching va uning bugun qilgan eng kulgili ishini kelajak uchun yozib qo‘ying. Raqamli terapiya ish beradi.'),
  ('507a4882-997e-48f9-8d0c-a6ff5f18c3ac', 'Advokatdek savdolashish 🗣️', '«Yana atigi 5 daqiqa o‘ynay, keyin kiyinaman», deyaptimi? U allaqachon siz bilan professional tarzda kelishishga urinmoqda. Nutqining rivojlanishi a’lo, ammo o‘z chegaralaringiz va qoidalaringizni mehr bilan saqlashni unutmang.'),
  ('982b6e37-c6cb-46f9-bd93-9fafd76bcda8', 'Sokinlik vaqti 🥱', 'Kunduzgi uyquga yotishni istamay, yig‘layaptimi? Majburlamang. Xonadagi chiroqlarni xiralashtirib, «Jim kitob varaqlash vaqti»ni e’lon qiling va ikkalangizga ham dam beradigan yangi odat yarating.'),
  ('dd274cad-cc38-4230-a074-0f529d065804', 'Bugun buni yemayman 🥣', 'Kecha ishtaha bilan yegan sho‘rvasini bugun og‘ziga ham olmayaptimi? Agar tishlari bilan bog‘liq muammo bo‘lmasa, bu shunchaki irodangizni sinashdir. Ovqatlanish rejasida xuddi shu vitaminlarni ta’minlaydigan boshqa retseptlarni ko‘rib chiqing.'),
  ('ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526', 'Dadaning g‘alati ovozlari 🤡', 'Sizning urinishlaringiz endi ish bermay qolganida, dadasining g‘alati ovozlari va kulgili yuz ifodalari vaziyatni darhol qutqaradi. Kechki injiqlik paytida vazifani darrov unga topshiring, o‘zingiz esa chetdan dam olib tomosha qiling.'),
  ('805b4060-d925-4469-abb9-000b87b286a1', 'Tabiat topishmog‘i 🍁', 'Uydagi zerikarli muhit ikkalangizni ham siqayaptimi? Parkka borib, eng g‘alati shakldagi toshni topish vazifasini bajaring. Tabiat uning uchun eng katta laboratoriya bo‘lib, barcha stressini yo‘qotadi.'),
  ('88ec7e91-36e6-4aab-9210-fc0f8e69cab3', 'Xayoliy mehmonlar dasturxon atrofida ☕', 'Bo‘sh piyolani sizga uzatib, «Choy iching», deyaptimi va xonada yo‘q do‘sti bilan gaplashyaptimi? Bu tasavvur rivojlanishining haqiqiy durdonasidir. Xonaning bir burchagida kechayotgan bu tomoshani buzmang, siz ham o‘sha choyni iching.'),
  ('9c237165-d4a6-41d4-ba0a-333830a89409', 'Aqlli ertakdagi men 🪄', 'Klassik kitoblarni yodlab bo‘lgansiz. Aqlli ertaklarni oching, bosh qahramon sifatida farzandingizni, zabt etiladigan joy sifatida esa uning xonasini tanlab, o‘zgacha uyqu mashg‘ulotini yarating.'),
  ('62114884-cb2a-44c8-ab0b-33ab815b8e09', 'Vannadagi sulh 🛀', 'Suv bilan o‘ynash shunchalik zavqliki, hatto barmoqlari burishib ketsa ham vannadan chiqishni istamaydi. Uni 5 daqiqa oldin ogohlantirib, taymerni yoqing. «Qo‘ng‘iroq chalinganda chiqamiz» qoidasi ko‘pincha ish beradi.'),
  ('9f52c47e-5431-4d83-b54d-9c8d7cbf5228', '«Qo‘limdan ushlamang!» erkinligi 🚶‍♂️', 'Ko‘chada qo‘lingizdan ushlashni qat’iyan rad etib, erkin yugurishni istaydi. Xavfsiz joylarda unga bunday erkinlikni bering. Uni ko‘zdan qochirmang, dunyoni o‘z qadamlari bilan zabt etishiga imkon bering.'),
  ('d319859d-6f77-4ec4-b4f9-90c9441fac9e', 'Rivojlanish izlari 📈', '3 yosh davrida uning motorikasi, so‘z boyligi va hissiy intellekti tez o‘zgaradi. Uning kichik kashfiyotlarini unutmaslik uchun ularni muntazam ravishda Rivojlanish kuzatuvchisiga qayd etib, arxivlab boring.'),
  ('01326cb0-274c-49ad-8b92-7ce1373a0568', 'Uzr so‘rab, yana o‘sha ishni qilish 🧸', 'Biror kishini urgani yoki nimanidir sindirgani uchun chin dildan uzr so‘raydi-yu, ammo 5 daqiqadan keyin aynan o‘sha harakatni yana takrorlaydimi? U hali o‘z impulslarini boshqara olmaydi. Qoidani sabr bilan qayta-qayta tushuntiring.'),
  ('1efb2536-bf55-4365-890d-581fbbac3193', 'Dardlashishga ehtiyoj 💬', 'Murakkab qaror qabul qilishingiz kerakmi? (Bog‘cha, tuvakka o‘rgatish, uyqu). Anacan hamjamiyatidagi tajribali onalarning maslahatlari hech bir kitobda yozilmagan, hayotiy va eng amaliy yechimlardir.'),
  ('d2d2c46d-7705-4c59-b1ff-a6a3d0986863', 'Ertak yakunini uning o‘zi yozsin 🪄', 'Klassik kitoblardan ikkalangiz ham zerikdingiz. Bu safar Aqlli ertaklarda hikoya qanday yakunlanishini farzandingiz tanlasin. «Seningcha, qahramonga kim yordam berdi?» deb, uyqu oldidan uning tasavvuriga erkinlik bering.'),
  ('0efdad7b-f986-4a21-8e04-fc9cffca1b7d', 'G‘alati talaffuzlar 🗣️', 'So‘zlarni shu qadar g‘alati va o‘ziga xos ohangda aytadiki, kulmay iloj yo‘q. Uning ustidan kulib, xatosini tuzatmang, aksincha, diqqat bilan tinglang va shunchaki jumlaning to‘g‘ri shaklini takrorlab javob bering.'),
  ('6d1f309e-d64f-4916-a1e2-48f064024563', 'Do‘kondagi unutuvchanlik tashvishi 🛒', 'Xotirangizga ishonib do‘konga bordingiz-u, taglikni unutib qaytdingizmi? Bunday holatlar bo‘lib turadi. Barcha kerakli narsalarni darhol Xaridlar ro‘yxatiga yozishni odat qiling, raqamli xotirangiz sizga yordam bersin.'),
  ('b478188b-090e-49fa-8067-44d7985fc9d2', 'His-tuyg‘ularingizni qog‘ozga tushiring 📝', 'Shunchalik charchaganingizni hech kim sezmayaptimi? Kayfiyat kundaligi sizni tinglash uchun doimo yoningizda. Bugun asabingizga tekkan barcha mayda-chuydalarni unga yozing va xayolingizni tozalang.'),
  ('51755ad7-f4a2-46b5-9170-1977fdac0046', 'Uyqu gormoni uchun sharoit 🌙', 'Tezroq uxlab qolishi uchun uyqudan 1 soat oldin xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Uyqu gormoni faqat qorong‘i va texnologiyalarsiz muhitda ishlab chiqariladi.'),
  ('556d15ad-f396-4daf-9a38-c5bd773f19f0', 'Bog‘dagi erkinlik 🌳', 'To‘rt devor orasida qolish uni tajanglashtiradi. Ob-havo va kiyim yordamchisi orqali tashqaridagi shamolga eng mos kiyimlar to‘plamini tanlab, bog‘ga chiqing. Qumga belansin, yugurib borayotib yiqilsin. Erkinlik uning rivojlanishi uchun eng yaxshi doridir.'),
  ('b2f0448e-4bda-4f45-8af5-d1f543150cda', 'Kutilmagan quchoq 💖', 'Xonaning o‘rtasida o‘ynab turganida birdan sizga qaraydi-da, yugurib kelib bo‘yningizdan quchoqlaydi. Bu barcha uyqusiz tunlar va charchoqlarga arziydi! Shu lahza baxsh etgan chuqur va betakror huzurdan zavqlaning.'),
  ('37e65e72-e2dc-4492-b8ea-92aeab4db745', 'Sog‘lom ona, sog‘lom bola 🥑', 'Kundalik yugur-yugurda tushlikni oyoq ustida yemang. O‘tirib, zavq bilan temir va kalsiyga boy noodatiy salat tayyorlab yeng. Sizning energiyangiz bu uyning motoridir, uni asrang.'),
  ('9a78401e-398c-45fd-a3a7-dae1cd59ed31', 'Sukunat tasdig‘i 🤫', 'Shovqinli kundan keyin, bola uxlagach, Ovoz o‘lchagich yordamida xonadagi sukunatni o‘lchang. Nolga yaqinlashayotgan raqamlarni ko‘rishning o‘zi ona miyasi uchun eng yaxshi vizual massajdek ta’sir qiladi.'),
  ('ba7f66f9-da13-4eea-9e4a-a968d14f269b', 'Ovqat tayyorlashga aralashish 🧑‍🍳', 'Siz xamir yoyayotganingizda, u albatta yoningizga stul qo‘yib, jarayonga aralashadi. Unga o‘zining plastik idishiga un sepishiga ruxsat bering. Oshxona iflos bo‘ladi, ammo uning jiddiy va ishchan yuz ifodasi shuncha tozalashga arziydi.'),
  ('06f0acb2-a541-42e5-8b33-ed2285d3285f', 'Bir-biringizga minnatdorlik bildiring 🥂', 'Og‘ir kunni ortda qoldirdingiz. Bola uxlagach, juftingiz bilan bir piyola choy quyib, Bu bo‘ronli kunda siz menga juda ko‘p yordam berdingiz, deb minnatdorlik bildiring. Jamoaviy ruh mana shunday shakllanadi.'),
  ('4217bad1-d028-470b-a2a2-ceacb5b15105', 'Sun’iy intellekt, haqiqiy javob 🤖', '3 yosh inqirozining ilmiy va pediatrlar tasdiqlagan sabablari nimalar? Internetdagi qo‘rqinchli izohlarni o‘qish o‘rniga, darhol Anacan AI-dan bolaning psixologiyasi haqida aniq va professional tahlil so‘rang.'),
  ('50050f6d-75e8-48b1-9632-bcebb31ce6fa', 'Sensorli zo‘riqish 🔋', 'U kun bo‘yi ustingizga tirmashdi, sochingizni tortdi, shovqin qildi. Asab tizimingiz qizil signal bermoqda. Teginishlardan charchash mutlaqo real holat. Bolani turmush o‘rtog‘ingizga berib, xonaga kirib dam oling.'),
  ('354da7a1-73e7-4191-ab3d-5f7d75ac4224', 'Vaqt tushunchasi shakllanmoqda ⏱️', '«Ertaga», «kecha», «keyin» so‘zlarini tez-tez, ammo ba’zan noto‘g‘ri o‘rinda ishlatyaptimi? Unda vaqtni idrok etish qobiliyati shakllanmoqda! Uning bu urinishlarini tabassum bilan tinglang.'),
  ('8b9fda41-95cb-4937-8a79-67166a02c4b7', 'Ona uchun tanaffus ☕', 'Bolangiz mustaqil o‘ynayotganida darhol uy yumushlariga shoshilmang. Xonadagi tartibsizlik hech qayerga qochmaydi, ammo sizning quvvatingiz tugashi mumkin. O‘tirib, issiq qahvangizni iching.'),
  ('c1a7e066-6918-4641-ab6d-c5c20c553974', 'Karavotdan qochish rejasi 🛌', 'Beshigidan oshib chiqishga urinyaptimi? Xavfsizlik uchun xonani yana bir bor ko‘zdan kechiring. Katta bolalar karavotiga o‘tish vaqti yaqinlashmoqda.'),
  ('46401ae3-aa9a-4ec9-afa2-b6cab38572ff', 'Xayoliy ssenariylar 🧸', 'O‘yinchoqlariga ovqat berib, ularni davolayaptimi? Ramziy o‘yinlar empatiyaning asosidir. Rivojlanish kuzatuvchisida bu kognitiv sakrashni faxr bilan qayd eting.'),
  ('4cba464d-475d-46de-93c9-1a54b6d0a768', 'Sehrli tungi muhit 🪄', 'Uxlab qolishga qiynalyaptimi? Aqlli ertaklarda tishlarini yuvadigan qahramon ayiqcha haqida hikoya yaratib, yangi odatlarni ertakka aylantiring.'),
  ('7ef518fa-cecf-4467-bd34-eb7fb3a21761', 'Bog‘dagi muloqot 🌳', 'Boshqa bolalar bilan o‘ynashdan ko‘ra, ularning yonida o‘zi alohida o‘ynayaptimi? Parallel o‘yin bu yosh uchun mutlaqo tabiiy. Uni majburlamasdan, ijtimoiylashishini qo‘llab-quvvatlang.'),
  ('7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3', 'Teskari kiyinish faxri 🧦', 'Paypoqning tovoni oyog‘ining ustida turibdi, ammo uni o‘zi kiygani uchun faxrlanib yuribdi. Hech ham aralashmang. Undagi «men uddaladim» tuyg‘usi chiroyli yoki to‘g‘ri kiyinishdan million marta qadrliroq psixologik poydevordir. Mayli, kunini shunday o‘tkazsin.'),
  ('ca2fd133-6b0b-4852-a4b2-b830a12f0bc0', 'Ona uchun oflayn daqiqalar ☕', 'U o‘zi mustaqil ravishda pazl yig‘yapti va 10 daqiqadan beri jim. Siz esa bu paytdan uyni yig‘ishtirish uchun foydalanmoqchisiz. Yo‘q! Borib, divanga cho‘ziling. Kechgacha shu sur’atga bardosh bera olishingiz uchun sizning ham quvvatingiz to‘lishi kerak.'),
  ('e264b682-e7a9-4579-80a1-6e47fe7bccb3', 'Qorong‘ilik bilan do‘stlashish 🐰', 'Uxlashni istamay, xonadagi soyalardan qo‘rqayotganini aytyaptimi? Xonani butunlay qorong‘i qiling va devorda qo‘llaringiz yordamida qush, it shaklidagi soyalarni yarating. Qo‘rquvni o‘yinga aylantirib, unga qorong‘ilik bilan do‘stlashish va tasavvurini boshqarishga yordam bering.'),
  ('03f9e2c0-9e7a-47b1-892e-0261f73bfa13', 'Sun’iy intellekt va xavotirlar 🤖', 'Farzandingiz hali ham ayrim harflarni to‘g‘ri talaffuz qila olmayotgani sizni xavotirga soldimi? Internetdagi vahimali forumlarni yoping. Anacan AI’dan 38 oylik davrda nutq rivojlanishi me’yorlari haqida so‘rab, ilmiy va hayotiy haqiqatga mos javob oling.'),
  ('8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9', 'Sen bola bo‘l, men esa ona 👩‍👧', 'Rollarni almashtirish o‘yini boshlandi! U sizga «bu yerga kel», «ovqatingni ye», «yig‘lama» deb ko‘rsatmalar beryapti. Uning yetakchilik tajribasini mamnuniyat bilan qabul qiling va e’tiroz bildirmay, uning bolasi rolini o‘ynang. Bu empatiya rivojlanishining eng asosiy yo‘llaridan biridir.'),
  ('b97073a4-f745-41b1-953a-0e776ded1591', 'Chiroqlarni o‘chiring, uyqu kelsin 🌙', 'Tezroq uxlab qolishi uchun yotishdan 1 soat oldin xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin qorong‘i va texnologiyalarsiz muhitdagina tez ajralib chiqadi.'),
  ('85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff', 'Brokkoli detektivi 🥦', 'Sho‘rva ichidagi bittagina yashil sabzavotni topib, ovqat yeyishdan bosh tortyaptimi? Ovqatlanish rejasida sabzavotlarni rangli makaron bilan aralashtirib, uning e’tiborini chalg‘itish va foydali mahsulotlarni yashirishning eng mazali usullarini toping.'),
  ('9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21', 'Tuyg‘ularni tan olish 📝', 'Kun bo‘yi hamma narsaga yo‘q deyaverganingiz uchun o‘zingizni yomon his qilyapsizmi? Kayfiyat kundaligini oching. Bugun ichingizdagi eng qorong‘i qaniydi yolg‘iz bo‘lsam degan fikrni hech qanday filtrlarsiz yozing. O‘zingizni ayblamang, har bir ona ba’zan charchaydi va hammasidan qochib ketishni istaydi.'),
  ('df69592f-4c0f-4591-8df6-51164eef4e12', 'Bu mening aybim emas! 🤷‍♂️', 'Suvni ataylab yerga to‘kdi-yu, aybni stolga ag‘darib, Stol sirg‘alib ketdi dedi. Bu yolg‘on emas, balki bola miyasining mas’uliyatdan qochish va o‘zini himoya qilish instinktidir. U bilan tortishmang, Kel, stolga yordam berib, birga artamiz deb, ranjitmasdan mas’uliyatni o‘rgating.'),
  ('7ac03452-73e8-4680-9a3a-f2917f96ee7f', 'To‘rt devor psixologiyasi ⛅', 'Uy sizni siqmoqda, bola esa tajovuzkor bo‘lib bormoqda. Ob-havoni tekshiring, mos kiyimlarni tanlang-da, eshikni yopib, parkka shoshiling. Kislorod va erkin harakatlanish ham uning miyasi, ham sizning charchagan asablaringiz uchun eng yaxshi detoks bo‘ladi.'),
  ('ab102c70-f16b-4f7f-8521-b11e20c36d7a', 'Kiyimlarni taxlash operatsiyasi 🧺', 'Siz katta mehnat bilan toza kiyimlarni taxlaysiz, u esa 2 soniyada ularning orasiga kirib, hammasini sochib tashlaydi. Xonada chuqur sukunat cho‘kadi... Asablaringiz taranglashdimi? Chuqur nafas oling. Sochilib yotgan kiyimlar uyumi ustiga o‘zingizni tashlab, bu tartibsizlikka kulgancha taslim bo‘ling.'),
  ('e3d6247b-8c6f-4322-9f82-93d3245cab38', 'Aqlli ertak rejissyori 🪄', 'Klassik kitoblardagi qahramonlardan ikkovingiz ham zerikdingiz. Aqlli ertaklarni oching va bu oqshom syujetni uning o‘zi o‘ylab topishiga imkon bering. Endi bu uchar dinozavr qayerga borsin? deb so‘rang, u o‘zi yaratgan xayolot olamida uyquga ketsin.'),
  ('62178f50-5d62-4afb-bacf-33c6e7bf5732', 'Dadaning parvoz rejimi ✈️', 'Uyda energiyasini sarflay olmay, yotmaslik uchun ming xil bahona topadi. Dadasini chaqiring. U bolani havoga ko‘tarib, samolyotdek uchirganda, xona qahqahaga to‘ladi, yig‘ilib qolgan barcha jismoniy zo‘riqish esa ter bilan birga chiqib ketadi.'),
  ('7338bae4-7d68-4f02-8b9f-7e3603f62bb9', '“Siz yomon onasiz!” zarbasi 💔', 'Istagan o‘yinchog‘ini olib bermaganingiz uchun yuzingizga qarab, yomonligingizni aytdimi? Ko‘nglingizga olmang. U hali his-tuyg‘ularini to‘g‘ri so‘zlar bilan ifodalay olmaydi, aslida esa “Men juda jahlim chiqdi va hafsalam pir bo‘ldi”, demoqchi. Ko‘zlariga qarab, shunchaki uning his-tuyg‘ularini tushunganingizni bildiring.'),
  ('c4d16b0b-f2b1-40f5-8462-8e7c3419883e', 'Do‘kondagi “Men haydayman” qaysarligi 🛒', 'Do‘kon aravachasini o‘zi haydamoqchi bo‘lib, uni peshtaxtalarga urib, hammaning e’tiborini tortadi. Aralashganingiz sari yig‘laydi. Aravachani birga haydashingizga imkon bering. Biror narsani unutmaslik uchun esa miyangiz kamroq charchashi maqsadida ilovadagi Xaridlar ro‘yxatini faol tuting.'),
  ('159b5a7f-d190-47d4-8cda-ba692f07b0d0', 'Ovoz o‘lchagichdagi sukunat 🤫', 'U nihoyat uxlab qoldi! Uyni qoplagan sukunat shu qadar chuqurki, quloqlaringiz shang‘illaydi. Ovoz o‘lchagichni yoqing va ekrandagi 0-10 desibel ko‘rsatkichiga qarab, miyangiz asta-sekin qanday tiklanayotganini ko‘z bilan his qiling.'),
  ('ece2fe16-c57e-4a1f-a594-5e39da1118d6', 'Hamjamiyatdagi dardkashlik 💬', 'Juda charchagansiz va hech kimga hech narsani tushuntirishni istamaysiz. Anacan Hamjamiyatiga kirib, shunchaki kuzatuvchi bo‘ling. Boshqa onalarning ham xuddi shunday charchagani va bolalarining kulgili injiqliklarini ko‘rish sizda “Men yolg‘iz emasman” degan tuyg‘uni uyg‘otib, eng yaxshi taskinga aylanadi.'),
  ('fabbf657-c431-4c98-ba31-613ca3dc8a47', 'Oshxonaning kichik oshpazi 🧑‍🍳', 'Siz xamir yoyayotganingizda, u albatta yoningizga stul qo‘yib, jarayonga aralashadi. Unga o‘zi uchun ajratilgan plastik idishga un sepishga ruxsat bering. Oshxona iflos bo‘ladi, ammo uning jiddiy, ishchan yuz ifodasi va “Men ham uddalay olaman” degan tuyg‘usi shuncha tozalashga arziydi.'),
  ('4c7e076f-90de-4c2c-ae58-d9d897931fd4', 'Kunduzgi uyqu tugadimi? ⏱️', 'Kechqurun uxlab qolishi 1 soatdan ko‘proq vaqt olyaptimi? Uyqu taymeri jadvaliga qarang. 3 yosh inqirozi davrida kunduzgi uyquni butunlay bekor qilish va kechki uyqu vaqtini ertaroqqa surish payti kelgan bo‘lishi mumkin.'),
  ('b52dda4e-86c5-4200-973f-b7fbeb8869cc', 'Tugamaydigan «Nega?» savollari 🌪️', 'Baliqlar nega yurmaydi?, Quyosh qayerga ketdi? Erta tongdanoq uning miyasi soatiga 100 ta savol tezligida olam sirlarini anglashga urinadi. Charchasangiz ham, unga mantiqli va qisqa javoblar bering. U koinot sirlarini sizning ovoz ohangingiz orqali o‘rganadi.'),
  ('c583d30d-5142-4b40-bcb3-399830284928', 'Ifloslanishga to‘liq ruxsat 🏖️', 'Loy va qum bilan o‘ynashni xohlayaptimi? Mayli, ifloslansin! Sensor rivojlanishni qo‘llab-quvvatlaydigan bunday mashg‘ulotlar uchun eng oson tozalanadigan jihozlarni Tavsiya etilgan mahsulotlardan toping va bolangizga erkin o‘ynash imkonini bering.'),
  ('0446eb50-5fac-4056-ad65-76a95baf67f3', 'Soya bilan jang 👻', 'Devordagi soyasidan qo‘rqib, ortingizga yashirinyaptimi? Tasavvur chegara bilmaydi. Xonani qorong‘ilashtirib, fonar yordamida qo‘llaringiz bilan devorda soya o‘yinlarini yarating.'),
  ('b090e002-92d1-408a-8249-476d9566115b', 'Musiqa bilan uyquga tayyorgarlik 🎶', 'Kechga yaqin hech bir sababsiz boshlanadigan injiqliklarni mayin klassik musiqa bilan tinchlantirib ko‘ring. Ko‘pincha bu oddiy, ammo samarali usul uyda mo‘jiza yaratib, xonaga chuqur va orombaxsh sokinlik olib kiradi.'),
  ('ba177a78-642c-483b-9a15-4d4a68a758af', 'Tananing ogohlantirishi 🩸', 'Sababsiz asabiylik va charchoqqa taslim bo‘lmang. Hayz kuzatuvchisiga qarang — tanangiz sizga signal beryapti. O‘zingizni ayblash o‘rniga, magniyga boy yegulik bilan hordiq chiqaring.'),
  ('66da20be-59e4-4c6a-b44a-168bd86bf8c2', 'Ko‘zgu qarshisidagi teatr 🎭', 'U ertalab ko‘zgu qarshisiga turib, yig‘lash, kulish va hayratlanish kabi turli yuz ifodalarini mashq qiladi. U o‘z his-tuyg‘ularini qanday ifodalashni va bunda yuzining qanday ko‘rinish olishini kashf etmoqda. Bu ajoyib aktyorlik tomoshasini uzoqdan jilmayib kuzating.'),
  ('69d26c82-f68d-4fca-acec-f2cabf4901f8', 'Dadaning sehrli qo‘llari 🫂', 'Kun bo‘yi ko‘tarib yurishdan qo‘llaringiz uzilib tushay deydi, ammo u yana quchoqqa olishingizni xohlaydi. Dadasini chaqiring. Dadasining qo‘llarida uchish bolaning e’tiborga bo‘lgan ehtiyojini qondiradi, sizning qo‘llaringizga esa juda zarur bo‘lgan hordiqni beradi.'),
  ('b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6', 'Axlat emas, san’at 🎨', 'U xona o‘rtasida mayda qog‘oz parchalari va kesilgan iplardan ulkan san’at asari yaratibdi va uni tashlab yuborishingizga yo‘l qo‘ymayapti. Hamma joy ozoda bo‘lishi kerak degan istakni bir chetga suring. U yaratgan bu tartibsizlikni hurmat qiling, tozalash ertagacha kutishi mumkin.'),
  ('3613ef28-90fe-4c93-a13a-cc4ded2b5ad4', '«Men o‘zim!» qat’iyati 🛑', 'U oyoq kiyimining bog‘ichini o‘zi bog‘lamoqchi, siz esa uydan chiqishga allaqachon 10 daqiqa kechikyapsiz. Shoshilmang. Uning rivojlanishi uchun vaqt rejangiz buzilishidan ko‘ra, o‘ziga bo‘lgan ishonchi shikastlanmasligi muhimroq. Unga urinib ko‘rish imkonini bering.'),
  ('67736a86-09e4-4211-ade6-1d5d48e8a05f', 'Shivirlab aytilgan hikoyalar 🌙', 'Bugun ko‘p gapirganingizdan ovozingiz bo‘g‘ilib, o‘pkangiz ham charchadi. Chiroqlarni o‘chiring, uning yoniga yoting va kun davomida bo‘lgan voqealarni qulog‘iga shivirlab aytib bering. Shivirlash uning diqqatini jamlaydi va miyasini gipnotik tarzda chuqur uyquga tayyorlaydi.'),
  ('8d9fad31-a8cd-481f-953a-35d411108040', 'Mukammal ona haqidagi afsonalar 🛑', 'Ijtimoiy tarmoqlardagi bolalar ranglarni bilib, raqamlarni ingliz tilida sanayapti-yu, sizning bolangiz buni xohlamayaptimi? Darhol taqqoslashni bas qiling! Har bir bolaning rivojlanish sur’ati o‘ziga xos va turlicha. U o‘z sur’atida mukammaldir.'),
  ('07209316-984c-477d-a3c0-ff2c7202c5fa', 'Bog‘cha haqida o‘ylar 🏫', 'Farzandingiz ijtimoiylashishga ko‘proq ehtiyoj sezayotganini payqayapsizmi? Bog‘chaga borish uchun ayni vaqtmi? Anacan hamjamiyatiga qo‘shilib, boshqa onalarning moslashuv bo‘yicha haqiqiy tajribalarini o‘qing va qaror qabul qilishni osonlashtiring.'),
  ('3f7992d5-c092-46f7-84f8-f10e51f36593', 'To‘satdan jahli chiqishi 💥', 'O‘ynab turganida birdan jahli chiqib, o‘yinchoqlarini uloqtirdimi? U hali his-tuyg‘ularini boshqara olmaydi. Baqirish o‘rniga, Jahling chiqqanini ko‘ryapman, kel, birga chuqur nafas olamiz, deb hamdardlik bildiring va u bilan aloqada bo‘ling.'),
  ('a376f906-e66c-4618-827e-79f3b75ebd16', 'Yotoqxonada chiroqlar o‘chganda bezovta bo‘ladimi? 🌙', 'Xonaning bir burchagiga iliq rangli kichik tungi chiroq qo‘ying. Xonaning qolgan qismi esa chuqur uyqu uchun butunlay qorong‘i bo‘lishi kerak.'),
  ('171bedf4-3516-44a5-9404-c089661d5bbd', 'Jonsiz buyumlar bilan suhbat 🗣️', 'Bog‘da toshga yoki uyda stulga jiddiy ohangda nimalarnidir gapiradi, hatto ularni koyiydi. U ramziy o‘yinlar orqali dunyoni anglaydi. Rivojlanish kuzatuvchisida uning bunday o‘ziga xos ssenariylarini albatta qayd eting.'),
  ('a74f3aea-565f-455f-bdbe-9ee44f6c7e35', 'Iliq suv mo‘jizasi 🛀', 'Ba’zan hech narsa yordam bermaydi, u shunchaki hamma narsaga yig‘layveradi. Uni iliq suv to‘ldirilgan vannaga tushiring va suvga biroz ko‘pik qo‘shing. Suvning g‘aroyib, taranglikni ketkazuvchi kuchi butun xonaga va uning asab tizimiga bir zumda xotirjamlik olib keladi.'),
  ('b4c6b7ac-81bd-476f-9816-9e8c14627206', 'Ob-havo ogohlantirishi ⛅', 'Sayrga chiqayotganda derazadan qarab xulosa qilishga shoshilmang. Ob-havo va kiyim bo‘yicha yordamchi orqali tashqaridagi haqiqiy shamol va haroratga eng mos kiyimlar to‘plamini tanlang. Shunda uydan xotirjam va tayyor holda chiqib, bolaga energiyasini ochiq havoda sarflash imkonini yaratasiz.'),
  ('1a2422fa-5d4e-4bbc-9f26-d69dd838496d', 'So‘zlarni ataylab o‘zgartirish 🗣️', 'Mashina o‘rniga o‘jarlik bilan «shamina» deydi va sizning kulishingizni kutadi. U hazil tuyg‘usini kashf etmoqda. Kuling, ammo miyasi to‘g‘ri variantni ham eslab qolishi uchun har safar to‘g‘ri talaffuzni muloyimlik bilan ta’kidlashni unutmang.'),
  ('21b5ead3-32a1-4d0e-96a9-1e38bf19fcec', 'Ona, o‘zingiz ham ovqatlaning 🥗', 'Uni ovqatlantirish uchun tuxumni 4 xil usulda pishirdingiz, ammo o‘zingiz nima yedingiz? Sog‘lom retseptlardan 5 daqiqada tayyor bo‘ladigan, temir va kalsiyga boy maxsus bir likopcha taom tayyorlab, o‘zingizni siylang va quvvatingizni asrang.'),
  ('cc6b3853-5963-47b7-b4f5-310bfd1919c2', 'Uyquni kechiktirish taktikasi ⏱️', 'Uxlash vaqti kelganida birdan chanqab qoladimi, hojatxonaga borgisi keladimi yoki devor bilan xayrlashadimi? Taymer o‘rnating. Qo‘ng‘iroq chalinganda hamma uxlaydi degan qoidani joriy etib, bu tuganmas xayrlashuvlardan sabr va xotirjamlik bilan qutuling.'),
  ('629ea652-62bd-4947-96b6-0e7f4cabb751', 'O‘yinchoqlar bilan yig‘ilish 🧸', 'Barcha ayiqchalari va mashinalarini qatorga terib, ularga barmog‘i bilan juda jiddiy tarzda nimanidir tushuntiryaptimi? Unda yetakchilik va diqqat ko‘nikmalari shakllanmoqda. Xonaning bir chetida turib, uning bu xayoliy yig‘ilishini bezovta qilmasdan, jimgina kuzating.'),
  ('8fdbd74e-0b03-4420-a816-6a0ea6ecdb73', 'Dadaning g‘alati tovushlari 🤡', 'Sizning usullaringiz endi ish bermay qolganida, dadaning hayvonlarga taqlid qilib chiqaradigan g‘alati tovushlari va kulgili yuz ifodalari vaziyatni darhol qutqaradi. Kechki injiqlik paytida navbatni unga bering va chetdan quvnoq qahqahalarni tomosha qiling.'),
  ('b32c30b6-11a0-4afc-aed3-bdfb0cc56622', 'Kunduzgi uyquga qarshi isyon 🥱', 'Yotishni istamay, yig‘layaptimi? Majburlamang. Xonadagi chiroqlarni xiralashtirib, Sokin kitob varaqlash soatini e’lon qiling va ikkalangizga ham orom beradigan yangi tartib yarating. Shunda siz ham, u ham dam oladi.'),
  ('2fc82c8d-f425-4306-866a-3f621177b592', 'Multfilm tanqidchisi 📺', 'Ko‘rgan multfilmini sizga o‘z grammatikasi bilan aytib beradi, kim qayerga ketganini jiddiy tushuntiradi. Uni diqqat bilan, hayratlangandek tinglang. O‘zini dunyodagi eng aqlli insondek his qilishiga imkon bering.'),
  ('63daef22-cfd1-421f-8f7d-267873d17f9e', 'Mukammallik bo‘lmaydi 🛑', 'Bugun hech narsa reja bo‘yicha ketmadimi? O‘zingizni ayblamang. Siz haqiqiy onasiz, ijtimoiy tarmoqlardagi filtrlangan illyuziya emassiz. Farzandingizga shunchaki tabassumingiz va quchog‘ingiz kerak.'),
  ('e3cb9a40-b6ca-4e32-b4da-ab6d4899625b', 'Tungi vahimaning siri 😭', 'Yarim tunda ko‘zlari yumuq holda yig‘lab uyg‘ondi va hech kimni eshitmayaptimi? Yig‘i tahlili orqali tekshiring; agar bu tungi vahima bo‘lsa, uni uyg‘otishga urinmang. Shunchaki yonida bo‘lib, indamay unga xotirjamlik va ishonch bering.'),
  ('10d94f4d-5823-4afc-963c-ff0397bf1a29', 'Shunchaki quchoqlang 🫂', 'Hech qanday o‘yin, kitob yoki ertak kerak emas. Bu oqshom uni shunchaki bag‘ringizga bosing, uning yoqimli hididan to‘yib nafas oling va qorong‘ida unga qanchalik qadrli ekanini pichirlab ayting.'),
  ('3860d960-f463-4c1e-873a-4917b9b7c101', 'Taqiqlangan so‘zlar 🤐', 'Qayerdandir eshitgan o‘sha yomon so‘zni kulib sizga qaytaryaptimi va munosabatingizni kutyaptimi? Eng kuchli qurolingiz — hech qanday munosabat bildirmaslik. Kulmang, jahlingiz chiqmasin, shunchaki e’tibor bermang. U tez orada bu so‘zni unutadi.'),
  ('fbd7d1b9-4e13-463d-80fa-fbbd34869d9e', 'Uyni yig‘ishtirmaslikka ruxsat 🌪️', 'Har kuni bir xil o‘yinchoqlarni yig‘ishdan charchadingizmi? Bugun yig‘ishtirmang! Uy muzey emas, unda hayot qaynaydi. Tartibsizlikka emas, farzandingizning erkin o‘rganish quvonchiga e’tibor qarating va dam oling.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('523ef85e-fa2f-49a1-b3f9-34f2d35d22a1'::uuid, 'Ob-havo razvedkasi ⛅', 'Tashqarida ob-havo qandayligi aniq emasmi? Ob-havo va kiyim tanlash vositasi derazadan ko‘rinmaydigan shamol tezligini aniqlab, mos kiyimlar uyg‘unligini bir zumda tavsiya qilsin.'),
  ('5b3dc48b-525e-45b8-ba47-dd1abb851741', 'Oyoq kiyimini o‘zi yechadi 👟', 'Uni kiyintirish endi kurashga aylanib qoldimi? U paypoq va oyoq kiyimini o‘zi tortib yechadi. Uning harakat ko‘nikmalariga qoyil qoling!'),
  ('cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8', 'Dadaning ko‘magi 🫂', 'Tunda chaqaloq uyg‘onganida bir safar siz, bir safar juftingiz tursin. Yukni bir jamoa bo‘lib, teng yarmiga bo‘ling.'),
  ('3522ca83-324c-49f9-ba7a-ffdc8c379ba2', 'Uyquni kechiktiruvchi hojatxona 🚽', 'Endi uxlab qoladi deganingizda, birdan hojatxonaga borgisi kelganini aytadi. Olib borasiz, ammo hech narsa qilmaydi. Bu uyquni kechiktirish san’atining eng nozik usullaridan biridir. Baqirmang, “Oxirgi marta boramiz va to‘g‘ri yotoqqa qaytamiz” degan chegarani aniq belgilang.'),
  ('676880bc-91f2-426e-9b15-e2ce61b68fc4', 'Yotoq sayyohi 🛏️', 'Tunni o‘z yotog‘ida boshlab, ertalab sizning yotog‘ingizda ko‘ndalangiga cho‘zilgan, oyoqlari esa yuzingizda turgan holda uyg‘onadi. Uning hududni shu tarzda egallashini kulib qabul qiling. Sizning iliq hidingiz uning uchun eng ishonchli makondir.'),
  ('bf74dbb7-0eae-47bc-acea-2beeb831e679', 'Qutining sehri 📦', 'Unga olib bergan qimmat va ovozli o‘yinchoqni bir chetga tashlab, 1 soatdan beri uning qutisi bilan o‘ynayaptimi? Bola miyasi tayyor ssenariylarni emas, tasavvuri bilan istagan narsaga aylantira oladigan bo‘sh buyumlarni yaxshi ko‘radi. Karton quti uning uchun kosmik kemadir, unga tegmang.'),
  ('267500b1-a84b-4046-a247-9d2097325550', 'Pastga qarang, u nimani kashf etmoqda? 👣', 'U yalangoyoq yurishdan, gilam yoki xonadagi toshlarga tegishdan zavqlanadi. Oyoq tagidagi nervlarning qo‘zg‘alishi uning muvozanati va harakat ko‘nikmalari uchun juda muhim, unga paypoqsiz yurishga ruxsat bering.'),
  ('2b6e6b05-f741-49ca-84e3-fa8deb8b2661', 'Juftlik uchun tanaffus 🥂', 'Bola uxlab qoldi. Endi uy ishlarini bir chetga qo‘ying. Juftingiz bilan kamida 20 daqiqa davomida bola va xarajatlardan boshqa istalgan mavzuda suhbatlashing. Siz nafaqat ota-ona, balki juftlik ham ekansiz!'),
  ('9d8da9d6-f615-4275-a01c-20687a161090', 'Do‘kondagi yordamchingiz 🛒', 'Do‘konga borganingizda eng kerakli narsani doim unutib qo‘yasizmi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni u yerga yozib qo‘ying, juftingiz ishdan qaytayotganda ro‘yxat bo‘yicha hammasini olib kelsin, siz esa boshingizni qotirmang.'),
  ('2b451101-7b49-4ea1-a25f-f07ea36f7e85', 'Kundalikka dardingizni to‘king 📝', 'Kimdir sizga «Uyda o‘tirib, nimaga charchaysiz?» dedimi? Darhol Kayfiyat kundaligini oching va butun jahlingizni barmoqlaringiz orqali ekranga to‘king. Soxta tabassum qilishdan ko‘ra, chin his-tuyg‘ularingizni yozish — terapiya.'),
  ('5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5', 'Sizga tushuntirib beraman! ☝️', 'U siz biladigan narsani juda jiddiy va bilimdon qiyofada sizga tushuntirib beradi. Shu tariqa u o‘z bilimini sinab ko‘rmoqda. Kulib yubormaslikka zo‘rg‘a chidayotgan bo‘lsangiz ham, uni jiddiy tinglang va fikrini tasdiqlang.'),
  ('62a5480b-e62d-48dc-a56f-7c512e104949', 'Sukunatning raqamli o‘lchovi 🤫', 'U nihoyat uxlab qoldi! Uyni qoplagan sukunatga ishona olmayapsiz. Shovqin o‘lchagichni yoqing va ekrandagi 0-10 detsibel ko‘rsatkichiga qarab, miyangiz asta-sekin dam olayotganini his qiling.'),
  ('42b797ef-b169-4515-ad62-c08b78bfdaca', 'Qishda yozgi isyon ❄️', 'Tashqarida shamol esyapti, ammo u baribir yozgi shortigini kiyishni talab qilmoqda. Tushuntirishga urinish — vaqtni behuda sarflash. Ob-havo va kiyim vositasini ochib, ekrandagi qalin kiyingan bola belgisini unga ko‘rsating. Qara, telefon ham bugun shim kiyishimiz kerakligini aytyapti, degan hiyla juda yaxshi ish beradi.'),
  ('74bf7168-d7dc-468c-87a3-562a3bef9f2a', 'Xayoliy tishlash 🍏', 'Qo‘lida hech narsa yo‘q, ammo oldingizga kelib, Ol, tishla, deya xayoliy olmani uzatadi. Rolli o‘yinlar — bolaning shaxsiyati shakllanadigan eng muhim maydonlardan biri. O‘sha bo‘shliqni ishtaha bilan qarsillatib tishlang va bu dunyodagi eng mazali olma ekanini tasdiqlang.'),
  ('d3d1367f-aa40-489c-9f91-b803403dff09', 'Derazadagi maxluq 👻', 'Tashqarida tebranayotgan daraxtning soyasi xonaga tushadi va u qo‘rqib, ortingizga yashirinadi. Xona chirog‘ini yoqmang. Qo‘lingizga fonar olib, soyaga qarating va Qara, bu shunchaki daraxtning raqsi, deya qo‘rquvni sehrli taassurotga aylantiring.'),
  ('2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6', 'Menga qarang! marafoni 👀', 'Ertalab uyg‘onishi bilan roppa-rosa 40 marta Oyi, menga qarang, dedimi? U sakraydi, aylanadi va sizning ma’qullashingizni kutadi. Nigohingizni telefondan uzib, atigi 3 daqiqa butun e’tiboringizni unga qarating va ajoyibsan, deng. Bunday uzluksiz e’tibor uning mehrga bo‘lgan ehtiyojini qondirish uchun yetarli bo‘ladi.'),
  ('4e536027-0b7a-4ac3-acef-a7ba874bd609', 'Onaning dangasalik qilish huquqi 🍕', 'Bugun hamma narsaga baqirgingiz kelyaptimi? Uy ag‘dar-to‘ntar bo‘lib yotibdimi? Tozalashni qo‘ya turing, oshxonaga ham kirmang. Tashqaridan pitsa yoki tayyorlash oson bo‘lgan biror yegulik buyurtma qiling. Mukammal ona bo‘lish haqidagi xayoldan voz keching, ruhiy salomatligingiz uyda tayyorlangan ovqatdan ancha qadrliroq.'),
  ('c57f5d91-caec-47eb-964d-abcee011e0e2', 'Juftlik komasi 📺', 'Bola uxlab qoldi! Nihoyat, turmush o‘rtog‘ingiz bilan film tomosha qilish uchun divanga o‘tirdingiz, ammo 10 daqiqadan so‘ng ikkalangiz ham uxlab qoldingiz. Bu — sizning haqiqatingiz. Bir-biringizga suyanib uxlab qolgan o‘sha charchagan, ammo yoqimli manzara — sevgining o‘zi.'),
  ('9ecbc8da-836b-48fc-a294-6aaa4bafb6f3', 'Yolg‘izlik sog‘inchi 🚪', 'Kun bo‘yi ustingizga chiqib, sizga yopishib oladigan boladan charchadingiz. Hojatxonaga kirib, eshikni yopdingiz va 5 daqiqaga yolg‘iz qoldingiz. Darhol Kayfiyat kundaligini oching, ichingizda to‘planib qolgan siqilish hissini ekranga to‘kib, yengil torting.'),
  ('acb8e717-26b4-427c-9df9-4c6aeb16734c', 'Hikoya rejissyori 🪄', 'Bu oqshom ovozingiz ham charchagan. Aqlli ertaklarni yoqing. Farzandingizga «Bugun qahramon sen bo‘lasan, fonda esa yomg‘ir yog‘adi», deb, unga mos, tinchlantiruvchi va o‘ziga xos ovozli muhit yarating va uni ohista uyquga kuzating.'),
  ('c58d19cd-28c0-452e-ab4b-85c75da1f2b0', 'Birinchi mantiqsiz hazil 🤡', '«It mashinaga mindi-yu, portlab ketdi!» deb, o‘z-o‘zidan qah-qah otib kuladi. Bunda hech qanday ma’no yo‘q, ammo u hazil tuyg‘usini endigina kashf etmoqda. Mantiq izlamang, uning beg‘ubor va quvnoq kulgisiga siz ham baralla qo‘shiling.'),
  ('0a22f56d-c8f3-477d-a3c0-1cf48a52b75f', 'Sirpanchiq siyosati 🛝', 'Bog‘da sirpanchiqning tepasida turib olib, boshqa bolalarga uchishga yo‘l bermayapti. Uyalib, uni qo‘pollik bilan pastga tortmang. Atrofdagilarga e’tibor bermay, unga navbat qoidasini muloyim ovozda eslating. U egalik hissini shu tarzda himoya qilmoqda.'),
  ('2e61e71c-40b9-4acb-82fb-ac9b3ee6a222', 'U endi chaqaloq emas! 🌟', 'U o‘z qarorlari, g‘aroyib savollari va ulkan qalbiga ega bo‘lgan to‘laqonli inson. Uning kuchli xarakterini sindirmay, to‘g‘ri yo‘naltirib ulg‘aytirayotganingiz uchun o‘zingizga katta rahmat ayting. Siz juda yaxshi uddalayapsiz.'),
  ('a5162fa5-e190-42b6-b85c-5309ce76b381', 'Shampansiz g‘alaba 🥂', 'Og‘ir kundan so‘ng stakanlarga oddiy issiq choy quying. Juftingiz bilan divanda yuzma-yuz o‘tirib, «Bugun ham o‘sha tartibsizlikdan omon chiqdik», deya stakanlarni urishtiring. Siz bu uyning ham qo‘mondonlari, ham bir jamoasisiz.'),
  ('2333a8bc-122b-4087-9603-3c895b2daf77', 'Ovqat tanlashda mantiq yo‘q. 🥦', 'Kecha ishtaha bilan yegan sho‘rvasini bugun og‘ziga ham olmayaptimi? Sog‘lom retseptlarga o‘ting va sabzavotlarni pyure qilib, rang-barang makaron souslari ichiga qanday yashirish mumkinligini bilib oling. Niqoblash san’atini o‘rganing.'),
  ('5e903417-88bd-42b5-bb8c-507e12e432bf', 'Suvosti saltanati 🛀', 'Vannada cho‘milish endi shunchaki yuvinish emas, balki suvosti kemasi missiyasi. Suv atrofga sachrayversin. Suvning o‘sha sehrli ta’siri kun bo‘yi unda to‘plangan qaysar, salbiy energiyani yuvib, oqova bilan olib ketadi.'),
  ('d3d2b281-0b44-4f04-8791-8ceca32ccdb3', 'Daho ixtirochi 👟', 'Oyoq kiyimini qulog‘iga tutib, jiddiy ohangda Allo deb nimalarnidir gapiryapti. U buyumlarga yangi vazifalar o‘ylab topmoqda! Bu g‘aroyib va ajoyib lahzani o‘tkazib yubormang. Chaqaloq fotosessiyasi orqali bu quvnoq ixtirochini suratga olib, arxivingizning eng ko‘zga ko‘ringan joyiga qo‘ying.'),
  ('185309c1-aba3-48ec-9411-535c92af4024', 'Raqamli sukunat terapiyasi 🤫', 'Nihoyat, xonani mutlaq sukunat qopladi. Idish yuvish mashinasini joylashga shoshilmang. Ovoz o‘lchagichni ishga tushiring va ekrandagi raqamlar 0 desibelgacha pasayishini kuzatib, charchagan miyangiz qanday tin olayotganini his qiling.'),
  ('4794fa88-36bd-4251-a4ea-871854d0d5ac', 'Chiqindi ko‘paytiruvchi san’atkor ✂️', 'Qo‘liga tushgan toza qog‘ozni mingta mayda bo‘lakka yirtib, xonaga sochib tashlayaptimi? Uning mayda motorikasi ishlayapti! Asabiylashib, supurgi tomon yugurmang. Qog‘oz parchalarini bir qutiga yig‘ib, qor yog‘dirish o‘yinini o‘ynang.'),
  ('bcbae78a-e00a-4482-8778-25c54ab9a376', 'Ko‘zgudagi raqib 🪞', 'Ko‘zgu qarshisida turib, o‘ziga qoshlarini chimiradi, jahldor va g‘alati yuz ifodalarini qiladi. U his-tuyg‘ular yuzida qanday aks etishini sinab ko‘rmoqda. Chetdan ovoz chiqarmay, bu mitti teatr aktyorining mashg‘ulotini qiziqish bilan tomosha qiling.'),
  ('1681892e-80a4-445a-827d-19733c9c6b73', 'Hamjamiyat kuchi 💬', '“Nega mening bolam bunchalik qaysar?” degan o‘y sizga tinchlik bermayapti. Anacan hamjamiyatiga qo‘shiling. Boshqa onalarning uyida ham yuz beradigan shunga o‘xshash bema’ni injiqliklarni o‘qib, yolg‘iz emasligingizni va mutlaqo tabiiy jarayonni boshdan kechirayotganingizni tushunasiz.'),
  ('450f109f-b886-4ee2-8c86-66186d74b732', 'Yorug‘lik ritmi 🌙', 'Tezroq uxlab qolishi uchun yotishdan 1 soat oldin xonadagi barcha qo‘shimcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin faqat qorong‘i va texnologiyalarsiz muhitda tez ajralib chiqib, ishingizni osonlashtiradi.'),
  ('b4a0c1d1-e187-401c-89d3-83448ef5f879', 'Dinozavrning nonushtasi 🦖', 'U nonushtada qo‘llarini ishlatmasdan, og‘zini to‘g‘ridan-to‘g‘ri likopchaga yaqinlashtirib, dinozavr kabi ovqatlanmoqchi. Unga odob o‘rgatishga shoshilmang! 5 daqiqa dinozavr bo‘lishiga ruxsat bering — bu o‘yindan zerikib, baribir qoshiqni qo‘liga oladi.'),
  ('331d91d4-ea8d-4af5-be08-e82eb1b8836d', '“O‘zim qilaman” tezligi 🐢', 'Uydan chiqishingiz kerak, ammo u oyoq kiyimini, albatta, o‘zi kiyadi va bu toshbaqa tezligida 15 daqiqa davom etadi. Aralashsangiz, yig‘i va injiqlik 30 daqiqaga cho‘ziladi. Ketayotgan vaqtga emas, uning g‘ururiga putur yetmasligiga e’tibor qarating va sabr bilan kuting.'),
  ('bd96c118-6b22-4005-829a-5d2036e47887', 'G‘oyib bo‘lgan kalitlar 🔑', 'Uy kalitlarini topolmayapsizmi? Muzlatkich yoki oyoq kiyim javonini tekshiring. U buyumlarni yashirish orqali ularning ko‘zdan yo‘qolsa ham mavjud bo‘lib qolishini sinab ko‘rmoqda. Bu kulgili xazina izlash jarayonida jahlingizni chiqarish o‘rniga kulishni tanlang.'),
  ('c22e7a31-d31e-4595-845a-77f2550b33d1', 'Shivirlash gipnozi 🤫', 'U karavotda yotib, oyoqlarini havoga ko‘taradi va uxlashni istamaydi. Baqirish o‘rniga ovozingizni birdan pasaytirib, u bilan faqat shivirlab gaplashing. Bola sizni eshitish uchun butun diqqatini jamlaganida, miyasi avtomatik ravishda tinchlanib, uyqu rejimiga o‘tadi.'),
  ('15c2879b-fa80-4ef3-b734-53366c8b7916', 'To‘satdan jo‘sh urgan mehr 🥰', 'O‘ynab turgan joyida o‘yinchog‘ini tashlab, yugurib keladi-da, bo‘yningizdan quchib: «Sizni yaxshi ko‘raman», deydi. Mana shu lahza barcha charchoq va uyqusizlikni bir zumda yo‘qotadigan sehrdir. Uni mahkam bag‘ringizga bosing va yoqimli hidini to‘yib-to‘yib hidlang.'),
  ('c0446dd4-cfe7-4c72-9419-07304cef46d7', 'Dadaning g‘aroyib ertagi 📖', 'Bu oqshom ovozingiz charchagan. Ertak o‘qishni dadasiga topshiring. U kitobdagi rasmdan butunlay farq qiladigan, o‘zi to‘qigan kulgili hikoyani aytib, bolani qahqahaga soladi. Siz esa bir chetda, bir piyola choy bilan bu manzarani zavqlanib tomosha qiling.'),
  ('df2fef22-961b-4197-8f8b-a55345b6bbaa', 'Do‘kon aravachasi bo‘roni 🛒', 'Katta do‘kon aravachasi o‘zidan ham katta bo‘lsa-da, uni albatta o‘zi haydamoqchi bo‘ladi. Odamlar orasida yig‘latgandan ko‘ra, qo‘llarini aravachaning chetida qoldiring-u, o‘zingiz sezdirmay yo‘naltirib turing.'),
  ('1528a888-1cfa-4bf5-b2b7-c533244518f5', 'Teskari kiyilgan erkinlik 👗', 'Shimini teskari kiyib olib, qat’iy ohangda: «O‘zim kiydim», deydi. Ko‘rinishini o‘ylamang. Uning ortib borayotgan o‘ziga ishonchi va mustaqillik hissi kiyimning to‘g‘ri kiyilganidan ancha muhimroq. Bu mitti isyonkor bilan faxrlaning.'),
  ('3b7890c9-fcdd-4513-a90d-c39e56fa7a0a', 'Tartibsizlik o‘rtasidagi qahva ☕', 'U xonaning o‘rtasiga barcha o‘yinchoqlarini yoyib, o‘ziga qal’a quryapti. Siz bu tartibsizlikni yig‘ishtirishingiz bilan u yana hammasini sochib tashlaydi. Shuning uchun kurashishni bas qiling, xonaning bir chetiga borib, qahvangizni sovitmay iching va tartibsizlikni chetdan kuzatib, dam oling.'),
  ('903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a', 'Xonadagi soyalar 🐰', 'Qorong‘ilikdan qo‘rqa boshladimi? Xonani butunlay qorong‘i qiling va kichik fonar yordamida shiftda yorug‘lik o‘yinlari hamda hayvonlar soyalarini yarating. U qo‘rqadigan qorong‘ilikni maroqli mashg‘ulotga, uxlashdan oldin birga kuladigan kichik bir sarguzashtga aylantiring.'),
  ('11c8bab9-c92e-47a2-b7c0-34d8c43e8735', 'Qo‘llarga dam 🫂', 'Kun bo‘yi ustingizga chiqishi va quchoq so‘rashi sabab butun tanangiz og‘riydi. Kechqurun navbatni dadasiga topshiring. U bolani yelkasiga mindirib, ot bo‘lib o‘ynatsa, bolaning e’tiborga bo‘lgan ehtiyoji qondiriladi, qo‘llaringiz esa kerakli damni oladi.'),
  ('5ddf0bc2-3619-404d-a56d-27e47d73626e', 'Tonggi konsert 🎤', 'Quyosh hali to‘liq chiqmagan, u esa karavotda sakrab, siz tushunmaydigan tilda baland ovozda qo‘shiq aytyapti. Ha, uyqungiz kelyapti, ammo xona bo‘ylab aylanib yurgan bu hayotiy quvvat sizni ham o‘rningizdan turg‘izadi. Uning ovoziga shunchaki tabassum qiling.'),
  ('c7c4ce1e-98e4-4beb-992c-e1f8c9783567', 'Sun’iy intellekt — najotkor 🤖', 'Ona, quyosh qayerga uxlagani ketadi? Bu savoldan dovdirab qoldingizmi? Izohni murakkablashtirmang. Anacan AI-ga bolaning yoshini ko‘rsatib, shu savolni bering va 3 yoshli bola bemalol tushuna oladigan, ertakka o‘xshash ajoyib javobni olib, unga aytib bering.'),
  ('0daa509c-a73b-47b1-a76d-b85764cf98f2', 'Sokin ko‘z yoshlari 💖', 'U kun bo‘yi sizni aqldan ozdirdi. Ammo hozir karavotda shu qadar begunoh uxlayaptiki, unga qarab ko‘nglingiz bo‘shab ketadi, shunday emasmi? Onalikning eng katta paradoksi aynan shu. Ko‘zingizdan dumalagan o‘sha bir tomchi yosh — uning borligiga shukronangizdir.'),
  ('2d96922a-7550-4150-a8ed-19cdd56a8801', 'Yashirin oziqlantirish operatsiyasi 🥣', 'Kecha sevib yegan tuxumini bugun og‘ziga ham olmaydi. Uning irodasi bilan kurashmang. Sog‘lom retseptlardan foydalanib, oqsilli mahsulotlarni turli, rang-barang va qiziqarli shakllarga keltiradigan ayyorona tamaddi retseptlarini sinab ko‘ring va g‘olib bo‘ling.'),
  ('a6a15ff2-f8a6-4007-b1d8-974680e64a8d', 'Mantiqning barbod bo‘lishi 🛑', 'Suvini qizil stakanda berishingizni so‘rab baqiradi, qizil stakanga quyganingizda esa bu safar nega bunga quydingiz, deb yig‘laydi. Bunda mantiq yo‘q. U shunchaki charchagan va his-tuyg‘ularini chiqarib yuborishi kerak. Xotirjam kuting, bo‘ron o‘z-o‘zidan tinadi.'),
  ('86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd', 'Uzluksiz uyqu umidi 🤞', 'U uxlab qoldi va uy chuqur sukunatga cho‘mdi. Sizning eng katta orzuingiz — uning bu kecha uyg‘onmasligi. Ovoz o‘lchagichdagi mayin o‘rmon shovqinini fon ovozi sifatida past ovozda yoqib, uning chuqur uyqu bosqichida qolishiga yordam bering.'),
  ('906c34fb-a999-448f-8756-7ba4d8fc80cd', 'Tabiat laboratoriyasi 🍂', 'Uyda o‘tirish sizni zeriktirdi, bola esa bezovta. Ob-havo va kiyimini tekshirib, uni albatta sayrga olib chiqing. Shunchaki qurigan shoxlar va barglarni yig‘ish vazifasini bering: bu uning ortiqcha energiyasini chiqarishiga yordam beradi, siz esa to‘rt devor orasidan chiqib, toza havodan bahramand bo‘lasiz.'),
  ('af0535a2-83d1-4838-8bfc-0cfb607ff2f5', 'O‘yinchoqlarning onasi 🧸', 'Xonadan ovoz kelmoqda. Diqqat bilan quloq solsangiz, u ayiqchasini xuddi sizning ohangingizda, siz ishlatadigan iboralar bilan koyiyapti! U sizning eng yaxshi nusxangiz. Bu o‘z xatti-harakatlaringizga chetdan nazar tashlash uchun ajoyib imkoniyat.'),
  ('0300b128-8698-433f-8d28-7ef165f88a96', 'Bo‘lishib bo‘lmaydigan nonushta 🍳', 'O‘z likopchasidagidan sizga aslo bermaydi, ammo kelib, sizning likopchangizdagi tuxumdan yeyishni qat’iy talab qiladi. Bolalar doimo ota-onasining tanloviga ko‘proq ishonadi. Qarshilik qilmang, luqmangizni bu mitti xudbinchaga mehr bilan bering.'),
  ('334f9c8b-ef27-4cd7-845a-eb18706654fc', 'Ro‘yxatsiz falokat 🛒', 'Xotirangizga ishonib, uyga keldingiz-u, bola uchun eng muhim mahsulot — sutni olmaganingizni payqadingiz. Miyangiz shundoq ham juda band. Bundan buyon biror narsa kerakligi yodingizga tushishi bilanoq uni ilovadagi Xaridlar ro‘yxatiga yozishni odat qiling va o‘zingizni stressdan asrang.'),
  ('ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f', 'Vannadagi okean 🌊', 'Vannada cho‘milish endi shunchaki tozalanish emas, balki to‘lqinlar yasash o‘yiniga aylandi. Suv atrofga sachrasin, mayli. Suvning o‘sha sehrli ta’siri unda kun bo‘yi to‘plangan qaysar, salbiy energiyani yuvib, oqizib yuboradi va uyqusini yanada chuqurlashtiradi.'),
  ('056e606b-664d-4a4e-94b5-81db6f2adf23', 'Siz mukammalsiz 🛑', 'Ijtimoiy tarmoqlarda har kuni farzandi bilan san’at asarlari yaratadigan, uyi yaraqlab turadigan onalarni ko‘rib, o‘zingizni ayblayapsizmi? Bu filtrlarga ishonmang. Sizning tartibsiz, shovqinli va haqiqiy uyingiz farzandingiz uchun eng iliq, mehrga to‘la va mukammal maskandir.'),
  ('156b6d8e-1bbe-4769-b258-c89d41a67564', 'Kichkina advokatning dalili 🗣️', 'Shokolad yeyman, chunki men katta bo‘lganman. U sabab-oqibat bog‘liqligini anglab, siz bilan kelishishga va savdolashishga urinmoqda! Nutqining rivojlanishi a’lo darajada. Uni maqtang, ammo chegaralaringiz va qoidalaringizga ham mehr bilan amal qiling.'),
  ('838e23dd-ecaf-4568-9687-59518e77bc77', 'Sukunat terapiyasi 🤫', 'U nihoyat uxlab qoldi! Shovqin o‘lchagichni yoqing va ekrandagi raqamlar 0 detsibelgacha tushishini kuzatib, charchagan miyangiz qanday tiniqlashayotganini, bu ko‘z bilan ko‘riladigan sukunat sizga qanday orom berayotganini his qiling.'),
  ('1645ac24-40c0-4cef-8645-e26caf67a799', 'Oshxonadagi ko‘ngilsiz hodisa 🧑‍🍳', 'Siz xamir yoyayotganingizda u kelib, qo‘lini unga tiqadi va hamma joyni oppoq qiladi. Ha, oshxona iflos bo‘ldi, ishingiz ko‘paydi. Ammo uning jiddiy, ishchan yuz ifodasini Chaqaloq fotosessiyasi yordamida darhol suratga oling. Kir ketadi, ammo bu xotira qoladi.'),
  ('58f0130e-9824-44fe-9963-a1e86c3e18cc', 'O‘zingiz bilan faxrlaning 🚀', 'Ortga nazar tashlab, uning naqadar kuchli xarakterli insonga aylanganini ko‘rasiz. Bugun unga uzoq tikilib, shunday ajoyib insonni voyaga yetkazganingiz uchun o‘zingiz bilan faxrlaning.'),
  ('f65305c4-c08d-4180-9df9-53864d7df4a9', 'Jamoaga minnatdorlik 🥂', 'Yana bir qiyin va notinch kunni ortda qoldirdingiz. Bola uxlagach, juftingiz bilan bir piyola choy ichib, Bugun menga juda ko‘p yordam berding, rahmat, deb ayting. Farzand tarbiyasi yolg‘iz emas, ahil jamoa bilan yanada go‘zal bo‘ladi.'),
  ('52fd1b46-da9f-4903-91e9-9855c04a5c68', 'Empatiya belgilari 🧸', 'O‘yinchog‘i yiqilib tushganda uni silab, Yig‘lama deydimi? Demak, unda empatiya hissi shakllanmoqda! Bu yoqimli bosqichni Rivojlanish kuzatuvchisiga albatta qayd eting.'),
  ('8cc847d7-8dbe-41eb-84d4-4cb88879af35', 'Teskari kiyimlar 👗', 'Qo‘lidagi ko‘ylakni albatta orqasini oldiga qilib kiyishni xohlayaptimi? Qarshilik qilmang. Mayli, bir kun uyda shunday yursin, irodasini sindirmang.'),
  ('8ec0eb18-27f1-4127-9c31-f0777f9a4904', 'Biz bir jamoamiz! 💖', 'Og‘ir kundan so‘ng juftingiz bilan yuzma-yuz o‘tirib, dardlashing. Bir-biringizni qo‘llab-quvvatlash yukni rostdan ham teng ikkiga bo‘ladi.'),
  ('47e4625b-1969-49f3-9819-a17d4bddc0c8', 'Ko‘rpa muhandisligi 🛏️', 'Endi uxlab qolay deganda, birdan yig‘lay boshlaydi: Ko‘rpaning uchi bukilib qolibdi! Ko‘rpaning millimetrigacha tekis turishi uning uchun hayotiy ahamiyatga ega. Chuqur nafas oling, ko‘rpani xuddi dazmollangandek tekislang va bu kulgili injiqlikka shunchaki jilmaying.'),
  ('743bf968-dea7-4d72-ac2d-22654230f0a2', 'Shubhali sukunat 🤫', 'Uyda birdan chuqur sukunat cho‘kdi. Shovqin o‘lchagich 0 detsibelni ko‘rsatmoqda. Bola jim bo‘lsa, demak, qayerdadir katta bir tadqiqot olib borilmoqda. Devorga chizilgan rasmlar yoki qirqilgan qog‘ozlarni ko‘rishga ruhan tayyorlanib, xonaga kiring.'),
  ('9fa0703c-5759-4d65-aa22-1042aa7b5843', 'Bahslashmang. 💼', 'Men bu bo‘tqani yemayman, chunki u sariq! U shu qadar benuqson va ishonarli bema’ni mantiq yuritadiki, hatto o‘zingizni aybdordek his qilishingiz mumkin. Bahslashmang. To‘g‘ri aytasan, u sariq. Ichiga qizil rezavorlar solsаk-chi? deb kichik advokatni ko‘ndiring.'),
  ('15c2d5ec-3e4a-4b1d-b6d2-a891cc587847', 'Dadaning suv jangi 🛁', 'Bu oqshom cho‘milish marosimi butunlay dadasining zimmasida. Ular suvni atrofga sachratishsin, siz esa eshik ortida mutlaq sukunatdan zavqlaning.'),
  ('2054a805-49e3-459b-8315-84f392392707', 'Kiyimlar isyoni 🥽', 'U uyda suzish ko‘zoynagi va qishki qalpoq kiyib yurishni xohlaydi. Qat’iy turib oldi, ularni yechmayapti. Jamiyat qoidalarini unuting. Uning ijodkorligi va qaror qabul qilish erkinligini cheklamaslik uchun kunni shu noodatiy, kulgili kiyim uyg‘unligida o‘tkazishiga ruxsat bering.'),
  ('5be61e62-9e95-417b-9db3-15386a93c72a', 'Do‘kon aravachasidagi syurpriz 🛒', 'Kassaga yaqinlashganingizda do‘kon aravachasidan siz tanlamagan 3 xil shokolad va 1 dona g‘alati shakldagi sovun chiqdi. Tezkor harakat bilan ularni joyiga qaytaring. Biror narsani unutmaslik va maqsaddan chalg‘imaslik uchun esa xaridlar ro‘yxatini doim ko‘zdan qochirmang.'),
  ('22ac2508-9b42-4e19-b15b-cc1dca8c750b', 'Eshitish qurilmasi o‘chdi 🙉', '“O‘yinchoqlarni yig‘ishtir”, “Kel, qo‘lingni yuv” deysiz, ammo javob yo‘q. Eshitmaganga olish 3 yoshli bolaning eng sevimli mashg‘ulotidir. Baqirish o‘rniga uning yoniga boring va qulog‘iga juda mayin ovozda pichirlang. Ovoz ohangining birdan o‘zgarishi darhol uning diqqatini tortadi.'),
  ('4bb7714f-90ea-44a6-8f84-3a989d3c428e', 'Hammomdagi shantaj 🛀', 'Vannaga kirayotganda yig‘lagan edi, endi esa suvdan chiqmaslik uchun dod solmoqda. Suvning magnitdek kuchi uni sehrlab qo‘ydi. Oldindan 3 daqiqalik ogohlantirish bering va taymerni yoqing. Qo‘ng‘iroq chalinganda “o‘yin tugadi” marosimi har doim ish beradi.'),
  ('a6053646-98c9-47f9-ae28-32c8e38f416e', 'Taom dizayneri 🥦', 'Likopchadagi taomlarni rangi va shakliga qarab ajratadi, yashillarini esa stol chetiga suradi. Ovqatlanish rejasini ishga soling. O‘sha sabzavotlarni qanday qilib ko‘rinmas pyurega aylantirib, kotletlar va souslarga yashirish mumkinligini kashf etib, bu o‘yinda g‘olib chiqing.'),
  ('454d0433-fa13-4bd5-95fe-c40365aff560', 'Uyning bosh shifokori 🩺', 'O‘yinchoq stetoskopini olib, ko‘ksingizga qo‘yadi, qoshlarini chimirib, «Nafas oling», deydi. Siz esa gapga quloq soladigan bemorsiz. Bu rolli o‘yindan foydalanib qoling: ko‘zingizni yuming va 3 daqiqalik ko‘rik davomida shunchaki yerda yotib, belingizga dam bering.'),
  ('603f7d3e-e83f-41b9-ade3-bd0fa858fbaf', 'Dadaning ovoz paychalari 📖', 'Bugun ovozingiz charchagan, tomog‘ingiz qurigan. Kechki ertakni dadasiga topshiring. U kitobdagi rasmdan butunlay farq qiladigan kulgili va to‘qima hikoya aytib, bolani rosa kuldiradi. Siz esa bu yoqimli manzarani bir chetda issiq choy ichib tomosha qiling.'),
  ('e4995ac6-5e09-45b3-8f40-851f3616a9f6', '«Oyi, qarang!» davri 👀', 'Divandan sakraydi va ayni bir harakatni roppa-rosa 50 marta takrorlab, har safar «Oyi, menga qarang!» deydi. Nigohingizni telefondan uzing. U harakatning o‘zi uchun emas, ko‘zlaringizdagi o‘sha ma’qullash uchquni uchun sakrayapti. Unga uzluksiz 5 daqiqa ajrating, e’tiboringizga to‘yib olsin.'),
  ('41b57fa8-5ee9-47c4-bdaf-6650d5ddc287', 'Musiqali gipnoz 🎶', 'Kechga yaqin sababsiz to‘polonlar va yig‘i xurujlari boshlandi. Televizorni o‘chiring, chiroqlarni xiralashtiring va xonada juda past ovozda klassik musiqa qo‘ying. Musiqaning chuqur ohanglari muhitni sehrli tarzda o‘zgartirib, xonaga osoyishtalik olib kiradi.'),
  ('d113ec32-8781-4153-b853-ad718dad74e9', 'Onaning «Reset» tugmasi 🚪', 'Shovqin-surondan boshingiz g‘uvillab, hammaga baqirgingiz kelyapti. Kayfiyat kundaligini oching. Unga butun charchoq va holdan toyganingizni erkin yozing. Bu qisqa raqamli terapiya sizni qayta tiklaydi.'),
  ('0b46f253-2b1f-4b21-b471-54a500b94e42', 'Qorong‘ilik bilan raqs 🌙', 'Tezroq uxlab qolishi uchun yotishdan 1 soat oldin xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin (uyqu gormoni) faqat qorong‘i va texnologiyalarsiz muhitda tez ajralib chiqib, uyquga ketishni ta’minlaydi.'),
  ('53f4b2ce-2dcb-457d-bccf-d9242c156c63', 'Ko‘chadagi xazina 🍁', 'Yerdan topgan kir butilka qopqog‘i yoki noodatiy rangdagi toshni xuddi oltin topgandek quvonib sizga ko‘rsatadi. «Tashlab yubor, bu kir», deyish o‘rniga, «Rangi juda g‘aroyib ekan, kel, uyda yuvamiz», deb uning kashfiyotga bo‘lgan ishtiyoqini qadrlang.'),
  ('d8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f', 'Falsafa soati yana boshlandi 🤔', 'Shamol nega esadi? Barglar nega to‘kiladi? Chuqur falsafiy savollar ertalabdanoq boshingizni qotiradi. Tushuntirishni murakkablashtirmang, tabiatni u tushunadigan ertak tilida izohlang. Sizning ovozingiz uning uchun koinotni anglashning eng ishonchli yo‘lidir.'),
  ('4a8b061c-822f-4468-b267-6996ffaeb6d8', 'Oshxonadagi konsert 🥄', 'Qozonlar va yog‘och qoshiqlarni olib, oshxonaning o‘rtasida konsert beradi. Boshingiz og‘risa ham, bu uning ritmni his etishi va ijodkorligi rivojlanayotganidan dalolat. Darrov aralashmang, bir necha daqiqa davomida bu jo‘shqin energiyaning tovush to‘lqinlari bilan xonaga taralishiga imkon bering.'),
  ('79b03a5c-cc04-4f7b-9361-f8120f787406', 'Hamjamiyatdagi taskin 💬', '«Nega mening bolam bunchalik qaysar?» degan o‘y sizni ich-ichingizdan qiynaydi. Anacan hamjamiyatiga qo‘shiling. Boshqa onalarning uyida yuz beradigan shunga o‘xshash bema’ni injiqlik xurujlari haqida o‘qigach, yolg‘iz emasligingizni va mutlaqo sog‘lom, odatiy bolani ulg‘aytirayotganingizni tushunasiz.'),
  ('c0b67368-8315-449a-b685-71a8e309a2c6', 'Nafasining iliqligi 💖', 'U kun bo‘yi sizni aqldan ozdiray dedi, har narsaga yig‘ladi. Ammo hozir to‘shakda ko‘ksingizga suykalib yotibdi, uning bir maromdagi iliq nafasi xonani to‘ldirmoqda. Onalikning eng katta mukofoti aynan shu. Uni bag‘ringizga mahkam bosing va barcha charchog‘ingiz shu nafas bilan uchib ketayotganini his eting.'),
  ('07a807e7-5500-4214-ab98-d5372a84c109', 'Jamoaviy mehnat samarasi 🥂', 'Yana bir qiyin va g‘alayonli kunni ortda qoldirdingiz. Bola uxlagach, juftingiz bilan bir piyola choy quyib, «Bugun ham bu tartibsizlikdan omon chiqdik, biz ajoyib jamoamiz», deya bir-biringizga minnatdorlik bildiring. Ota-onalik yolg‘iz emas, ko‘mak bilan yanada go‘zal bo‘ladi.'),
  ('7715199a-4ef6-480d-9548-a833acc549dd', 'Teskari kiyilgan poyabzal 👟', 'Poyabzalini teskari kiyib olgan, ammo xuddi dunyoni zabt etgandek faxr bilan yuribdi. Aralashib, to‘g‘rilashga urinsangiz, hammasi barbod bo‘ladi. Uning o‘ziga ishonchi va mustaqilligi tashqi ko‘rinishdan muhimroq. Bu mitti isyonchi faxr bilan qadam tashlayversin.'),
  ('b205ec5f-9776-4abd-8a5c-b967e050819e', 'Oshxonadagi to‘polon 🧑‍🍳', 'Siz xamir yoyayotganingizda kelib, qo‘lini unga tiqadi-da, hamma joyni oppoq qiladi. Ha, oshxona rasvo bo‘ldi. Ammo uning o‘sha jiddiy, ishchan yuz ifodasini Chaqaloq fotosessiyasi yordamida darhol suratga muhrlang. Tozalikka bir yo‘l topiladi, o‘sha kulgili kadr esa abadiy qoladi.'),
  ('18bd2439-9788-43c4-81c5-8852d0241a0d', 'Jonli ko‘zgu 🦜', 'Siz jahlingiz chiqqanda qiladigan yuz ifodangizni aynan takrorlab, o‘yinchog‘ini koyiyapti. Darhol o‘zingizga chetdan nazar soling! U nimani ko‘rsa, shuni takrorlaydi. Bu kulgili, ammo o‘ylantiradigan manzara xatti-harakatlaringizga ko‘proq e’tibor berishingiz uchun ajoyib ko‘zgudir.'),
  ('57b60f69-46b8-4792-b8f6-95c7ec477f5b', 'Aqlli ertakdagi men 🪄', 'Klassik kitoblarni yodlab bo‘lgansiz va ularni o‘qishdan charchagansiz. Aqlli ertaklarni oching. Farzandingizni bosh qahramon qilib, fon uchun esa tinchlantiruvchi o‘rmon tovushlarini tanlang va o‘zgacha, hech qanday kuch talab qilmaydigan uyqu seansini yarating.'),
  ('8391ff6e-4225-4aa9-9011-6c07f64cfe8a', 'Toza havo ⛅', 'Ob-havo va kiyimini tekshirib, uni albatta tashqariga olib chiqing. Unga qurigan shoxlar va toshlarni yig‘ish vazifasini bering: u energiyasini sarflaydi, siz esa to‘rt devor orasidan chiqib, chuqur nafas olasiz.'),
  ('1d548457-d3f9-490c-889a-735e0fede3a4', 'Yotoq bo‘ylab ko‘chish 🛏️', 'Kechasi to‘g‘ri holatda uxlab, ertalab oyoqlari yostiqda, boshi esa yotoqning butunlay qarama-qarshi burchagida uyg‘onadi. U hatto uyqusida ham dunyoni kashf etadi! Uni uyg‘otishdan oldin bu kulgili tungi ko‘chishlarini miriqib tomosha qiling.'),
  ('9fa8e885-34cc-4a52-b9b9-6155faa47396', 'Falsafiy uyqu kechikishi 🦉', 'Yotoqqa kirishi bilan Ona, yulduzlar nega tushib ketmaydi? kabi chuqur savollar beradi. Maqsadi ilm o‘rganish emas, uxlash vaqtini cho‘zishdir. Savollariga qisqa, to‘qima va yoqimli javoblar berib, darhol Aqlli ertaklar yordamida xonani uyqu sukunatiga cho‘mdiring.'),
  ('b5e65866-a678-4ef1-91b0-5f12331c2cae', 'Libosli qahramon 🦸‍♂️', 'Uy ichida qishki etik yoki superqahramon niqobida yurishni qat’iy xohlayaptimi? Jamiyat me’yorlari va estetikani bir chetga suring. Bu uning o‘zligini kashf etish jarayonidir. Xonada etiklarini kiyib, o‘zini qahramondek his qilishiga imkon bering.'),
  ('0497aa5e-024a-43eb-ba38-bda044dfec73', 'Dinozavrning tishlari 🦖', 'Tishlarini yuvishdan keskin bosh tortib, cho‘tkani uloqtiryaptimi? Buni o‘yinga aylantiring! Qo‘liga zaxira cho‘tkani berib, Kel, avval o‘yinchoq dinozavringning tishlarini yuvamiz deng. U dinozavrning tishlarini tozalayotganida, siz ham sezdirmay uning tishlarini yuvib qo‘ying.'),
  ('2824815e-ab93-4e74-b868-7dee6ae3bcac', 'Mustaqillik dog‘lari 🥣', 'Yogurtni albatta sanchqi bilan yeyishni xohlaydi va hamma joyni bulg‘aydi. Aralashib, sanchqini qo‘lidan olmang. To‘kilgan ovqatni tozalash mumkin, ammo uning men o‘zim qilaman degan ishonchini tiklash qiyin. Silikon fartukni taqib, bu manzarani sabr bilan kuzating.'),
  ('33c034f1-168d-424b-b367-21b9eb4799c9', 'Onaning 10 daqiqasi 🚪', 'Shovqin-surondan miyangiz karaxt bo‘lib qoldi. Kayfiyat kundaligini oching va bugun sizni asabiylashtirgan barcha narsani ekranga bemalol yozib, ichki qayta yuklash tugmangizni bosing.'),
  ('1fc95e57-80a1-42af-8907-c939c12adef9', 'Axlat qutisining jozibasi 📦', 'Shuncha qimmatbaho, yorqin o‘yinchoqlar turganda, u bo‘sh plastik suv idishi yoki karton quti bilan soatlab o‘ynaydi. Bola tasavvuri tayyor ssenariylarni emas, ijodkorlik uchun imkon beradigan oddiy buyumlarni yoqtiradi. Uni kuzating va undan o‘rganing.'),
  ('61bc311a-ba5b-43dc-b36e-6a65967f1df0', 'Uyqu inqilobi ☁️', 'Ertalab uyg‘onishi bilan sizga qoshlarini chimirib, arazlaydi. Sababi? Tushida siz unga xohlagan o‘yinchog‘ini bermabsiz! Bola miyasi tush bilan haqiqatni hali to‘liq ajrata olmaydi. Jiddiy ohangda uzr so‘rang va bu g‘alati vaziyatdan ichingizda kulib qo‘ying.'),
  ('c193e688-7d18-417e-aa1d-53580a727596', 'So‘zsiz nigohlar 🥂', 'Bola nihoyat uxlab qoldi. Siz va juftingiz divanda yonma-yon o‘tiribsiz, hatto gaplashishga ham holingiz yo‘q. Shunchaki sukutda bir-biringizga qarab jilmayasiz. Ha, bu so‘zsiz nigohlar «biz bu tartibsizlikni uddalayapmiz» deyishning eng go‘zal usulidir.'),
  ('98f98e2b-5170-4983-96d7-fe8b44837cdf', 'Devordagi teatr 🐰', 'Qorong‘ilikdan qo‘rqishini bahona qilib, yotoqdan qochadi. Xonadagi barcha chiroqlarni o‘chiring, fonarni yoqing va devorda qo‘llaringiz bilan qush va kuchuk soyalarini yarating. U qo‘rqadigan qorong‘ilik bir necha soniya ichida uning uchun dunyodagi eng xavfsiz teatrga aylanadi.'),
  ('bf60fea7-a806-46ec-a023-ae8a1e62e95a', 'Parkdan ketish taktikasi 🌳', 'Parkdan qaytish vaqti keldi va yig‘i boshlandi. Uni sudrab olib ketishga urinmang. «Qani, ko‘ramiz, mashinagacha kim tezroq yugurib borarkan?» deb musobaqa uyushtiring. Bolalar bellashish va g‘alaba qozonishga hech qachon yo‘q demaydilar.'),
  ('e6013d08-4f44-4955-a2ce-c8556d1e2010', 'Ko‘rinmas mehmon 👻', 'Nonushta paytida xayoliy do‘sti uchun ham dasturxonga likopcha qo‘yishingizni talab qiladi. Bu ruhiy bo‘shliq emas, balki tafakkur rivojidagi sakrashdir. O‘sha likopchani qo‘ying va mehmoningizga ham xayolan choy quyib, bu ajoyib tomoshaning bir qismiga aylaning.'),
  ('3cde3483-1ec6-4721-b8a3-2803d38e22f1', 'Yangi so‘zlar kashfiyoti 🗣️', 'U buyumlarga o‘zi butunlay to‘qib chiqargan, hech bir tilda mavjud bo‘lmagan yangi nomlar qo‘yadi. Hatto sizdan ham aynan shu so‘zni ishlatishingizni qat’iy talab qiladi! Rivojlanish kuzatuvchisini oching va kelajakda bu kulgili so‘zlarni o‘qib, birga kulish uchun ularni albatta yozib qo‘ying.'),
  ('50316f93-f1fa-4052-831d-66931b46940d', 'Uyning yashirin xazinalari 🔑', 'Uy kalitlari yoki pultni topolmayapsizmi? O‘yinchoq pechning ichiga yoki uning karavoti ostiga qarang. U buyumlarni yashirib, olam qanday ishlashini sinab ko‘rmoqda. Bu kulgili xazina o‘yinida asabiylashish o‘rniga kulishni va chuqur nafas olishni tanlang.'),
  ('e6c3f535-9f72-4297-8076-fd7145c977da', 'Cho‘milish paradoksi 🛀', 'Vannaga tushishni istamay yig‘lagan edi, endi esa chiqmaslik uchun dod solmoqda! Suvning sehrli va tinchlantiruvchi ta’siri uni maftun etdi. Suvdan chiqishini ortiqcha dramaga aylantirmaslik uchun sochiqni iliq quchoq deb atang, uni sochiqqa o‘rab, vannadan olib chiqing.'),
  ('0d31e21b-368c-475e-b2bc-811f2bd6c64c', 'Meniki! degan qaysarlik 🧸', 'Uydagi istalgan bir buyumni quchoqlab, Bu meniki! deb baqiradi va hech kimga bermaydi. U egalik chegaralarini o‘rganmoqda. Uni xudbinlikda ayblamang, shunchaki o‘sha paytda bu buyum unga tegishli ekanini qabul qiling.'),
  ('81e2b129-a3fd-4f20-b3aa-69e3df1d9014', 'Ovozingizning ohangi 🌙', 'U kitobdagi ertak voqealarini emas, sizning ovoz ohangingizni tinglaydi. Bu oqshom voqealar rivojini unuting. Hikoyani cho‘zibroq, mayin kuy kabi past ovozda o‘qib, uning asab tizimiga bevosita uyqu signalini yuboring.'),
  ('92e01489-6842-4c96-9e36-b31b3377a1e1', 'Ijtimoiy tarmoqlar illyuziyasi 📱', 'Internetdagi mukammal onalarni ko‘rib, uyingizdagi tartibsizlik uchun o‘zingizni ayblayapsizmi? To‘xtang. O‘sha 15 soniyalik filtrlangan videolarga ishonmang.'),
  ('267b7226-68df-4c3e-8db0-91462616e5aa', 'Sukunat detsibeli 🤫', 'U nihoyat uxlab qoldi! Xonani yig‘ishtirishga shoshilmang. Shovqin o‘lchagichni ishga tushiring va ekrandagi 0-10 detsibel raqamiga qarang. Uydagi mutlaq sukunatning ana shu vizual tasdig‘i charchagan miyangizga eng yoqimli massajdek ta’sir qiladi.'),
  ('9a9573ec-71e1-4545-84fd-a3a1f5b2af6b', 'Falsafa professori 🧐', 'Onajon, quyosh nega u yerda? deb emas, shunchaki Quyosh nega bor? deb so‘raydi. Uning savollari tobora mavhumlashib bormoqda. Soatlab ilmiy izoh berishga urinib, miyangizni charchatmang. Chunki U bizni isitishni yaxshi ko‘radi kabi qisqa, ertaknamo va mehrli javob uni to‘liq qoniqtiradi.'),
  ('c8cadde3-c829-4a73-89c2-d28ffc494046', 'Oyoqlar ta’tilda 🚶‍♂️', 'Ko‘chaning o‘rtasida birdan yerga o‘tirib, oyoqlarim sinib qoldi, meni ko‘tarib oling deydi. Yo‘q, u charchamagan, shunchaki sizni sinab ko‘ryapti. Bu nayrangga yon bermang. Qani, mashinagacha pingvindek qanday borarkanmiz? deb uni o‘yinga jalb qiling.'),
  ('d2c59147-ed1d-426c-a22f-74bab5a93a1b', 'Rangli parhez 🥕', 'Bugun faqat to‘q sariq rangli narsalarni yeyishga qaror qilibdi va qolgan hamma narsani rad etyapti. Bolalarcha mantiq yana ishga tushdi! Foydali retseptlarda sabzavotlarni qanday yashirish mumkinligini bilib oling. Qovoq va sabzi pyuresidan tayyorlanadigan turli retseptlar yordamida bu qaysarlikni yengib o‘ting.'),
  ('d7d30904-6d53-4964-8b13-c4680a8d7346', 'Tonggi xonanda 🎤', 'Hali tong sahar, siz ko‘zingizni zo‘rg‘a ochayotganingizda, u qo‘lidagi o‘yinchog‘i bilan xonaning o‘rtasida konsert beradi. Uni jim qilishga urinmang. Bolalarning bu jo‘shqin, tuganmas hayotiy quvvati aslida xonadonga baraka va quvonch olib kiradi. Unga tabassum bilan qarang.'),
  ('e2fc49a4-e751-47d3-a247-fa5b6429b0ca', 'Shifobaxsh teginish 💆‍♂️', 'Yotoqda hech tinchlanmayapti. Ertak va musiqani bir chetga qo‘ying. Uning kichkina oyoqlari yoki orqasini juda yengil, silovchi harakatlar bilan massaj qiling. Jismoniy yaqinlik uning ham, sizning ham tanangizdagi kortizol (stress gormoni) miqdorini darhol kamaytirib, uyqu keltiradi.'),
  ('297d6ab5-a5e9-4978-98b2-bd85528e89d5', 'Ko‘rinmas gardlar 🧹', 'Qo‘lidagi kichkina supurgi bilan gilam ustidagi ko‘rinmas changlarni o‘ta jiddiy qiyofada tozalamoqda. U shunchaki sizga taqlid qilyapti. Uning bu mas’uliyatli onini Chaqaloq fotosessiyasida suratga oling — uyning eng kichkina va eng yoqimtoy xizmatchisi ish ustida.'),
  ('79e7bb66-f1dd-4164-bbd9-7c802b073b10', 'Shovqin o‘lchagich terapiyasi 🤫', 'Uydagi o‘sha tinib-tinchimas dovul nihoyat uyquga taslim bo‘ldi. Xonada idish yuvish mashinasining tovushidan boshqa hech narsa eshitilmaydi. Shovqin o‘lchagichni yoqing va ekrandagi eng past detsibel ko‘rsatkichlariga qarab, ko‘zlaringizni yuming. Bu sokin manzara miyangiz uchun eng yaxshi massajdir.'),
  ('fee25f48-2972-4bf2-9d26-d0fbea33a7f3', 'Mushukcha bo‘lib uyg‘onish 🐾', 'Bugun ertalab u inson emas. To‘rt oyoqlab yuradi, oyog‘ingizga suykaladi va faqat miyovlab muloqot qiladi. Bu tasavvurning eng shirin va yuksak cho‘qqisidir. Qoidalar o‘rnatish o‘rniga, siz ham unga xayoliy sut idishini uzatib, bu o‘yindan zavqlaning.'),
  ('0d53c056-84aa-4820-a905-2f2e60542791', 'Hamjamiyatdagi e’tirof 💬', 'Bugun har bir narsaga baqirdingiz va o‘zingizni dunyodagi eng sabrsiz ona deb his qilyapsizmi? Iltimos, yolg‘iz emasligingizni biling. Anacan hamjamiyatiga kiring, boshqa onalar ham bugun sizdek holdan toyganini o‘qing va vijdon azobini tinchlantiring.'),
  ('844a3d1a-225d-46c7-945c-c5eaf88248c4', 'Dadaning g‘aroyib ertagi 📖', 'Bu oqshom xonada sizning emas, dadaning ovozi yangrasin. Ertak kitobini dadasiga bering va u hikoyani ataylab teskarisiga, kulgili va bema’ni tarzda aytib bersin. Bolaning uni tuzatishdan qanday zavqlanishini va dadasiga qarab qanday qah-qah otishini chetdan kuzating.'),
  ('c862c51e-5b03-4e55-bd66-35165e58d3d8', 'Avangard me’mor 🥞', 'Nonushtadagi quymoqchalarni ustma-ust taxlab minora quradi, o‘rtasini teshib, ichidan barmog‘ini o‘tkazadi. Ovqat bilan o‘ynash uning uchun yangi muhandislik loyihasidir. Stolning iflos bo‘lishiga ko‘z yuming — u shu tariqa taomning tuzilishini o‘rganmoqda.'),
  ('772055c7-02e3-4df1-ab25-b0a7ed011afe', 'Xayoliy do‘kon 🍅', 'Xonaning bir burchagiga o‘yinchoqlarini yig‘ib, sizga xayoliy pul evaziga xayoliy pomidor sotadi. Bu savdo o‘yiniga juda jiddiy yondashing. Xayoliy pomidorni sotib olib, ishtaha bilan yeyayotgandek ko‘rsating. Rolli o‘yinlar uning ijtimoiy intellekti va matematik tafakkuri uchun eng mustahkam poydevordir.'),
  ('9c4fcd9f-eca4-4781-b7b6-58a379dc2126', 'Onaning yashirin shokoladi 🍫', 'Oshxona javonining ortida undan yashirincha bir bo‘lak shokolad yeyayotgan ona, bu glyukoza sizning eng tabiiy haqqingizdir. Kun bo‘yi uning shuncha energiyasi va tuganmas «nega?»lariga bardosh berish uchun siz ham quvvat olishingiz shart. Chuqur nafas oling va maza qilib chaynang.'),
  ('a0a70ea3-00c4-4338-848e-bcb45a1157ff', 'Tungi vahima 😭', 'Yarim tunda ko‘zlari yumuq holda yig‘lab uyg‘ondi va hech kimni eshitmayapti. Yig‘isini kuzatib aniqlang: agar bu tungi vahima bo‘lsa, uni silkitmang va uyg‘otishga urinmang. Shunchaki yonida indamay turib, unga xavfsizlik hissini bering — bu o‘tib ketadi.'),
  ('2d19f095-845a-4bde-a575-de7451355856', 'Muzdek mantiq 🥶', 'Muzlatkichni ochib, undan muz qolipini talab qiladi va qo‘llari sovqotayotganiga qaramay, uni qo‘yib yubormaydi. U issiq va sovuq tushunchalarini o‘z tanasi orqali sinab ko‘rmoqda. Bir idishga iliq, boshqasiga muzdek suv solib, bu kashfiyotni kichik ilmiy tajribaga aylantiring — qaysarligi darhol yo‘qoladi.'),
  ('5b70990d-933c-46b2-be30-1407db2c7b1b', 'Tabiat qo‘yniga chiqish shart ⛅', 'To‘rt devor orasida uning energiyasi tajovuzkorlikka aylanadi va har bir gapi «yo‘q» bilan boshlanadi. Ob-havo qandayligi va kiyim masalasidan qat’i nazar, mos ravishda tayyorlanib, uni albatta tashqariga olib chiqing. Tuproqqa tegish uning asab tizimini darhol qayta tiklaydi.'),
  ('72b51261-3fd9-4ba4-a07e-a52ab32038d0', 'Tungi chiroq 🌙', 'Yotoqxonada chiroqlar o‘chirilganda bezovta bo‘ladimi? Xonaning bir burchagiga iliq rangli (to‘q sariq yoki qizil) kichik tungi chiroq qo‘ying. Xonaning qolgan qismi esa melatonin ajralishi va chuqur uyqu uchun butunlay qorong‘i bo‘lib qolishi kerak.'),
  ('0bee47e7-94df-4d8c-b500-e8adc690d1ff', 'Raqamli ro‘yxat — najotkor 🛒', 'Do‘kon o‘rtasida turib, «Men bu yerga nima olish uchun kelgandim?» deb o‘ylab qolasiz. Onalik miyasi shundoq ham ming bo‘lakka bo‘lingan. Biror narsa kerakligi yodingizga tushgan zahoti uni ilovadagi Xaridlar ro‘yxatiga yozishni odat qiling va yukingizni yengillashtiring.'),
  ('7574c80e-2022-481c-9e84-dd04a5dc3520', '«Sizga yordam beray!» nayrangi 🧽', 'Siz idish yuvayotganingizda u albatta yoningizga stul qo‘yib, suv bilan o‘ynashni xohlaydimi? Aslida u yordam berishni emas, jarayonning qoq markazida bo‘lishni istaydi. Unga kichkina plastik idish va gubka bering. Oshxona suvga botadi, ammo uning o‘ziga bo‘lgan ishonchi nihoyatda oshadi.'),
  ('ed6ba029-b0b0-4d21-8825-996dcfdf7f9e', 'Musiqaning sehrli to‘lqini 🎶', 'Kechga yaqin hech bir sababsiz boshlanadigan janjal va qichqiriqlarni yengil klassik musiqa bilan bosishga urinib ko‘ring. Ko‘pincha bu oddiy, ammo samarali usul xonadagi tajang muhitni sehrli tarzda o‘zgartirib, bolani chuqur xotirjamlikka cho‘mdiradi.'),
  ('df056dc0-b341-46d5-89e8-51170248ba0c', 'Garderob muhandisi 👗', 'Bugun u ko‘chaga har xil paypoq va teskarisiga kiyilgan ko‘ylakda chiqmoqchi. Jamiyatning uyg‘unlik haqidagi qoidalarini bir chetga suring. Mustaqil qaror qabul qilish va uni himoya qilish erkinligi ranglar uyg‘unligidan ancha muhimroq hayot sabog‘idir. Ruxsat bering.'),
  ('ed70e165-6613-45b8-9098-e5a1501e357a', 'Sun’iy intellekt va xotirjamlik 🤖', '3 yarim yoshga yaqinlashganda bolangizdagi keskin hissiy o‘zgarishlar sizni xavotirga soldimi? Internetdagi qo‘rqinchli va ruhiy jarohat yetkazadigan forumlarni yoping. Anacan AI orqali bu yoshdagi inqirozlar haqida ilmiy va psixologik jihatdan asoslangan, ko‘nglingizni tinchlantiradigan javob oling.'),
  ('fd525f60-163f-4a76-b89b-734831b1ea09', 'Ssenariyni u yozsin 🪄', 'Klassik kitoblardan ikkalangiz ham zerikdingiz, xonada esa zerikarli muhit hukm surmoqda. Aqlli ertaklarni oching va bu oqshom voqealar rivojini u boshqarishiga imkon bering. «Endi uchar mashina qayerga borsin?» deb so‘rang, xayolida olamlarni zabt etib uxlab qolsin.'),
  ('4cc9dfab-73bb-408b-8fd7-0cdb3ba02840', 'Shivirlash gipnozi 🤫', 'Karavotda yotib, oyoqlarini havoga ko‘taradi va aslo uxlashni istamaydi. Baqirish o‘rniga ovozingizni birdan pasaytiring va u bilan faqat shivirlab gaplashing. Chaqaloq sizni eshitish uchun diqqatini jamlaganida, miyasi avtomatik ravishda gipnozlangandek uyqu rejimiga o‘tadi.'),
  ('815c8c47-103f-4098-9702-cdb4705b486d', 'Ona uchun oflayn lahza 🛋️', 'U multfilm ko‘rayotganida yoki o‘yinchoqlari bilan berilib o‘ynayotganida, siz idish yuvish mashinasini bo‘shatish yoki kirlarni osish uchun yugurasizmi? To‘xtang! O‘sha 10 daqiqani shunchaki divanda yotib, shiftga qarash va hech narsani o‘ylamaslik uchun sarflang. Siz robot emassiz.'),
  ('ac5c326d-30b1-4f87-8420-9236c8047849', 'Tugallanmagan gaplarni yakunlang 🗣️', 'Biror so‘zni unutib qo‘ysa, qo‘llari bilan ishora qiladi, qoshlarini chimiradi va uni topishingizni kutadi. Uning so‘z boyligi oshib bormoqda, shunchaki miyasi tilidan tezroq ishlaydi. Gapini sabr bilan tugatganingizda, yuzida paydo bo‘ladigan «haa, aynan shuni aytmoqchi edim» degan yengillikni kuzating.'),
  ('7eaa01a6-6e1b-4778-9360-22935e0a6bcc', 'Taom dizayneri 🥦', 'Likopchadagi yeguliklarni rangi va shakliga qarab ajratadi, yashillarini esa chetga suradi. Sog‘lom retseptlar bo‘limiga kiring. Sabzavotlarni qanday qilib sezilmaydigan pyurega aylantirish va mazali souslar ichiga yashirishni bilib olib, bu o‘yinda sezdirmay g‘alaba qozoning.'),
  ('91e22232-e032-41dd-a3bf-200483eec697', 'Dadaning belida ot minish 🐴', 'U hali butun kuchini sarflamagan va uxlashga qarshilik qilmoqda. Dadasini yordamga chaqiring. Dadasi bolani beliga mindirib, ot bo‘lib chopganida, xona qahqahaga to‘ladi, to‘planib qolgan barcha jismoniy zo‘riqish va tuganmas energiya esa bir necha soniya ichida ter bilan birga yo‘qoladi.'),
  ('f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5', 'Xavfli so‘zlar 🤐', 'Ko‘chada yoki televizorda eshitgan o‘sha yomon so‘zni kulib sizga takrorlaydi va munosabatingizni katta qiziqish bilan kutadi. Eng kuchli qurolingiz — hech qanday munosabat bildirmaslik. Kulmang, jahlingiz chiqmasin, shunchaki e’tibor bermang. U bu so‘zni tez orada unutadi.'),
  ('07324b19-8c8c-4d15-8c79-0b07b4d8c8cf', 'Vannadagi okean 🌊', 'Vannada cho‘milish endi shunchaki tozalanish emas, balki to‘lqinlar yasash o‘yinidir. Suv atrofga sachrasin, hammom ho‘l bo‘lsin — mayli. Suvning o‘sha sehrli ta’siri kun bo‘yi unda to‘plangan o‘jar, salbiy energiyani yuvib, oqova bilan olib ketadi.'),
  ('501e8f67-b2b7-4164-9b32-0326fabd781c', 'Yopiq eshik ortidagi sirlar 🚪', 'Xonasiga kirib, eshikni ichkaridan yopib, yolg‘iz qolishni xohlayaptimi? Unda shaxsiy hudud tushunchasi va o‘ziga xoslik shakllanmoqda. Xavfsizlik choralarini ko‘rib, unga shaxsiy hayot uchun shu kichik huquqni bering. U ulg‘aymoqda.'),
  ('9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7', 'Kayfiyat kundaligidagi e’tirof 📝', 'Telefoningizni qo‘lingizga oling. Ijtimoiy tarmoqlarda boshqalarning mukammal hayotini tomosha qilish o‘rniga, Kayfiyat kundaligini oching va bugun uning qilgan eng kulgili, sizni eng ko‘p kuldirgan ishini kelajak uchun yozib qo‘ying. U yerga yozish — eng sof terapiya.'),
  ('4acc88e2-20b2-4215-8fcd-8a14393b92b9', 'Juftlik shampani 🥂', 'Bola uxlab qoldi. Shampan bo‘lmasa ham, piyolalarga issiq choy quying va juftingiz bilan «Bu bo‘ronli kunni ham sog‘-omon yakunladik», deb piyolalarni urishtiring. Siz bu uyning ham sarkardalari, ham yengilmas jamoasisiz.'),
  ('4b9f4b0d-becb-4db4-85ec-0a0caae64162', 'Mantiqsiz ko‘z yoshlar 🐶', 'Ko‘chada ko‘rgan it unga qaramagani yoki barg yerga tushgani uchun ho‘ngrab yig‘ladimi? Bundan mantiq izlamang. Bu uning uchun chindan ham chuqur qayg‘u. Shunchaki «Bilaman, sen uning senga qarashini xohlaganding», deb his-tuyg‘usini tan oling.'),
  ('9ae0817a-4137-49f1-8c45-fb16cc1d750b', 'Bog‘dagi siyosat 🤝', 'Sirpanchiqda boshqa bolani itarib, o‘zi uchishni xohlayaptimi? Bo‘lishish hali u uchun to‘liq shakllanmagan murakkab tushuncha. Uni uyaltirish yoki jazolash o‘rniga, «Hozir uning navbati», deb shunchaki tartib-qoidani eslatib qo‘ying.'),
  ('23303195-392c-42b3-a778-b5f932e7d2fb', 'Tananing bong urishi 🩸', 'Sababsiz jizzakilik va charchoqqa taslim bo‘lmang. Hayz kuzatuvchisiga qarang — tanangiz sizga ishora bermoqda. O‘zingizni ayblash o‘rniga, magniyga boy yegulik bilan dam oling.'),
  ('455a26dd-2714-4e7f-a8b0-c2319880fdbd', 'Soya bilan kurash 👻', 'Devordagi soyasidan qo‘rqib, ortingizga yashirinadimi? 3 yoshning o‘rtalariga kelib tasavvur chegara bilmaydi. Xonani qorong‘ilatib, fonar yordamida devorda qo‘llaringiz bilan soya o‘yinlarini yarating. U qo‘rqadigan qorong‘ilikni eng qiziqarli mashg‘ulotga aylantiring.'),
  ('ca0412c4-f03e-412b-a720-1ce839d731c8', 'Ertaklar sehri 🪄', 'Odatdagi o‘qish usulini bir chetga suring. Aqlli ertaklarni oching. Ertakdagi shamol ovozi, eshik g‘ichirlashi va qahramonning qadam tovushlarini og‘zingiz bilan chiqarib, xonada kichik ovozli teatr yarating. U bu tomoshadan hayratda qoladi.'),
  ('5ee7392d-5b0b-4213-bc93-84f42871cfbd', 'Uyquni kechiktirish taktikasi ⏱️', 'Uxlash vaqti kelganda birdan chanqab, hojatxonaga borgisi keladimi yoki hatto devor bilan xayrlashadimi? Taymer qo‘ying. Qo‘ng‘iroq chalinganda hamma uxlaydi degan qoidani joriy etib, bu cheksiz xayrlashuvlar va mohirona nayranglardan sabr bilan xalos bo‘ling.'),
  ('8ed6ac5e-566a-43de-a26f-f6688bac7a5c', 'O‘yinchoqlarning onasi 🧸', 'Xonadan ovoz eshitiladi. Diqqat bilan quloq solsangiz, u ayiqchasini xuddi sizning ohangingizda, siz ishlatadigan o‘ziga xos iboralar bilan koyimoqda! U sizning eng aniq nusxangiz. Bu o‘z xatti-harakatlaringizga chetdan nazar tashlash uchun ajoyib imkoniyat.'),
  ('fcc9b956-df18-4d44-8e28-2c6ce0162f8e', 'Ob-havo razvedkasi ⛅', 'Tashqaridagi ob-havo tushunarsizmi: quyosh charaqlab turibdi, ammo shamol ham esyaptimi? Ob-havo va kiyim vositasi derazadan bilib bo‘lmaydigan shamol tezligi hamda mos kiyim to‘plamini sizga darhol aytsin. Eshik oldida ikkilanib vaqt yo‘qotmay, sayrga chiqing.'),
  ('1eb146d3-b624-4eb5-88ee-21bab3e1a546', 'Shunchaki bag‘ringizga bosing 🫂', 'Hech qanday o‘yin, ovozli kitob yoki ertak kerak emas. Bu oqshom uni shunchaki bag‘ringizga bosing, uning beg‘ubor hidini to‘yib-to‘yib ichingizga yuting va qorong‘ida unga qanchalik qadrli ekanini, uni qanchalar yaxshi ko‘rishingizni pichirlab ayting.'),
  ('39c13cd6-54ea-4fd8-a9da-7ceece969e6d', 'Marketdagi «Men haydayman» qaysarligi 🛒', 'U market aravachasini o‘zi haydashni xohlaydi va uni javonlarga urib, hamma yoqni ostin-ustun qiladi. Odamlar orasida uni yig‘latgandan ko‘ra, qo‘llarini aravacha chetida qoldiring va o‘zingiz sezdirmay yo‘nalishni boshqaring. Esdan chiqqan narsalarni esa Xaridlar ro‘yxatidan tekshiring.'),
  ('dcf51c40-2de5-47dc-a87f-c99740f37d0f', 'O‘yinchoqlar tartibsizligi 🌪️', 'Har kuni bir xil o‘yinchoqlarni yig‘ishtirishdan charchadingizmi? Bugun yig‘ishtirmang! Uy muzey emas, balki hayot qaynaydigan, kichkina kashfiyotchi ulg‘ayayotgan iliq maskandir. Tartibsizlikka emas, bolangizning erkin kashf etish zavqiga e’tibor qarating va dam oling.'),
  ('7f0898f3-4281-4b25-877c-f3060088913f', 'Pastga qarang, u nimani kashf etyapti? 👣', 'U yalangoyoq yurishdan, gilamga, xonadagi toshlarga yoki sovuq kafelga tegishdan zavqlanadi. Oyoq kaftidagi nervlarning faollashishi uning muvozanati va nevrologik rivojlanishi uchun juda muhim, shuning uchun paypoqsiz yurishiga aslo to‘sqinlik qilmang.'),
  ('a17ad881-1738-43fa-b18c-dd0c7b263be1', 'Sun’iy intellekt, haqiqiy yechim 🤖', 'Bolangizning hamma narsaga keskin munosabat bildirishi sizni qo‘rqitdimi? Internetdagi vahimali maqolalarni unuting. Anacan AI-dan bu shunchaki vaqtinchalik stress reaksiyasi yoki yo‘qligini so‘rang hamda ilmiy va pediatrlar tasdiqlagan javobni olib, xotirjam bo‘ling.'),
  ('be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e', 'Sukunatning raqamli o‘lchovi 🤫', 'U nihoyat uxlab qoldi! Uyni qoplagan sukunatga ishona olmayapsiz. Ovoz o‘lchagichni yoqing va ekrandagi 0-10 detsibel raqamiga qarab, miyangiz asta-sekin qanday tiklanib, dam olayotganini ko‘z bilan his qiling.'),
  ('542ab746-c3f8-40a2-81ae-c00828c5ed07', 'Dadaning maxfiy taktikasi 👨‍🍼', 'Kunduzgi charchoq va shovqin-suron sizga yetarli. Kechga yaqin bolani uxlashga tayyorlash va tishlarini yuvdirish jarayonini dadasining o‘yinlariga topshirib, siz boshqa xonada mutlaq sukunatda dam oling.'),
  ('843abd1b-ca68-4402-b6ea-b248f8954a8f', 'Onaning quvvat manbai 🥑', 'Uni ovqatlantirish uchun 4 xil menyu tuzdingiz, ammo o‘zingiz nima yedingiz? Sog‘lom retseptlar orasidan 5 daqiqada tayyor bo‘ladigan, kalsiyga boy maxsus tamaddini tanlang va hatto tik turgancha bo‘lsa ham, maza qilib yeng — siz bu uyning harakatlantiruvchi kuchisiz.'),
  ('9b9022d6-2ceb-4fd3-b3c5-141395cf895c', 'Bo‘lishib bo‘lmaydigan nonushta 🍳', 'O‘z likopchasidagi ovqatni sizga aslo bermaydi, ammo kelib, sizning likopchangizdagi tuxum yoki pishloqdan yeyishni qat’iy talab qiladi. Bolalar ota-onasining tanloviga doim to‘liq ishonadi. Qarshilik qilmang, luqmangizni unga mehr bilan bering.'),
  ('3a219301-d574-4311-87ab-5dc04ddcfd8f', 'Jamoaviy massaj 💆‍♂️', 'Bola uxlagach, kun davomida to‘plangan barcha jismoniy va ruhiy zo‘riqishdan xalos bo‘lish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Siz shunchaki bir uyda yashaydigan ota-ona emas, balki bir-birini doim qo‘llab-quvvatlaydigan mustahkam jamoasiz.'),
  ('77e473a7-cc66-4af3-964b-ebd4e0ce22a0', 'Bu mening aybim emas! 🤷‍♂️', 'Suvni ataylab yerga to‘kdi, ammo aybni stolga ag‘darib, Stol sirg‘alib ketdi dedi. Bu yolg‘on emas, balki o‘zini himoya qilish instinktidir. U bilan tortishmang, Kel, stolga yordam berib, birga artamiz deb, uning ko‘ngliga tegmasdan mas’uliyatni o‘rgating.'),
  ('a43b3c7f-b8b9-440c-abc6-6650d2627176', 'Hamjamiyat ko‘magi 💬', 'Men endi hech qachon avvalgidek erkin bo‘la olmayman degan o‘y sizni birdan siqib qo‘yadimi? Bu o‘tkinchi, ammo juda og‘ir va chuqur tuyg‘uni Anacan hamjamiyatidagi onalar bilan baham ko‘ring hamda ular ham xuddi shu yo‘llardan o‘tganini bilib, tasalli va ko‘mak oling.'),
  ('602df0e4-a84c-493f-a594-485626339a2a', 'Chiroqlarni o‘chiring, uyqu kelsin 🌙', 'Tezroq uxlab qolishi uchun yotishdan 1 soat oldin xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin (uyqu gormoni) faqat qorong‘i va texnologiyalarsiz muhitda tez ajralib chiqib, uyquga ketishni osonlashtiradi.'),
  ('871e1c8b-981d-456b-8f8e-49b3f9df1255', 'Bloglardan ilhom olish 📱', '40-oyga yaqin bolada qanday rivojlanish sakrashlari yuz beradi? U nimalarni qila olishi kerak? Ilovadagi rivojlanish haqidagi bloglarni ko‘rib chiqing va farzandingiz idrok hamda mantiq borasida qanchalik ilgarilab ketganini ko‘rib, ich-ichingizdan quvoning.'),
  ('dc309f01-53dd-4d8e-b0a5-566a9cb979d1', 'Tugallanmagan gaplarning davomi 🗣️', 'Biror so‘zni unutib qolsa, qo‘llari bilan ishora qiladi, qoshlarini chimiradi va uni topishingizni kutadi. Gapini sabr bilan tugatganingizda, uning yuzida paydo bo‘ladigan «haa, aynan shuni aytmoqchi edim» degan yengillikni kuzating. Uning tarjimoni faqat sizsiz.'),
  ('35170eca-5526-4a79-8f60-bb6c6204b11e', 'To‘satdan och qolish sindromi 🥱', 'Endigina yotoqqa kirganida «Onajon, qornim ochdi», deb oshxonaga yugurmoqchi bo‘ladimi? Uyquni kechiktirish uchun ajoyib bahona! Ovqatlanish rejasida kechki payt uchun uyquga yordam beradigan kichik tamaddi tanlab, bu bahonani oldindan yo‘qqa chiqaring.'),
  ('a52300ac-c13a-4b61-bfa8-c7cb27b41cfa', '«Oyoqlarim charchadi» shantaji 🚶‍♂️', 'Ko‘chada ketayotib, birdan yerga cho‘kkalab, «Oyoqlarim uzilib ketdi, meni ko‘tarib oling», deydimi? Bu jismoniy charchoq emas, shunchaki onani boshqarishga urinish. Buni o‘yinga aylantiring: qani, uyga kim quyondek sakrab tezroq yetib borarkin?'),
  ('ed5f6008-15d7-44f7-a33c-21fd4bedec89', 'Onaning Reset tugmasi 🚪', 'Shovqin-surondan boshingiz yorilgudek bo‘lib, hammaga baqirgingiz keladi. Kayfiyat kundaligini oching. U yerga butun charchoq va holdan toyganingizni erkin yozing. Bu qisqa raqamli terapiya sizni yana reset qiladi.'),
  ('5294e5b4-881b-4e55-b798-fa4dd914d649', 'Axlat emas, san’at 🎨', 'U xonaning o‘rtasida mayda qog‘oz parchalari va kesilgan iplardan katta san’at asari yaratib, uni tashlab yuborishingizga ruxsat bermayapti. Ozodalikka haddan tashqari berilishni bir chetga suring. U yaratgan tartibsizlikni hurmat qiling, tozalash ertagacha kutishi mumkin.'),
  ('b303b530-f33d-4aed-9563-288f674e5686', 'Yig‘i tahlilidan yordam😭', 'Yarim tunda ko‘zlari yumuq holda yig‘lab uyg‘ondi va hech kimni eshitmayapti. Yig‘i tahlili yordamida tekshiring; agar bu tungi vahima bo‘lsa, uni uyg‘otishga urinmang. Shunchaki yonida indamay turing, u bir necha daqiqadan keyin yana uxlab qoladi.'),
  ('d0b48160-e2df-4f83-a2aa-8dad8ce91b39', 'Jonsiz buyumlar bilan suhbat 🗣️', 'Bog‘dagi toshga yoki uydagi stulga jiddiy ohangda nimalarnidir gapiradi, hatto ularni koyiydi. Ramziy o‘yinlar orqali u dunyoni va undagi qoidalarni anglab boradi. Rivojlanish kuzatuvchisida uning bu o‘ziga xos ssenariylarini albatta qayd eting.'),
  ('3486268f-4b63-480f-87b2-0334f163c85e', 'Vannadagi o‘yin 🌊', 'Vannada cho‘milish endi shunchaki yuvinish emas, balki to‘lqinlar yaratish o‘yiniga aylandi. Suv atrofga sachrasin, hammom ho‘l bo‘lsa ham mayli. Suvning o‘sha sehrli ta’siri kun bo‘yi unda to‘plangan qaysarlik va salbiy energiyani yuvib, oqizib yuboradi.'),
  ('c30e7d23-adbf-430f-894c-89ab12e4b61e', 'Ataylab buzish 🧱', 'U katta mehnat bilan minora quradi, keyin esa kulib, uni bir zarb bilan buzadi. Shu tariqa u fizika va sabab-oqibat bog‘liqligini o‘rganmoqda. Jahlingiz chiqmasin, qulayotgan minoralar uning miyasida yangi neyron aloqalari shakllanayotganidan darak beradi. Uni qaytadan qurishiga yordam bering.'),
  ('f4280214-1e8a-4015-949d-34ae67c41790', 'Kunduzgi uyqu mojarosi 🥱', 'U yotishni istamay, yig‘layaptimi? Majburlamang. Xonadagi yorug‘likni pasaytirib, Jim kitob varaqlash soatini e’lon qiling va ikkingizga ham hordiq beradigan yangi odat yarating. Shunda siz ham, u ham o‘ziga xos tarzda dam oladi.'),
  ('045a4c72-4a86-41d2-b03b-ae2eaef10270', 'Dadaning ertagi 📖', 'Bu oqshom ovozingiz charchadi. Ertak o‘qishni dadasiga topshiring. U kitobdagi rasmdan butunlay farq qiladigan, to‘qima va kulgili hikoya aytib, bolani qah-qah otib kuldiradi. Siz esa bir chetda, bir piyola choy bilan bu manzarani zavq bilan tomosha qiling.'),
  ('4f62a7a1-3c14-48ad-8798-069c557ed2c1', 'Kir yuvish yordamchisi 🧺', 'Siz katta mehnat bilan kiyimlarni taxlaysiz, u esa yordam beryapman deb, hammasini yana xonaga sochib tashlaydi. Jahlingiz chiqishining o‘rniga, ishni o‘yinga aylantiring: Qani, bu paypoqlarni savatga kim tezroq va aniqroq otar ekan?'),
  ('b2fc2b4c-64df-4f47-be2c-e630a4d24c5c', 'Tabiat qo‘yniga albatta chiqing ⛅', 'To‘rt devor orasida uning energiyasi tajovuzkorlikka aylanadi va har bir gapi yo‘q deb boshlanadi. Ob-havo va kiyimga qaramay, kerakli narsalarni tayyorlab, uni albatta tashqariga olib chiqing. Tuproqqa tegish uning asab tizimini darhol qayta tiklaydi.'),
  ('20cf0e7c-3293-4269-b577-f8012d7d5117', 'Mantiqning barbod bo‘lishi 🔴', 'Suvini qizil stakanga quyishingizni so‘rab qichqiradi, qizil stakanga quyganingizda esa bu safar nega bunga quydingiz deb yig‘laydi. Bu yerda mantiq yo‘q. U shunchaki charchagan va hissiyotlarini chiqarib yuborishga ehtiyoj sezmoqda. Xotirjam kuting, bo‘ron o‘z-o‘zidan tinadi.'),
  ('3d467b3e-4418-42f9-965d-e11c13d74805', 'Cho‘ntakdan chiqqan xazinalar 🪨', 'Shimini yuvayotganda cho‘ntagidan 2 ta tosh, bitta qurigan barg va yarimta cho‘p chiqdimi? Siz uchun chiqindi bo‘lgan bu narsalar uning olamni kashf etish jarayonida to‘plagan qimmatli kolleksiyasidir. Ularni tashlab yuborish o‘rniga, kichik xazina qutisiga yig‘ing.'),
  ('78fd11f7-de1e-4540-906f-51f08156be41', 'Aqlli ertakdagi men 🪄', 'Mumtoz kitoblarni yodlab bo‘lgansiz. Aqlli ertaklarni oching, bosh qahramon sifatida bolangizni, zabt etiladigan joy sifatida esa uning xonasini tanlab, noodatiy va hech qanday kuch talab qilmaydigan ovozli uyqu seansini yarating.'),
  ('4a5979ea-637a-48c3-a6a9-1af57b3d55c4', 'Xayoliy do‘kon 🍅', 'Xonaning bir burchagiga o‘yinchoqlarini yig‘ib, sizga xayoliy pulga xayoliy pomidor sotadi. Bu savdo o‘yiniga juda jiddiy yondashing. Xayoliy pomidorni sotib olib, ishtaha bilan yeyayotgandek ko‘rsating. Rolli o‘yinlar uning ijtimoiy intellekti uchun eng mustahkam poydevordir.'),
  ('58c30ae3-2599-434d-af6b-bb25c9a1766d', 'Musiqiy gipnoz 🎶', 'Kechga yaqin hech qanday sababsiz injiqliklar va yig‘i xurujlari boshlandi. Televizorni o‘chiring, chiroqlarni xiralashtiring va xonada juda past ovozda mumtoz musiqa qo‘ying. Musiqaning chuqur ohanglari muhitni sehrli tarzda o‘zgartiradi.'),
  ('d8b0e257-5429-4bf7-b2a7-1bb116658651', 'Mukammallik mavjud emas 🛑', 'Bugun sabringiz chidamadimi? O‘zingizni yomon his qilmang. Internetdagi benuqson ona haqidagi xayollardan uzoqlashing. Siz haqiqiy onasiz, o‘z his-tuyg‘ularingizni va charchog‘ingizni yashirishga majbur emassiz.'),
  ('4673a3e6-d285-4515-9173-039b8bcbc1e0', 'Xaridlar yordamchisi 🛒', 'Do‘konga borganingizda eng kerakli narsani doim unutib qoldirasizmi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni o‘sha yerga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda hammasini ro‘yxat bo‘yicha olib kelsin, siz esa boshingizni qotirmang.'),
  ('dd38c03c-a89e-4942-af31-f459dbf71386', '“Ona, menga qarang!” davri 👀', 'U divandan sakraydi va bir xil harakatni roppa-rosa 50 marta takrorlab: “Ona, menga qarang!” deydi. Nigohingizni telefondan uzing. U ko‘zlaringizdagi ma’qullash uchqunini ko‘rish uchun sakrayapti. Unga uzluksiz 5 daqiqa ajrating, e’tiboringizga to‘yib olsin.'),
  ('effd03a1-4f68-42a7-8c25-eabba9947bc3', 'Shivirlab aytilgan hikoyalar 🌙', 'Bugun juda ko‘p gapirganingizdan ovozingiz va o‘pkangiz charchadi. Chiroqlarni o‘chiring, uning yoniga yoting va kun davomida sodir bo‘lgan voqealarni qulog‘iga shivirlab aytib bering. Shivirlash uning diqqatini jamlaydi va miyasini gipnotik tarzda chuqur uyquga tayyorlaydi.'),
  ('b2543089-e56e-4e5f-b7a7-8528d7fea1b5', 'Ertalabki diktator ish boshida 👑', 'U yerga siz o‘tirmang, ayiqcham o‘tiradi! Nonushta paytida butun stolni u boshqaradi. Uning irodasini keskin sindirmasdan, «Mayli, ayiqchang u yerda o‘tirsin, men esa bu yerda o‘tiraman», deb muvozanatni va xonadagi tinchlikni saqlang.'),
  ('c7639a79-f169-46c8-bd32-85e01fd08685', 'Sham yorug‘ida choy 🕯️', 'Bola uxlab qoldi. Chiroqlarni o‘chirib, stol ustida bitta sham yoqing. Bu romantika uchun emas, shunchaki kun bo‘yi taranglashgan asablaringizni hamda ekranlar va shovqindan charchagan ko‘zlaringizni tinchlantirish uchun.'),
  ('c83edf54-e27c-4125-b28b-f2d18dfa66d3', 'Teginishlardan charchash 🔋', 'U kun bo‘yi ustingizga tirmashadi, quchoqlashingizni xohlaydi va sochingiz bilan o‘ynaydi. Teginishlardan charchash (touched out) — haqiqiy holat. Hech bo‘lmasa 15 daqiqaga bir o‘zingiz xonaga kirib, tanangiz faqat o‘zingizga tegishli ekanini his qilishga haqqingiz bor.'),
  ('01e96341-0baa-4735-9565-edc8b43ed916', 'Dadaning belida ot minish 🐴', 'U hali bor kuchini sarflab ulgurmagan va yotishga qarshilik qilyapti. Dadasini yordamga chaqiring. U bolani beliga mindirib, ot bo‘lib chopganida, xona qahqahaga to‘ladi, to‘planib qolgan barcha jismoniy zo‘riqish va tuganmas energiya esa bir necha soniya ichida ter bilan birga chiqib ketadi.'),
  ('384ff620-f71d-4bc9-9283-5e83ec033e38', 'Hamjamiyatda ko‘ngilni bo‘shatish 💬', 'Bugun har bir narsaga baqirdingiz va o‘zingizni dunyodagi eng sabrsiz ona kabi his qilyapsizmi? Iltimos, yolg‘iz emasligingizni biling. Anacan hamjamiyatiga kiring va boshqa onalar ham bugun siz kabi holdan toyganini o‘qib, yengil torting.'),
  ('da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9', 'Ko‘zgudagi raqib 🪞', 'U ko‘zgu qarshisida turib, o‘ziga qoshlarini chimiradi, jahldor va g‘alati yuz ifodalarini qiladi. U turli his-tuyg‘ular yuzida qanday aks etishini sinab ko‘ryapti. Bu mitti teatr aktyorining mashg‘ulotini chetdan, ovoz chiqarmay, qiziqish bilan kuzating.'),
  ('2b47e995-a54a-442e-b303-43e9894db748', 'Ertak yakunini uning o‘zi yozsin 🪄', 'Klassik kitoblardan ikkalangiz ham charchadingiz. Bu safar aqlli ertaklarda hikoya qanday tugashini farzandingiz tanlasin. «Sizningcha, qahramonga kim yordam berdi?» deb so‘rab, uxlashdan oldin uning tasavvuriga erkinlik bering.'),
  ('e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a', 'Muzdek mantiq 🥶', 'U muzlatkichni ochib, muz qolipini so‘raydi va qo‘llari sovqotayotganiga qaramay, uni qo‘yib yubormaydi. Issiq va sovuq tushunchalarini o‘z tanasi orqali sinab ko‘rmoqda. Bir idishga iliq, boshqasiga muzdek suv solib, bu kashfiyotni kichik ilmiy tajribaga aylantiring.'),
  ('fd41f13f-2abd-4cce-ba8e-06a55c0b506f', 'Dada bilan parkda yugurish 👨‍👧', 'Onalik 24/7 davom etadigan navbatchilik emas. Hamkoringizni ishga soling! Bugun tuganmas energiyasini dadasi bilan parkda sarflasin, siz esa uyda mutlaq sukunatdan zavqlaning.'),
  ('587f6b4e-5494-4f6a-8efa-28e0cb53f529', 'Oshxonadagi konsert 🥄', 'U qozonlar va yog‘och qoshiqlarni olib, oshxona o‘rtasida konsert uyushtirmoqda. Boshingiz og‘risa ham, bu uning ritmni his etishi va ijodkorligi rivojlanayotganidan darak. Darhol aralashmang, bir necha daqiqa davomida bu jo‘shqin energiya tovush to‘lqinlari bilan xonaga tarqalishiga imkon bering.'),
  ('a36ee256-d6c9-4345-a732-3a052e7dd260', 'Ob-havo razvedkasi ⛅', 'Tashqarida havo unchalik aniq emasmi: quyosh charaqlab turibdi, ammo shamol ham esyaptimi? Ob-havo va kiyim tanlash vositasi derazadan bilib bo‘lmaydigan shamol tezligi hamda mos kiyim uyg‘unligini sizga darhol aytsin. Eshik oldida ikkilanib vaqt yo‘qotmay, sayrga chiqing.'),
  ('c95b298d-8316-46aa-ace1-1fc1956a0fda', 'Jamoaviy massaj 💆‍♂️', 'Farzandingiz uxlagach, kun davomida to‘plangan stressdan xalos bo‘lish uchun hamkoringiz bilan bir-biringizning yelkangizni massaj qiling. Siz shunchaki bir uyda yashaydigan ota-ona emas, balki mustahkam tayanch bo‘ladigan jamoasiz.'),
  ('2c31302d-18e1-44cd-8719-76e1444cd735', 'Yashirin taom operatsiyasi 🥣', 'Kecha jon deb yegan tuxumini bugun og‘ziga ham olmaydi. Uning irodasi bilan kurashmang. Sog‘lom retseptlarda oqsilli mahsulotlarni turli, rang-barang va qiziqarli shakllarda taqdim etadigan ayyorona gazak retseptlarini sinab ko‘ring va g‘olib bo‘ling.'),
  ('723d3b58-0a46-493d-ba9b-9e4d8c6656ee', 'Sukunat tasdig‘i 🤫', 'Shovqinli kundan so‘ng, bola uxlaganida Ovoz o‘lchagich yordamida xonadagi sukunatni o‘lchang. Raqamlarning nolga yaqinlashayotganini ko‘rish, bu ko‘zga ko‘rinadigan osoyishtalik ona miyasi uchun eng yoqimli massajdek ta’sir qiladi.'),
  ('f226f50f-54a9-4f4e-ad02-b0959087d7d6', 'Kutilmagan «Sizni sevaman» 💖', 'Xonaning o‘rtasida o‘ynab turganida birdan sizga qaraydi, yugurib kelib, bo‘yningizdan quchadi. Bu barcha uyqusiz tunlar va charchoqlarga arziydi! Shu lahza olib kelgan chuqur va betakror xotirjamlikdan zavqlaning.'),
  ('3517ce10-8615-407d-be3b-394eda1c9fa6', 'Chiroqlarni o‘chiring, uxlash vaqti 🌙', 'Tezroq uxlab qolishi uchun yotishdan 1 soat oldin xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin (uyqu gormoni) faqat qorong‘i va texnologiyalarsiz muhitda tez ajraladi.'),
  ('7daa2d64-db1d-42ea-8cec-a0101d304bbf', 'Oziq tolaga ehtiyoj 💩', 'Ko‘p yuguradi, ammo suv ichishni unutadi. Tuvakdagi najasini kuzatib boring. Ich qotishi xavfi bo‘lsa, buni ilovaga qayd eting va darhol Ovqatlanishni nazorat qilish vositasi yordamida menyuga suli yormasi va olxo‘ri qo‘shing.'),
  ('e079d221-e081-498b-8457-7e4dc4555c89', 'Xavfli so‘zlar 🤐', 'Ko‘chada yoki televizorda eshitgan yomon so‘zni kulib sizga takrorlaydi va munosabatingizni katta qiziqish bilan kutadi. Eng kuchli qurolingiz — hech qanday munosabat bildirmaslik. Kulmang, jahlingiz chiqmasin, shunchaki e’tibor bermang. U bu so‘zni tez orada unutadi.'),
  ('7a91d538-17ac-47d6-a73e-975aed76abb5', 'Kichik biznesmen 🍅', 'Xonaning bir burchagiga o‘yinchoqlarini yig‘ib, sizga xayoliy pul evaziga xayoliy pomidor sotadi. Bu savdo o‘yiniga juda jiddiy yondashing. Xayoliy pomidorni sotib olib, uni ishtaha bilan yeyayotgandek ko‘rsating. Rolli o‘yinlar uning ijtimoiy intellekti va matematik tafakkuri uchun eng mustahkam poydevordir.'),
  ('87c32869-7e9b-4faa-bbbe-1c640a3da5bb', 'Kalsiy qalqoni 🦴', 'Tez o‘sayotgan suyaklar uchun kalsiy juda zarur. Sut ichmayaptimi? Ovqatlanishni kuzatish vositasi yordamida bugun qancha pishloq, qatiq yoki brokkoli iste’mol qilganini albatta hisoblang.'),
  ('dca4203c-2783-4935-8d52-5e2abbd31c77', 'Yotoqdan qochish 🏃‍♂️', '«Suv bering», «O‘yinchog‘imni topib bering»... Uxlamaslik uchun 3 yoshli bolaning bahonalari tugamaydi. Uyqu taymerini yoqing va belgilangan chegaralarga qat’iy rioya qiling.'),
  ('0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605', 'Ulkan yuk 🎒', 'Og‘ir sumkalaringizni yoki katta soyabonni albatta o‘zi ko‘tarishni xohlaydi, sudrab bo‘lsa ham olib boradi, ammo yordamni keskin rad etadi. Kuchini sinab ko‘rishiga imkon bering: u o‘zini uydagi eng kuchli qahramon deb his qilishni xohlaydi. Uning mustaqilligiga to‘sqinlik qilmang.'),
  ('13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf', 'Yangi shaxsiyat 🕷️', 'Ertalab uyg‘onib, sizga jiddiy ohangda: «Men bola emasman, men o‘rgimchakman», deydi. 40-oyga kelib uning tasavvuri chegara bilmay qoladi. Bahslashmang, unga nonushta qiladigan o‘rgimchak rolini bering va bu g‘aroyib tomoshaga qo‘shiling.'),
  ('b2a11f30-5597-4b15-9f01-835c2894a09b', 'Tugamaydigan bahonalar 🦶', 'Endi uxlab qolay deganda, «Oyog‘imning barmog‘i qichishyapti», degan bahona bilan yotoqdan turmoqchi bo‘ladi. U uyquni kechiktirish san’atini puxta egallagan. Jiddiy bo‘ling, oyog‘ini qashiyotgandek qiling va qat’iyat bilan chiroqlarni o‘chiring — chegaralarni siz belgilang.'),
  ('417acfcf-4492-4093-aa86-48285ecc470a', 'Dadaning qalpoq kiyish sharti 🧢', 'Uxlashga yotish uchun dadasi albatta qishki qalpoq kiyishini talab qiladi. Dadasi o‘sha qalpoqni kiyib, kulgili tovushlar chiqarsin. Oqshomdagi bu g‘alati va bema’ni holat uyqu oldidan sizni ham kuldiradi, bolaning qaysarligini ham bir zumda yo‘qotadi.'),
  ('7516076d-1a63-4620-b73e-63a31b706bac', 'Fizika qonunlariga qarshi qaysarlik 💧', '«Suvni quruq holda xohlayman», deb ho‘ngrab yig‘layaptimi? Bola miyasi imkonsiz narsalarni talab qilish orqali aslida sizning irodangizni sinaydi. Bu vaziyatdan mantiq izlamang, shunchaki boshqa rangli buyum bilan uning diqqatini darhol chalg‘iting.'),
  ('b726a724-b8d0-4de2-92f7-30636fde8d1a', 'Shkaf ichidagi jimjitlik 🚪', 'Uyda to‘satdan jimlik cho‘kdi va uni shkaf ichida yashirinib, o‘zi bilan o‘zi o‘ynayotgan holda topdingiz. Bu — shaxsiy makon izlayotganidan darak. Uni u yerdan darhol olib chiqmang: u ham shovqindan uzoqlashib, yolg‘iz qolishni va miyasiga dam berishni istaydi.'),
  ('4b514d29-e0d8-49a4-850f-900d0c46bffa', 'Jimjit g‘azab 😤', 'Istagi amalga oshmasa, yig‘lash o‘rniga qo‘llarini ko‘ksida chalishtirib, devorga qaragancha sizdan arazlaydi. Bu — his-tuyg‘ularni boshqarishning yangi va juda muhim bosqichi. Uni majburlamang, 3 daqiqadan so‘ng hech narsa bo‘lmagandek kulib qaytadi.'),
  ('4b721431-3565-4047-8fb3-144c9d3a8f8b', 'Oltindek jimjitlik o‘lchovi 🤫', 'Uydagi shovqindan quloqlaringiz shang‘illaydi. U nihoyat uxlab qolganida Ovoz o‘lchagich vositasini faollashtiring. Ekrandagi nolga yaqin raqamlarni, raqamli jimjitlikni kuzatish charchagan onaning miyasi uchun eng yoqimli vizual massajdir.'),
  ('6fcf10ba-99bd-4b23-bbff-0487161fbfe4', 'Yangi tilning kashf etilishi 🗣️', 'Uchar-qochar, Issiq-sovuq kabi o‘zi o‘ylab topgan murakkab va g‘alati so‘zlarni kashf etdi. Uning lug‘at boyligi nihoyatda tez kengaymoqda. Rivojlanish kuzatuvchisida u o‘ylab topgan bu kulgili so‘zlarni unutilmas xotira sifatida albatta qayd eting.'),
  ('272c7bb7-edd9-4323-8db9-05fe3c752757', 'Keskin hissiy o‘zgarishlar 🤖', 'Farzandingiz 3 yarim yoshga yaqinlashganda undagi keskin hissiy o‘zgarishlar sizni tashvishga soldimi? Internetdagi qo‘rqinchli va ruhiy jarohat yetkazuvchi forumlarni yoping. Anacan AI’dan bu yoshdagi inqirozlar haqida ilmiy va psixologik jihatdan asoslangan, ko‘nglingizni tinchlantiradigan javob oling.'),
  ('53a9bbe1-a99a-4438-963b-9b63a44c8eb3', 'Iliq suv mo‘jizasi 🛀', 'Ba’zida hech narsa yordam bermaydi, u shunchaki hamma narsaga yig‘layveradi. Uni iliq suvli vannaga tushiring va suvga biroz ko‘pik qo‘shing. Suvning o‘sha sirli, taranglikni ketkazuvchi kuchi butun xonaga va uning asab tizimiga bir zumda xotirjamlik olib kiradi.'),
  ('b49dbabf-98b6-4f35-8748-de30793c2722', 'Garderob muhandisi 👗', 'Bugun u ko‘chaga har xil paypoq va teskari kiyilgan ko‘ylakda chiqishni xohlayapti. Jamiyatning kiyimlarni moslashtirish qoidalarini bir chetga suring. Mustaqil qaror qabul qilish va uni himoya qilish erkinligi ranglarning uyg‘unligidan ko‘ra ancha muhim hayotiy saboqdir. Ruxsat bering.'),
  ('00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5', 'Jonli diktofon 🎙️', 'Kecha turmush o‘rtog‘ingiz bilan gaplashayotganda tasodifan aytib yuborgan, balki noo‘rin bo‘lgan bir so‘zni u bugun ertalab o‘yinchog‘iga aytyapti! U sizning jonli ko‘zgungizdir. Uning yonida qanday hissiyot bilan gapirayotganingizga alohida e’tibor bering — u hammasini birma-bir takrorlaydi.'),
  ('885b2dd9-966f-46c2-bbae-00f0fd65a479', 'Dadaning qiziqarli ertagi 📖', 'Bu oqshom xonada sizning ovozingiz yangramasin. Ertak kitobini dadasiga bering va u voqeani ataylab teskarisiga, kulgili va bema’ni tarzda aytib bersin. Farzandingiz uni tuzatishdan qanchalik zavqlanishini va dadasiga qarab qanday qahqaha otishini chetdan kuzating.'),
  ('fdf68496-5c5f-493c-aaed-7e9ab140b9c8', 'Hamjamiyat kuchi 💬', '“Nega mening farzandim bunchalik qaysar?” degan o‘y sizga tinchlik bermayapti. Anacan hamjamiyatiga qo‘shiling. Boshqa onalarning uyida ham shunga o‘xshash bema’ni inqirozlar yuz berayotganini o‘qib, yolg‘iz emasligingizni va mutlaqo to‘g‘ri yo‘lda ekaningizni ko‘rasiz.'),
  ('489a0197-f1e2-44a5-bece-55d85fa323ae', 'Ob-havo razvedkasi ⛅', 'Quyosh charaqlab turibdi, ammo u qishki kurtkasini kiymoqchi. Bahslashmang. Ob-havo va kiyim vositasini ochib, ekrandagi yengil kiyingan bola belgisini unga ko‘rsating. «Qara, telefon bugun havo issiq deyapti», degan hiyla har doim ajoyib ishlaydi.'),
  ('64df174c-9f28-403f-83be-8452dd687caf', 'Ssenariy uning qo‘lida 🪄', 'Klassik ertaklar endi uning e’tiborini tortmayaptimi? Aqlli ertaklarni oching va undan so‘rang: «Endi bu sehrli poyezd qayerga borsin?» O‘zi o‘ylab topgan o‘sha g‘aroyib va mutlaqo bema’ni yakun bilan xayol surib, uyquga ketsin.'),
  ('e9ba59d9-6287-434c-823d-456c6d21f0ef', 'Tish shifokori qabuli 🦷', 'U tish cho‘tkasini qo‘liga olib, tishlaringizni jiddiy tekshirmoqchimi? Og‘zingizni oching va bu quvnoq shifokorning aytganlarini bajaring. Rolli o‘yinlar shaxs kamoloti va qo‘rquvlarni yengishning eng samarali hamda eng qiziqarli usullaridan biridir.'),
  ('cafa10cc-4494-418e-834e-6ddf05c49140', 'Chiqindi emas, xazina 🍬', 'Bir necha kundan beri saqlab yurgan, ammo o‘ynamagan eski shokolad o‘ramini chiqindiga tashlaganingiz uchun qiyomat qoyim bo‘ldimi? Siz uchun chiqindi bo‘lgan narsa uning qimmatli to‘plamining bir qismi bo‘lishi mumkin. Yig‘isini to‘xtatish uchun e’tiborini darhol yanada qiziqarliroq buyumga qarating.'),
  ('d9ad6664-d013-4d53-b45b-e81b7aa6c58c', 'Shampansiz g‘alaba 🥂', 'Bola uxlab qoldi. Shampan bo‘lmasa ham, stakanlarga issiq choy quying va juftingiz bilan: «Bugun ham bu shiddatli tartibsizlikni eplay oldik», deb stakanlarni urishtiring. Siz oilaning mustahkam va tolmas jamoasisiz.'),
  ('e8db8e88-207e-4ac3-9421-9b1c49bdfd27', 'Brokkoli izquvari 🥦', 'U sho‘rvadagi bittagina yashil sabzavotni topib, ovqat yeyishdan bosh tortyaptimi? Ovqatlanish rejasidagi sabzavotlarni rangli makaron bilan aralashtirib, e’tiborini chalg‘itish yoki pyure qilib yashirishning eng mohirona usullarini qo‘llang.'),
  ('2c413ba6-81fc-4861-95ac-e87a4f29055d', 'G‘aroyib hamroh 🥄', 'Bog‘ga ketayotganda mashinalarini emas, oshxonadan topib olgan cho‘michni o‘zi bilan olib borishni talab qiladi. To‘sqinlik qilmang! Bu cho‘mich bugun bog‘da qum qazish uchun uning eng noodatiy, ammo eng foydali o‘yinchog‘iga aylanadi.'),
  ('b865240d-5ee4-4c57-917c-6139d1ce4039', 'Mushuklar suvdan qo‘rqadi 🐈', 'Vannaga tushmaslik uchun «Men mushukman, mushuklar cho‘milmaydi», deydi. Uning rolini qabul qilib, o‘yinni davom ettiring: «Bu mushuk sovun ko‘piklari bilan o‘ynashni xohlarmikan?» deb uni qiziqtiring va qarshiliklarni tasavvur kuchi yordamida yengib o‘ting.'),
  ('f573b98e-335c-4b92-b5f7-06c122ba5b12', 'Mohirona savdolashuv 🛒', 'Do‘konda konfet uchun yig‘lash o‘rniga: «Buni olsak, sho‘rvamni yeyman», deb savdolashadi. Tabriklaymiz, kichkina advokatingiz ulg‘aymoqda! Hech narsani unutmaslik uchun xaridlar ro‘yxatini ochiq tuting, u bilan bahslashayotganda chalg‘ib qolmang.'),
  ('605e9c74-a673-4f1f-9b27-383f6a4810eb', '«Menga qarang!» davri 👀', 'Divandan sakraydi va ayni bir harakatni roppa-rosa 50 marta takrorlab, har safar sizning ma’qullashingizni kutadi. Ko‘zingizni telefondan uzing. U harakatning o‘zi uchun emas, shunchaki ko‘zlaringizdagi mehrga to‘la ma’qullash uchqunini ko‘rish uchun sakrayapti.'),
  ('61cf1118-2d1d-4e42-9dac-f7a6ca616e71', 'Sokin sirdosh 📝', 'Sizni hech kim tushunmayotgandek va uyda juda qattiq charchayotgandek his qilyapsizmi? Soxta tabassumlarni bir chetga suring. Kayfiyat kundaligiga bugun aslida qanchalik holdan toyganingizni yozing. Ekranga tushgan har bir so‘z yelkangizdagi og‘ir yukni yengillashtiradi.'),
  ('a2f88e5e-134a-4514-9134-a36d1a155887', 'Polda uyqu 🥱', 'Kunduzgi uyqudan bosh tortib, o‘jarlik qildi, ammo o‘yinchoqlari orasida, gilam ustida g‘ujanak bo‘lib uxlab qoldi. Uni karavotga ko‘tarib olib borib uyg‘otmang, xona o‘rtasidagi o‘sha beg‘ubor manzaradan zavqlaning, o‘zingiz ham 1 soat dam oling.'),
  ('465bfed4-fe0b-4cbe-96cc-61ab753a7ff8', 'Tanadagi san’at 🖍️', 'Birdan atrof jimib qolganidan shubhalandingiz va uni qo‘llariga flomaster bilan san’at asari chizayotganida topdingiz. Jahlingiz chiqmasin. Uning mayda motorikasi yangi narsalarni kashf etmoqda, terisi esa baribir suv bilan yuviladi. Chuqur nafas oling va bu kulgili lahzani videoga tushiring.'),
  ('5f1b9ed1-3342-457d-874b-d33366fcceaf', 'Shivirlash gipnozi 🤫', 'U yotoqda shunchalik faolki, hech uxlamaydi. Ovozingizni ko‘tarish o‘rniga, birdan ovozingizni pasaytiring. U bilan faqat shivirlab gaplashing. Bola sizni eshitish uchun diqqatini jamlaganida, uning miyasi avtomatik ravishda uyqu rejimiga o‘tadi.'),
  ('6ac2df5a-944c-4a22-9450-7bfad30550c4', 'Onalar hamjamiyatining kuchi 💬', '«Bu bola hech qachon tinchlanmaydi», degan o‘y sizni charchatyaptimi? Anacan hamjamiyatiga qo‘shiling. U yerdagi onalarning shunga o‘xshash va hatto yanada kulgili qaysarlik haqidagi hikoyalarini o‘qib, yolg‘iz emasligingizni his qilasiz va yengil nafas olasiz.'),
  ('7b051600-3f87-4940-baec-461cd64e5af1', 'Falsafa professori 🤔', '«Nega shamol ko‘rinmaydi?», «Nega barglar to‘kiladi?» Tong sahardan bunday chuqur savollar miyangizni qizdiradi. Soatlab ilmiy izoh berishga urinmang. Chunki «Daraxtlar kiyimlarini almashtiryapti» kabi o‘ylab topilgan yoqimli javoblar bu yoshda uni to‘liq qoniqtiradi.'),
  ('7bab0bc1-e2b8-4588-8d81-ecc8ddbde523', 'Soyalar bilan raqs 🐰', 'U qorong‘ilikdan qo‘rqishini bahona qilib, yotoqdan qochadi. Xonadagi barcha chiroqlarni o‘chiring, fonarni yoqing va devorda qo‘llaringiz bilan qush hamda it soyalarini yarating. U qo‘rqadigan qorong‘ilik bir necha soniyada teatrga aylanadi.'),
  ('d0ef94fa-1acc-4932-b3b2-947791c88119', 'Sun’iy intellekt — najotkor 🤖', 'Bolaning savollari yoki g‘alati xatti-harakatlariga javob topa olmayapsizmi? Anacan AI''ga murojaat qiling. U 3 yoshdan oshgan bolalar miyasi qanday ishlashini sizga pediatr tilida, xotirjam qiluvchi va juda qisqa shaklda tushuntirib beradi.'),
  ('52a1e30d-f365-493c-8480-78b508714eb6', 'Qorong‘ilikdan qo‘rqadimi? 👻', '3,5 yoshga yaqinlashganda qorong‘ilikdan qo‘rqish tez-tez kuzatiladi. Xonasiga kichik tungi chiroq qo‘ying va Aqlli ertaklarda jasur qahramonlar haqida hikoyalar yarating.'),
  ('cbfa1fac-401d-41c2-974d-c9424b7436ce', 'Onalar suhbati 💬', '“Nega mening bolam hali ham tuvakka to‘liq o‘rganmadi?” degan o‘y sizni charchatyaptimi? Anacan hamjamiyatiga qo‘shiling va har bir bolaning rivojlanish sur’ati turlicha ekanini ko‘ring.'),
  ('cde5f67f-33e9-4a06-9155-b70a56cb6c73', 'So‘zlarni o‘zgartiradimi? 🗣️', 'Ayrim harflarni ataylab o‘zgartirib, kulgili tovushlar chiqaradimi va bundan kuladimi? U tilning moslashuvchanligini kashf etmoqda. Siz ham unga qo‘shilib, so‘z o‘yinlarini o‘ynang.'),
  ('57748696-ab80-425d-85cf-6283ca454879', 'Do‘stlik tuyg‘ulari 👫', 'Bog‘da endi boshqa bolalar bilan birga (parallel emas, o‘zaro muloqot qilib) o‘ynashga harakat qilyaptimi? Ijtimoiylashuv rasman boshlandi! Uni uzoqdan kuzatib, xavfsizligini ta’minlang.'),
  ('9fedc843-d647-418d-b31f-ad9bf956e849', 'Cho‘ntagingizdagi ro‘yxat 🛒', 'Kundalik yumushlar orasida shampun tugadimi yoki nam salfetkami? Buni eslab qolishga urinmang, darhol Xaridlar ro‘yxatiga yozing va turmush o‘rtog‘ingiz bilan sinxronlashtiring.'),
  ('ac1c42c5-b375-4935-bfbe-c3b0f8da74a1', 'Sukunatga ehtiyoj 🤫', 'Uxlab qolganidan keyingi dastlabki yarim soat eng nozik davrdir. Ovoz o‘lchagich yordamida xonadagi shovqin darajasini detsibelda tekshiring va qo‘shni xonadagi televizor ovozini pasaytiring.'),
  ('2e15df12-458b-434c-ac05-d42b6b0a04b3', 'Nafasining iliqligi 💖', 'U kun bo‘yi sizni rosa charchatdi, hamma narsaga qarshilik qildi. Ammo hozir yotoqda ko‘ksingizga suykalib yotibdi, xona esa uning bir maromdagi nafasi bilan to‘lgan. Onalikning eng katta mukofoti aynan shu. Uni bag‘ringizga mahkam bosing va barcha charchoqni unuting.'),
  ('b9503491-2c22-4639-94ac-cc1a79aea888', 'Teskari kiyilgan oyoq kiyim faxri 👟', 'Oyoq kiyimini teskari kiyib olgan, ammo xuddi dunyoni zabt etgandek mag‘rur yuribdi. Aralashib, to‘g‘rilashga urinmang. Bolaning o‘ziga ishonchi va mustaqilligi kiyimning chiroyli ko‘rinishidan million marta muhimroq.'),
  ('cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4', 'Hamdardlik cho‘qqisi 🩹', 'O‘yinchoq ayiqchasining qo‘li og‘riyapti deb, unga yara plastiri yopishtirib, o‘pyaptimi? Uning shunday katta va mehribon qalbiga qoyil qoling. Bu chuqur hamdardlik tuyg‘usini Rivojlanish kuzatuvchisida eng go‘zal xarakter fazilati sifatida faxr bilan qayd eting.'),
  ('1f4d8560-3286-4e95-8474-fcafd793fada', 'Dadasining maydoni 👨‍👧', 'Sabringiz tugayaptimi? Xona eshigini yoping va bolani dadasi bilan yolg‘iz qoldiring. Bugun kechqurun uydagi o‘yinlarning yagona boshqaruvchisi dadasi bo‘lsin, siz esa dam oling.'),
  ('af913905-7dd6-4f3e-bf26-424dee34a1c5', 'Qarang, men nima qilyapman! 🤸‍♂️', 'Bir oyoqda turishga yoki sakrashga urinib, e’tiboringizni jalb qilyaptimi? U sizning ma’qullashingizni istaydi. Bu jismoniy muvozanat ko‘nikmasini Rivojlanish kuzatuvchisida qayd etib, uni olqishlang.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('cd8e0cdd-1b7c-42e3-856f-3b4914ee1697'::uuid, 'Sabzavotlar jangi 🥦', 'Likopchadagi yashil sabzavotlarni chetga suryaptimi? Kurashmang. Foydali retseptlardan sabzavotlarni keks yoki kotlet ichiga yashirishga yordam beradigan ayyorona usullarni toping.'),
  ('602f2986-8e86-421e-ab71-94038d048ccf', 'Advokatdek gapiradi 🗣️', 'Endi siz bilan gap orqali savdolashishga urinyaptimi? Yana biroz o‘ynay, keyin uxlayman, deyaptimi? Nutqi juda yaxshi rivojlanmoqda, ammo o‘z chegaralaringizni saqlashni unutmang.'),
  ('6701933c-47e8-4c97-996b-a27409d87c3c', 'Pazl va mantiq 🧩', '5-6 bo‘lakli pazllarni birlashtirishga urinyaptimi? U geometriya va mantiqni o‘rganmoqda. Uning takroriy, ammo o‘rgatuvchi bu harakatlariga xalaqit bermang.'),
  ('a0d7169c-229c-430c-a926-4c31eef15e2c', 'Otaning ko‘magi 🫂', 'Tunda uyg‘onganida, albatta, navbatlashib turing. Ba’zan qorong‘ida faqat otasining bir maromdagi silashi va hidi bolani bir zumda tinchlantiradi.'),
  ('55bba77e-306b-49e8-94ad-180de8387a8b', 'Ko‘k olma talabi 🍏', 'Ko‘zini ochishi bilan baqirib, sizdan ko‘k olma so‘raydi. Tabiatda bunday narsa yo‘qligini tushuntirib, fizika/biologiyadan dars o‘tishga urinmang. Ko‘k olmalar hali uxlayapti, kel, qizilini uyg‘otamiz, deb uning bema’ni mantig‘iga xuddi shunday bema’ni, ammo ish beradigan javob qaytaring.'),
  ('5d5d4766-5ced-4cf7-8ea9-3acdffe118cf', 'Ko‘rpa vasvasasi 🛏️', 'Endi uxlab qolay deganida, birdan Ko‘rpa chap oyog‘imga tegib turibdi! deb yig‘lay boshlaydi. 3 yarim yoshli bolaning uyquni kechiktirish uchun o‘ylab topgan bu yangi vasvasasiga ichingizda kulib qo‘ying. Hech narsa demay ko‘rpani to‘g‘rilang va qat’iyat bilan xona chiroqlarini butunlay o‘chiring.'),
  ('8bcf9de1-187f-451e-8f68-1235d768b6ad', 'Shubhali sukunatning badali 💄', 'Uyda to‘satdan yuzaga kelgan 10 daqiqalik sukunatning oqibati: Xonaga kirsangiz, u eng sevimli lab bo‘yog‘ingiz bilan ham yuzini, ham oynani bo‘yab tashlagan bo‘ladi. Jahlingiz chiqishi uchun endi kech.'),
  ('02c49204-da15-4fa6-aab8-953dbda0aa33', 'Aqlli ertakdagi men 🪄', 'Klassik kitoblarni o‘qiyverib, ovoz paylaringiz charchadi. Aqlli ertaklarni yoqing. Farzandingizni bosh qahramon qilib, fon uchun tinchlantiruvchi o‘rmon tovushlarini tanlang va hech qanday kuch talab qilmaydigan, o‘zgacha, gipnotik uyqu seansini yarating.'),
  ('b5cdd715-cb24-4a73-93b6-d40eb1d78c2e', 'Hamjamiyatning sokin taskini 💬', '“Men endi hech qachon avvalgi erkin, beg‘am o‘zim bo‘la olmayman”, degan o‘y to‘satdan sizni bo‘g‘ayotgandek bo‘ladimi? Anacan hamjamiyatiga qo‘shiling. Boshqa onalar ham bu og‘ir, ammo mutlaqo tabiiy hislarni boshdan kechirayotganini va bu onalikning bir bosqichi ekanini o‘qib, taskin toping.'),
  ('dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c', 'So‘zlar remiksi 🗣️', '“Suv” va “sut” so‘zlarini birlashtirib, “sutsuv” kabi butunlay yangi so‘zlar o‘ylab topadi va kuladi. U o‘z lug‘ati bilan remiks qilyapti! Uning bu til o‘yinlariga qahqaha bilan qo‘shiling: miyasi aynan shunday tajribalar orqali til chegaralarini o‘rganadi.'),
  ('4d3c3b0d-80ec-45f4-815f-fb2e6cc34948', 'Kutilmagan mehr portlashi 🫂', 'Ertalab sizga “Keting”, degan bola yotog‘iga kirgach, bo‘yningizdan mahkam quchoqlab: “Sizni dunyolarcha yaxshi ko‘raman”, deydi. Mana, onalik paradoksi! Uning iliq nafasini chuqur his qiling va kun bo‘yi yig‘ilgan barcha charchoq uchib ketishiga imkon bering.'),
  ('50186ca0-d65c-4eb2-80df-487222e57b43', 'Oyi, bu yerdan keting! 💔', 'Biror istagi amalga oshmasa, sizga qarab: “Sizni xohlamayman, bu yerdan keting!” deydi. Ko‘nglingiz og‘rimasin. U hali g‘azabini qanday boshqarishni bilmaydi. Buni shaxsan o‘zingizga olmang. “Men shu yerdaman, tinchlanganingda gaplashamiz”, deb, unga his-tuyg‘ularini erkin boshdan kechirishi uchun imkon bering.'),
  ('ee0e20bd-35e2-417c-adfc-d1000ee7da40', 'Do‘kondagi advokat 🛒', 'Do‘konda konfet uchun o‘zini yerga tashlash o‘rniga: “Buni olsak, uyda sho‘rvamni yeyman”, deb savdolashadi. Tabriklaymiz, kichkina advokatingiz ulg‘aymoqda! Biror narsani unutib qo‘ymaslik uchun Xaridlar ro‘yxatini ochiq tuting, shunda u bilan bahslashayotib, asosiy maqsaddan chalg‘imaysiz.'),
  ('42ac5c0d-b412-4999-8839-ddf0e44a9d4b', 'Otaning sehrli qo‘llari ✈️', 'Kun bo‘yi ko‘tarib yurishdan qo‘llaringiz uzilib tushay deydi, ammo u hamon g‘ayratga to‘la va uxlashni istamaydi. Otasini yordamga chaqiring. U bolani havoga ko‘tarib, samolyot qilib o‘ynatganda, xona qahqahaga to‘ladi va to‘planib qolgan cheksiz energiya bir necha soniya ichida tugaydi.'),
  ('5a50a7bc-7ff1-421e-abac-beffc69e1480', 'Bordyur chetidagi sinov 🧱', 'Bog‘ga ketayotganda u odatiy yo‘ldan emas, xuddi dorbozdek bordyurning eng tor va baland chetidan yurishni qat’iy talab qiladi. Yirik motorika va muvozanat rivojlanmoqda! Qo‘lidan ushlab, xavfsizligini ta’minlang va u uchun juda muhim bo‘lgan bu kichik cho‘qqini zabt etishiga imkon bering.'),
  ('fd37073a-86b1-4420-9d46-293b17c2e64b', 'Ko‘rinmas it bilan sayr 🐕', 'U xonaning o‘rtasida qo‘lini pastga uzatib, ko‘rinmas itni silaydi va u bilan gaplashadi. Bu tasavvur rivojining eng beg‘ubor bosqichidir. «Itning ismi nima?» deb so‘rang va xonaning bir burchagiga xayoliy suv idishini qo‘yib, bu ajoyib teatrda ikkinchi darajali aktyorga aylaning.'),
  ('29371981-c485-4102-9d09-323cae4a8b4c', 'Garderob isyoni 🕶️', 'U nonushtaga quyosh ko‘zoynagi va qishki bosh kiyimda kelib, ularni yechishni qat’iyan rad etadi. Tashqi ko‘rinish va «odamlar nima deydi» degan o‘ylarni chetga suring. Mustaqil qaror qabul qilish va uni himoya qilish erkinligi kiyimlarning bir-biriga mosligidan ko‘ra ancha muhim psixologik poydevordir.'),
  ('51cdbeb9-6ab2-41f5-bfe2-9e148aedb489', 'Sukunatning raqamli o‘lchovi 🤫', 'Uydagi shovqindan quloqlaringiz jaranglaydi. U nihoyat uxlab qolganida, Shovqin o‘lchagichni yoqing. Ekrandagi 0-10 desibelgacha pasaygan raqamli sukunatni kuzatish charchagan ona miyasi uchun eng yoqimli va ko‘rgazmali tinchlantiruvchi massajdir.'),
  ('fca5f016-a334-4b48-86a0-e10c617f28f2', 'Chumoli qutqaruvchisi 🐜', 'Bog‘da yerdagi chumolini bosib ketishlaridan himoya qilish uchun yig‘lab, yo‘lni to‘sdimi? Uning bu ulkan mehr-shafqati va hamdardlik qobiliyatiga qoyil qoling.'),
  ('2ee42120-6dce-4972-a1f5-41636027a46e', 'Vannadagi sunami 🌊', 'Vannada cho‘milish endi shunchaki tozalanish emas, balki kichik sunami yaratish o‘yinidir. Suv atrofga sachrasin. Suvning o‘sha sirli, energiyani o‘ziga tortuvchi magnit ta’siri kun bo‘yi unda to‘plangan o‘jar, salbiy energiyani yuvib, oqova suv bilan olib ketadi.'),
  ('3a758cd5-028f-4ac8-be02-5dda6a95b453', 'Onaning dangasalik qilish huquqi 🍕', 'Bugun hamma narsaga baqirgingiz kelyaptimi? Uy ostin-ustun bo‘lib yotibdimi? Tozalashni qo‘ya turing, ovqat ham pishirmang. Tashqaridan pitsa yoki tayyorlash eng oson bo‘lgan taomga buyurtma bering. Mukammal ona bo‘lish haqidagi tasavvurni unuting — ruhiy salomatligingiz uy ovqatidan ancha qadrli.'),
  ('d683b351-38a0-49ed-a8b1-b2fe98cd3d08', 'Suvni o‘zi quyishga bo‘lgan qaysarlik 💧', 'U suvni katta ko‘zadan kichik stakanga albatta o‘zi quyishni xohlaydi. Suv stolga, u yerdan esa polga to‘kiladi. Ammo uning latta olib, o‘sha joyni tozalashga urinayotgan mitti qo‘llariga qarang. U xato qilish orqali mas’uliyatni o‘rganmoqda, bu tartibsizlikning o‘zi rivojlanishdir.'),
  ('746ce0d9-945c-4d05-9518-1097d9f22fcd', 'Kichik qaychilar bilan tanishuv ✂️', 'U bolalar uchun xavfsiz plastik qaychi bilan qog‘oz kesishga urinyaptimi? Bu mayda motorika uchun ajoyib mashq! Buni rivojlanish kuzatuvchisida albatta qayd eting.'),
  ('d01a4de6-1799-4ace-b8f9-b22ea720b143', '“Menga qara!” degan qaysarlik 👀', 'Siz telefonga yoki boshqa ishga qarayotganingizda, u kelib yuzingizni o‘ziga qaratadimi? U sizning butun e’tiboringizni istaydi. Ko‘zlariga qarab, uni tinglayotganingizni his qildiring.'),
  ('ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c', 'Dadaning navbati 👨‍🍼', 'Tunda chaqaloq uyg‘onishining barcha mashaqqatini bir o‘zingiz ko‘tarmang. Turmush o‘rtog‘ingizni ham uyg‘oting — jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir.'),
  ('4e5540da-110f-46b1-a6fe-0833314d27a6', 'Nima pishirsam ekan? 🍲', 'Qo‘shimcha ovqat menyusi uchun g‘oyalaringiz tugadimi? Internetda adashib qolmang, Sog‘lom retseptlar bo‘limidan yangi mazalarni kashf eting.'),
  ('7d3efca9-83bd-4ef7-a064-007baae56a2f', 'O‘ziga xos ertak 🪄', 'Aqlli ertaklarda bosh qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: Sehrli qaychi bilan dunyoni rang-barang qiladigan jasur kichkintoy.'),
  ('fa3aa9fa-1390-45bd-833a-86ce9790410b', 'Men ham yordam beray! 🧹', 'Siz kiyimlarni taxlayotganingizda ularni qo‘lingizdan olishga urinadimi? U o‘zini allaqachon katta his qilyapti. Unga kichkina sochiq berib, yordam qilishiga ruxsat bering.'),
  ('9049cae3-8dbb-4e95-8c21-0965664d904f', 'Sizga bir sir aytaman 🤫', 'To‘shakka yotib, ko‘zlari endi yumilayotganida birdan: Oyi, sizga bir sir aytaman, deb uyquni qochirishga urinadi. Uyquni kechiktirish san’ati bo‘yicha rasman doktorlik dissertatsiyasini himoya qilishyapti. Tabassum qilib: Siringni tushingda aytarsan, deng-da, chiroqlarni qat’iyat bilan o‘chiring.'),
  ('a097a156-cfb7-4bbb-a187-0b6a9ba7dade', 'Pechenyening faqat kremi 🍪', 'Dumaloq pechenyening o‘rtasidagi kremni yalab, quruq qismlarini stol chetiga terib chiqdimi? Tabriklaymiz, siz rasman 3.5 yoshli bolaning ovqatlanish falsafasi bilan tanishdingiz. Sog‘lom retseptlar bo‘limida uning e’tiborini tortadigan foydaliroq, ammo qiziqarli tamaddilarni kashf eting.'),
  ('bf046ede-b62a-43aa-8a59-9305494237e5', 'Siz kuylamang! taqiqi 🛑', 'Orqa fonda yangrayotgan bolalar qo‘shig‘iga xirgoyi qilib qo‘shilgan edingiz, u shu zahoti: Siz kuylamang! deb baqirdi. Xonaning yagona yakkaxoni — u, sizning kuylashga urinishlaringiz esa uning sahnasini toraytiradi. Xafa bo‘lmang, sahnani shu kichkina xudbinga qoldiring.'),
  ('6b819068-b681-48a9-82bf-6d4801827c9e', 'Onaning devor bilan ko‘z urishtirishi 🛋️', 'Xonada shovqin-suron, u o‘yinchoqlarini bir-biriga uryapti, siz esa bo‘sh devorga tikilib, xayolan uzilib qolgansiz (zoned out). Bu miyangizning himoya mexanizmi. O‘sha 5 daqiqalik qotib qolish holatini o‘zingizga ko‘p deb bilmang — hayotga yana qaytishingiz uchun bu sizga kerak.'),
  ('6b9b4528-1015-4f69-940f-0bb0951b3bab', 'Jamoat joyidagi shokka tushiruvchi savollar 😳', 'Avtobusda yoki do‘konda baland ovozda: Bu xolaning burni nega buncha katta? deb so‘radimi? Yer yorilib, ichiga kirib ketsangiz deydigan o‘sha lahza! Uni jim qilishga urinib, uyaltirish o‘rniga, diqqatini darhol boshqa rangli buyumga qarating va vaziyatdan diplomatik tarzda chiqib keting.'),
  ('8d369fcb-2b04-4658-a824-5b34c817cbfd', 'Dadaning mantiqsiz shartlari 🎲', 'Kechasi pijama kiymaslik uchun uy bo‘ylab qochib yuribdi. Dadasi: Qani, bu pijamani ko‘zingni yumib kiya olarmikan-san? deb bema’ni bir o‘yin o‘ylab topadi. Va bum! Bola o‘zi sezmagan holda pijamasini kiyib oladi. Dadalarning mantiqsiz, ammo ish beradigan bunday o‘yinlarini chetdan turib faqat olqishlash qoladi.'),
  ('5eac5298-1552-4198-9ef8-4a16006b3701', 'Men chaqaloqman! nostalgiyasi 🍼', 'Birdan chaqaloqdek emaklab, yig‘lab, men chaqaloqman, meni quchoqlang deya boshladimi? Ulg‘ayish ba’zan ularni ham qo‘rqitadi va ular avvalgi xavfsiz chaqaloqlik kunlariga qaytishni istashadi. Uni bir necha daqiqaga xuddi o‘sha eski kunlardagidek quchoqlab, erkalang.'),
  ('bb01fed8-0d6f-4127-8a47-f959e37b46e4', 'Loydan sho‘rva 🍲', 'Bog‘da suv bilan tuproqni aralashtirib, ona, sizga sho‘rva pishirdim deya o‘sha loyni sizga uzatadi. Jirkanmang! O‘sha sho‘rvani xayolan dunyodagi eng mazali taomdek iching.'),
  ('c5e8c723-3ce3-424f-8294-5aece5936ca5', 'Sukunatning raqamli zavqi 🤫', 'Uydagi tartibsizlik nihoyat tugadi va u uxlab qoldi. Shovqin o‘lchagichni yoqing va xonadagi sukunat darajasini (0-10 desibel) ekranda kuzating. Nolga yaqin o‘sha raqamlarni ko‘rish charchagan onaning miyasiga dunyodagi eng qimmat spa seansidek ta’sir qiladi.'),
  ('204c6838-b697-4616-9592-52e0162c6a92', 'Banan ustidagi tirnalgan joy 🍌', 'Banan po‘stini archganda, ustida millimetrcha kichik tirnalgan joyni ko‘rib, Bu buzilibdi! deb baqiradi. Bolalarning tashqi mukammallikka intilishi aql bovar qilmas darajada. O‘sha joyini pichoq bilan kesib, Qutqardim! deb bu kichik dramaga yakun yasang.'),
  ('49d8e195-1371-46c6-a98a-c6f38e78e098', 'Eshiklarni qulflash missiyasi 🚪', 'Uydagi barcha xonalarning eshiklarini ichkaridan qulflab, sizni tashqarida qoldirishdan o‘zgacha zavq oladi. U shaxsiy makon tushunchasini yangicha talqin qilmoqda. Barmoqlari qisilib qolmasligi uchun ehtiyot choralarini ko‘ring, ammo uning o‘z hududini e’lon qilish o‘yiniga jiddiy xalaqit bermang.'),
  ('524b4634-31bf-4fa3-860b-d29e08cc3c10', 'Ertakdagi turli ovoz ohanglari 🪄', 'Bugun kechqurun Aqlli ertaklarni yoqing, ammo matnni har xil ohangda o‘qing. Ayiqning ovozini yo‘g‘on, qushnikini esa ingichka qilib, xonada kichik teatr yarating. Bu bir xillikni buzadi va bolaning diqqatini bir zumda ertakka, undan esa uyquga chorlaydi.'),
  ('603225e8-0807-426b-b793-892dfeb9e281', 'Qorong‘idagi shivirli kashfiyotlar 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Yoniga yotib, kun davomida sodir bo‘lgan voqealarni yoki uning fe’l-atvoridagi sizga eng yoqadigan jihatni juda past ovozda qulog‘iga shivirlab ayting. Shivir — miyani uyquga tayyorlaydigan va shovqinni unuttiradigan eng sirli usullardan biridir.'),
  ('60fcf611-529f-4586-9532-af738483766f', 'Uy ichidagi soyabon ☂️', 'Tashqarida quyosh charaqlab turibdi, ammo u uy ichida ochiq soyabon bilan yurishni xohlaydi. Uning tasavvuri real muhit chegaralarini tan olmaydi. Uyda bo‘sh joy bo‘lsa, o‘sha soyabon ostida o‘ziga kichik qarorgoh qurishiga ruxsat bering. Bolalarning o‘ziga xos mantiqini jamiyat me’yorlari bilan bo‘g‘mang.'),
  ('831decae-1343-4bbb-bf11-1f398cc1bc2d', 'Do‘kondagi Yo‘q sinovi 🛒', 'Do‘konning qoq o‘rtasida konfet so‘radi, siz Yo‘q dedingiz va u yig‘lay boshladi. Atrofdagilarning tanqidiy nigohlariga qaramay, qaroringizdan qaytmadingiz. Siz ajoyib onasiz! Biror narsani unutmaslik va tezroq chiqib ketish uchun esa Xaridlar ro‘yxatini ko‘zdan qochirmang.'),
  ('1d613098-d421-410e-ae85-8cfd9552b432', 'Hech bir sababsiz «Nega ismimni aytdingiz?» 😤', 'Siz shunchaki «Kel, ovqat tayyor», dedingiz, u esa jahli chiqib, «Nega mening ismimni aytdingiz?» deya yig‘lay boshladi. Bu yoshda his-tuyg‘ular shu qadar chalkash bo‘ladiki, ba’zan hech bir sababsiz ham xafa bo‘lishadi. Hech narsani tushuntirmang, 2 daqiqadan keyin o‘zi ovqat yeyishga yugurib keladi.'),
  ('ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02', 'Sun’iy intellekt va g‘alati fobiyalar 🤖', 'U birdan doim o‘ynaydigan qizil mashinasidan qo‘rqib qoldimi? Sababsizdek tuyuladigan fobiyalar sizni xavotirga solsa, internetdagi qo‘rqinchli forumlarni yoping. Anacan AI’dan 3.5 yoshli bolaning tasavvuridagi g‘alati holatlar haqida ilmiy va xotirjam qiluvchi javob oling.'),
  ('cacabcad-105f-4eff-bcae-aa81bf6e1cbd', 'Juftlik bo‘lib film tomosha qilish... 🎬', 'Bola uxlab qoldi! Nihoyat turmush o‘rtog‘ingiz bilan film tomosha qilish uchun divanga o‘tirdingiz, ammo 10-daqiqadayoq ikkalangiz ham qattiq uyquga ketdingiz. Bu — sizning haqiqatingiz. Bir-biringizga suyanib uxlab qolgan o‘sha charchoq manzarasi chinakam jamoaviy hamkorlikning ifodasidir.'),
  ('45baf1a1-9599-41ad-8361-b1f8a05e79a2', 'To‘shakdagi ushoqlar 🍞', 'Ertalab ko‘zingizni ochsangiz, to‘shak ichi kreker ushoqlariga to‘lib yotibdi. Ma’lum bo‘lishicha, u tong sahardan o‘ziga nonushta tayyorlabdi. Baqirish o‘rniga, uning muammoni mustaqil hal qilish qobiliyatini Rivojlanish kuzatuvchisida kulgili bir xotira sifatida qayd eting.'),
  ('5b590891-270c-48fa-a5d7-d69f319ed48e', 'Dadaning yelka massaji 💆‍♂️', 'Bugun ko‘p vaqt oyoqda turdingiz, uning ortidan yugurib, yerdan o‘yinchoqlarni yig‘averib, belingiz uzilgudek bo‘ldi. Bola uxlashi bilan turmush o‘rtog‘ingizdan 10 daqiqalik yelka massajini so‘rang. Siz uyning ustunisiz, ustunlar esa albatta dam olishi va tiklanishi kerak.'),
  ('5ff3402c-285a-4d58-a123-bc33ce162448', 'O‘zim qilaman! 🛑', 'U oyoq kiyimining bog‘ichini albatta o‘zi bog‘lamoqchi bo‘ladi, uddalay olmay jahli chiqadi, ammo yordamingizni ham keskin rad etadi. Chuqur nafas oling. Buzilgan vaqt jadvalidan ko‘ra, shikastlanmagan o‘ziga bo‘lgan ishonch uning kelajagi uchun muhimroqdir. Kuting.'),
  ('8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346', '“U menga qaradi!” fojiasi 👀', 'Parkda boshqa bir bola shunchaki unga qaragani uchun ho‘ngrab yig‘lay boshladimi? Ijtimoiy chegaralarini endigina anglayotgan bola uchun hatto birovning qarashi ham uning hududiga aralashishdek tuyulishi mumkin. Uni quchoqlab, “U shunchaki sening chiroyli ko‘ylagingga qarayotgan edi”, deb e’tiborini boshqa narsaga qarating.'),
  ('b272e283-3b37-4825-9917-d8f7f4f54d69', 'Aqlli ertaklar bilan sokinlik 🪄', 'U xona bo‘ylab yugurib, yotishni rad etyapti. Chiroqlarni xiralashtiring. Aqlli ertaklarda qiziqarli hikoya yarating va o‘qib bering.'),
  ('ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc', 'O‘yinchoqlarni qatorga terish 🚗', 'U barcha mashinalarini xonaning bir chetidan ikkinchi chetigacha millimetr aniqlikda qatorga terib chiqdi va hatto bittasining joyi o‘zgarishiga ham yo‘l qo‘ymayapti. Bu vizual tartibga bo‘lgan ehtiyojdir. Bu mitti me’morning ishini chetdan jimgina tomosha qiling va tartibini buzmang.'),
  ('0136ed32-a803-4c48-aa0d-ab3379945e1c', 'Hamjamiyatda yashirin o‘quvchi bo‘lish 💬', 'Siz juda charchagansiz va hech kimga hech narsani tushuntirishni yoki dardlashishni istamayapsiz. Anacan Hamjamiyatiga kirib, shunchaki o‘quvchi bo‘ling. Boshqa onalarning xuddi shunday bema’ni injiqlik xurujlarini qanday yengayotganini ko‘rish — eng kuchli sokin terapiyadir.'),
  ('b9bc7eed-7b9f-4aa8-8301-118abf554ade', 'Noto‘g‘ri qoshiq o‘lchami inqirozi 🥄', 'Sho‘rvani katta qoshiqda berganingiz uchun deyarli inqilob ko‘tarildi. “Men kichkina qoshiqni xohlagandim!” Taom bir xil bo‘lsa-da, bolaning mantiqiga ko‘ra, qoshiqning o‘lchami ovqatning ta’mini o‘zgartiradi. Bahslashmang, shunchaki qoshiqni almashtiring va kuchingizni asrang.'),
  ('c2cb9b1d-61a5-43c0-97ec-813152f9cfe1', '“Ustimni yop!” vasvasasi 🛏️', 'U endigina uxlab qolayotganida ko‘rpaning uchi ochilib qoladi va “Ustimni yop!” deb baqiradi. Ko‘rpa chetlarining mutlaqo tekis turishi uning uchun hayot-mamot masalasidek muhim. Ko‘rpani xuddi dazmollangandek tekislang va bu kulgili uyqu marosimlarini ichingizda jilmayib qabul qiling.'),
  ('4aca275a-17a5-44c6-88b5-fa54de701839', 'Plastirga muhabbat 🩹', 'U tanasida ko‘rinmas bir yara topib, o‘sha joyga yara plastiri yopishtirishingizni qat’iy talab qilmoqda. Bu jismoniy og‘riq emas, shunchaki onasining e’tibori va mehriga bo‘lgan ehtiyojdir. O‘sha kichkina plastirni yopishtirib, o‘pib qo‘ying — ishoning, kuningiz qutqariladi.'),
  ('6549682b-784d-4e30-b184-53c2ea51b45f', 'Sukunatning vizual zavqi 🤫', 'Uydagi tartibsizlik nihoyat tugadi va u uxlab qoldi. Idishlarni yuvishga shoshilmang! Shovqin o‘lchagichni yoqing va xonadagi mutlaq sukunatga (0-10 detsibel) qarab, 15 daqiqa davomida miyangiz qanday dam olayotganini, bu vizual sukunat sizni qanday tiklayotganini his qiling.'),
  ('c51feab8-8101-47a7-82b7-0a8e946ff974', 'Qum me’morchiligi 🏰', 'U parkdagi qum maydonchasini xuddi xazina qidirayotgandek chuqur qazimoqda. Ust-boshi loy. Ammo uning bu kashfiyot onini buzmang. Ob-havoga mos va kir bo‘lishiga achinmaydigan kiyimlarni oldindan tanlasangiz, bu manzarani stresssiz kuzata olasiz.'),
  ('95e37724-7f25-4dc6-a06e-d194ca45d333', 'Kechki mashq — dadasining ustida sakrash 🤸‍♂️', 'U energiyasini sarflay olmadi va yotishni istamayapti. Dadasini divanga yotqizing va bolaning uning ustida sakrashiga ruxsat bering. Dadasi chiqaradigan kulgili tovushlar xonani qahqahaga to‘ldiradi va ortiqcha energiyaning barchasi bir necha soniyada tugaydi.'),
  ('9680e706-6c53-46d8-b37d-e2b2ed358ee7', 'Onaning o‘ziga g‘amxo‘rligi 🥗', 'Uni to‘ydirish uchun 3 xil menyu o‘ylab topdingiz-u, o‘zingiz yana och qoldingizmi? Ovqatlanish rejasi bo‘limidan nafaqat bolalar, balki onalar uchun ham quvvat beradigan, 10 daqiqada tayyorlanadigan, temir va kalsiyga boy tushlikni tanlang va o‘zingizni qadrlang.'),
  ('c0f71481-4d8f-40e3-87af-c4432426cfab', 'Sen kimsan? o‘yini 🎭', 'Ertalab u sizga qarab, juda jiddiy qiyofada: Sen kimsan? Mening onam qani? deydi. Tasavvur rivojining eng yuqori cho‘qqisi! O‘yinga qo‘shiling: Men qo‘shni xolangman, onang hozir keladi, deb ovozingizni o‘zgartiring va bu ajoyib teatrni davom ettiring.'),
  ('17737c7f-74cb-4797-867c-90a8c03b4bfe', 'Hojatxona qog‘ozi san’ati 🧻', 'Bir necha daqiqalik jimlik... Xonaga kirganingizda esa hojatxona qog‘ozining hammasi yechilib, uy bo‘ylab yoyilib yotganini ko‘rasiz! Jahlingiz chiqmasin, yaxshisi qog‘ozlarni yig‘ib, birgalikda qorbobo yoki koptok yasang. Tartibsizlikni baqiriq bilan emas, ijodkorlik bilan yengib chiqing.'),
  ('300e5d4c-57c8-45bf-bdcd-829a6024697a', 'Quloqqa shivirlangan mehrli so‘zlar 💖', 'U kun bo‘yi sizni aqldan ozdiray dedi, har narsada o‘jarlik qildi. Ammo hozir yotoqda shunchalik begunoh bo‘lib uxlayaptiki... Yoniga yoting va uni qanchalik yaxshi ko‘rishingizni, bugun qilgan yaxshi ishlarini qulog‘iga shivirlang. Bolalar hatto uyqusida ham onasining mehrga to‘la ovozini his qiladi.'),
  ('42d87f04-8d19-4c11-b1e4-703ee34de8db', 'Kir yuvish mashinasi kashfiyoti 🧺', 'Kir yuvish mashinasi qarshisida o‘tirib, aylanayotgan kiyimlarga xuddi multfilm tomosha qilayotgandek diqqat bilan qarayapti. Bu mutlaqo bepul va ongni tinchlantiradigan mashg‘ulot. Unga xalaqit bermang, siz ham imkoniyatdan foydalanib dam oling.'),
  ('56f07d8f-4184-4cda-b356-e566ad65a81d', 'Ertakdan qochishga urinishlar 🏃‍♂️', 'Ertak o‘qiyotganingizda, har fursatda «O‘yinchog‘imni olib kelaman», deb yotoqdan sakrab tushib, yugurib ketadi. Uyquga taslim bo‘lishni istamaydi. Ovoz ohangingizni birdan juda pasaytirib, shivirlab o‘qiy boshlang. Sizni eshitish uchun yotoqqa qaytishga majbur bo‘ladi, diqqat bilan tinglaydi va uxlab qoladi.'),
  ('6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8', 'Men katta bo‘lganman, qahva ichaman! ☕', 'U finjoningizga qo‘l uzatib, qat’iy ohangda: «Men katta bo‘lganman, men ham qahva ichaman», deydi. U shunchaki sizning dunyongizga qo‘shilishni istaydi. Uning kichkina finjoniga biroz sut va kakao quyib: «Mana, bu sening bolalar qahvang», deng va u bilan finjon urishtiring.'),
  ('7a51f55e-c494-489a-927c-6f2193813549', 'Ob-havo va qatlamlab kiyintirish usuli ⛅', 'Bahor yaqinlashgani sari ob-havo o‘zgaruvchan bo‘ladi; ertalab sovuq, tushda esa issiq. Ob-havo va kiyim vositasi sizga piyoz usulida (qatlamlab) kiyintirishni eslatadi. Istirohat bog‘ida havo isigani sari kiyimning bir qatlamini yechib, ham uning terlashiga, ham o‘zingizning asabiylashishingizga yo‘l qo‘ymang.'),
  ('175e4578-dab7-4e75-8a87-dd96baf6d2c6', 'Qo‘shiqni qaytar! 🎶', 'Radioda yangragan va tugagan qo‘shiqni yana qo‘yishni xohlaydi. Siz bu jonli efir bo‘lgani va qo‘shiq tugaganini tushuntirasiz. Ammo u “Qaytar!” deb yig‘laydi. Bola miyasi jonli efir mantig‘ini hali tushunmaydi. Diqqatini chalg‘itish uchun qo‘shiqni o‘zingiz boshqacha, kulgili ovozda kuylay boshlang.'),
  ('a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7', 'Xaridlar ro‘yxatidagi keraksiz narsalar 🛒', 'Do‘konga borishdan oldin xaridlar ro‘yxatini ochdingiz va u orqangizdan kelib, telefon ekranini bosib, ro‘yxatga ketma-ket tushunarsiz harflar va shokolad qo‘shayotganini ko‘rdingiz. Ha, ular raqamli dunyoni juda tez kashf etishadi!'),
  ('f9e8851b-f40e-4ed9-a246-2e1405232755', 'Sukunatdagi choy ☕', 'U xona o‘rtasida o‘yinchoqlarini qator qilib terib, o‘zi mustaqil o‘ynayapti. Iltimos, o‘sha fursatni uy supurishga sarflamang! Divanga o‘tiring, qahva yoki choyingizni issiqligida iching va 10 daqiqa hech narsani o‘ylamay, shunchaki shu sukunatdan zavqlaning.'),
  ('92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e', 'Uyqu uchun taymer usuli ⏱️', 'Uxlash vaqti kelganda birdan chanqab qoladimi, hojatxonaga borgisi keladimi yoki devor bilan xayrlashadimi? Taymer o‘rnating. “Qo‘ng‘iroq chalinganda hamma uxlaydi” qoidasini joriy qilib, bu tuganmas xayrlashuv va mohirona manipulyatsiyadan bahs-munozarasiz qutuling.'),
  ('9d39f5c1-6418-4ab4-8bba-64b21fccd4ac', 'Haqiqiy rassom devorni tanlaydi 🖍️', 'Bir necha soniyalik sukunat xavfli yakun topdi. Xonaga kirib, uning devorga flomaster bilan san’at asari chizganini ko‘rdingiz. Chuqur nafas oling. Mayda motorikasi rivojlanyapti, devorni esa baribir tozalasa bo‘ladi. Kelajakda birga kulish uchun bu durdona asarni albatta suratga oling.'),
  ('dda9eb22-cebb-4f1b-962b-3223d17b83eb', 'Anacan hamjamiyatining kuchi 💬', '“Nega mening bolam bunchalik qaysar?” degan o‘y sizga tinchlik bermayapti. Anacan hamjamiyatiga kiring. Boshqa onalarning uyida ham yuz beradigan shunga o‘xshash bema’ni injiqliklarni o‘qib, yolg‘iz emasligingizni va mutlaqo to‘g‘ri yo‘lda ekaningizni ko‘rasiz.'),
  ('063d0e5f-8a19-45c6-b301-96c01e527e0a', 'O‘g‘irlangan burun o‘yini 👃', 'Burningizni oldim! deb bosh barmog‘ingizni ko‘rsatasiz, u esa bunga chin dildan ishonib, yig‘lay boshlaydi! 3.5 yoshda tasavvur ba’zan haqiqat bilan xayolni ajrata olmaydi. Darhol Ana, joyiga qo‘ydim deb, burnidan o‘ping va bu kichik qo‘rquvni tabassumga aylantiring.'),
  ('31689193-e8a3-408a-bec9-cc30d1fc08c4', 'Juftingiz bilan so‘zsiz nigohlar 🥂', 'Bola nihoyat uxlab qoldi. Siz va juftingiz divanda yonma-yon o‘tiribsiz, hatto gaplashishga ham holingiz yo‘q. Shunchaki sukutda bir-biringizga qarab jilmayasiz. Bu so‘zsiz nigohlar biz bu tartibsizlikni ajoyib tarzda yengib o‘tyapmiz deyishning eng chiroyli usulidir.'),
  ('7834ecb1-6218-4b7b-a3ed-c138894407b9', 'Sun’iy intellekt va to‘satdan boshlangan qaysarlik 🤖', 'Kecha hali xotirjam bo‘lgan bola bugun hamma narsaga tajovuzkor munosabat bildiryaptimi? Internetdan qo‘rqinchli sabablarni qidirmang. Anacan AI’dan ushbu rivojlanish sakrashining (mental leap) psixologik sabablari haqida so‘rang va pediatr tasdiqlagan javob yordamida xavotiringizni yo‘qoting.'),
  ('9dcc2901-fb6b-4d84-a478-46c76064f671', 'Buni men topdim — egalik qilishga moyil kichkintoy 🔑', 'Uydagi pult yoki dadasining kalitini yerdan olib, Buni men topdim, demak meniki! deb turib oladi. Uning uchun topish egalik qilishni anglatadi. Qo‘lidan zo‘rlik bilan tortib olmang. Men uchun topib berganingga rahmat deb, diqqatini boshqa o‘yinchoqqa qarating va buyumni qaytarib oling.'),
  ('c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec', 'Vannaxonadagi mini-spa 🛀', 'Bu oqshom vannani faqat u uchun emas, o‘zingiz uchun ham tayyorlang. Bola uxlagach, iliq suv, biroz ko‘pik va vannaxonada yonib turgan bitta sham. Eshikni qulflang va atigi 15 daqiqaga onalik rolidan chiqib, yana o‘zingiz bo‘ling.'),
  ('cfb02ba9-2584-45e0-a1c3-ce6672adabe6', 'Sartaroshlik urinishi ✂️', 'Xonaga kirganingizda, uning qo‘lida qaychi bilan qo‘g‘irchog‘ining sochini kesishga urinayotganini ko‘rasiz. Bunday holat har bir onaning dahshatli tushidir. Jahlingiz chiqmasdan qaychini oling va bu sartaroshlik urinishini Chaqaloq fotosessiyasida kulgili xotira sifatida saqlab qo‘ying.'),
  ('1c56259d-5943-4110-9eaf-5c1870b222b1', 'Ertalabdan bekinmachoq 🙈', 'Siz ishga yoki bog‘chaga kechikyapsiz, u esa parda ortiga yashirinib: «Meni toping!» deydi. Asablaringiz taranglashsa ham, baqirish jarayonni yanada cho‘zadi. «Qani, mening shirin bolajonim qayerda ekan?» deb o‘yinga 2 daqiqaga qo‘shiling, uni toping va yashiringan joyidan olib chiqing.'),
  ('7b148d61-8829-4863-ab9e-6d4a0bb51f81', 'Ovqatni rangiga qarab ajratish 🍅', 'U likopchadagi taomlarni rangi va shakliga qarab ajratadi, yashillarini esa chetga suradi. Ovqatlanish rejasiga kiring. Sabzavotlarni qanday qilib sezilmaydigan pyurega aylantirish va mazali souslar orasiga yashirishni bilib oling — shu tariqa bu o‘yinda sezdirmay g‘olib chiqing.'),
  ('b42730c5-7949-4ebf-93b6-63b027cfa615', 'Dadaning to‘qima hikoyalari 📖', 'Bu oqshom xonada siz emas, dada gapirsin. Ertak kitobini dadasiga bering va u hikoyani ataylab chalkashtirib, kulgili va bema’ni tarzda aytib bersin. Farzandingiz uni tuzatishdan qanchalik zavqlanishini va dadasining gaplariga qanday qah-qah otib kulishini chetdan kuzating.'),
  ('4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5', 'Jahlingizni kayfiyat kundaligiga to‘kish 📝', 'Uyda qanchalik charchayotganingizni hech kim sezmayaptimi? Kayfiyat kundaligi — eng sokin sirdoshingiz. Bugun sizni jahldan chiqargan barcha mayda-chuydalarni unga yozing va ekranga qarab miyangiz qanday yengillashayotganini, tashvishlaringiz esa qanday tarqalayotganini his qiling.'),
  ('5c983784-bca8-4998-adca-b16664e5be99', 'Uyda bosh kiyimda yurish 🧢', 'U qishki bosh kiyimini uyda ham kiyib yurishni xohlaydi. Turib oladi, yechmaydi. Jamiyat qoidalarini bir chetga suring. Uning ijodkorligi va qaror qabul qilish erkinligini cheklamaslik uchun kunni shu noodatiy, kulgili ko‘rinishda o‘tkazishiga ruxsat bering. Xona harorati me’yorda bo‘lsa, mayli, kiyib yursin.'),
  ('9d6dd60c-7863-4418-b9e4-e9cffd903339', '«Siz meni eshitmayapsiz!» degan e’tiroz 😠', 'Siz telefonga qarab yoki ovqatni aralashtirib turganingizda, u kelib yuzingizni o‘ziga qaratadi: «Menga qarang!» U haq. U shunchaki yonida bo‘lishingizni emas, butun diqqatingizni istaydi. Ishingizni to‘xtatib, atigi 3 daqiqa davomida uning ko‘ziga qarang va diqqat bilan tinglang.'),
  ('45e62ed0-8906-4bfa-998b-97725faac7dc', 'Parkda tanishishga urinishlar 🤝', 'U parkda notanish bolaning yoniga borib, «Mening ismim...» deya o‘zini tanishtiradi. Ijtimoiy ko‘nikmalari hayratlanarli tezlikda shakllanmoqda. Rivojlanish kuzatuvchisida uning muloqot qilishga qaratilgan bu jasoratli urinishlarini shaxsiy rivojlanishining faxrli bir lahzasi sifatida saqlab qo‘ying.'),
  ('6538fe5a-5021-49de-8c05-b4294e3a7259', 'O‘jar «Yo‘q» davri 🛑', 'Suv ichasizmi? — Yo‘q! Ammo 5 soniyadan keyin suv so‘rab yig‘laydi. Bu — qarorlarining oqibatini sinab ko‘rish davri. Ular aslida xohlagan narsalariga ham «yo‘q» deyishadi. Suvni stol ustiga qo‘ying, majburlamang — ichki kurashini yakunlab, o‘zi ichadi.'),
  ('c5259254-085d-4cab-81d7-de92adaaa126', 'Aqlli ertaklar bilan oson uyqu 🪄', 'Mumtoz kitoblarni yodlab bo‘lgansiz. Aqlli ertaklarni oching, bosh qahramon sifatida farzandingizni, zabt etiladigan joy sifatida esa uning xonasini tanlab, noodatiy va hech qanday kuch talab qilmaydigan audio uyqu seansini yarating. O‘zingiz ham dam oling.'),
  ('3267eb25-4eba-48a9-b86e-272c45f62299', 'Qorong‘i xonada soyalar teatri 🐰', 'Qorong‘ilikdan qo‘rqishini bahona qilib, yotoqdan qochadi. Xonadagi barcha chiroqlarni o‘chiring, fonarni yoqing va devorda qo‘llaringiz yordamida qush va kuchuk soyalarini yarating. U qo‘rqadigan qorong‘ilik bir necha soniya ichida teatrga aylanadi.'),
  ('4ac972f2-0058-41fe-9a63-593036a6aa46', 'Ovoz o‘lchagich bilan sukunatni saqlash 🤫', 'Uydagi shovqin-surondan quloqlaringiz qomatga keladi. U nihoyat uxlab qolgach, Ovoz o‘lchagich vositasini faollashtiring. Ekrandagi nolga yaqin raqamlarni, raqamli sukunatni kuzatish charchagan onaning miyasi uchun eng yoqimli vizual massajdir.'),
  ('b4510edb-beed-40b8-b0ad-884291f78f89', '«Siz o‘tirmang!» diktaturasi 🪑', 'Siz divanga o‘tirmoqchisiz, u esa yugurib kelib: «U yerda ayiqcham o‘tiradi, siz turing!» deydi. Uyni o‘zi boshqarishga urinmoqda. Uning irodasini keskin sindirmasdan: «Ayiqchang bu yerda, men esa uning yonida o‘tiraman», deb muvozanatni va xonadagi tinchlikni saqlang.'),
  ('a33e5975-6dcb-4e61-93db-f52a429ffcb8', 'Anacan AI: Bolalar nega yolg‘on gapiradi? 🤥', '“Suvni men to‘kmadim, o‘yinchoq to‘kdi”, dedi. U yolg‘on gapiryaptimi yoki tasavvurini ishga solyaptimi? Internetdan qo‘rqinchli javoblarni qidirmang. Anacan AI orqali 3.5 yoshli bolaning bunday xayoliy tasavvurlari rivojlanishning mutlaqo tabiiy bosqichi ekanini bilib, xotirjam bo‘ling.'),
  ('f03a726a-5a9c-4eda-ab04-4d6b21a432cd', 'Juftingiz bilan kulgi xuruji 🥂', 'Bola nihoyat uxlab qoldi. Kun davomida sizni aqldan ozdirgan o‘sha bema’ni voqeani juftingizga aytib berayotib, birdan ikkalangiz ham qahqaha otib yuborasiz. Ha, bu kulgilar ota-onalikning eng yoqimli mukofotidir.'),
  ('fce85c76-de6a-416c-a8d9-e7fd462bd967', 'O‘yinchoqlarni vannaga olib kirish 🛀', 'Cho‘milishni istamaydi, ammo barcha mashinalari va plastik ayiqchalarini vannaga yig‘gachgina suvga tushishga rozi bo‘ladi. To‘sqinlik qilmang. Vannadagi o‘sha o‘yinchoqlar unga suvning tinchlantiruvchi ta’siridan bahramand bo‘lishga yordam beradigan eng yaxshi vositalardir.'),
  ('383239b8-7f85-4507-9f51-cdc8a13d1e8f', 'Makaron sevgisi 🍝', 'Kecha sevib yegan go‘shtini bugun rad etadi, faqat kun bo‘yi makaron yeyishni xohlaydi. Uning irodasi bilan kurashmang. Foydali retseptlarda oqsil va sabzavotlarni makaron sousiga sezdirmay qo‘shishni o‘rganib, vaziyatdan g‘olib chiqing.'),
  ('6fb57a61-aa7b-441f-afc3-ed5b09208ed5', 'Ko‘zgu qarshisidagi raqslar 🪞', 'Ko‘zgu qarshisida turib qo‘shiq aytadi va turli raqs harakatlarini sinab ko‘radi. U o‘z tanasining ritmini va qanday ko‘rinishini o‘rganmoqda! Rivojlanish kuzatuvchisida uning o‘z tanasini anglashini va ritmni his qilishini quvonch bilan qayd eting.'),
  ('86182307-b484-4518-a023-a22ef5f8216d', 'Shivirlab aytilgan uyqu dueti 🌙', 'U yotoqda shu qadar faolki, uxlay olmaydi. Ovozingizni balandlatish o‘rniga, birdan ohangingizni pasaytirib, uning sevimli qo‘shig‘ini shivirlab kuylay boshlang. Bola sizni eshitish uchun diqqatini jamlaganida, miyasi avtomatik ravishda gipnotik holatga tushib, uyqu rejimiga o‘tadi.'),
  ('229bf8d4-9bef-44e1-90de-84a850188af4', 'Sovuq qahva haqiqati ☕', 'Qahvani damlab, 3 soatdan keyin muzdek holda ichish — onalikning yozilmagan qonuni. Ammo bugun boshqacha yo‘l tuting! Uni sevimli multfilmi bilan bir oz yolg‘iz qoldiring va qahvangizni issiqligida iching. Siz robot emassiz, dam olishga haqqingiz bor.'),
  ('78ebbc01-68e9-48f1-b518-6ad7212482ec', 'Shovqin o‘lchagichdagi raqamli sukunat 🤫', 'U nihoyat uxlab qoldi! Uyni qoplagan sukunatga ishona olmayapsiz. Shovqin o‘lchagichni yoqing va ekrandagi 0-10 detsibel ko‘rsatkichiga qarab, miyangiz asta-sekin qanday tiklanayotganini ko‘z oldingizda his qiling.'),
  ('83129caa-97cc-414e-93e5-8bffa69fcbb9', 'Men sizning onangizman! 👩‍👧', 'Rollar almashinuvi o‘yini boshlandi! U sizga «Bu yerga kel, yotog‘ingga kir, yig‘lama», deb buyruq bermoqda. Uning bu yetakchilik tajribasini mamnuniyat bilan qabul qiling va indamay uning bolasi rolini o‘ynang — bu empatiyani rivojlantiradi.'),
  ('257a6a67-1139-417f-a422-373f16be4a85', 'Yashirin vitaminlar operatsiyasi 🥣', 'Kecha sevib yegan taomini bugun og‘ziga ham oldira olmayapsiz. Uning irodasi bilan kurashmang. Foydali retseptlarda oqsilli mahsulotlarni turli, rang-barang va qiziqarli shakllarga keltiradigan gazak retseptlarini sinab ko‘ring va vaziyatni o‘z foydangizga hal qiling.'),
  ('e8a36b6d-250c-4114-bd67-1068cf626c68', 'O‘yinchog‘im kasal 🩺', 'U o‘yinchoq stetoskopini olib, ayiqchasini jiddiy tekshirmoqda va unga yara plastirini yopishtirmoqda. Ramziy o‘yinlar orqali u mehr-shafqatni o‘rganadi va atrofidagi dunyoni anglaydi. Siz ham shifoxonadagi bemor roliga kirib, o‘yinga qo‘shiling.'),
  ('fc4c9174-8969-47bc-b1ba-7be545e849f3', 'Aqlli ertaklar bilan orzular sari 🪄', 'Klassik kitoblarni yodlab bo‘ldingiz. Aqlli ertaklarni yoqing, bosh qahramon sifatida farzandingizni, zabt etiladigan joy sifatida esa uning xonasini tanlang va hech qanday kuch talab qilmaydigan, noodatiy audio uyqu seansini yarating.'),
  ('4cd431fe-3e79-44d3-a7ca-53965a307626', 'Soch tarash — dushman 🪮', 'Taroqni ko‘rishi bilan dod solib, xonadan qochib ketadi. Kurashishni bas qiling. Avval taroqni unga bering, sochingizni yoki qo‘g‘irchog‘ining sochini tarashiga imkon bering. Nazorat o‘zida ekanini his qilgach, navbatni sizga berishga rozi bo‘ladi.'),
  ('7de027d7-5609-44f6-aeb7-25a62639a344', 'Anacan hamjamiyatida ko‘mak 💬', '«Men endi hech qachon avvalgidek erkin bo‘la olmayman», degan o‘y sizni to‘satdan bo‘g‘ayotgandek bo‘ladimi? Bu vaqtinchalik, ammo juda og‘ir va chuqur kechinmani Anacan hamjamiyatidagi onalar bilan bo‘lishing. Ular ham xuddi shu yo‘llardan o‘tganini bilib, taskin va ko‘mak oling.'),
  ('f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0', 'Suv terapiyasi 🌊', 'Ba’zan hech narsa yordam bermaydi, u shunchaki hamma narsaga yig‘layveradi. Uni iliq suv to‘ldirilgan vannaga tushiring va suvga biroz ko‘pik qo‘shing. Suvning o‘sha sirli, taranglikni yo‘qotuvchi sehrli ta’siri butun xonaga va uning asab tizimiga bir zumda xotirjamlik olib keladi.'),
  ('11b4acb5-0c50-4711-bda6-86d12a2c254b', 'Dadaning massaj vaqti 💆‍♂️', 'Bugun ko‘p vaqt oyoqda turdingiz, uning ortidan yugurib, yerdagi o‘yinchoqlarni yig‘averib belingiz og‘riyapti. Bola uxlashi bilan turmush o‘rtog‘ingizdan yelkangizni 10 daqiqa uqalab qo‘yishini so‘rang. Siz oilaning tayanchisiz, tayanch esa albatta dam olishi va kuchini tiklashi kerak.'),
  ('48e0f071-5110-45a7-a007-23be77bbd305', 'Teskari kiyilgan ko‘ylak g‘ururi 👕', 'Ko‘ylagini teskari kiyib olib, buni go‘yo dunyoni zabt etgandek faxr bilan namoyish qilmoqda. Odamlar orasiga kiyimini teskari kiyib chiqayotgan bola — o‘z qarorini himoya qilayotgan boladir. Zarrachalik ham aralashmang, uning bunday o‘ziga ishonchiga havas qiling.'),
  ('b20bcc48-1ecb-4706-9d32-0f8329c7cd46', 'Do‘kondagi sinovlar 🛒', 'Kassaga yaqinlashganingizda, xarid aravachasidan siz tanlamagan 3 xil shokolad chiqdi. U chegaralaringizni sinayapti. Tezkorlik bilan ularni joyiga qaytaring. Biror narsani unutib qo‘ymaslik uchun esa ilovadagi Xaridlar ro‘yxatini doim kuzatib boring.'),
  ('3bc4e55a-369a-4bca-8a42-e2a95a607168', 'Kayfiyat kundaligidagi izhorlar 📝', 'Uyda qanchalik charchayotganingizni hech kim ko‘rmayaptimi? Kayfiyat kundaligi — sizning eng sokin sirdoshingiz. Bugun asabingizga tekkan barcha mayda-chuydalarni unga yozing va ekranga qarab, miyangiz qanday yengillashayotgani, tashvishlaringiz esa qanday tarqalayotganini his qiling.'),
  ('7da1ffab-3792-4ba0-b3b7-ce279478fa15', 'Ob-havo va kutilmagan o‘zgarishlar ⛅', 'Tashqarida havo unchalik aniq emasmi: quyosh charaqlab turibdi-yu, ammo shamol ham esyaptimi? Ob-havo va kiyim tanlash vositasi derazadan bilib bo‘lmaydigan shamol tezligi va mos kiyim uyg‘unligini sizga darhol aytib bersin. Eshik oldida ikkilanib vaqt yo‘qotmay, sayrga chiqing.'),
  ('be5cb204-e61d-452b-9a0e-bb977bd6249c', 'Mantiqsiz ko‘z yoshlar ☀️', '“Quyosh ko‘zimga qarayapti”, deb ho‘ngrab yig‘ladimi? Bunday paytda mantiq izlamang. Bu uning uchun chindan ham chuqur qayg‘u: u dunyoni boshqara olmayotganidan jahli chiqmoqda. Pardani yopib, “Quyoshni yashirdim”, deng va shunchaki uning hislarini tan oling.'),
  ('05028726-3b26-4576-b76c-968926aa3c37', 'Yolg‘iz qolishga ehtiyoj 🚪', 'Shovqin-surondan boshingiz yorilay deyapti, hammaga baqirgingiz kelyapti. Uni xavfsiz joyga qo‘yib, hojatxonaga kiring va eshikni yoping. Shunchaki 5 daqiqa devorga qarab turing, hech narsa qilmang. Bu qisqa tanaffus sizni onalik vazifasiga qaytadan tayyorlaydi.'),
  ('3d57cc08-81bc-4a6c-804c-4488f1dababe', 'Yalangoyoq yurish qoidasi 👣', 'U yalangoyoq yurishdan, gilamga, xonadagi toshlarga yoki sovuq kafelga tegishdan zavqlanadi. Oyoq kaftidagi nervlarning faollashishi uning muvozanati va nevrologik rivojlanishi uchun juda muhim. Sovqotmayotgan bo‘lsa, paypoqsiz yurishiga aslo to‘sqinlik qilmang.'),
  ('903639ea-1976-4233-a451-64887050fd95', 'Dadaning g‘alati ovozlari 🤡', 'Sizning urinishlaringiz endi yordam bermay qolganda, dadasi chiqaradigan g‘alati hayvon tovushlari va kulgili yuz ifodalari vaziyatni darhol qutqaradi. Kechki injiqlik paytlarida vazifani darrov unga topshiring, o‘zingiz esa chetdan dam olib, tomosha qiling.'),
  ('4cb1e963-5e79-4f65-b536-3c251c29e851', 'Bugun men pishiraman 🧑‍🍳', 'Siz xamir yoyayotganingizda, u albatta yoningizga stul qo‘yib, jarayonga aralashadimi? Aslida u yordam berishni emas, jarayonning qoq markazida bo‘lishni xohlaydi. Unga kichkina zuvala bering. Oshxona iflos bo‘ladi, ammo uning o‘ziga bo‘lgan ishonchi va ijodkorligi ulkan darajada oshadi.'),
  ('7f5013df-f5cb-4869-9600-c6ec01184189', 'Yangi so‘zlarni qayd etish 📈', 'U buyumlarga o‘zi butunlay to‘qib chiqargan, hech bir tilda mavjud bo‘lmagan yangi nomlar qo‘yadi. Qolaversa, sizdan ham aynan shu so‘zni ishlatishingizni qat’iy talab qiladi! Rivojlanish kuzatuvchisini oching va kelajakda o‘qib kulish uchun uning bu kulgili so‘zlarini albatta arxivga saqlang.'),
  ('df048442-7c05-4ccf-850d-802c3f348e55', 'Qorong‘ilik bilan murosa qilish 🌙', 'Tezroq uxlab qolishi uchun uyqudan 1 soat oldin xonadagi barcha ortiqcha chiroqlarni o‘chiring va planshet ekranlarini chetga qo‘ying. Melatonin faqat qorong‘i va texnologiyalarsiz muhitda tez ajralib chiqib, uyquga ketishni osonlashtiradi.'),
  ('18eabc56-86a4-4978-a5a6-151a3c410b3b', 'Chiroqlarni o‘chiring, sukunatni tinglang 🤫', 'U nihoyat uxlab qoldi. Endi uydagi eng kichik tovush ham sizni bezovta qiladi. Chiroqlarni xiralashtiring, televizorni o‘chiring va qorong‘ilik bag‘ridagi o‘sha noyob sukunatdan huzurlaning. Kun bo‘yi to‘plangan charchoq ham shu tariqa tarqaladi.'),
  ('90892878-829c-442e-a1ef-747f03a0affd', 'Sababsiz arazlashlar 😤', 'Siz shunchaki «Kel, ovqat tayyor», dedingiz, u esa qo‘llarini ko‘ksida chalishtirib, devorga qaragancha sizdan arazladi. Bu yoshda hissiyotlar shu qadar chalkash bo‘ladiki, ba’zan hech bir sababsiz ham arazlashadi. Hech narsani tushuntirmang, 2 daqiqadan keyin o‘zi ovqatga yugurib keladi.'),
  ('e85911c9-eb5a-4470-b9d6-9a1a5872b746', 'Anacan AI: Bolalik qo‘rquvlari 🤖', 'U birdan doim o‘ynab yurgan qizil mashinasidan qo‘rqa boshladimi? Sababsiz tuyulgan fobiyalar sizni xavotirga solsa, internetdagi ruhiy jarohatlar haqidagi forumlarni yoping. Anacan AI’dan 3.5 yoshli bola tasavvurining g‘aroyib jihatlari haqida ilmiy va ko‘nglingizni tinchlantiradigan javob oling.'),
  ('037f6c5f-0014-4a61-89cc-f6268f8f792a', 'Pichirlash gipnozi 🌙', 'Karavotda yotib, oyoqlarini havoga ko‘taradi va uxlashni aslo istamaydi. Baqirish o‘rniga birdan ovozingizni pasaytiring va u bilan faqat pichirlab gaplashing. Bola sizni eshitish uchun diqqatini jamlaganida, miyasi avtomatik ravishda go‘yo gipnoz holatiga tushib, uyqu rejimiga o‘tadi.'),
  ('b0b14a33-4ccb-42a3-a0a7-0359199a066c', 'Anacan hamjamiyatida yengillik 💬', 'Juda charchagansiz va hech kimga hech narsani tushuntirishni istamayapsiz. Anacan hamjamiyatiga kirib, shunchaki o‘quvchi bo‘ling. Boshqa onalar ham xuddi shunday charchayotganini ko‘rish sizda «Men yolg‘iz emasman» degan tuyg‘uni uyg‘otadi va eng yaxshi terapiyaga aylanadi.'),
  ('b51e5eaf-9b52-4501-9631-0ad7c9e7aebd', 'Savollar yomg‘iri — Nega? 🌪️', '«Baliqlar nega yurmaydi?», «Quyosh qayerga ketdi?» Tong sahardan uning miyasi soatiga 100 ta savol tezligida olam sirlarini anglashga urinadi. Charchasangiz ham, unga qisqa javoblar bering. U koinot sirlarini sizning ovozingiz orqali o‘rganadi.'),
  ('56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f', 'Bu meniki! — Hamma narsani o‘ziniki qilish 🧸', 'Uydagi istalgan buyumni quchoqlab, «Bu meniki!» deb baqiradi va uni hech kimga bermaydi. U egalik chegaralarini anglab bormoqda. Uni xudbinlikda ayblamang, diqqatini boshqa o‘yinga yo‘naltirib, buyumni qaytarib oling.'),
  ('77d341ac-ecee-44bc-a34c-b8046e7ebe38', 'Onaning o‘z ulushi 🥗', 'Uni to‘ydirish uchun 3 xil taom o‘ylab topdingiz-u, o‘zingiz yana och qoldingizmi? Ovqatlanish rejasi bo‘limidan nafaqat bolalar, balki onalar uchun ham mos, 10 daqiqada tayyorlanadigan, temir va kalsiyga boy, quvvat beruvchi tushlikni tanlang va o‘zingizni qadrlang.'),
  ('97e76dee-bae4-4d8b-bffd-646b99d0b6bc', 'Juftlik shampani 🥂', 'Og‘ir kundan so‘ng stakanlarga oddiy issiq choy quying. Turmush o‘rtog‘ingiz bilan divanda yuzma-yuz o‘tirib, «Bugun ham bu tartibsizlikdan omon chiqdik», deya stakanlarni urishtiring. Siz bu uyning ham sarkardalari, ham jamoasisiz.'),
  ('0dc18b7e-e572-47af-8c7b-0d7785728f82', 'O‘zi quyishga bo‘lgan qaysarlik 💧', 'U katta ko‘zadan kichkina stakanga suvni albatta o‘zi quyadi. Suv stolga, u yerdan esa polga to‘kiladi. Ammo uning latta olib, to‘kilgan joyni tozalashga urinayotgan mitti qo‘llariga qarang. U xato qilish orqali mas’uliyatni o‘rganmoqda, jahlingiz chiqmasin.'),
  ('4f75092c-a7ba-4a8b-9f64-4af1718f2cab', 'Vannadagi okean 🌊', 'Vannada cho‘milish endi shunchaki yuvinish emas, balki to‘lqin yasash o‘yiniga aylangan. Suv atrofga sachrayversin. Suvning o‘sha sehrli ta’siri unda kun bo‘yi to‘plangan qaysarlik va salbiy energiyani yuvib, oqizib yuboradi.'),
  ('d4d0d422-f5f6-490e-8c72-e88ef36a1315', 'Xaridlar ro‘yxati — unutilganlar 🛒', 'Do‘konga borganingizda eng kerakli narsani unutib qoldirasizmi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni unga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda hammasini ro‘yxat bo‘yicha olib kelsin, siz esa miyangizni ortiqcha ma’lumot bilan band qilmang.'),
  ('418c1711-4059-4957-81d3-edd1c0d2c899', 'Parkdagi me’morchilik 🏰', 'U parkdagi qum maydonchasida xuddi xazina qidirayotgandek chuqur qaziydi. Usti-boshi loy bo‘ladi. Ammo uning bu kashfiyot onlariga xalaqit bermang. Ob-havoga mos va kir bo‘lishi mumkinligini hisobga olib oldindan tanlangan kiyimlar bu manzarani stresssiz kuzatishingizga imkon beradi.'),
  ('4690cd10-6ebf-45be-8b49-fc76a078e4f1', 'Jonsiz buyumlar bilan g‘aroyib do‘stlik 🗣️', 'U parkdagi toshga yoki uydagi stulga jiddiy ohangda nimalarnidir gapiradi, hatto ularni koyiydi. Ramziy o‘yinlar orqali u atrofidagi dunyoni anglaydi. Rivojlanish kuzatuvchisida uning bunday o‘ziga xos ssenariylarini albatta qayd eting.'),
  ('a43560ca-6c77-420e-beaa-23a6e7c51732', 'Aqlli ertakdagi Men 🪄', 'Bugun kechqurun Aqlli ertaklarda bosh qahramonga farzandingizning ismini bering. Ertak qahramoni ham xonasini yig‘ishtirib, keyin xotirjam uxlaganini aytib bering. Shu tariqa qoidalarni unga baqirib emas, bilvosita o‘rgating.'),
  ('9e327ded-a5c0-48ad-901c-52606eb80762', 'Kayfiyat kundaligi — yengillik lahzasi 📝', 'Telefonni qo‘lingizga oling. Ijtimoiy tarmoqlarda boshqalarning hayotini tomosha qilib o‘tirish o‘rniga, Kayfiyat kundaligini oching va uning bugun qilgan eng kulgili ishini kelajak uchun yozib qo‘ying. Bu raqamli terapiya sizni ham tinchlantiradi.'),
  ('a7cb2140-287a-4406-a2b5-5d7c82c31a2d', 'Dadaning belida ot minish 🐴', 'U hali ham bor kuchini sarflamagan va uxlashga qarshilik qilyapti. Dadasini yordamga chaqiring. Dadasi bolani beliga mindirib, ot bo‘lib chopganida, xona qahqahaga to‘ladi, to‘planib qolgan barcha jismoniy zo‘riqish va tuganmas energiya esa bir necha soniya ichida ter bilan birga yo‘qoladi.'),
  ('e21478c9-e278-43bf-8cfc-ce997f28ab6d', '“Menga qarang!” davri 👀', 'U divandan sakraydi va bir xil harakatni roppa-rosa 50 marta takrorlab: “Ona, menga qarang!” deydi. Ko‘zingizni telefondan uzing. U harakatning o‘zi uchun emas, ko‘zlaringizdagi ma’qullash uchqunini ko‘rish uchun sakrayapti. Unga chalg‘imasdan 5 daqiqa vaqt ajrating, mehringizga to‘yib olsin.'),
  ('4a32ef42-8519-4a15-ae15-b2e86c604165', 'Shovqin o‘lchagichda 0 detsibel 🤫', 'U nihoyat uxlab qoldi! Uyni qoplagan sukunatga ishongingiz kelmaydi. Shovqin o‘lchagichni yoqing va ekrandagi 0-10 detsibel ko‘rsatkichiga qarab, miyangiz asta-sekin orom olayotganini, bu ko‘z bilan ko‘rinadigan sukunat sizni qanday tinchlantirayotganini his qiling.'),
  ('5db98ad2-4a41-4a94-8924-de68639a6a28', 'Erkin raqs 🎶', 'U eshitgan ilk ritmdayoq, xoh reklama ovozi, xoh mashina signali bo‘lsin, raqsga tusha boshlaydi. Hayotga u kabi quvonch bilan qarang! Xonada unga qo‘shilib, bir necha daqiqa sho‘x raqsga tushing — barcha stressingiz tarqab ketadi.'),
  ('8095b6da-2b93-462b-bce2-881fa1732924', 'Kuzatuvchi — rivojlanishdan faxrlanish 📈', 'U endi chaqaloq emas! U o‘z qarorlari, g‘aroyib savollari va ulkan qalbiga ega bo‘lgan to‘laqonli inson. Siz juda yaxshi uddalayapsiz!'),
  ('064149bc-eacb-463c-b371-3ee4af7db167', 'Gilamdagi chegara chiziqlari 🗺️', 'U xonadan oshxonaga faqat gilamdagi qizil chiziqlarni bosib o''tish mumkin degan qoida chiqardi. Yirik motorika va diqqat birgalikda ishlamoqda. Bu mantiqsiz qoidani buzmang, siz ham u bilan birga chiziqlar ustida raqsga tushib, ertalabki badantarbiyangizni bajaring.'),
  ('2980ee34-de75-4617-8093-160c3c2da3a0', 'Yostiq ostidagi teatr 🎪', 'U yotog‘iga kiradi, ammo boshini yostiq ostiga yashirib, o‘zi bilan o‘zi gaplashadi. Xonani butunlay qorong‘i qiling. O‘sha qorong‘i va xavfsiz boshpanasida o‘z ssenariylarini tuzib, asta-sekin uyqu olamiga o‘tishiga imkon bering, aralashmang.'),
  ('af38ac43-154c-4c60-9f01-51c84d74b264', 'Cho‘ntakdagi makaron sinovi 🍝', 'Kir yuvish mashinasiga solgan shimingiz cho‘ntagidan qurib qolgan makaron chiqdimi? Siz uchun bu chiqindi, u uchun esa balki yo‘lda qornim ochib qolar degan zaxiradir. Uni koyimang, rejalashtirish qobiliyatining ilk belgilarini Rivojlanish kuzatuvchisiga kulgili xotira sifatida yozib qo‘ying.'),
  ('881d0866-6df6-4dec-801b-67b99df853c5', 'Suvni qurit! talabi 💧', 'U stakandagi suvni ichish o‘rniga Bu juda ho‘l, uni qurit deb baqiradi. 3.5 yoshning absurd olamiga xush kelibsiz. Tushuntirishga urinish quvvatingizni tugatadi. Yaxshi, boshqa quruq suv olib kelaman deb, xuddi shu suvni boshqa rangdagi stakanda bering.'),
  ('d2f34bfd-32c7-43f7-89fd-d8226236a390', 'Dadaning yashirin porasi 🤫', 'U tishlarini yuvishni istamaydi. Dadasi sekingina yoniga kelib Tishingni yuvsang, cho‘ntagimdagi sehrli toshni ko‘rsataman deydi. Onalik qoidalarini ba’zan dadalarning ayyorona, ammo darhol ish beradigan noodatiy o‘yinlari uchun buzishga to‘g‘ri keladi.'),
  ('f968f309-08cf-46ae-901b-44ed8420ced0', 'Balkondan jamiyatni kuzatish 👀', 'U balkonga chiqib, ko‘chadan o‘tayotgan har bir kishiga baqirib qo‘l silkitadi va javob olmasa, xafa bo‘ladi. Ijtimoiy muloqotga ehtiyoj eng yuqori nuqtada. Uni ichkariga tortmang, Ular juda uzoqda, balki eshitmagandir deb, hamdardlik tuyg‘usiga zarar yetkazmasdan qo‘llab-quvvatlang.'),
  ('01eb4758-ff80-4ee6-b2d8-884207fd7862', 'Jim kitob o‘qish seansi 📖', 'Bu oqshom hech kim gapirmaydi. Aqlli ertaklarni yoqing, matnni ovoz chiqarib o‘qish o‘rniga, qurilmadan taralayotgan mayin tabiat tovushlari jo‘rligida rasmlarni jimgina tomosha qiling. Ko‘rish xotirasi uni charchatib, o‘z-o‘zidan uyquga olib ketadi.'),
  ('fae36977-58eb-48b1-8551-438307ad854b', 'Tuxumning noto‘g‘ri tomoni 🍳', 'Qaynatilgan tuxumni o‘rtasidan kesganingiz uchun katta janjal boshlandi. Men uni butunligicha xohlagandim! Taomning ko‘rinishi ular uchun eng nozik masalalardan biridir. Sog‘lom retseptlarni ko‘rib, mahsulotlarni to‘g‘ri shaklda va qiziqarli qilib kesib qanday taqdim etishni o‘rganing.'),
  ('fed4ec8b-badd-4ae2-b8cd-74446e67eee7', 'Tabiatdagi izquvar 🔍', 'U parkda shunchaki chumolilar uyasini kuzatish uchun 20 daqiqa qimirlamay o‘tirdi. Uni shoshirmang. Ob-havo va kiyim yordamchisi orqali ob-havoni oldindan tekshirib, unga mos ravishda issiqroq kiyintirgan bo‘lsangiz, bu mitti biologga dunyoni kashf etish imkonini bering.'),
  ('0601b05e-a2e4-4730-b08b-f661e0e89b2a', 'Vannadagi mini laboratoriya 🛀', 'U suvga turli rangdagi sovunlarni qo‘shib, sehrli eliksir tayyorlamoqda. Hammom iflos bo‘ladi, albatta. Ammo u erituvchilar va moddalarning aralashishini o‘rganmoqda. Bu ilmiy izlanish oqshomgi charchoqni ketkazib, uni osoyishta uyquga tayyorlaydigan eng yaxshi vositadir.'),
  ('15d2ba80-4fad-4f86-8e70-6261ae666ebc', 'Shkaf ichidagi ijtimoiy yakkalanish 🚪', 'Uyning o‘rtasida shovqin birdan tindi. Uni kiyim shkafi ichida, qorong‘ida yolg‘iz o‘ynayotganida topdingiz. Bu depressiya emas, shunchaki hissiy jihatdan qayta tiklanish onidir. Eshikni ohista yopib, unga shaxsiy makondan bahramand bo‘lish imkonini bering.'),
  ('869bedae-ce51-4c50-8799-4b322d523e09', 'Tegishga qarshi isyon 🔋', 'Kun bo‘yi tanangizga tirmashib, sochingizni tortgan boladan jismonan holdan toyibsiz. Uni darhol xavfsiz joyga qo‘yib, boshqa xonaga o‘ting. Kayfiyat kundaligiga Tanam menga tegishli emas deb yozib, teginishlardan bezish sindromining ruhiy yukini yengillashtiring.'),
  ('18c831a2-2a8d-41b4-aec0-3fc3423e4549', 'Tovush o‘lchagich bilan ichki xotirjamlik 🤫', 'U nihoyat uxlab qoldi. Quloqlaringizdagi shang‘illash esa hali ham tinmayapti. Ilovadagi Tovush o‘lchagichni oching. Ekrandagi 0 desibel yozuviga qarab, xonadagi sukunat miyangizga qanday singib, sizni tiklayotganini his qiling.'),
  ('64255b01-33d4-405e-b645-f0ff22d8defe', 'Telefon o‘g‘risi 📱', 'O‘zingizga choy quyayotganingizda telefoningiz yo‘qolganini, u esa divan ortida sizga o‘xshab Alo deyayotganini ko‘rdingiz. U raqamli odatlaringizni o‘rganmoqda. Qurilmani olayotganda Telefonim ham sen bilan gaplashmoqchi ekan deb, o‘yin orqali qaytarib oling.'),
  ('d0533c80-d46b-4d9f-9654-8ce50e72523b', 'O‘zing kiyin! siyosati 👖', 'U oyoqlarini osmonga ko‘tarib, Men chaqaloqman, sen meni kiyintir deydi. Bolalar mustaqillik va qaramlik o‘rtasida ikkilanib turishadi. Uni majburlab kiyintirmang. Kiyimni yoniga qo‘yib, Bu superqahramon shim o‘z egasini kutyapti deb, biroz ayyorlik ishlating.'),
  ('5d82c548-2228-430b-916c-6c21c900e5fe', 'Pichirlashning sirli kuchi 🌙', 'U yotishdan qochish uchun turli bahonalar o‘ylab topadi. Ovozingizni juda pasaytirib, faqat pichirlab gapiring. Sizni tushunish uchun u butun diqqatini jamlashga majbur bo‘ladi, bu esa uning miyasini gipnoz qilgandek tinchlantirib, uxlatadi.'),
  ('e401c834-583c-49ec-8d04-289b6b62d99b', 'Anacan hamjamiyatida taskin 💬', 'Men hech qachon mukammal bo‘la olmayman degan tuyg‘u sizni bo‘g‘yaptimi? Instagramdagi o‘sha ideal onalar haqidagi xayolni unuting. Anacan Hamjamiyatiga kiring va uyi ag‘dar-to‘ntar bo‘lgan, farzandi devorga chizib tashlagan onalarning samimiy e’tiroflarini o‘qib, Men mutlaqo normalman deng.'),
  ('fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6', 'Dinozavr mantig‘i 🦖', 'Ertalab u hech bir savolga javob bermay, faqat bo‘kiradi. Bugun u T-Rex. T-Rexlar bo‘tqa yeydimi? deb, u o‘ylab topgan shu obrazga moslashing va ertalabki odatlarni bir tomchi ko‘z yoshisiz yakunlang.'),
  ('5a7d778f-6e03-4003-a60c-0214c0dc5a0b', 'Dadaning to‘qima qahramonlari 🦸‍♂️', 'Bu oqshom kitobdagi ertaklarni unuting. Dada bosh qahramoni bolaning o‘zi bo‘lgan to‘qima va fantastik hikoya aytib bersin. «Shunda u qilichini sug‘urib... tishlarini yuvdi!» kabi jumlalar bolani qah-qahaga solib, uyquga tayyorlaydi.'),
  ('732719f9-46cf-4097-a068-781df2eeaf00', 'O‘z rasmini tanqid qilish 🖍️', 'Chizgan qora-qura rasmini ko‘rsatib, «Bu siz edingiz, lekin yaxshi chiqmadi», deydi-da, uni yirtib tashlaydi. Unda o‘zini tanqid qilish qobiliyati shakllanmoqda! Uning his-tuyg‘ularini kamsitmang, «Keyingi rasmda qizil rangni ham sinab ko‘rarsan?» deb, rivojlanishini qo‘llab-quvvatlang.'),
  ('aa506c93-122a-43f1-8742-2605113c516c', 'Do‘konda «Buni men topdim» 🛒', 'Kassaga yaqinlashganingizda aravachadan siz solmagan bir o‘ram pechenye chiqadi. U sezdirmay izlanish olib borgan. Xaridlar ro‘yxatini ochib, «Qara, bu ro‘yxatimizda yo‘q, keyingi safar yozib qo‘yamiz», deb qoidani raqamli ro‘yxat bilan asoslang.'),
  ('0b6916b1-4773-417f-aed4-71c7ff7f85e9', 'Ikkingiz uchun choy zavqi 🥂', 'Og‘ir kundan so‘ng stakanlarga oddiy issiq choy quying. Turmush o‘rtog‘ingiz bilan divanda yuzma-yuz o‘tirib, «Bugungi tartibsizlikdan ham eson-omon o‘tdik, biz ajoyib jamoamiz», deya stakanlarni urishtiring. Siz oilaning mustahkam tayanchisiz.'),
  ('8bce8353-bf73-417b-8a15-56b41142ba18', 'Yashirin sabzavotlar operatsiyasi 🥦', 'Sho‘rva ichidagi bittagina guruch donasi yoki sabzini topib, «Men buni yemayman», deydi. Ovqatlanish rejasiga kiring. Oqsil va sabzavotlarni rang-barang keks shakliga keltirishni o‘rganib, bu qaysar oshpazchaning miyasini chalg‘iting.'),
  ('ef39807d-1235-46a3-9ca8-a0f70bb2fa23', 'Mebelga tirmashish olimpiadasi 🧗‍♂️', 'Divan cheti bo‘ylab deraza tomon tirmashmoqda. Uy siz uchun xavf-xatarga to‘la joy, uning uchun esa sport zalidir. «Ehtiyot bo‘l, yiqilasan!» deb vahima qilish o‘rniga, «Qo‘lingni u yerga qo‘y», deya uning harakatga bo‘lgan ehtiyojini to‘g‘ri yo‘naltiring.'),
  ('000abcf3-b4c9-4928-8d58-c7a8f138f07f', 'Sun’iy intellekt va xotirjamlik 🤖', 'Farzandingizda to‘satdan paydo bo‘lgan duduqlanish yoki jahl xurujlari sizni internetdan og‘ir kasalliklarni izlashga majbur qildimi? To‘xtang! Anacan AI’dan bu 3 yoshdagi rivojlanish sakrashi bilan bog‘liqmi, deb so‘rang va pediatrlar tasdiqlagan, ko‘nglingizni tinchlantiruvchi javob oling.'),
  ('ac974535-4db4-4ecb-aa90-d75a7dabe40a', 'Xonadagi ovoz effektlari 🪄', 'Aqlli ertaklarni yoqing. Hikoyani o‘qiyotganda eshik g‘ichirlashi, shamol ovozi va shivirlashga taqlid qilib, xonada ovozli teatr yarating. Bu noodatiy tovushlar uning diqqatini bir zumda ertak olamiga, u yerdan esa chuqur uyquga olib kiradi.'),
  ('e9945ad4-3802-48f8-b0bf-d94527c3999b', 'Soyadan qochish 👻', 'Ko‘chada ketayotib, u to‘satdan o‘z soyasidan qo‘rqib, ortingizga yashirindi. Bundan mantiq izlamang, 3.5 yoshdagi tasavvur aynan shunday ishlaydi. «Kel, soyaning ustiga sakraymiz», deb, uni qo‘rqitgan narsani darhol harakatli o‘yinga aylantiring.'),
  ('06d21315-e90d-4d7c-a84d-b0f3acd86dc9', 'Dadaning yelka massaji 💆‍♂️', 'Bugun ko‘p vaqt oyoqda turdingiz, uning ortidan yugurib, yerdagi o‘yinchoqlarni yig‘averib belingiz og‘rib ketdi. Bola uxlagach, juftingizdan yelkangizni 10 daqiqa massaj qilib berishini so‘rang. Siz uyning motorisiz, motor esa albatta dam olishi va kuchini tiklashi kerak.'),
  ('3d278e8d-5fc9-46fa-ad40-bcef90b99e90', '«Sen yomon onasan!» dedimi? 💔', 'Siz u xohlagan mashinani olib bermaganingiz uchun u shu gapni aytdi. Yuragingiz og‘ridi. Ammo bilingki, u hali his-tuyg‘ularini to‘g‘ri ifodalay olmaydi, aslida «Ko‘nglim qoldi», demoqchi. Uni shunchaki bag‘ringizga bosing va hislarini qabul qiling.'),
  ('d54e4e25-89e6-430d-b9c4-307312ee2246', 'Moda tushunchasi 👗', 'U qishki paypoq ustidan yozgi sandal kiyib, parkka bormoqchi. Qat’iy turib oldi, yechmayapti. Jamiyat me’yorlarini unuting. Uning ijodkorligini so‘ndirmaslik uchun kunni shu noodatiy, kulgili ko‘rinishda o‘tkazishiga ruxsat bering — u erkin bo‘lishni o‘rganmoqda.'),
  ('28383f04-88e3-44f0-b462-99283a8b08f3', 'Tananing hayqirig‘i 🩸', 'Sababsiz jahldorlik va charchoqqa taslim bo‘lmang. Hayz kuzatuvchisiga qarang — tanangiz sizga signal bermoqda. O‘zingizni ayblash o‘rniga, Sog‘lom retseptlar bo‘limidagi magniyga boy yegulik bilan hordiq chiqaring.'),
  ('4c7f9f66-bdd5-4db6-8e78-8af325982d85', 'Ertalabdan falsafa 🤔', 'Nega qushlar yiqilmaydi? Daraxt nega yashil bo‘lib qoldi? Erta tongdanoq ilmiy anjuman ochiq deb e’lon qilindi. Aniq tushuntirishlar berishdan charchagan bo‘lsangiz, Nima deb o‘ylaysan, nega? deb savolni o‘ziga qaytaring va uning ajoyib, to‘qima javoblarini tinglang.'),
  ('ab1d1514-de05-4637-8009-2407cc320f46', 'Uyqu uchun taymer kelishuvi ⏱️', 'Uxlash vaqti kelishi bilan birdan chanqab qoladi, hojatxonaga borgisi keladi yoki devor bilan xayrlasha boshlaydi. Taymer o‘rnating. Qo‘ng‘iroq chalinganda hamma chiroqlarni o‘chiradi degan qoidani joriy qilib, bu cheksiz xayrlashuvlar va mohirona nayranglardan sabr bilan qutuling.'),
  ('310065f1-7769-41dc-b05f-15aba7ca4982', 'Do‘kondagi Xohlayman inqirozi 🛒', 'Kassa oldida shirinlik so‘rab baqiryaptimi? Atrofdagilarning qoralovchi nigohlariga aslo e’tibor bermang. Xotirjam ko‘ziga qarab, qoidani tushuntiring va fikringizdan qaytmang. Ro‘yxatingizda bo‘lmasa, sotib olinmaydi.'),
  ('d64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e', 'Sen kimsan? o‘yini 🎭', 'U sizga juda jiddiy qiyofada qarab, Sen kimsan? Mening onam qani? deydi. U siz bilan aktyorlik o‘yinini o‘ynayapti! Men qo‘shni xolaman, onang hozir keladi deb, ovozingizni o‘zgartirgan holda bu ajoyib teatrni davom ettiring.'),
  ('f9b49a33-7a6d-4463-b26d-b51d28283257', 'Kutilmagan Seni sevaman 💖', 'Xonaning o‘rtasida o‘ynab turganida birdan sizga qaraydi, yugurib kelib bo‘yningizdan quchadi. Barcha uyqusiz tunlar va charchoqlarga arziydi! Bu lahza olib kelgan chuqur, betakror huzurdan bahramand bo‘ling — barcha tartibsizliklarni bir zumda unutasiz.'),
  ('9fab66ef-18f3-4cdb-8e01-0a4f9485cffe', 'Ko‘zgudagi raqib 🪞', 'Ko‘zgu qarshisida turib, o‘ziga qoshlarini chimiradi, jahldor va g‘alati yuz ifodalarini qiladi. U hissiyotlar yuzida qanday aks etishini sinab ko‘rmoqda. Chetdan ovoz chiqarmay, bu mitti teatr aktyorining mashqini zavq bilan tomosha qiling.'),
  ('b8be3052-4ca5-4460-8506-d2c5926555b2', 'Ona uchun yolg‘izlik soati 🚪', 'Shovqin-surondan boshingiz yorilgudek bo‘lib, hamma narsaga baqirgingiz kelyapti. Uni xavfsiz joyga qo‘yib, hojatxonaga kiring va eshikni yoping. Kayfiyat kundaligini oching. Unga ichingizdagi barcha charchoq va holdan toyishni bemalol yozing. Bu qisqa terapiya kuchingizni qayta tiklaydi.'),
  ('cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6', 'Qorong‘ilik bilan do‘stlashish 🐰', 'Qorong‘ilikdan qo‘rqishini bahona qilib, yotoqdan qochadi. Xonadagi barcha chiroqlarni o‘chiring, fonarni yoqing va devorda qo‘llaringiz bilan qush hamda kuchuk soyalarini yarating. U qo‘rqadigan qorong‘ilik bir necha soniyada teatrga aylanadi.'),
  ('217250d8-e2a0-42ca-ac61-232ced171632', 'Ob-havoni tekshirish taktikasi ⛅', 'Tashqarida quyosh charaqlab turibdi, ammo shamol ham esmoqda. Derazadan qarab aldanmang. Ob-havo va kiyim vositasi sizga his qilinadigan haroratni hamda kiyimlarni qanday to‘g‘ri qatlamlab kiyishni bir zumda aytib bersin. Shunda eshik oldida ikkilanib vaqt yo‘qotmay, sog‘lom sayrga chiqasiz.'),
  ('4a193a83-4450-45ef-8b03-b9487c79d984', 'Bu mening aybim emas! 🤷‍♂️', 'Suvni ataylab yerga to‘kdi, ammo aybni o‘yinchog‘iga yuklab: «U turtib yubordi», dedi. Bu yolg‘on emas, balki bola miyasining himoya mexanizmidir. U bilan tortishmang. «Kel, bu o‘yinchoqqa ham qanday tozalashni o‘rgatamiz», deb uning e’tiborini boshqa tomonga burang.'),
  ('c170e0aa-73e3-4e36-8c66-e8887556d5ab', 'Vannadagi okean bo‘roni 🌊', 'Vannada cho‘milish endi shunchaki tozalanish emas, balki kichik sunami yaratish o‘yinidir. Mayli, suv atrofga sachrasin. Suvning o‘sha sirli, energiyani o‘ziga tortuvchi magnit ta’siri kun bo‘yi unda to‘plangan qaysar va salbiy energiyani yuvib, oqova bilan olib ketadi.'),
  ('3674bd2e-5c13-4e77-8d3d-732d072d4226', 'Axlat emas, san’at 🎨', 'U xonaning o‘rtasida mayda qog‘oz parchalari va kesilgan iplardan ulkan san’at asari yaratdi va uni tashlab yuborishingizga ruxsat bermayapti. Ozodalikka haddan tashqari berilishni bir chetga suring. U yaratgan tartibsizlikni hurmat qiling, tozalash ertagacha kutishi mumkin.'),
  ('a910e33f-005d-4ed1-a228-647503e47993', 'Sukunat halovati 🤫', 'Nihoyat u uxlab qoldi! Uyni qoplagan sukunatga ishona olmayapsiz. Shovqin o‘lchagichni yoqing va ekrandagi 0-10 detsibel ko‘rsatkichiga qarab, miyangiz asta-sekin dam olayotganini, bu ko‘zga ko‘rinadigan sukunat sizni qanday erkalayotganini his qiling.'),
  ('f14df610-5f47-47f4-b085-7728f03a38c4', 'Tugallanmagan gaplarni to‘ldiring 🗣️', 'Biror so‘zni unutib qolsa, qo‘llari bilan ishora qiladi, qoshlarini chimiradi va sizning topishingizni kutadi. Uning so‘z boyligi oshib bormoqda, shunchaki miyasi tilidan tezroq ishlaydi. Gapini sabr bilan tugatib berganingizda, yuzida paydo bo‘ladigan «Ha-a, aynan shuni aytmoqchi edim», degan yengillikni kuzating.'),
  ('489e6dea-7ed3-426f-a373-fa7b11cafdff', 'Dadaning belida ot-o‘yin 🐴', 'U hali bor kuchini sarflamagan va yotishga qarshilik qilmoqda. Dadani yordamga chaqiring. Dadasi bolani beliga mindirib, ot bo‘lib chopganida, xona qahqahaga to‘ladi, yig‘ilib qolgan barcha jismoniy zo‘riqish va tuganmas energiya esa bir necha soniyada ter bilan birga yo‘qoladi.'),
  ('654f0e0a-2920-4fe5-8cf5-be2fa96fa926', 'Onaning quvvat batonchasi 🥑', 'Uni ovqatlantirish uchun 4 xil menyu tuzdingiz, ammo o‘zingiz nima yedingiz? Sog‘lom retseptlar orasidan 5 daqiqada tayyor bo‘ladigan, kalsiyga boy maxsus gazakni tanlang va oyoqda bo‘lsa ham maza qilib yeng. Siz bu uyning dvigatelisiz, quvvat olishingiz kerak.'),
  ('f72407e2-133f-448d-813f-15315e00fa30', 'Mushukdek uyg‘onish 🐾', 'Bugun ertalab u inson emas. To‘rt oyoqlab yuribdi, oyog‘ingizga suykalib, faqat «miyov» deb muloqot qilmoqda. Bu tasavvurning eng yoqimli ko‘rinishi. Qoidalar o‘rnatish o‘rniga, siz ham unga xayoliy sut idishini uzating va bu o‘yindan zavqlaning.'),
  ('28d0f55b-6b15-4788-8b02-4740d679f342', 'Rejim surilib ketyaptimi? ⏱️', 'Kechqurun uxlab qolishi juda cho‘zilyaptimi? Uyqu taymeri jadvaliga qarang. Balki kunduzgi uyqudan butunlay voz kechib, kechki uyqu vaqtini ertaroqqa surish payti kelgandir.'),
  ('2c32efa0-ce45-4ee9-9fb5-78b505fc81dc', 'Multfilm tanqidchisi 📺', 'Ko‘rgan multfilmini sizga o‘z grammatikasi bilan so‘zlab beradi, kim qayerga ketganini jiddiy tushuntiradi. Uni diqqat bilan, hayratlangandek tinglang. Tasavvuri qanot yozsin va o‘zini dunyodagi eng aqlli insondek his qilsin.'),
  ('bc152191-c6d9-4a5e-b03a-d59aaa89994d', 'Hamjamiyatning sokin ko‘magi 💬', 'Juda charchagansiz va hech kimga hech narsani tushuntirishni ham, dardlashishni ham istamayapsiz. Anacan hamjamiyatiga kirib, shunchaki kuzatuvchi bo‘ling. Boshqa onalarning xuddi shunday bema’ni injiqliklarni qanday yengayotganini ko‘rish — eng kuchli sokin tasallidir.'),
  ('487012f7-5a3f-49e2-9f9d-2533c14f18c9', 'Yotoqdan qochish 🏃‍♂️', 'Suv ber, o‘yinchog‘imni top... Uxlamaslik uchun 3 yoshli bolaning bahonalari tugamaydi. Uyqu taymerini yoqing, belgilangan chegaralarni qat’iy saqlang va Oq shovqinlar yordamida xonani tinchlantiring.'),
  ('543ac832-5997-4074-94fa-e27c0915dc20', 'Doston to‘qiydigan kichkintoy 🗣️', 'Endi so‘zlarni birlashtirib, xayoliy hikoyalar va fantastik ssenariylar to‘qiyaptimi? Bu ajoyib nutqiy rivojlanish davrini o‘tkazib yubormang: darhol ovozini yozib oling va Chaqaloq albomida abadiylashtiring.'),
  ('75d14b5e-1909-445c-9146-d6cc02f1b594', 'Kalsiy qalqoni 🦴', 'Tez o‘sayotgan suyaklar uchun kalsiy juda zarur. Sut ichmayaptimi? Ovqatlanishni nazorat qilish vositasi yordamida bugun qancha pishloq, qatiq yoki brokkoli iste’mol qilganini albatta hisoblang.'),
  ('5be6af82-89c1-4468-a900-9f899a3717f7', 'Meniki! davri 🧸', 'O‘yinchog‘ini hech kimga bermayaptimi? Bu xudbinlik emas, rivojlanishning tabiiy bosqichi. Bo‘lishish emas, navbat bilan o‘ynash tushunchasi haqida Bloglardan o‘qib, amalda qo‘llang.'),
  ('6c5b3273-7cbb-4026-9d69-cd0596d59019', 'Ertalabki inqilob 🛑', 'Kecha juda yaxshi ko‘rgan taomini bugun nafrat bilan rad etyaptimi? Bu ishtahasizlik emas, shunchaki vaziyatni boshqarishga urinish. Injiqlik paytida qanday xotirjam qolish haqida Anacan AI bilan dardlashib, chuqur nafas oling va dasturxon atrofida aslo jang qilmang.'),
  ('e85b3357-f072-4120-8d16-ffdc101f5e86', 'Dadaning maydoni 👨‍👧', 'Onalik 24/7 davom etadigan navbatchilik emas. Hamrohingizni ham ishga soling! Bugun tuganmas energiyasini chaqaloq dadasi bilan bog‘da sarflasin, siz esa uyda mutlaq sukunatdan zavqlaning.'),
  ('4b47f634-fca5-4f0e-a391-d61c2ad9b71e', 'Onaning tanaffusi ☕', 'Bola bilan tinmay gaplashish va savollariga javob berish charchatadi. Onalar uchun qulay joylardan bolalar burchagi bor kafeni toping, issiq qahvangizni iching, boshqa onalar bilan dardlashib, biroz nafas rostlang.'),
  ('4e86cfa1-9302-4174-a4b5-457a860c75dd', 'Dadaning ertak aytish navbati 📚', 'Bu oqshomgi uyqu marosimi butunlay dadasining zimmasida. U ertak o‘qisin, siz esa eshik ortida mutlaq sukunatdan zavqlaning.'),
  ('ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7', 'O‘zim qilaman! 🛑', 'Har bir ishga aralashib, kiyinish jarayonini 3 marta uzaytiradimi? Sochilib yotgan narsalarga emas, uning ortib borayotgan o‘ziga ishonchiga qarang. Sabringiz tugay boshlaganda, injiqliklarni o‘yin bilan hal qilish haqida Bloglardan o‘qib, chuqur nafas oling.'),
  ('784cb32f-466a-4d9b-9df3-23fb3c0de764', 'Musiqali gipnoz 🎶', 'Kechga yaqin sababsiz to‘polonlar va yig‘i xurujlari boshlandi. Televizorni o‘chiring, chiroqlarni xiralashtiring va xonada juda mayin klassik musiqa yangrasin. Musiqaning chuqur ohanglari muhitni sehrli tarzda o‘zgartirib, xonaga sokinlik olib kiradi.'),
  ('791a6f93-24a4-4445-acfb-0bee156d7b20', 'Bo‘lishib bo‘lmaydigan nonushta 🍳', 'O‘z likopchasidagidan sizga aslo bermaydi, ammo kelib, sizning likopchangizdagi tuxumdan yeyishni qat’iy talab qiladi. Bolalar ota-onasining tanloviga doimo to‘liq ishonadi. Qarshilik qilmang, luqmangizni unga mehr bilan bering va tabassum qiling.'),
  ('840bd918-95f6-4c59-bcb3-4b0f4eaea73b', 'Jonsiz buyumlar bilan suhbat 🗣️', 'U bog‘dagi toshga yoki uydagi stulga jiddiy ohangda nimalarnidir gapirib, hatto ularni koyiydi. Ramziy o‘yinlar orqali u atrofidagi dunyoni anglaydi. Rivojlanish kuzatuvchisida uning bunday o‘ziga xos ssenariylarini albatta qayd eting — bu yuksak ijodkorlik belgisidir!'),
  ('11214951-0661-40fc-a2c7-d7aedff5cf90', 'Kayfiyat kundaligidagi e’tirof 📝', 'Telefoningizni qo‘lingizga oling. Ijtimoiy tarmoqlarda boshqalarning mukammal hayotini varaqlash o‘rniga, Kayfiyat kundaligini oching va bugun uning qilgan eng kulgili, sizni eng ko‘p kuldirgan ishini kelajak uchun yozib qo‘ying. U yerga yozish — eng sof terapiya.'),
  ('1219c5e2-02af-4f74-a734-ea08c3018209', 'Siz kuylamang! taqiqi 🛑', 'Orqa fonda yangrayotgan bolalar qo‘shig‘iga xirgoyi qilib qo‘shildingiz, u esa shu zahoti: Siz kuylamang! — deb baqirdi. Xonaning yagona yakkaxoni — u, sizning kuylashga urinishlaringiz esa uning sahnasini toraytiradi. Xafa bo‘lmang, sahnani shu mitti xudbinchaga qoldiring.'),
  ('9dfdb936-66eb-43a1-b7d1-6fccd5198f88', 'Aqlli ertakdagi Men 🪄', 'Bugun kechqurun Aqlli ertaklardagi qahramonni bevosita farzandingizning ismi bilan atang. Ertak qahramoni ham xonasini yig‘ishtirib, keyin xotirjam uxlaganini aytib bering va qoidalarni unga baqirib emas, bilvosita singdiring.'),
  ('086dfc4e-9fb2-412e-ade9-cb121424e290', 'Issiq choy va sukunat 🍵', 'Taymer to‘xtadi, bola uxlab qoldi. Uy ishlarini unuting, hammasi kutib turishi mumkin. Sog‘lom retseptlardan mazali ichimlik tayyorlab, o‘zingiz bilan yolg‘iz qolishdan zavqlaning.'),
  ('577db9f8-8f80-4ad0-9e5c-4fd106adca75', 'Ertalabki bekinmachoq 🙈', 'Siz ishga yoki bog‘chaga kechikyapsiz, u esa parda ortiga yashirinib, Meni top! deydi. Asablaringiz taranglashgan bo‘lsa ham, baqirish jarayonni yanada cho‘zadi. Qani, mening shirin bolajonim qayerda ekan? deb o‘yinga 2 daqiqaga qo‘shiling, uni topib, yashiringan joyidan olib chiqing.'),
  ('61996b98-7da4-41e9-be9f-afe630090cfe', 'Ovqatni rangiga qarab ajratish 🍅', 'U likopchadagi ovqatlarni rangi va shakliga qarab ajratadi, yashillarini esa chetga suradi. Oziqlanish rejasiga kiring. Sabzavotlarni ko‘rinmas pyurega aylantirib, mazali souslar ichiga qanday yashirishni bilib oling va bu o‘yinda sezdirmay g‘alaba qozoning.'),
  ('01916001-64ad-41ab-8fea-1c1101a3ae1c', 'Sukunatga ehtiyoj 🤫', 'U nihoyat uxlab qoldi! Uyni qoplagan sukunatga ishongingiz kelmaydi. Ovoz o‘lchagichni yoqing va ekrandagi 0-10 detsibel ko‘rsatkichiga qarab, miyangiz asta-sekin dam olayotganini, bu ko‘zga ko‘rinadigan sukunat sizni qanday erkalayotganini his eting.'),
  ('95ce868b-b982-4c4e-baa7-7ca7cd3520b4', 'Cho‘ntakdan chiqqan xazinalar 🪨', 'Shimini yuvayotganda cho‘ntagidan 2 ta tosh, bitta qurigan barg va yarimta cho‘p chiqdimi? Siz uchun chiqindi bo‘lgan bu narsalar uning olamni kashf etish jarayonida to‘plagan qimmatli kolleksiyasidir. Ularni tashlab yuborish o‘rniga kichik xazina qutisiga yig‘ing.'),
  ('97aa3207-a7a2-42a1-9e74-01d2388db3b1', 'Eshiklarni qulflash missiyasi 🚪', 'Uydagi barcha xonalarning eshiklarini ichkaridan qulflab, sizni tashqarida qoldirish unga alohida zavq bag‘ishlaydi. U shaxsiy hudud tushunchasini o‘zicha yangidan kashf etmoqda. Barmoqlari qisilib qolmasligi uchun ehtiyot choralarini ko‘ring, ammo uning o‘z hududini e’lon qilish o‘yiniga jiddiy xalal bermang.'),
  ('2f583ff5-e2c4-4fbb-acdc-470ccf241970', 'Hojatxona qog‘ozi san’ati 🧻', 'Bir necha daqiqalik sukunat... Xonaga kirganingizda esa hojatxona qog‘ozining hammasi yechilib, butun uyga yoyilganini ko‘rasiz! Jahlingiz chiqmasin, aksincha, qog‘ozlarni yig‘ib, birgalikda qorbobo yoki koptok yasang. Betartiblikni baqiriq bilan emas, ijodkorlik bilan yengib chiqing.'),
  ('6ae9e7b9-b61e-4945-82bd-3ceb19652949', 'Kir yuvish mashinasi kashfiyoti 🧺', 'Kir yuvish mashinasi qarshisida o‘tirib, aylanayotgan kiyimlarga xuddi multfilm tomosha qilayotgandek diqqat bilan qarayapti. Bu mutlaqo bepul va ongni tinchlantiruvchi tomosha. Unga xalaqit bermang, siz ham fursatdan foydalanib dam oling — betartiblik qisqa tanaffus qildi.'),
  ('c8193b18-f83a-473a-bda3-5d573d734271', 'Quloqqa pichirlangan mehr so‘zlari 💖', 'U kun bo‘yi sizni aqldan ozdiray dedi, hamma narsaga o‘jarlik qildi. Ammo hozir yotoqda shu qadar beg‘ubor uxlayaptiki... Yoniga yoting va uni qanchalik yaxshi ko‘rishingizni, bugun qilgan yaxshi ishlarini qulog‘iga pichirlab ayting. Bolalar hatto uyqusida ham onasining mehrga to‘la ovozini his qiladi.'),
  ('8f4abc30-5451-459c-a1af-55ec249af8b0', '«Sen meni eshitmayapsan!» zarbasi 😠', 'Siz telefonga qarayotganingizda yoki ovqatni aralashtirayotganingizda u kelib, yuzingizni o‘ziga qaratadi: Menga qarang! U haq. Unga shunchaki yonida bo‘lishingiz emas, bo‘linmagan e’tiboringiz kerak. Ishingizni to‘xtatib, atigi 3 daqiqa davomida uning ko‘zlariga qaragan holda diqqat bilan tinglang.'),
  ('9069176c-b719-421b-bb4f-85cd101945a6', 'Ertakdan qochishga urinishlar 🏃‍♂️', 'Ertak o‘qiyotganingizda u har fursatda «o‘yinchog‘imni olib kelaman» deb yotoqdan sakrab tushib, yugurib ketadi. Uyquga taslim bo‘lishni istamaydi. Ovozingizni birdan juda pasaytirib, pichirlab o‘qiy boshlang. Sizni eshitish uchun beixtiyor yotoqqa qaytib, butun diqqatini jamlaydi.'),
  ('e4d134d2-7f4f-4894-b6f3-6051d4c2f528', 'Ob-havo va qavat-qavat kiyintirish usuli ⛅', 'Bahor yaqinlashgani sari ob-havo o‘zgaruvchan bo‘ladi: ertalab sovuq, tushda esa issiq. Ob-havo va kiyim vositasi sizga piyoz usulida, ya’ni qavat-qavat kiyintirishni eslatadi. Bog‘da havo isigani sari kiyimning bir qavatini yechib, bolangizning terlashini ham, o‘zingizning stressingizni ham oldini oling.'),
  ('918e0a4a-7932-41e0-b1cb-29b726120c0e', 'Sun’iy intellekt va to‘satdan boshlangan injiqliklar 🤖', 'Kecha-kunduzgacha tinch bo‘lgan bola bugun hamma narsaga tajovuzkor munosabat bildiryaptimi? Internetdan qo‘rqinchli sabablarni qidirmang. Anacan AI-dan bu rivojlanishdagi sakrashning (mental leap) psixologik sabablarini so‘rang va pediatr tasdiqlagan javob yordamida xavotiringizni yo‘qoting.'),
  ('b03065aa-7764-4054-8d16-b42a880815cc', 'O‘g‘irlangan burun o‘yini 👃', 'Burningni oldim! deb bosh barmog‘ingizni ko‘rsatasiz, u esa bunga rostdan ham ishonib, yig‘lay boshlaydi! 3.5 yoshda tasavvur ba’zan haqiqat bilan xayolni ajrata olmaydi. Darhol Mana, qaytarib joyiga qo‘ydim deb, burnidan o‘ping va bu kichik jarohatli holatni tabassumga aylantiring.'),
  ('f9660fac-3163-450f-a18c-f1ac86faf296', 'Turmush o‘rtog‘ingiz bilan so‘zsiz nigoh almashish 🥂', 'Bola nihoyat uxlab qoldi. Siz va turmush o‘rtog‘ingiz divanda yonma-yon o‘tiribsiz, hatto gaplashishga ham holingiz yo‘q. Shunchaki jimlikda bir-biringizga qarab jilmayasiz. Bu so‘zsiz nigohlar biz bu tartibsizlikni a’lo darajada uddalayapmiz deyishning eng go‘zal usulidir.'),
  ('48be6a74-039a-47b4-b2e6-38a02b369aa1', 'Buni men topdim — egalik qiluvchi kichkintoy 🔑', 'Uydagi pultni yoki dadasining kalitini yerdan olib, Buni men topdim, demak meniki! deb turib oladi. Uning uchun topish egalik qilishni anglatadi. Qo‘lidan zo‘rlik bilan tortib olmang, Men uchun topib berganingga rahmat deb, e’tiborini boshqa o‘yinchoqqa qarating va buyumni qaytarib oling.'),
  ('53233246-1c9c-44d8-aa89-08a12ab1932c', 'Oshxonadagi konsert 🥄', 'Qozonlar va yog‘och qoshiqlarni olib, oshxona o‘rtasida konsert beradi. Boshingiz og‘risa ham, bu uning ritmni his qilish qobiliyati va ijodkorligi rivojlanayotganidan dalolat beradi. Darrov aralashmang, bir necha daqiqa davomida o‘sha jo‘shqin energiyaning tovush to‘lqinlari bilan xona bo‘ylab tarqalishiga imkon bering.'),
  ('54609407-cfb4-47a1-8f37-28a152cd5950', 'Vannaxonadagi mini-spa 🛀', 'Bu oqshom vannani faqat unga emas, o‘zingizga ham tayyorlang. Bola uxlagach, iliq suv, biroz ko‘pik va vannaxonada yonib turgan bitta sham. Eshikni qulflang va atigi 15 daqiqaga onalik rolidan chiqib, yana o‘zingiz bo‘ling — siz bunga loyiqsiz.'),
  ('017dd4ef-6a6d-470c-a536-c9d8157780f2', 'Qorong‘ilikka taklif 🌙', 'Yotoqxonada chiroqlar o‘chirilganda bezovta bo‘ladimi? Xonaning bir burchagiga iliq rangli (to‘q sariq yoki qizil) kichik tungi chiroq qo‘ying. Xonaning qolgan qismi esa melatonin ajralishi va chuqur uyqu uchun butunlay qorong‘i bo‘lishi kerak.'),
  ('0cf9c44c-98af-4034-b557-39b1dbb9f133', 'Sartaroshlikka urinish ✂️', 'Xonaga kirganingizda, uning qo‘lidagi qaychi bilan qo‘g‘irchog‘ining sochini kesishga urinayotganini ko‘rasiz. Bunday holat har bir onaning qo‘rqinchli tushidir. Jahlingiz chiqmasdan qaychini olib qo‘ying va bu sartaroshlikka urinishni chaqaloq fotosessiyasida kulgili bir xotira sifatida saqlab qo‘ying.'),
  ('86c98bc5-4f00-463f-9722-124e19e389a1', 'Tabiat qo‘yniga albatta chiqing ⛅', 'To‘rt devor orasida uning energiyasi tajovuzkorlikka aylanadi va har bir gapi «yo‘q» bilan boshlanadi. Ob-havo va kiyimdan qat’i nazar, mos ravishda tayyorlanib, uni albatta tashqariga olib chiqing. Tuproqqa tegish uning asab tizimini darhol qayta muvozanatga keltiradi.'),
  ('04ffb755-8100-4999-9284-739b81b180be', 'Bu meniki! — Hamma narsani o‘ziniki qilish 🧸', 'Uydagi istalgan buyumni quchoqlab, «Bu meniki!» deb baqiradi va uni hech kimga bermaydi. U egalik chegaralarini o‘rganmoqda. Uni xudbinlikda ayblamang, e’tiborini boshqa o‘yinga qaratib, buyumni qaytarib oling.'),
  ('1f9e9c23-d051-49a3-8538-a3275546e6a3', 'Axlat emas, san’at 🎨', 'U xonaning o‘rtasida mayda qog‘oz parchalari va kesilgan iplardan katta san’at asari yaratgan, uni tashlab yuborishingizga esa ruxsat bermayapti. Ozodalikka haddan tashqari berilishni bir chetga suring. U yaratgan tartibsizlikni hurmat qiling, tozalash ertagacha kutishi mumkin.'),
  ('55f7cd1c-adbb-4e6a-bcc0-5847c157d42a', 'Dadaning belida ot minish 🐴', 'U hali ham bor kuchini sarflamagan va uxlashga qarshilik qilmoqda. Dadasini yordamga chaqiring. Dadasi bolani beliga mindirib, ot bo‘lib chopganida, xona qahqahaga to‘ladi, to‘planib qolgan barcha jismoniy zo‘riqish va tuganmas energiya esa ter bilan birga soniyalar ichida yo‘qoladi.'),
  ('370a629d-a585-41ae-ad7c-85bbfe349f3d', 'Kayfiyat kundaligidagi e''tirof', 'Telefonni qo''lingizga oling. Ijtimoiy tarmoqlarda boshqalarning hayotini tomosha qilish o''rniga, Kayfiyat kundaligini oching va bugun uning qilgan eng kulgili ishini kelajak uchun yozib qo''ying. Bu raqamli terapiya sizni ham tinchlantiradi — ekranga qarab, tashvishlaringiz qanday tarqalib ketayotganini his qiling.'),
  ('8353b398-30f5-4594-98bd-74c894cfb243', 'Qo''shiqni qaytar! 🎶', 'Radioda yangragan va tugagan qo''shiqni yana qo''yishni so''raydi. Siz bu jonli efir bo''lganini va qo''shiq tugaganini tushuntirasiz. Ammo u Qaytar! deb yig''laydi. Bola miyasi jonli efir mantiqini hali tushunmaydi. Diqqatini chalg''itish uchun qo''shiqni o''zingiz boshqacha, kulgili ovozda kuylay boshlang.'),
  ('f3893094-7182-4330-982a-7ccd3eced333', 'Sukunatdagi choy ☕', 'U xona o''rtasida o''yinchoqlarini qator qilib terib, o''zi mustaqil o''ynayapti. Iltimos, bu fursatni uy supurishga sarflamang! Divanga o''tiring, qahva yoki choyingizni issiqligida iching va 10 daqiqa hech narsani o''ylamasdan, shunchaki shu sukunatdan zavqlaning.'),
  ('52d5f808-8d3e-4769-9814-0abc72834d43', 'Uyqu uchun taymer taktikasi ⏱️', 'Uxlash vaqti kelganda birdan chanqab qoladimi, hojatxonaga borgisi keladimi yoki devor bilan xayrlashadimi? Taymer o''rnating. Qo''ng''iroq chalinganda hamma uxlaydi qoidasini joriy qilib, bu cheksiz xayrlashuv va mohirona nayranglardan tortishuvsiz qutuling.'),
  ('7cbac7ca-9f74-4319-bb84-ce56d77a4832', 'Anacan hamjamiyatining kuchi 💬', 'Mening bolam nega bunchalik qaysar? degan o''y xayolingizni band qilmoqda. Anacan hamjamiyatiga kiring. Boshqa onalarning uyida ham yuz beradigan shunga o''xshash bema''ni injiqlik xurujlari haqida o''qib, yolg''iz emasligingizni va mutlaqo tabiiy jarayondan o''tayotganingizni ko''rasiz.'),
  ('c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b', 'Haqiqiy rassom devorni tanlaydi 🖍️', 'Bir necha soniyalik sukunat xavfli tus oldi. Xonaga kirib, uning devorga flomaster bilan san''at asari chizganini ko''rdingiz. Chuqur nafas oling. Uning mayda motorikasi rivojlanmoqda, devorni esa baribir tozalasa bo''ladi. Kelajakda birga kulish uchun bu durdona asarni albatta suratga oling.'),
  ('11adcff5-957f-4e30-8ecc-96f09d1482fe', 'Ertaklar olami 🪄', 'Klassik ertaklarni bir chetga qo‘ying. Aqlli ertaklarni oching. Maxsus ertak yarating.'),
  ('4418649d-d556-4a03-af91-b1d0242b6324', 'Hamjamiyat ko‘magi 💬', 'Juda charchagansiz va hech kimga hech narsani tushuntirishni yoki dardlashishni istamayapsiz. Anacan hamjamiyatiga kirib, shunchaki kuzatuvchi bo‘ling. Boshqa onalar xuddi shunday bema’ni inqirozlarni qanday yengayotganini ko‘rish — eng kuchli so‘zsiz tasallidir.'),
  ('6e6ecb59-b07b-44ae-b10f-31d088fcccf0', 'Tonggi diktator ish boshida 👑', 'U yerga sen o‘tirma, ayiqcham o‘tiradi! Nonushta paytida butun stolni u boshqaradi. Uning irodasini keskin sindirmasdan, Yaxshi, ayiqchang o‘sha yerda o‘tirsin, men esa bu yerda o‘tiraman deb, muvozanat va xonadagi tinchlikni saqlang.'),
  ('1b1ca975-b7c1-4e57-9e31-3f5e83031e0f', 'Kunduzgi uyqu isyoni 🥱', 'Yotishni istamay, yig‘layaptimi? Majburlamang. Xonadagi yorug‘likni pasaytirib, Jim kitob varaqlash vaqti deb e’lon qiling va ikkalangizga ham dam beradigan yangi odat yarating. Shunda siz ham, u ham o‘ziga xos tarzda dam oladi.'),
  ('8ca291c9-dcd2-4396-9580-b58e8c48c73a', 'Ssenariyni u yozsin 🪄', 'Klassik kitoblardan ikkalangiz ham zerikkansiz va xonada zerikarli muhit hukm surmoqda. Aqlli ertaklarni oching va bu oqshom voqealar rivojini u boshqarishiga ruxsat bering. Endi uchar mashina qayerga borsin? deb so‘rang, xayolan olamlarni zabt etib uxlab qolsin.'),
  ('bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83', 'Ko‘zgudagi raqib 🪞', 'Ko‘zgu qarshisida turib, o‘ziga o‘zi qoshlarini chimiradi, jahldor va g‘alati yuz ifodalarini qiladi. U hissiyotlar yuzida qanday aks etishini sinab ko‘rmoqda. Chet­dan ovoz chiqarmay, bu mitti teatr aktyorining mashqini zavq bilan tomosha qiling.'),
  ('c78f6742-28ba-40d4-8884-94cee25316f0', 'Devor bilan pichirlashib suhbatlashish 🤫', 'To‘shakka kirib, yuzini devorga o‘girgancha kim bilandir pichirlashib dardlashyaptimi? Juda ham yoqimli! Chiroqlarni o‘chirib, o‘sha pichirlashlar asta-sekin uyquga singib ketishini tinglab, dam oling.'),
  ('ca5cea03-5260-4977-bf88-cfe3ed937e38', 'Noto‘g‘ri stakan janjali? 🥤', 'Suvni sariq stakanda berganingiz uchun uyda qiyomat qo‘pdimi? Ko‘nglingizga olmang, u shunchaki bugun ertalab chegaralaringizni sinab ko‘ryapti. Suvni darhol ko‘k stakanga quyib, uyda tinchlik o‘rnating va kuchingizni kunning qolgan qismiga asrang.'),
  ('f8e8bb79-94ba-4264-b58d-e4f81f8007f5', 'Changyutgich bilan adovat 🌪️', 'Uyni tozalayotganingizda «changlarimni supurmang», deb yig‘lab, yo‘lingizni to‘syaptimi? Egalik hissi bema’nilik darajasiga yetibdi. Changyutgichni o‘chiring va 5 daqiqa davomida changlar bilan xayrlashish marosimini o‘tkazing. Ishoning, bu tartibsizlikni tezroq tugatadi.'),
  ('0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9', 'Kiyimlar yana mos kelmadi 🧥', 'Ko‘chaga chiqmoqchisiz-u, u rezina etik bilan kalta yengli kiyim kiyishni xohlayaptimi? Bahslashmang. Telefonda ob-havoni ochib, bunday kiyinishga telefon ruxsat bermayotganini ko‘rsating. Qoidani raqamli ekranga topshiring, o‘zingiz chetga chiqing — u ko‘ylagini indamay kiyib oladi.'),
  ('310c5e1a-58e7-49ee-a785-62a8445bbaba', 'Bir piyola choy orzusi ☕', 'Shunchalik charchadingizki, u o‘ynab turganida sekingina oshxonaga qochib kirib, eshikni yopdingizmi? Haqsiz. Kayfiyat kundaligini ochib, atigi uchta so‘z yozing: Bugun omon qoldim. Ba’zida onaga atigi o‘sha 5 daqiqalik tanaffus kerak bo‘ladi.'),
  ('a80cc41d-cd81-475f-9ddf-075470e2ad74', 'Bulutni ushlang, ketmasin! ☁️', 'Derazadan qarab, bulut uzoqlashayotgani uchun yig‘layaptimi? Shamolni ilmiy tushuntirishga vaqtingizni sarflamang. «U hozir boshqa bolalarga salom berish uchun ketdi», deng. Uning bu g‘aroyib falsafasiga hazil va kichik to‘qimalar bilan javob berib, kunni qutqarib qoling.'),
  ('154abe48-3205-47d2-a68c-a06bfd4856c5', 'Dadasi bilan divanda kurash 🤼‍♂️', 'Uxlashga yotmaslik uchun qochib, yashirinib oldimi? Navbatni dadasiga bering. Divanda hazillashib kurashishsin. Shovqinli, terlatadigan, ota-bola o‘yini farzandingizning qolgan qaysar energiyasini ham chiqarib yuborib, uni uyquga taslim qiladi.'),
  ('1d80be38-a3ec-4e4f-a266-479942a81b0f', 'Internetdagi onalardan charchadingizmi? 📵', 'Instagramni ochishingiz bilan boshqalarning mukammal farzandlarini ko‘rib, tushkunlikka tushmang! Ilovani yoping-da, Anacan Hamjamiyatiga kiring. Boshqalarning uyi ham siznikidek ag‘dar-to‘ntar, bolalari esa shovqinchi ekanini ko‘rib, chuqur nafas oling — siz yolg‘iz emassiz!'),
  ('f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37', 'Buni men pishiraman! 🍳', 'Tuxumni albatta o‘zi chaqmoqchi bo‘lib, yarmini stolga to‘kib yubordimi? O‘zidan faxrlangan mitti oshpazning quvonchiga sherik bo‘ling. Oshxona baribir yuviladi, ammo uning rivojlanayotgan o‘ziga ishonchi va mustaqilligiga to‘sqinlik qilmang.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('66d60d54-4a5d-4de0-a372-047beaa63d3c'::uuid, 'Yashirin makaron zaxirasi 🍝', 'Shimini yuvayotganda cho‘ntagidan qurib qolgan makaron chiqdimi? Bu ochko‘zlik emas, bolalarcha rejalashtirish. Jiddiy qiyofada uni axlatga tashlang, ammo ich-ichingizdan bu mitti tadqiqotchi va g‘amxo‘r ta’minotchiga jilmayib qo‘ying. Ular ulg‘ayishyapti!'),
  ('d2eca751-d4a9-42ee-89e8-a1b216e785bc', 'Sukunatning ekrandagi raqami 🤫', 'Nihoyat uxlab qoldi. Uy shu qadar jimjit bo‘lib qoldiki, quloqlaringiz shang‘illayaptimi? Ilovadagi Ovoz o‘lchagichni oching. Undagi 0 detsibel yozuviga qarash shovqindan charchab, karaxt bo‘lgan miyangiz uchun dunyodagi eng yaxshi vizual massaj bo‘ladi.'),
  ('d6eb2191-63cd-4b2d-9410-9f12b1424bea', 'Ko‘ylakning yorlig‘i botyapti! 🏷️', 'Orqasidagi kichkina yorliq ignadek botgani uchun ko‘ylakni kiymayman, dedimi? 3.5 yoshdagi sensor sezgirlik odamni aqldan ozdiradi. Umuman bahslashmang, qaychini olib, yorliqni tagidan kesib tashlang va bu mitti inqirozni bir zumda bartaraf eting.'),
  ('772e1eef-c912-4a17-abaa-b5296c686fe3', 'U tosh meniki edi! 🪨', 'Parkdan olib kelgan o‘sha kir toshini tashlab yuborganingiz uchun dod solyaptimi? Ma’lum bo‘lishicha, u eng yaqin do‘sti ekan. Darhol boshqa bir yaltiroq buyum topib, «Qara, tosh senga buni esdalik uchun yuboribdi», degan uydirma hikoya bilan vaziyatdan mohirona chiqib keting.'),
  ('8d7ffafe-9007-449d-a1c5-50fafa6a8a92', 'Mening ertagim, mening qoidam 📖', 'Ertak o‘qiyotganda bir so‘zni noto‘g‘ri aytdingiz va u darhol sizni tuzatdimi? Demak, yodlab olibdi! Kitobni yoping-da, «Unda bugun kechqurun sen menga o‘qib ber», deng. Uning tasavvur olami ishlasin, siz esa shunchaki yonboshlab, ovozini tinglang.'),
  ('ba68f77d-f963-479b-bdc5-453510fe2fd8', 'Sho‘rva detektivi ish ustida 🥕', 'Qoshiqni sho‘rvaga solib, bittagina piyozni topdi-da, chetga olib qo‘ydimi? Zargardek aniqlik! Darhol Sog‘lom retseptlarni ko‘rib chiqing, ertadan boshlab o‘sha sabzavotlarni blenderdan o‘tkazib, souslar ichiga qanday yashirishni o‘rganing va sezdirmay g‘alaba qozoning.'),
  ('3f320efd-46d8-4e41-85e8-a584506068f1', 'Juftlik bo‘lib sukunatda 🥂', 'Bola uxladi, uy yig‘ishtirildi. Juftingiz bilan divanda yonma-yon o‘tiring, hatto televizorni ham yoqmang. Shunchaki bir-biringizga «Buni ham uddaladik, omon qoldik», degan nigoh bilan qarang. Ishoning, ota-onalikning eng romantik va eng haqiqiy lahzasi aynan shu.'),
  ('5c1ffe1c-132b-41ee-89f2-40908e4efd15', 'Do‘kondagi o‘sha dahshatli «Xohlayman!» 🛒', 'Kassaning shundoqqina oldida shokolad uchun qichqiryaptimi? Orqadagilarning nigohlariga qaramay, taslim bo‘lmang. Xaridlar ro‘yxatini ochib, «Bu ro‘yxatda yo‘q, kassa buni o‘tkazmaydi», deng. Tashqi bir vakolat ular uchun doim ishonchliroq tuyuladi.'),
  ('68fe0739-89b9-4724-85e1-174aecc17d9d', 'Nega men bilan gaplashding? 😤', 'Shunchaki «Xayrli tong», deganingiz uchun jahli chiqdimi? Sababsiz arazlash davri avjida. Unga bosim qilmang, choyingizni quyib iching. Ishoning, 2 daqiqadan keyin o‘zi kelib tizzangizni quchoqlaydi. Uning his-tuyg‘ulari shu qadar chalkash!'),
  ('5a73dbf6-a948-449b-bd9f-bd6acec175f3', 'To‘rt oyoqlab yurgan bola 🐾', 'Bugun ertalab u yotoqdan boladek emas, kuchukdek emaklab chiqdimi? Qoidalarni o‘qib, asabiylashmang. «Barakalla, mening aqlli kuchukcham», deb nonushtasini bering. Rolli o‘yinlarga qo‘shilish o‘jarlik qilishdan ko‘ra ancha kam energiya talab qiladi.'),
  ('b5299007-402e-4c46-9a86-5fb45df938df', 'Yarim tunda to‘satdan qichqirish 😭', 'Kechasi ko‘zlari yumuq holda yig‘lab uyg‘ondi va sizni eshitmayaptimi? Yig‘isini tahlil qiling: bu tungi vahima. Uni uyg‘otmaslikka harakat qiling, shunchaki yonida turing, qo‘lidan ushlab, silang. O‘z-o‘zidan tinchlanib, yana chuqur uyquga ketadi.'),
  ('cd19d080-ed21-40f3-b449-164e996aed41', 'Tanam o‘zimga tegishli emas 🔋', 'Kun bo‘yi oyog‘ingizga yopishib olib, quchoqqa olishni so‘rayaptimi? Siz jismonan holdan toyibsiz. Tegishlardan charchash (touched out) holatini boshdan kechiryapsiz. Uni xonada o‘yinchoqlari bilan qoldirib, 5 daqiqaga hammomga kirib oling va shunchaki yolg‘iz qolish hissidan bahramand bo‘ling. Bunga haqqingiz bor.'),
  ('3c2e2a41-c838-4dd0-b137-24862355a226', 'Eshikni men ochaman! 🚪', 'Uydan chiqayotganda eshikni siz ochganingiz uchun yig‘lab, uni qayta yopishingizni talab qildimi? Bu yoshda nazorat hissi eng katta psixologik ehtiyojdir. Mayli, bunga 1 daqiqa sarflang, ammo shu orqali ko‘chada yuz berishi mumkin bo‘lgan 30 daqiqalik injiqlikning oldini olib, uning o‘ziga bo‘lgan ishonchini mustahkamlaysiz.'),
  ('93ebf06c-8a17-42ec-bbd4-671ae644ffaa', 'Vannadagi suv toshqini 🌊', 'Cho‘milish shunchaki bahona, aslida u vannada okean yaratib, to‘lqinlar bilan o‘ynayaptimi? Mayli, o‘ynasin. Suvning shovqini va sachrashi uning ichidagi tuganmas, o‘jar energiyani yuvib ketadi. Kechqurun hech qanday qarshiliksiz yotog‘iga yotadi.'),
  ('ed5a44fd-8133-4d4a-859e-893fc179d90d', 'G‘alati savollarga AI javobi 🤖', '«Oyi, soyam tunda qayerga ketadi?» degan savol qarshisida nima deyishni bilmay qoldingizmi? Hech narsa to‘qib chiqarmang. Anacan AI-ni oching va 3.5 yoshli bola uchun ertakdek, yoqimli ilmiy javob olib, unga o‘qib bering. O‘zingizni buyuk faylasuf va hamma narsani biladigan onadek his eting.'),
  ('14c25fd3-e3ee-49fb-8520-527d8c11b191', 'Teskari kiyilgan faxr 👕', 'Ko‘ylagini teskari kiyib olib, uni to‘g‘rilashingizga aslo yo‘l qo‘ymayaptimi? Bu uning ishi! Ko‘zlaridagi «Men uddaladim!» degan ishonch kiyimni to‘g‘ri kiyishdan muhimroq. Mayli, kun bo‘yi shu holatda faxrlanib yursin — bu uning tanlovi.'),
  ('4ffcb0aa-a9e4-48df-8c7b-2bcf41163980', 'Shivirlab uxlatish 🤫', 'Yotoqdan turib, xona bo‘ylab yuguryaptimi, uxlashni istamayaptimi? Baqirmang. Birdan juda past ovozda, shivirlab gapira boshlang. Sizni tushunish uchun diqqatini shu qadar jamlashiga to‘g‘ri keladiki, miyasi charchab, avtomatik ravishda uyqu rejimiga o‘tadi. Sinab ko‘ring!'),
  ('5dd3ffc3-a306-476f-91ee-6cb8332ca500', 'Mukammal sukunat lahzasi 🛋️', 'Pazllari bilan shu qadar berilib o‘ynayaptiki, uyda birdan sukunat cho‘kdimi? Shubhalanmang, darhol o‘zingizga bir piyola qahva quying. O‘sha noyob va oltinga teng daqiqalarni uy tozalashga yoki kir yuvishga emas, ruhiy dam olishga sarflang. Siz robot emassiz.'),
  ('3481c7e9-17f1-45e8-b5ca-16ba68fd1628', 'Vannadagi mitti laboratoriya 🛀', 'Suvga turli rangdagi sovunlarni qo‘shib, sehrli eliksir tayyorlayapti. Ha, hammom iflos bo‘ladi. Ammo u erituvchilar va moddalarning aralashishini o‘rganmoqda. Bu ilmiy izlanish kechki charchoqni chiqarib, uni osoyishta uyquga tayyorlaydigan eng yaxshi vositadir.'),
  ('628064ef-a8e4-4e1f-b2f9-27acab4d05cf', 'Tegishlardan tanaffus 🔋', 'Kun bo‘yi ustingizga chiqib, sochingizni tortgan boladan jismonan holdan toyibsiz. Uni darhol xavfsiz joyda qoldirib, boshqa xonaga o‘ting. Kayfiyat kundaligingizga «Tanam menga tegishli emas» deb yozib, ushbu touched out sindromining ruhiy yukini yengillashtiring.'),
  ('6dfd2aa0-4f21-483a-bbab-d26de61eb620', 'Shkaf ichidagi yolg‘izlik 🚪', 'Uy o‘rtasidagi shovqin-suron birdan tindi. Uni kiyim shkafi ichida, qorong‘ida yolg‘iz o‘ynayotganida topdingiz. Bu depressiya emas, shunchaki hissiy qayta tiklanish lahzasi. Eshikni sekingina yopib, unga shaxsiy makondan bahramand bo‘lish imkonini bering.'),
  ('401f5436-2de1-44e1-911f-f31af21dfae8', 'Dadaning to‘qima qahramonlari 🦸‍♂️', 'Bu oqshom kitobdagi ertaklarni unuting. Dada bosh qahramoni bolaning o‘zi bo‘lgan to‘qima va fantastik hikoya aytib bersin. «Shunda u qilichini sug‘urib... tishlarini yuvdi!» kabi jumlalar bolani qahqahaga solib, uyquga tayyorlaydi.'),
  ('cc1183e6-40b5-4a08-b574-b47668387f44', 'O‘z rasmini tanqid qilish 🖍️', 'Chizgan qora qoralamasini ko‘rsatib, «Bu siz edingiz, lekin yaxshi chiqmadi», deydi-da, yirtib tashlaydi. Unda o‘zini tanqid qilish qobiliyati shakllanmoqda! Uning hislarini kamsitmang, «Keyingi rasmda qizil rangni ham sinab ko‘rarsan?» deb, rivojlanishini qo‘llab-quvvatlang.'),
  ('faf3013a-4d98-4178-82f0-b76954e80a74', 'Do‘konda «Buni men topdim» 🛒', 'Kassaga yaqinlashganingizda aravachadan siz solmagan bir o‘ram pechenye chiqadi. U sezdirmay izlanish olib borgan. Xaridlar ro‘yxatini ochib, «Qara, bu ro‘yxatimizda yo‘q, keyingi safar yozib qo‘yamiz», deb, qoidani raqamli hakamga yuklang.'),
  ('064802a6-44a3-418a-af04-e8b21366e4d7', 'Mebelga tirmashish olimpiadasi 🧗‍♂️', 'U divan chetidan deraza tomon tirmashadi. Uy siz uchun xavf-xatarga to‘la joy, uning uchun esa sport zalidir. «Ehtiyot bo‘l, yiqilasan!» deb vahima qilish o‘rniga, «Qo‘lingni u yerga qo‘y», deya uning harakatga bo‘lgan ehtiyojini to‘g‘ri yo‘naltiring.'),
  ('1c07d667-ff98-498d-8a14-c5dc48ceda8c', 'Yashirin sabzavotlar operatsiyasi 🥦', 'U sho‘rva ichidagi bittagina guruch donasi yoki sabzini topib, «Men buni yemayman», deydi. Ovqatlanish rejasiga kiring. Oqsil va sabzavotlarni qanday qilib rang-barang keks shakliga keltirishni o‘rganib, bu qaysar oshpazning miyasini chalg‘iting.'),
  ('7ce3cc61-1a21-499e-a7c2-d24e3693336c', 'Juftlik choyi 🥂', 'Og‘ir kundan so‘ng stakanlarga oddiy issiq choy quying. Turmush o‘rtog‘ingiz bilan divanda yuzma-yuz o‘tirib, «Bugun ham o‘sha tartibsizlikdan omon chiqdik, biz ajoyib jamoamiz», deya stakanlarni urishtiring. Siz oilaning mustahkam poydevorisiz.'),
  ('8d6625c2-a9b5-42f5-804d-da69978a47f8', 'Telefon o‘g‘risi 📱', 'O‘zingizga choy quyayotib, telefoningiz yo‘qolganini va u divan ortida sizga o‘xshab Alo deyayotganini ko‘rdingiz. U raqamli odatlaringizni skanerlamoqda.'),
  ('e750fc50-e44a-47b8-b631-5ac89b90275d', 'O‘zing kiyin! siyosati 👖', 'Oyoqlarini osmonga ko‘tarib, Men chaqaloqman, sen kiyintir deydi. Ular mustaqillik va qaramlik orasida borib-kelishadi. Zo‘rlab kiyintirmang. Kiyimni yoniga qo‘yib, Bu superqahramon shimi o‘z egasini kutyapti, deb hiyla ishlating.'),
  ('fa66784d-c126-46e1-ac35-502bd4ad5f50', 'Ovoz o‘lchagich bilan ichki xotirjamlik 🤫', 'U nihoyat uxlab qoldi. Quloqlaringizdagi shang‘illash esa to‘xtamayapti. Ilovadagi Ovoz o‘lchagichni oching. Ekrandagi 0 desibel yozuviga qarab, xonadagi sukunat miyangizga qanday singib borayotganini va sizni qanday tiklayotganini ko‘z bilan tasdiqlang.'),
  ('61c7ca48-5a19-4998-8086-07edd1d4d938', 'Anacan hamjamiyatida taskin 💬', 'Men hech qachon mukammal bo‘la olmayman degan tuyg‘u sizni bo‘g‘yaptimi? Instagramdagi o‘sha mukammal onalar xayolini unuting. Anacan Hamjamiyatiga kiring va uyi ostin-ustun, farzandi esa devorlarga chizgan onalarning samimiy e’tiroflarini o‘qib, Men mutlaqo normalman, deng.'),
  ('7a600dc5-32dc-4b11-81f6-fb429bfb7588', 'Shivirlashning sirli kuchi 🌙', 'U yotoqqa yotmaslik uchun bahonalar o‘ylab topadi. Ovozingizni juda pasaytirib, faqat shivirlab gapiring. Sizni tushunish uchun u butun diqqatini jamlashga majbur bo‘ladi va bu diqqat uning miyasini gipnoz qilib, uxlatadi.'),
  ('fbad87dc-8f76-4644-9e49-49107be8118b', 'Dinozavr mantig‘i 🦖', 'Ertalab hech bir savolga javob bermay, faqat o‘kiradi. Bugun u T-Rex. Xo‘sh, T-Rex-lar bo‘tqa yeydimi? deb, u o‘ylab topgan shu obrazga moslashing va ertalabki yumushlarni ko‘z yoshlarsiz yakunlang.'),
  ('1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2', 'Soyadan qo‘rqish 👻', 'Ko‘chada ketayotib, birdan o‘z soyasidan qo‘rqib, ortingizga yashirindi. Bundan mantiq izlamang — 3.5 yoshli bolaning tasavvuri shunday ishlaydi. «Kel, soyaning ustiga sakraymiz», deb, u qo‘rqayotgan narsani darhol jismoniy o‘yinga aylantiring.'),
  ('9cee1c64-59c7-411a-9cc4-1d823dfe8c01', 'Sun’iy intellekt va xotirjamlik 🤖', 'Farzandingizda to‘satdan paydo bo‘lgan duduqlanish yoki jahldorlik xurujlari sizni internetdan xavfli kasalliklarni izlashga undadimi? To‘xtang! Anacan AI’dan bu 3 yoshdagi rivojlanish sakrashi bilan bog‘liqmi, deb so‘rang va pediatrlar tasdiqlagan, ko‘nglingizni tinchlantiruvchi javob oling.'),
  ('d8c70945-12ad-4739-98a0-3d98184c5d44', 'Xonadagi ovoz effektlari 🪄', 'Aqlli ertaklarni yoqing. Hikoyani o‘qiyotganda shunchaki eshik g‘ichirlashi, shamol ovozi va shivirlashlarni chiqarib, xonada ovozli teatr yarating. Bu noodatiy tovushlar uning diqqatini bir zumda ertak olamiga, u yerdan esa chuqur uyquga yetaklaydi.'),
  ('a4d74500-c7bc-4a1a-a200-c6bae74eb5ce', 'Nonning o‘rtasi meniki! 🍞', 'Farzandingiz bir bo‘lak nonning faqat o‘rtasini yeb, chetlarini sizga uzatyaptimi? Non chetlari uchun tortishmang. Ertadan nonni metall pechenye qoliplari (hayvon shaklidagi) bilan kesing. Chiroyli shakl ovqat borasidagi bu muammoni bir zumda hal qiladi.'),
  ('e1513af5-17e8-478e-acc0-67084e546889', 'Shunchaki hidini to‘yib his qiling 🫂', 'Bugun u sizni rostdan ham aqldan ozdirib, butun quvvatingizni so‘rib oldimi? Ammo yotoqda shunchalik beg‘ubor uxlayaptiki... Chiroqlarni o‘chiring, ertak o‘qimang. Yoniga yotib, bolaning o‘sha musaffo hidini chuqur-chuqur his qiling va bugungi kun uchun ham shukr qiling.'),
  ('f1d4800f-e749-493d-9ba5-56a7cf6edfa0', 'Uydan chiqishni istamayman muammosi ⛅', 'To‘rt devor orasida siqilib qoldingiz, u esa divanda yig‘lab, tashqariga chiqishni istamayaptimi? Ob-havo va kiyim bo‘limini ochib, mos kiyimlar to‘plamini tanlang va xohlamasa ham, uni parkka olib boring. Toza havo yuziga tegishi bilan butun o‘sha jahli bir zumda tarqaladi. Sizga ishonamiz!'),
  ('3a198cfb-0f8d-4bb9-b96b-0ead690adcbf', 'Bir-biriga qo‘shilmaydigan taomlar qonuni 🚫', 'Nonushtada pomidor bodringga tegib ketgani uchun inqilob boshlandimi? 3.5 yoshning rasmiy ovqatlanish falsafasiga xush kelibsiz. Mantiq izlamang, Sog‘lom retseptlar bo‘limida likopchani qanday qilib qiziqarli va bir-biridan ajratilgan hududlarga bo‘lishni o‘rganing hamda bu absurd inqirozni tinch yo‘l bilan hal qiling.'),
  ('9f8b4dfd-dfd3-4045-969a-2d6b122add47', 'Uyqu oldidan diplomatik muzokara 🤝', 'Yotmaslik uchun siz bilan rasman savdolashadi: Ikki qultum suv ichaman, bir marta quchoqlaysiz, keyin uxlayman. Bu mohirona nayrangga jilmayib qo‘ying. Shartini qabul qiling-da, chiroqlarni qat’iyat bilan o‘chirib, kelishuvni darhol yakunlang.'),
  ('d547337a-f6dc-44bb-a0b7-19904928148b', 'Poldagi lava o‘yini 🌋', 'Pol — lava, divanga chiq! Tasavvur kuchi uyni changalzorga aylantirdi. Ishlaringizni bir chetga qo‘ying va hech bo‘lmasa 2 daqiqaga siz ham lavadan qochib, uning dunyosiga qo‘shiling. Ba’zan bolaning qoidalariga bo‘ysunish stressdan xalos bo‘lishning eng yaxshi usulidir.'),
  ('6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba', 'Axlat qutisidagi sirlar 🗑️', 'Do‘kondan sotib olgan o‘yinchoqni emas, uning o‘ramidagi pufakchali plyonkani quchoqlab, kun bo‘yi o‘ynayaptimi? Bola miyasi tayyor ssenariylarni emas, erkinlikni yaxshi ko‘radi. Rivojlanish kuzatuvchisiga uning ana shunday noodatiy ijodkorlik lahzalarini faxr bilan qayd eting.'),
  ('7fe2513f-2da9-40be-8ba2-3f77c91758aa', 'Oqshomning osoyishta lahzalari 🛀', 'Kun bo‘yi «nega?»larni eshitib, boshingiz qotdi. Uni iliq suv to‘ldirilgan vannaga tushiring, suvga biroz ko‘pik qo‘shing. O‘zingiz esa yoniga o‘tirib, shunchaki suvning shovqiniga e’tibor qarating. Suvning sehrli ta’siri bolaning qaysarligini ham yuvib ketadi, sizning asablaringizni ham tinchlantiradi.'),
  ('e5f2539f-4aa6-4c0d-ad49-b97d6f90a867', 'Siz meni eshitmayapsiz! 😤', 'Menga quloq soling! deb yuzingizni qo‘llari bilan o‘ziga qaratadi. U shunchaki yonida bo‘lishingizni emas, diqqatingiz 100% unda bo‘lishini xohlaydi. Telefonni yoki qo‘lingizdagi ishni atigi 3 daqiqaga chetga qo‘yib, uning ko‘zlariga qaragan holda diqqat bilan tinglang. Bu soatlab davom etishi mumkin bo‘lgan injiqlikning oldini oladi.'),
  ('9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e', 'Fizikaga qarshi chiqqan qaysarlik 💧', 'Suvni stolga to‘kib yubordi va endi sizdan uni yana stakanga yig‘ib berishingizni yig‘lab talab qilmoqda! Ha, bu xonada mantiq yo‘q, faqat ortga qaytarib bo‘lmaydigan xatodan hafsalasi pir bo‘lgan bolakay bor. Tushuntirishga urinmang, qo‘liga sochiq tutqazib, “Kel, bu suvni yo‘q qilib yuboramiz”, deb vaziyatni o‘yinga aylantiring.'),
  ('aff11dbf-a5df-4f87-ba8b-797021b1bfe4', 'Ona uchun oflayn boshpana 🚪', 'Shovqindan quloqlaringiz jaranglab ketdi. Uni xavfsiz joyda (yoki dadasi bilan) qoldirib, hojatxonaga kiring va eshikni yoping. Shunchaki 5 daqiqa devorga qarab o‘tiring, hech narsa qilmang, hatto telefonni ham ochmang. Shu qisqa sukunat sizni yana onalik vazifasiga qaytaradigan eng kuchli vositadir.'),
  ('f965edcf-2124-46c3-82a9-e8d418ee755a', 'Dadaning parvoz rejimi ✈️', 'Uyda energiyasini sarflay olmadi va uxlashni istamayapti. Dadasini divanga chaqiring. U bolani havoga ko‘tarib, samolyot qilib o‘ynatganida, xonani to‘ldirgan qahqahalar yig‘ilib qolgan barcha jismoniy zo‘riqishni bir necha soniyada yo‘qotadi. Endi navbat dadasiga.'),
  ('535821ef-9689-4454-87b8-1d43fe500b62', 'Yangi tilning ixtiro qilinishi 🗣️', '“O‘yinchog‘im xafa bo‘ldi”, “Osmon yig‘ladi” kabi his-tuyg‘ularni buyumlarga ko‘chirib, butunlay o‘zi o‘ylab topgan poetik jumlalarni tuzadi. Uning so‘z boyligi va hissiy intellekti shiddat bilan rivojlanmoqda. Chaqaloq fotosessiyasining video rejimidan foydalanib, uning bu yoqimli falsafasini darhol arxivga saqlab qo‘ying.'),
  ('baf0af3c-984e-45f1-a68f-93e13e9f1cef', 'Oshxona yetakchisi ish boshida 🧑‍🍳', 'Siz keks tayyorlayotganingizda, albatta yoningizga stul qo‘yib, unni o‘zi solishni xohlaydi. Ruxsat bersangiz, oshxona ostin-ustun bo‘ladi. Unga bo‘sh idish, suv va ozgina un berib, “Sen o‘z keksing uchun xamir qor”, deng. Tartibsizlik bo‘ladi, ammo uning mustaqil ish qilish istagi to‘liq qondiriladi.'),
  ('cba9ff3e-e38f-40b7-b48d-13e030f8993a', '“O‘zingiz Yeng!” isyoni 🥣', 'O‘zi yeya olsa ham, qaysarlik bilan siz ovqatlantirishingizni talab qiladi, keyin esa qoshiqni itarib, yig‘laydi. Bu qarama-qarshiliklar davri. Uni ovqatlantirishga urinmang, och qolishidan ham qo‘rqmang. Likopchani oldiga qo‘yib, “Och qolsang, yersan”, deb stoldan turing. O‘zi yeydi.'),
  ('0da92da6-227b-4bc4-8733-939d83f883ad', 'Yarim tun falsafasi 🦉', 'Endigina yotoqqa kirganingizda, Onajon, nega bulutlar pastga tushmaydi? kabi chuqur savollar beradimi? Uning maqsadi ilm o‘rganish emas, siz bilan gaplashib, uxlash vaqtini kechiktirishdir. Chunki ular tepada uxlaydi kabi qisqa, to‘qima javob bering va Aqlli ertaklardagi mayin kuyni yoqib, qat’iyat bilan uyqu sukunatini ta’minlang.'),
  ('1b4bdd7d-042a-4be6-a59f-82892d67ff8d', 'Do‘kondagi o‘sha shok savol 😳', 'Kassa navbatida turganingizda baland ovozda Bu xolaning sochi nega bunaqa? deb so‘radimi? Uni uyaltirib, jim bo‘lishga majburlamang, diqqatini darhol ilovadagi Xaridlar ro‘yxatiga qarating: Qani, ko‘raylik-chi, olma olganmidik? deb vaziyatdan diplomatik tarzda chiqib keting.'),
  ('62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e', 'U ko‘ylak nega yuvildi?! 👕', 'Sevimli, rangi allaqachon o‘chib ketgan o‘sha ko‘ylakni kir yuvish mashinasiga solganingiz uchun uyda motam e’lon qilindimi? Bolalarning buyumlarga bog‘lanib qolishi ba’zan mantiq chegarasidan chiqadi. Bahslashmang, darhol Chaqaloq fotosessiyasini oching, uning shu jahldor holatini suratga olib, vaziyatni kulgiga aylantiring. Qani, ekranda qanchalik jahldor ko‘rinayotganingizni ko‘raylik degan hiyla uning diqqatini bir zumda chalg‘itadi, sinab ko‘ring!'),
  ('4e937fd6-67f9-496a-b0c5-be8bf0840c6d', 'Chiroqlarni o‘chiring, soyalar teatri boshlansin 🐰', 'Qorong‘ilikdan qo‘rqib, yo‘lakka yolg‘iz chiqishni istamayaptimi? Xona chiroqlarini butunlay o‘chiring va kichik fonarni yoqing. Devorda qo‘llaringiz bilan kuchuk, qush soyalarini yasab, qorong‘ilikni uning uchun qo‘rqinchli joydan o‘yin maydonchasiga aylantiring. Uning uxlab qolishi bir zumlik masala bo‘ladi.'),
  ('6d8c96e4-6f09-4805-a4a8-4acf034ab6c9', 'Sizga ham offline bo‘lish kerak ☕', 'Xonada o‘yinchoqlari bilan shunchalik berilib o‘ynayaptiki, uyga birdan sukunat cho‘kdimi? Jonim, bu lahzani uy supurish yoki kiyimlarni taxlashga sarflamang! Borib divanga yoting, Kayfiyat kundaligiga shunchaki 5 daqiqalik osoyishtalik deb yozing va qahvangizni issiqligida iching. Siz ham bu xonadonning bir a’zosisiz.'),
  ('f30558ce-2e74-4368-ad59-ff72d43fefc7', 'Men to‘kmadim, ayiqcham qildi! 🧸', 'Suvni ataylab yerga to‘kib, aybni o‘yinchog‘iga ag‘daryaptimi? U yolg‘on gapirmayapti, shunchaki 3.5 yoshga xos himoya mexanizmini kashf etgan. O‘jarlik qilmang, Unda kel, ayiqchangga qanday tozalashni o‘rgatamiz deng va sochiqni uning qo‘liga bering. U ham mas’uliyatni o‘rganadi, ham o‘ziga bo‘lgan ishonchi zarar ko‘rmaydi.'),
  ('1633765a-e691-4a02-b657-169e03223f3f', 'Onaning oziq-ovqat zaxirasi 🥗', 'Uni to‘ydirish uchun turli xil taomlar o‘ylab topdingiz, ammo o‘zingiz yana oyoq ustida quruq narsalar yeb qo‘ydingizmi? Sog‘lom retseptlardan nafaqat bolalar, balki onalar uchun ham quvvat beradigan, 10 daqiqada tayyorlanadigan, temir va kalsiyga boy tushlikni tanlab, o‘zingizga g‘amxo‘rlik qiling.'),
  ('2d30d5d5-9abc-4c5e-847a-462fa693fbda', 'O‘yinchog‘im kasal o‘yini 🩺', 'U o‘yinchoq stetoskopini olib, ayiqchasini jiddiy tekshiradi va unga yara plastirini yopishtiradi. Ramziy o‘yinlar orqali u mehr-shafqat va g‘amxo‘rlik tuyg‘ularini anglaydi. Siz ham bemor roliga kirib, shifoxonadagidek yoting va u sizni 5 daqiqa davomida indamay tekshirishiga imkon bering.'),
  ('37ed4aaf-5c8b-418c-8274-802f79f0bf41', 'Aqlli ertaklar bilan oson uyqu 🪄', 'Klassik kitoblarni yodlab bo‘lgansiz. Aqlli ertaklarni oching, bosh qahramon sifatida bolangizni, zabt etiladigan joy sifatida esa uning xonasini tanlab, noodatiy va hech qanday kuch talab qilmaydigan uyqu seansini yarating.'),
  ('72e4a373-da8e-4cf7-b36b-25d3d3a13b6e', 'Shunchaki quchoqlang 🫂', 'Hech qanday o‘yin, kitob yoki ertak kerak emas. Bu oqshom uni shunchaki bag‘ringizga bosing, uning yoqimli hidini to‘yib-to‘yib ichingizga torting va qorong‘ida u siz uchun qanchalik qadrli ekanini, uni qanchalik sevishingizni pichirlab ayting.'),
  ('8d0e8d79-2ed2-4d47-9d71-055f26b53574', 'Jonsiz buyumlar bilan suhbat 🗣️', 'U bog‘dagi toshga yoki uydagi stulga o‘ta jiddiy ohangda nimalarnidir gapiradi, ularni koyiydi. Ramziy o‘yinlar orqali u dunyoni anglaydi.'),
  ('b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9', 'Ertalabki bekinmachoq 🙈', 'Siz ishga yoki bog‘chaga kechikyapsiz, u esa parda ortiga yashirinib: Meni top! deydi. Asabingiz taranglashsa ham, baqirish jarayonni yanada cho‘zadi. Qani, mening shirin bolam qayerda ekan? deb o‘yinga 2 daqiqaga qo‘shiling, uni topib, yashiringan joyidan olib chiqing.'),
  ('5672be3d-87ec-469d-a4b7-fca0b00ec9ac', 'Parkdagi siyosat 🤝', 'Sirpanchiqda boshqa bolani itarib, o‘zi uchmoqchimi? Bo‘lishish hali uning uchun to‘liq shakllanmagan, murakkab tushuncha. Uni uyaltirish yoki jazolash o‘rniga, «Hozir uning navbati», deb shunchaki tartib-qoidani eslatib qo‘ying.'),
  ('7b9a42e6-44aa-4528-9036-fbb93f662348', 'Quyosh nega menga qarayapti?! ☀️', 'Ertalab ko‘zini ochishi bilan «Quyosh nega ko‘zimga tik qarayapti?» deb ho‘ngrab yig‘layaptimi? Mantiq izlashga yoki tabiat hodisalarini tushuntirishga urinmang — u shunchaki dunyoni boshqara olmayotganidan jahli chiqyapti. Pardani yopib, «Quyoshni sen uchun yashirib qo‘ydim», deng va bu bema’ni muammoni bir zumda hal qiling.'),
  ('bf33243a-24ca-4b24-a11a-d703c038cdcf', 'Mashinam hali uxlamadi! 🚗', 'Yotmaslik uchun «Mashinamning uyqusi kelmayapti», deb turib olyaptimi? Bolalar ko‘pincha o‘zlarining uxlamasligi va qarshiligini o‘yinchoqlariga yuklaydi. Bahslashmang, Aqlli ertaklarni yoqing va mashinalar haqida ertak yarating. Mashina uxlab qolishi bilan u ham beixtiyor ko‘zlarini yumadi. Sinab ko‘ring!'),
  ('5c063277-1aff-4166-9dbe-d6ab5866cdbd', 'Nonning chetlari kesilsin! 🍞', 'Tostning faqat yumshoq joyini yeb, chetlarini qat’iyan rad etyaptimi? Bu yoshning o‘ziga xos vizual didi bor. Nonlarni yoqimli hayvonlar shaklida kesishni o‘rganing. Bunday dizayn bu tortishuvga bir zumda barham beradi.'),
  ('a42141c6-7a93-4719-be36-e495b333ffee', 'Jim qarashib o‘tirish zavqi 🥂', 'Bola uxladi, uy yig‘ishtirildi. Turmush o‘rtog‘ingiz bilan divanda yonma-yon o‘tiring, hatto televizorni ham yoqmang. Shunchaki bir-biringizga «Bugun ham omon qoldik», degan nigoh bilan qarang. Ishoning, charchoq bilan kechadigan ota-onalikning eng romantik va samimiy lahzasi aynan shu.'),
  ('fbd48b54-2407-4752-a5b5-4e335233ace4', 'Ko‘rinmas dog‘ fojiasi 👕', 'Ko‘ylagidan faqat mikroskopda ko‘rish mumkin bo‘lgan dog‘ni topib, uni kiyishdan bosh tortdimi? O‘sha dog‘ni nam salfetka bilan go‘yoki artib tashlang va «Sehr bilan yo‘q qildim», deng. Bola onasining sehriga doim ishonadi — sinab ko‘ring.'),
  ('081fe93d-51fc-4e73-b956-ea2d06dcec72', 'Suvni boshqa stakanda bering! 🥤', 'Suvni sariq stakanda berganingiz uchun uyda qiyomat qo‘pdimi? Buni ko‘nglingizga olmang, u shunchaki chegaralarini sinab ko‘ryapti. Suvni darhol u xohlagan stakanga quyib bering va xonada tinchlik o‘rnatib, kuchingizni kunning qolgan qismiga asrang.'),
  ('12e39cd9-ad30-497d-8902-0c8e0d1a5c56', 'Parkdan ketish uchun musobaqa usuli 🌳', 'Parkdan qaytish vaqti keldi-yu, yig‘i boshlandimi? Uni sudrab olib ketish yordam bermaydi. «Qani, mashinagacha kim pingvindek tezroq yurib borarkin?» deb, diqqatini darhol kulgili musobaqaga qarating. U albatta g‘olib bo‘lishni xohlaydi.'),
  ('ec5e51b0-e017-4226-9363-9dfff1dce391', 'Dadasi bilan divanda kurash 🤼‍♂️', 'Uxlashga yotmaslik uchun qochib, yashirinib oldimi? Navbatni dadasiga bering. Divanda hazillashib kurashishsin. Bu shovqinli va terlatadigan o‘yin bolaning qolgan qaysar energiyasini ham chiqarib, uning osongina uyquga ketishiga yordam beradi.'),
  ('01fb525b-af8a-41d4-8fd1-724d4fd01667', 'Musiqali gipnoz ta’siri 🎶', 'Kechga yaqin hech bir sababsiz boshlanadigan injiqliklarni mayin klassik musiqa bilan to‘xtatib ko‘ring. Televizorni o‘chiring. Ko‘pincha bu oddiy usul past chastotali shovqinni bosadi va xonaga go‘yo mo‘jizaviy sokinlik olib kiradi.'),
  ('d8b40eb7-3665-4514-839c-874f3d30ec40', 'O‘zi to‘qib topgan iboralar 🗣️', '«Osmon yig‘ladi», «Mashina xafa bo‘ldi» kabi g‘aroyib jumlalar tuzyaptimi? Uning so‘z boyligi shiddat bilan o‘smoqda va u so‘zlar bilan o‘ynayapti. Rivojlanish kuzatuvini ochib, uning bu yoqimli, she’riy falsafasini saqlab qo‘ying — yillar o‘tib, uni o‘qib rosa kulasiz.'),
  ('f96cc98d-a4e0-44e3-9617-a284b205c20e', 'Ekran uchun vijdon azobisiz tanaffus 📺', 'Bugun ishlaringiz ko‘p bo‘lgani uchun u televizor qarshisida uzoq qolib ketdimi? Vijdon azobi qiynayaptimi? Har kuningiz mukammal bo‘lishi shart emas. Ba’zida ekranlar bizni katta tartibsizliklardan qutqaradigan eng bezarar enagadir. O‘zingizni ayblamang.'),
  ('246edaf3-5d30-44d2-bda4-13ec5fbf5f36', 'Qorong‘i xonada soyalar teatri 🐰', 'Qorong‘ilikdan qo‘rqib, yotishni istamayaptimi? Xonadagi chiroqlarni butunlay o‘chirib, kichik fonarni yoqing. Devorda qo‘llaringiz bilan kuchuk va qush soyalarini yarating. Qo‘rqinchli qorong‘ilikni uning uchun o‘yin maydonchasiga aylantiring — uxlab qolishi bir zumlik ish bo‘ladi.'),
  ('d3b4180b-5723-4f72-a6c8-b4229f2e876c', 'Dinozavrlar bo‘tqa yemaydi! 🦖', 'Ertalab hech bir savolga javob bermay, faqat bo‘kiryaptimi? Demak, u bugun T-Rex. T-Rexlar nonushta qiladimi? deb, u o‘ylab topgan shu obrazga moslashing va stolga ko‘z yoshlarisiz o‘tirishiga yordam bering.'),
  ('e089800c-6f76-4909-bafd-021551368a5f', 'Bugun holdan toyganman 🛑', 'Hamma narsa ustma-ust kelib, ovozingizni balandlatdingiz. Endi esa vijdon azobini his qilyapsiz. Siz robot emassiz. Kayfiyat kundaligini ochib, Bugun rostdan ham charchadim deb yozing. O‘zingizni soxta tabassum qilishga majburlashdan ko‘ra, bu e’tirof sizga ko‘proq yordam beradi.'),
  ('a8aeb934-2767-4365-a584-e2b99fc16215', 'Siz kimsiz? o‘yini 🎭', 'Ertalab sizga begonadek qarab, Sen kimsan? Onam qani? dedimi? Bu yangi rolli o‘yin. Men qo‘shni xolaman, onang hozir keladi, deng. Mayli, ertalab xona kulgidan larzaga kelsin — bu qaysarlik bilan olishishdan ko‘ra ancha kam kuch talab qiladi.'),
  ('cf7b3532-560e-4c59-af5f-4a64a8510605', 'Ertak o‘qimay uxlatish 🪄', 'Bugun kechqurun ertak o‘qishga holingiz yo‘qmi? Aqlli ertaklarni yoqing. Fon sifatida faqat shivirlayotgan o‘rmon va shamol tovushlarini qo‘ying. Qorong‘ilikda u bilan birga tabiat tovushlarini tinglab, shovqindan dam oling. Ko‘zlaringizdagi charchoq bir zumda yo‘qoladi.'),
  ('f8301d61-e90d-4d1c-b4e2-7f1feb3be70d', 'Kir yuvish mashinasida unutilgan xazina 🍝', 'Shimini yuvayotganda cho‘ntagidan qurib qolgan makaron yoki tosh chiqdimi? Bu ochko‘zlik emas, bolalarcha kashfiyotchilik. Jiddiy qiyofada uni axlatga tashlang, ammo ich-ichingizdan zaxira to‘plovchi bu bolakayga jilmaying. Rivojlanish kuzatuvchisida buni kulgili lahza sifatida qayd eting.'),
  ('3f11dc71-3a89-4499-8bac-19038f6fdeb4', 'G‘alati qo‘rquvlarning boshlanishi 🤖', 'Birdaniga vannadagi suv oqib ketadigan teshikdan qo‘rqishni boshladimi? Internetdan kasallik izlamang. Anacan AI’dan so‘rang va bu shu yoshdagi tasavvur sabab paydo bo‘ladigan mutlaqo tabiiy va o‘tkinchi fobiya ekanini bilib, vahimadan xalos bo‘ling.'),
  ('51e9982e-8a0e-4e2c-9ee7-749ec67f6283', 'O‘zim yeyman! 🥣', 'O‘zi yeya olsa ham, uni siz ovqatlantirishingizni qaysarlik bilan talab qiladi, qoshiqni uzatsangiz esa itarib, yig‘laydi. O‘zi ham nima xohlayotganini bilmaydi. Tarelkani oldiga qo‘yib, «Och qolsang, yersan», deng va stol yonidan turing. Och qolsa, o‘zi yeydi.'),
  ('cc8c59da-7b2e-4da4-87ec-e11a59ea5011', 'O‘zingizga ham biroz vaqt ajrating 💆‍♂️', 'Bola uxlagach, turmush o‘rtog‘ingizdan yelkangizni 10 daqiqa uqalab qo‘yishini so‘rang. Kun bo‘yi tinmay yugur-yugurdan bo‘yningiz qotib qolgan. Siz shunchaki bir uyda yashaydigan ota-ona emassiz, balki bir-biringizning eng yaqin ruhiy tayanchisiz.'),
  ('68be8da2-a2bd-442f-bb8b-f854ddbaa84b', 'Instagram onalari va haqiqat 📱', 'Instagramni ochishingiz bilan boshqalarning mukammal farzandlarini ko‘rib, tushkunlikka tushmang! Ilovani yoping-da, Anacan hamjamiyatiga kiring. Boshqalarning uyi ham sizniki kabi ag‘dar-to‘ntar, bolalari esa shovqinchi ekanini ko‘rib: «Men mutlaqo normalman!» deng.'),
  ('9d186c69-6a80-405e-9b2f-01d72d720233', 'Qo‘ng‘iroq chalinganda uxlaymiz ⏱️', 'Uxlash vaqti tobora cho‘zilib ketmoqda. Suv, hojatxona, devor bilan xayrlashish... Telefon taymerini sozlang. «Qo‘ng‘iroq ovozi eshitilganda hamma chiroqlarni o‘chiradi», degan qoida kiriting. Bu ovozni eshitganda hech qanday e’tirozsiz yotog‘iga kiradi.'),
  ('e4247830-a48b-4a17-9555-7ca391f03a7d', 'To‘rt oyoqlab yurgan bola 🐾', 'Bugun ertalab u yotoqdan bola kabi emas, kuchukdek emaklab chiqdimi? Nasihat qilib, jahlingizni chiqarmang. «Barakalla, mening aqlli kuchukcham», deb nonushtasini bering. Rolli o‘yinlarga qo‘shilish qaysarlik qilishdan ko‘ra ancha kam kuch talab qiladi.'),
  ('3b221a5a-9106-4d1d-8e8e-3de653008273', 'Tanam o‘zimga tegishli emas 🔋', 'Kun bo‘yi oyog‘ingizga yopishib olib, quchoqqa olishni so‘rayaptimi? Siz jismonan holdan toyibsiz. Siz teginishlardan charchagansiz. Uni o‘yinchoqlari bilan xonada qoldirib, 5 daqiqaga hammomga kirib oling va eshikni yoping. Shunchaki yolg‘iz qolish hissidan bahramand bo‘ling.'),
  ('633ad245-30eb-4956-9f39-7177c312745a', 'Yarim tunda to‘satdan qichqiriq 😭', 'U kechasi ko‘zlari yumuq holda yig‘lab uyg‘ondimi va sizni eshitmayaptimi? Yig‘isiga e’tibor bering: bu tungi vahima. Uni uyg‘otishga urinmang, shunchaki yonida turing, qo‘lidan ushlab, silab qo‘ying. U o‘z-o‘zidan tinchlanib, yana chuqur uyquga ketadi.'),
  ('8febb55a-81bd-4c4c-969e-a2b64ee79f90', 'Oshxonadagi kichik yordamchi falokati 🧑‍🍳', 'Siz xamir yoyayotganingizda u stulini olib kelib, unni albatta o‘zi sepmoqchi bo‘ldimi? Ruxsat bermasangiz, yig‘laydi. Unga kichik plastik idish va ozgina un bering. Oshxona un bo‘lib ketadi, ammo uning jiddiy oshpaz qiyofasi keyingi tozalashga arziydi.'),
  ('026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b', 'Eshikni men ochaman! 🚪', 'Uydan chiqayotganda eshikni siz ochganingiz uchun yig‘lab, uni qayta yopdirib, keyin o‘zi ochdimi? Bu yoshda vaziyatni nazorat qilish hissi eng katta psixologik ehtiyojdir. Mayli, bunga 1 daqiqa sarflang, ammo ko‘chada yuz berishi mumkin bo‘lgan 30 daqiqalik injiqlikning oldini oling.'),
  ('9e3821dd-5beb-4da8-ba9b-4369b4836b0a', 'Do‘kon o‘rtasida qotib qolish 🛒', 'Do‘kon o‘rtasida to‘xtab, «Men nima sotib olish uchun kelgandim?» deb o‘ylanib qoldingizmi? Onalik miyasi haqiqatan ham juda band. Ilovadagi Xaridlar ro‘yxatini ochib, shu raqamli xotiraga tayanish sizni bu tartibsizlikdan har doim qutqaradi.'),
  ('c3a12f76-8197-4f4b-b339-db8bd083cf0a', 'Vannadagi suv toshqini 🌊', 'Yuvinish shunchaki bahona, aslida u vannada okean yaratib, to‘lqinlar bilan o‘ynayaptimi? Mayli, o‘ynasin. Suvning shovqini va sachrashi uning ichidagi tuganmas, jo‘shqin energiyani yuvib ketadi. Kechqurun hech qanday qarshiliksiz yotog‘iga yotadi.'),
  ('051e4221-4f19-4e4b-a097-d797006e0813', 'Mukammal sukunat lahzasi 🛋️', 'Pazllari bilan shu qadar berilib o‘ynayaptiki, uy birdan jimib qoldimi? Shubhalanmang, darhol o‘zingizga qahva quyib oling. O‘sha noyob, oltinga teng daqiqalarni uy yig‘ishtirish yoki kir yuvishga emas, dam olishga va shiftga termulib yotishga sarflang. Siz robot emassiz.'),
  ('87efef38-8bd8-470c-82a9-956ee26f1fa2', 'Ko‘ylakning yorlig‘i botyapti! 🏷️', 'Orqasidagi mitti yorliq unga ignadek botayotgani uchun ko‘ylakni kiymaydimi? Bu yoshdagi sensor sezgirlik odamni aqldan ozdiradi. Hech tortishib o‘tirmang, qaychini oling-da, yorliqni tagidan kesib tashlab, bu kichik inqirozni bir zumda hal qiling.'),
  ('d321475d-a2ef-4c95-8a95-ccdb6522c470', 'Pichirlab uxlatish 🤫', 'To‘shagidan turib, xonada yuguryapti, uxlashni istamayaptimi? Baqirmang. Birdan juda sekin, pichirlab gapira boshlang. Sizni tushunish uchun diqqatini shu qadar jamlashiga to‘g‘ri keladiki, miyasi charchab, avtomatik ravishda uyqu rejimiga o‘tadi. Sinab ko‘ring!'),
  ('7e80987d-061d-4fcd-8171-45d84324b66e', '“O‘yinchog‘im to‘kdi!” degan yolg‘on 🤷‍♂️', 'Suvni ataylab yerga to‘kdi-yu, keyin mashinasini barmog‘i bilan ko‘rsatib, “U itardi”, dedimi? Bu yolg‘on gapirish emas, himoyalanish mexanizmi. “Kel, bu mashinaga ham qanday tozalashni o‘rgatamiz”, deb uning miyasini ustalik bilan chalg‘iting.'),
  ('a3c5807d-b2c4-4369-a70a-3e8219c1c3ef', 'Ekrandagi sukunat raqami 🤫', 'Nihoyat uxlab qoldi. Uy shu qadar jimib qoldiki, quloqlaringiz shang‘illayaptimi? Ilovadagi ovoz o‘lchagichni oching. O‘sha 0 desibel yozuviga qarash charchagan, shovqindan karaxt bo‘lgan miyangiz uchun dunyodagi eng yaxshi vizual massaj bo‘ladi.'),
  ('c034d9ff-ba06-4346-b3af-4ee27df0fc64', 'Ko‘rinmas sabzavotlar operatsiyasi 🥦', 'Sho‘rva ichidagi bittagina sabzini topib olib, “Buni yemayman”, dedimi? Tanish holat! Sabzavotlarni pyure qilib, souslarga qo‘shing-chi, endi qanday topar ekan! Uning oshpazlik topqirligini yengib o‘ting.'),
  ('1d8c6250-cd7d-4c49-8588-80172d7ce7fd', 'Ob-havoni derazadan turib taxmin qilmang ⛅', 'Tashqarida quyosh charaqlayapti, ammo shamol ham esyaptimi? Ob-havo va kiyim vositasi bolani qat-qat kiyintirishni tavsiya qilsa, unga ishoning. Eshik oldida ikkilanib, nolib turish o‘rniga mos kiyimlarni tanlab, bemalol tashqariga chiqing.'),
  ('78e7980c-5a72-49e5-bf40-4486d421427a', 'O‘z ovqatini sizga bermaydi 🍳', 'O‘z likopchasidagi ovqatni sizga bermaydi-yu, ammo kelib, sizning likopchangizdan yeyishni qat’iy talab qiladimi? Bolalar ota-onasining tanloviga doimo to‘liq ishonadi. Qarshilik qilmang, luqmani mehr bilan unga uzating va bu kulgili xudbinlikka shunchaki jilmayib qo‘ying.'),
  ('bdc2de1f-725b-4742-942a-3e8bf91a38f3', 'Mening ertagim — mening qoidam 📖', 'Ertak o‘qiyotganda biror so‘zni xato aytdingiz va u darhol sizni tuzatdimi? Demak, yodlab olibdi! Kitobni yoping-da, Unda bugun kechqurun sen menga o‘qib ber, deng. Uning tasavvur olami ishlasin, siz esa shunchaki yonboshlab, uning o‘sha yoqimli ovozini tinglang.'),
  ('02c28ca2-9054-4fe0-ba4f-902da3aebfad', 'Minora qurib, keyin uni buzish 🧱', 'Kubiklardan katta mehnat bilan minora qurib, keyin esa qah-qah otib, uni bir urishda buzib tashlaydimi? Siz uning mehnatiga achinsangiz ham, u fizika va sabab-oqibat bog‘liqligini o‘rganmoqda. Bu buzilishlar uning miyasida yangi aloqalar paydo bo‘layotganidan darak, jahlingiz chiqmasin.'),
  ('380dd8d0-d6f8-457c-b025-9b12f69938f2', 'Mening tushligim qani? 🥗', 'Bolangizga sabzavotli maxsus taom tayyorlab, o‘zingiz esa non kemirib o‘tiribsizmi? To‘xtang! Ovqatlanish rejasidagi onalar uchun mo‘ljallangan, oson va 5 daqiqada tayyor bo‘ladigan salatni qiling. Nihoyat, bu uyning asosiy dvigateli — o‘zingizni quvvatlantirishni unutmang. Siz muhimsiz.'),
  ('44db284c-e980-4095-8376-f1dcb5c24c8a', 'Chiroqlarni o‘chiring, uyqu kelsin 🌙', 'Uxlashiga 1 soat qolganda xonadagi barcha yorqin chiroqlar va televizorni o‘chiring. Xona qorong‘ilashgani sari u o‘z-o‘zidan esnay boshlaydi. Shu tariqa melatoninni (uyqu gormonini) sezdirmay va tabiiy yo‘l bilan ishga tushirib, o‘z ishingizni osonlashtiring.'),
  ('006ab58d-d1e7-4e1c-a78e-139ada266050', 'Teskari kiyilgan faxr 👕', 'Ko‘ylagini teskari kiyib olib, hech ham to‘g‘rilashga qo‘ymayaptimi? O‘zi biladi! Uning «men uddaladim» degan ko‘zlaridagi o‘ziga ishonch ko‘ylakni to‘g‘ri kiyishdan muhimroq. Mayli, kun bo‘yi shu holida faxrlanib yursin — bu uning erkin tanlovi.'),
  ('a6797020-6e00-4e51-85e1-ce4c1dc47785', 'Gapingiz o‘tmay qolganda dadasi keladi 🤡', 'Endi gaplaringizga e’tibor bermay, o‘jarlik qilyaptimi? Dadasi kelib, g‘alati hayvon tovushlarini chiqarib, kulgili yuz ifodalarini ko‘rsatishi bilan darrov kula boshladimi? Ba’zan erkaklarning ana shunday mantiqsiz hazillari chindan ham uydagi vaziyatni qutqaradi. Siz esa chetdan tomosha qiling.'),
  ('bf79338f-3f38-4811-b226-50574547225b', 'G‘alati savollarga AI javobi 🤖', 'Onajon, soyam kechasi qayerga ketadi? degan savolni eshitib, nima deyishni bilmay qoldingizmi? Hech narsa to‘qimang. Anacan AI’ni oching va shu yoshga mos, ertaknamo, yoqimli ilmiy javobni olib, unga o‘qib bering. O‘zingizni buyuk faylasufdek his qilasiz.'),
  ('50a90b1b-61b0-4de1-8146-038e23b46eb9', 'Ichimdagi g‘azabni yozish 📝', 'Hech kim uyda qanchalik charchayotganingizni ko‘rmayaptimi va bu sizni portlash darajasiga olib kelyaptimi? Kayfiyat kundaligini oching. Bugun sizni nima g‘azablantirgan bo‘lsa, hammasini o‘sha yerga yozing. Soxta tabassum qilishdan ko‘ra, his-tuyg‘ularingizni qabul qilib, yozib chiqish sizga ko‘proq yordam beradi.'),
  ('86283ea0-922f-4b91-8fed-55bf6231330d', 'Jonsiz buyumlar bilan uzoq suhbatlar 🗣️', 'Bog‘dagi toshga yoki uydagi stulga jiddiy ohangda nimalarnidir gapiryaptimi? U o‘yin orqali qoidalarni va dunyoni anglab bormoqda.'),
  ('b3273f0d-ec07-48f9-82e7-89e57daaf623', 'Bu oqshom shunchaki quchoqlashaylik 🫂', 'Hech qanday o‘yin yoki ovozli kitob kerak emas. Bu oqshom uni shunchaki bag‘ringizga bosing, bolalarga xos beg‘ubor hidini chuqur-chuqur ichingizga torting va qorong‘ida unga siz uchun qanchalik qadrli ekanini pichirlab ayting. Shu ikkingizga ham yetadi.'),
  ('113aa528-0657-4840-905d-63eec2aa048b', 'Men bilaman, sizga ham o‘rgatay ☝️', 'Siz biladigan narsani jiddiy va aqlli qiyofada sizga tushuntiradimi? U o‘z aqlini sinab ko‘ryapti. Kulib yubormaslik uchun labingizni tishlang, uni juda jiddiy tinglab: «Rostdanmi? Katta rahmat», deng.'),
  ('70129896-2f43-4370-bbff-f84bbbb58845', 'Dadasi ertakni noto‘g‘ri aytib bersin 📖', 'Bugun kechqurun ertakni siz o‘qimang. Ertak kitobini dadasiga bering. Dadasi voqeani ataylab teskarisiga, kulgili va bema’ni tarzda aytib bersin. Farzandingiz uni tuzatishdan qanday zavqlanib, qah-qah otib kulishini chetdan maroq bilan kuzating.'),
  ('e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a', 'Yig‘ishtirishni qo‘ying, o‘yinchoqlar qolaversin 🎨', 'U xona o‘rtasida bo‘laklardan katta bir asar yaratib, uni yig‘ishtirishingizga yo‘l qo‘ymayaptimi? Mukammal tozalik istagini bir chetga suring. U yaratgan tartibsizlikka tegmang, yig‘ishtirish ertagacha kutishi mumkin. Uy muzey emas.'),
  ('4501063e-24e5-4f32-a723-396adeab0d2a', 'Multfilmni sizga aytib beryapti 📺', 'Ko‘rgan multfilmini sizga butunlay o‘zgacha mantiq bilan aytib, kim qayerga ketganini jiddiy tushuntiryaptimi? Uni hammasiga ishonayotgandek diqqat bilan tinglang. O‘zini dunyodagi eng aqlli va kuchli insondek his qilsin.'),
  ('68a8ce66-c86f-4596-b8d3-b0d44f55a37d', 'Do‘kondagi o‘sha dahshatli «xohlayman» 🛒', 'Kassaning shundoqqina oldida shokolad deb baqiryaptimi? Orqadagilarning nigohiga qaramay, taslim bo‘lmang. Xaridlar ro‘yxatini ochib: «Bu yerda yo‘q, kassa buni o‘tkazmaydi», deng. Tashqi bir vakolatli sabab ularga har doim ishonchliroq tuyuladi.'),
  ('7a348b09-00b7-46e1-8565-808daca1314c', 'Barcha charchoqni suv bilan yuvish 🛀', 'Ba’zan hech narsa yordam bermaydi, u shunchaki hamma narsaga yig‘layveradi. Uni iliq suv to‘ldirilgan vannaga tushiring. Suvning o‘sha sirli, taranglikni ketkazuvchi kuchi butun xonaga va uning asab tizimiga bir zumda chuqur xotirjamlik olib keladi. Sinab ko‘ring va bunga o‘zingiz amin bo‘ling.'),
  ('553ac831-9d91-4727-b2a6-83bd86e98633', 'Yostiq tekis emas! 🛏️', 'Yostiqni millimetrigacha tekislab berishingizni talab qilib yig‘layaptimi? Bu — mukammallikka intilish. Qoidalariga amal qiling, yostiqni xuddi chizg‘ich bilan o‘lchangandek tekislang va chiroqlarni qat’iylik bilan o‘chiring.'),
  ('895f4c44-bb71-4d9f-917c-8dc75b779cc8', 'Uydagi sukunat vahimasi 🚪', 'Uy birdan juda jim bo‘lib qoldimi? Uni izlab, eshik ortida xayol surib o‘tirganini topasiz. Qo‘rqmang, u shovqindan chetlanib, o‘zini qayta tiklayapti — unga buning uchun vaqt bering.'),
  ('fceb9d37-669a-42ac-ae17-36b46f1fa546', 'Kreker singani uchun qayg‘u 🍪', 'Kreker ikkiga bo‘lingani uchun qiyomat qoyim bo‘lyaptimi? Uni qayta yopishtira olmaysiz. «Qara, endi ikkita bo‘ldi: biri menga, biri senga», deb matematika va bo‘lishishni ishga soling.'),
  ('7871e777-44f4-425d-a10e-dda0547ccfc1', 'Muzqaymoq tushda qolib ketdi 🍦', 'Tushida muzqaymoq yeyayotgan ekan, uyg‘otganingiz uchun sizdan jahli chiqdimi? Tush bilan haqiqat bir-biriga aralashib ketgan. Uning jahldor chehrasini quchoqlab, kuling — haqiqatga qaytishi 2 daqiqa vaqt oladi.'),
  ('94d22bcb-5e09-49a0-bea6-432b56a92308', 'Suv idishining rangi 🚰', 'Kechasi suv so‘rayapti, ammo qizil stakanda emasmi? Yarim tunda mantiq izlab, unga nasihat qilmang. Darhol stakanni almashtiring, kuchingizni tong va tinchlik uchun asrang.'),
  ('c160b0b4-c39a-4e5d-bbc5-111f29e33385', '«Oyoq kiyimim ichida tosh bor» vahimasi 👟', 'Oyoq kiyimini 10 marta yechdirib tekshirtiryapti, lekin tosh yo‘q! Bu holat sizga tanishmi? Sezdirmay qo‘lingizga bitta qora donacha oling-da, «Qara, topdim, qutuldik», deb sayrni davom ettiring.'),
  ('63fa1eaa-e73f-4258-a342-669de7f7f892', 'Polga to‘kilgan tortishish kuchi 🍝', 'Ovqatni ataylab yerga tashlab, ortidan qarayaptimi? Baqirmang, aslida u sizni asabiylashtirmoqchi emas, tortishish kuchini sinab ko‘rmoqchi. Likopchasini indamay oldidan olib qo‘ying, saboq berishni keyinga qoldirasiz.'),
  ('6e8cabf6-04bc-4e0f-a26d-cdeb494389a5', 'Meni Batman deb chaqir! 🦇', 'Ertalab uyg‘onib, o‘z ismini rad etdimi va uni boshqa ism bilan chaqirishingizni talab qilyaptimi? Moslashing! 5 daqiqa davomida «Marhamat, Batman, bo‘tqangizni yeng», deb xonadagi taranglikni kulgiga aylantiring.'),
  ('b81a0aff-ac53-43cf-bdca-b8bf4192300e', 'Pijama rezinkasi tashvishi 👖', 'Pijamasi siqayotganini aytib dod solyaptimi (aslida esa ustidan tushib ketyapti)? Sensor sezgirligi o‘zini ko‘rsatyapti. «Kutib tur, sehrli afsun aytaman, kengayadi», deng va pijamani tortayotgandek bo‘ling. U bunga ishonadi!'),
  ('070422be-d317-4a23-a559-6432c6ae63ed', 'Ko‘zimni yumsam, yo‘qolib qolaman 👀', 'Ko‘zini pirpiratmaslikka urinib, yoshlanguncha chidab turibdimi? Bola miyasi ba’zan tushuntirib bo‘lmaydigan qo‘rquvlarni o‘ylab topadi. «Qara, men ko‘zimni yumdim, hali ham shu yerdaman», deb bu bema’ni qo‘rquvni o‘yinga aylantiring.'),
  ('652ec194-fa0e-4ca8-ab49-626452c474ad', 'Menga tegmang, issiq bo‘ladi 🛑', 'Birdan sizni quchoqlashdan bosh tortdimi? Xafa bo‘lmang! U shaxsiy chegaralarini va tanasi faqat o‘ziga tegishli ekanini sinab ko‘ryapti. Bu mustaqillik belgisi, chetdan turib faxr bilan kuzating.'),
  ('c7f18643-0c26-48a6-bc85-4480566ce781', 'Kreslo ostidagi uyqu 🛋️', 'To‘shagida yotishdan bosh tortib, kreslo ostida g‘ujanak bo‘lib uxlab qoldimi? Uni u yerdan zo‘rlab chiqarib, uyg‘otmang. Boshqacha va himoyalangan joyda uxlash zavqini his qilsin, siz ham dam oling.'),
  ('1fe87964-746d-4cf2-a7f3-21730045a9ae', 'Bo‘tqa nega issiq? 🥣', 'Issiq bo‘lmasa yemaydi, endi esa issiq deb yig‘layaptimi? Chorasiz vaziyat! Ichiga ataylab rangli muz bo‘lagini soling — bir zumda qiziqib, tinchlanadi.'),
  ('8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93', 'Eshik ortida yig‘lash 🚪', 'Eshikni yopib, xonasida yolg‘iz yig‘layaptimi va sizni yoniga istamayaptimi? Uni majburan quchoqlashga urinmang. Ba’zan bolalar ham his-tuyg‘ularini yolg‘iz boshdan kechirishni xohlaydi, unga vaqt va imkon bering.'),
  ('f52f2ceb-159e-4eff-95c6-70eae6ed7217', 'Kitobdagi bo‘riga g‘azab 🐺', 'Kitobdagi bo‘ri rasmini mushtlab, unga tanbeh beryaptimi? Tasavvuri ajoyib! Haqiqatni buzmasdan, «Sen meni himoya qilding, juda jasursan», deb uning o‘ziga bo‘lgan ishonchini mustahkamlang.'),
  ('3c299611-0f24-405d-b774-857cf09c273e', 'Paypog‘imni siz kiydirmang! 🧦', 'Siz qilgan har bir ishni qat’iyan rad etyaptimi? Ajoyib! Kiyimni divanga qo‘yib, «Kim birinchi kiyinadi?» musobaqasini boshlang. Bir necha soniya ichida o‘zi kiyinib oladi.'),
  ('3d738e03-bc77-4be0-b44b-95ecf5e6cdb0', 'Stol ostidagi falsafa 🤔', 'Stol ostiga kirib olib, u yerdan sizga turli uydirmalarni gapiryaptimi? Mayli, mitti faylasuf o‘zining xayoliy dunyosida qolsin, siz esa bu vaqtdan foydalanib dam oling.'),
  ('b5d5bf11-5ce6-464a-892e-f00915b62103', 'Ko‘rpaning ovozi kelyapti 🛌', 'Ko‘rpaning shitirlashidan uxlay olmayotgan emish! G‘alati bahonalar avjida. Ustini yengil adyol bilan yoping — har bir muammoning chorasini topishingizni ko‘rib, taslim bo‘ladi.'),
  ('56bcf6ad-42a4-41b4-a775-ca5dbc61f766', 'Hammomda cho‘milishga qarshilik 🛀', 'Suvga tushishni istamayaptimi? Suvga turli rangdagi idishlar, hatto plastik oshxona buyumlarini tashlang. Shunda suv birdaniga qo‘rqinchli joydan ko‘ngilochar maskanga aylanadi.'),
  ('7f7bb774-fd67-46a5-93fe-c0a784ba9885', 'Men dadaman 👔', 'Ertalab dadasining katta oyoq kiyimlarini kiyib, ishga ketmoqchimi? Shoshilmang! Uni eshikgacha kuzatib qo‘ying, liftni ko‘rishi bilan kulib ortiga qaytadi.'),
  ('dbd02f3e-2d56-4baa-bc3c-93886c747027', '0 detsibel muhabbati 🤫', 'Nihoyat uxlab qoldi! Ilovadagi Ovoz o‘lchagichni oching va ekranning eng pastiga tushgan o‘sha mutlaq sokinlikni kuzating. Bu ko‘zga ko‘rinadigan sukunat charchagan miyangizni xuddi haqiqiy spa kabi massaj qiladi.'),
  ('1c6686dd-4008-4750-acaf-4155c3330cdd', 'Daraxt bargini tashlab yubordi 🍂', 'Yerdagi bargni ko‘rib, daraxtdan xafa bo‘lib uni koyiyaptimi? Uning tabiat bilan aloqasi shu qadar beg‘ubor va kulgiliki!'),
  ('806ceb98-90c4-4de6-a42b-37c72e8d03ae', 'Soyam mendan oldinda ketyapti 👻', 'Soyasi undan oldinda ketayotgani uchun ko‘chada yig‘layaptimi? Uni bag‘ringizga olib: «Qarang, soyalar qo‘shildi», deng. Fizikani tushuntirish o‘rniga, unga shunchaki xotirjamlik va ishonch bering.'),
  ('a0789257-db81-493e-9643-abeb1d193c59', 'Dadaning g‘alati hazillari 🤡', 'Uxlash vaqti dadasi uni kuldirib, uyqusini ochib yuborgani uchun jahlingiz chiqmasin. O‘sha quvnoq qahqahalar bolaning kun davomida to‘plangan stressini butunlay yo‘qotadi — mayli, biroz shovqin solishsin.'),
  ('0879e029-e767-44f9-917b-506cde86d1a1', 'Tuxum yig‘lamasin 🍳', 'Tuxumni chaqqaningizda unga rahmi kelib, yemayaptimi? Uning hamdardligi cheksiz. «U endi sening mushaklaringda yashaydi», degan yoqimli uydirmalar bilan vaziyatni qutqaring.'),
  ('7338df78-5f1a-4db5-ae07-ccfc779e153a', 'Pichirlash o‘yini 🤫', 'Uxlashni istamay, qochib yuribdimi? Ovozingizni birdan pasaytirib, juda sekin pichirlang. Sizni eshitish uchun diqqatini jamlaydi, miyasi charchab, 5 daqiqada uyquga taslim bo‘ladi.'),
  ('b9a9483f-7511-4f19-847b-4d0786991104', 'Tananing faryodi 🩸', 'Sababsiz asabiylik va charchoqqa taslim bo‘lmang. Hayz kuzatuvchisiga qarang — tanangiz sizga signal bermoqda. O‘zingizni ayblash o‘rniga, Sog‘lom retseptlardan magniyga boy yegulik tanlab, dam oling.'),
  ('1bf9463f-7457-4983-af0a-2e62627ce701', 'Faqat qizil yeguliklar 🍅', 'Bugun qizil rangga oshuftalik kuni! Faqat qizil narsalarni xohlayaptimi? Ovqatlanish rejasiga qarang, unga bugun qizil pomidor va qulupnay bering. Bu g‘aroyib istagi amalga oshsin, qarshilik qilmang.'),
  ('73d3b07e-eaa0-4423-b3b3-a6fb8656c01c', 'O‘yinchog‘im kasal bo‘lib qoldi 🩺', 'Ayiqchasini kasalxonaga yotqizdimi? Siz ham kasal bo‘ling! Divanga yoting, u sizni ham 10 daqiqa hazilakamiga ko‘rikdan o‘tkazsin, shu bahonada belingiz dam oladi.'),
  ('ea408c5e-c419-4258-9053-eba96cea541e', 'Men bilan uxlang, degan talab 🫂', 'Yonida uxlashingizni talab qilyaptimi? Bir kunga qoidalarni buzib, uning hidini to‘yib-to‘yib ichingizga yutgancha u bilan birga uxlang. Bu har ikkingiz uchun ham mehr terapiyasidir.'),
  ('7d8bddb7-9260-4872-8287-e9bfde4a91d7', 'Sun’iy intellekt, menga yordam ber 🤖', 'Farzandingizning tinimsiz falsafiy savollar berishi sizni charchatdimi? Anacan AI-ga yozing — u siz uchun 4 yoshli bolaga mos, ilmiy asoslangan, sabrli va yoqimli javoblarni darhol tayyorlab beradi.'),
  ('9135dd5f-177c-4a9d-97a6-1658abd0da9a', 'Ko‘zguda o‘zimni tanimadim 🪞', 'Ko‘zguda o‘ziga qarab, yuz ifodalarini o‘zgartirib, o‘zidan jahli chiqyaptimi? Uning o‘zlik hissi va his-tuyg‘ulari shakllanmoqda. Bu kichik tomoshasini chetdan jimgina kuzating.'),
  ('a579865a-399f-44c5-a9b0-e44cc032ce14', 'Ertakdagi qahramon — menman! 🪄', 'Aqlli ertaklarda qahramonning ismini farzandingizning ismiga almashtiring. Ertak davomida qahramon qanchalik tez va gapga kirib uxlasa, farzandingiz ham undan ruhlanib, xuddi shunday qiladi.'),
  ('2d3b049d-536d-441d-a015-9e7326fee52e', 'Do‘kon o‘rtasida qotib qolmang 🛒', 'Do‘konga kirib, nima olmoqchi ekaningizni unutdingizmi? Xaridlar ro‘yxatini elektron shaklda yuritmasangiz, o‘sha tartibsizlik ichida hammasini unutishingiz mumkin. Har doim raqamli xotirangizga ishoning.'),
  ('47345c36-90d7-4e89-b816-0332dc1932ef', 'Tunda yulduz sanash 🌟', 'Yotoqxona shiftiga qarab, xayoliy yulduzlarni sanayaptimi? Sanayversin. U o‘ylab topgan yulduzlar soni 10 taga yetguncha ko‘zi ilinib, chuqur uyquga ketadi.'),
  ('924a98d3-0af0-4add-81f0-0d94e1af83c6', 'Qo‘llarim oyoqqa aylandi 🤸‍♂️', 'Qo‘llarida yurishga urinib, yiqilyaptimi? Ijodiy harakat ko‘nikmalari jadal rivojlanmoqda! Uyning xavfsiz joyida unga kichik to‘siqlar yo‘lagini yarating, energiyasini chiqarib olsin.'),
  ('2d98107a-3331-4f7f-8930-8f762e325d02', 'Teskari ko‘ylak erkinligi 👕', 'Ko‘ylagini orqa-old qilib kiyib, faxr bilan yuribdimi? To‘g‘rilamang! Uning o‘ziga ishonchi shu qadar balandki, chetdan kuzatib, kelajakdagi bu erkin ruhli yetakchi bilan faxrlaning.'),
  ('c5aa519b-baae-498e-a13b-bdf83115f0c9', 'Sukutga to‘la nigohlar 🥂', 'Bola uxlab qoldi, siz va juftingiz divanda indamay bir-biringizga qarab o‘tiribsiz. Hech narsa demaysiz. Aslida bu sukunat «Buni ham uddaladik» deyishning eng romantik usulidir.'),
  ('eaade7fe-4846-47fa-9bc5-4c49360a0a4a', 'Shamol meni itardi 💨', 'Tashqarida esayotgan shamoldan jahli chiqib, uni urmoqchimi? Ob-havo va kiyim vositasini oldindan ko‘rganingizda, balki umuman tashqariga chiqmasdingiz. Endi esa bu tomoshadan kulib, uyga yuguring.'),
  ('77606aaa-e2aa-442d-992d-f4dce779d9e5', 'Poldagi san’at 🎨', 'Xonaning o‘rtasida quruq makaronlardan rasm yaratib, sizga faxr bilan qarayaptimi? Tozalashni hozircha unuting, unga jilmaying.'),
  ('92c59586-e756-4176-87f0-6ee0836bd1f7', 'Dadaning uyqu keltiruvchi ertagi 📖', 'Ovozingiz charchadimi, ertak o‘qishni istamayapsizmi? Navbatni dadasiga bering. Uning o‘zgacha, yo‘g‘on ovozi va o‘zi to‘qib qo‘shadigan kulgili tafsilotlari bolani tezroq uxlatadi.'),
  ('dc97d51e-f4af-4633-84e4-fbe0fbe9e15a', 'Sochim menga og‘riq beryapti 🪮', 'Sochini tarash o‘lim bilan barobarmi? Suv purkagich bilan biroz namlang, diqqatini esa ko‘zgu qarshisida qilayotgan kulgili yuz ifodalaringizga qarating. Chalg‘igan zahoti sochini tarab oling.'),
  ('6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd', 'Ko‘rinmas dog‘ tashvishi 👕', 'Shimida dog‘ qidiryapti-yu, aslida hech narsa yo‘qmi? Bu yana o‘sha ko‘ziga ko‘rinayotgan injiqliklar. Nam salfetka bilan artgandek bo‘lib, «Mana, yo‘q bo‘ldi», deng. Bola miyasi bunday illuziyalarga juda tez ishonadi.'),
  ('7da643f9-a304-476b-9165-6028a945c141', 'Siz nariroqda o‘tiring 🛑', 'Karavoti yonida emas, uzoqroqda — eshik oldida o‘tirishingizni talab qilyaptimi? Xafa bo‘lmang! Bu uning mustaqillik sari tashlagan katta qadamidir, ich-ichingizdan quvonsangiz arziydi.'),
  ('b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba', 'Derazadagi qush meniki 🐦', 'Hovlidagi qushni uyga olib kirmoqchi bo‘lib yig‘layaptimi? Tabiatga mehr-muhabbati jo‘sh uribdi. «Qushchaning onasi uni uyida kutyapti», degan hikoya bu inqirozni bir zumda xotirjamlikka aylantiradi.'),
  ('544fb1ce-862b-49f6-8e2e-6b2192929ac3', 'Tungi qo‘rquvlar boshlanadi 👻', 'Karavot ostidagi maxluqdan qo‘rqyaptimi? Bo‘sh purkagich idishiga suv solib, xonaga sehrli maxluq haydovchi vositadek purkang. Qo‘rquv bir zumda yo‘qoladi.'),
  ('b51cc09c-00f6-4b63-945d-9cfceecedfb2', 'Tishimni barmog‘im yuvsin 🪥', 'Tish cho‘tkasini rad etib, tishini albatta barmog‘i bilan tozalamoqchimi? Qarshilik qilmang, ozgina tish pastasi surtilgan toza barmoq bilan ham bu ishni bajarish mumkin. Buni katta muammoga aylantirmang.'),
  ('e403fe31-012f-4f6b-80cb-45dd719c9f06', 'Yashirin shokolad lazzati 🍫', 'Bola televizor ko‘rayotganda oshxonada undan yashirincha shokolad yeyapsizmi? Yoqimli ishtaha! Shuncha injiqlikka bardosh berish uchun bu sizning eng tabiiy energiya batonchangiz — o‘zingizni ayblamang.'),
  ('50f1584c-32c1-44e9-9ef5-89a70a2afc5e', 'Dadaning sekingina kirib kelishi 👨‍🍼', 'Siz ertak o‘qib charchagan paytingizda, dada xonaga sekingina kirib, uni silaydi va sizga borib dam olishingizni ishora qiladi. Bu — ota-onalikdagi haqiqiy jamoaviy ish namoyon bo‘ladigan lahza.'),
  ('6694bf7a-8c8c-47c1-8991-2a84701c94f1', 'Bananni noto‘g‘ri archdingiz 🍌', 'Bahonalarning qiroli! Bananni siz archganingiz uchun qiyomat qo‘pdi. Yangi banan bering, uni o‘zi xohlaganidek, hatto o‘rtasidan sindirib bo‘lsa ham archisin — mustaqilligiga putur yetmasin.'),
  ('9aaf0e76-e78b-442f-afe1-7bb02c660da6', 'Havo juda issiq isyoni 🧥', 'Ko‘chaning o‘rtasida kurtkasini yechib tashlayapti, siz esa sovqotishidan xavotirdamisiz? Qarshilik qilmang, rostdan ham sovqotganda o‘zi kelib so‘raydi. Qilgan ishining oqibatini o‘zi his qilsin.'),
  ('02ff52cb-13af-47d3-83d9-4e3e21f04d45', 'Men stulman 🪑', 'O‘zini biror buyum deb tanishtirib, qimirlamay turibdimi? Ustiga hazillashib bir o‘yinchoq qo‘ying va Qanday chiroyli stul deb ayting. Bu g‘alati rol unga juda yoqadi va u tinchgina turadi.'),
  ('50fd969e-9bd4-4e5e-8927-9b3b9067a4be', 'Hamjamiyat menga nima deydi? 💬', 'Hamma narsani noto‘g‘ri qilayotgandek tuyulyaptimi? Anacan hamjamiyatiga kiring, boshqa onalarning sho‘x-shaddod bolalari haqidagi hikoyalarni o‘qing, chuqur nafas oling va o‘zingiznikiga shukr qiling!'),
  ('8d85cb27-805f-4ca6-a6a0-16122a07af20', 'Xonani butunlay qorong‘i qiling 🌙', 'Yo‘lakdan tushayotgan yorug‘lik tufayli uxlay olmayaptimi? Demak, mukammallikni xohlaydi. Eshikni mahkam yoping, xonani butunlay qorong‘i qiling va melatonin o‘z tabiiy vazifasini bajarib, uni uxlatishiga imkon bering.'),
  ('1752e8bc-24e4-4f1b-97e5-c557a4522bda', 'Osmon qayerga ketdi? ☁️', 'Tumanli havoda bergan kutilmagan falsafiy savoli miyangizni qotirib qo‘ydimi? «Sovqotmasin deb bulutlar uning ustini yopib qo‘ydi», deng. Uning miyasi hali ilmiy izohga tayyor emas, unga shunchaki ertak kerak.'),
  ('2d5bfd88-008f-4b96-a72a-390cdfe7c90d', 'Do‘kon o‘rtasida yugurish 🛒', 'Kassa oldida birdan yugurib ketib, javonlar orasiga yashirinadimi? Xaridlar ro‘yxatini elektron shaklda saqlang, shunda bunday vahimali paytlarda nimalarni olmaganingizni unutib, uyga quruq qo‘l bilan qaytmaysiz.'),
  ('5c94e9c6-00cb-4c58-b265-f248e6c3e544', 'Shivirlash o‘yini 🤫', 'Qichqirib yugurib, uxlashni istamayaptimi? Birdan ovozingizni juda pasaytiring. Juda sekin, shivirlab gapira boshlang. U sizni eshitish uchun diqqatini jamlaydi va uyqusi keladi.'),
  ('22c6ff37-5069-489b-9d49-2a97d14d2e2e', 'Men mukammal ona emasman 🛑', 'Bugun hammasi ostin-ustun bo‘lib, baqirib yubordingizmi? O‘zingizni ayblamang. Kayfiyat kundaligingizga shunchaki yozing: Bugun yomon o‘tdi, ammo men yaxshi onaman va ertaga yana urinib ko‘raman.'),
  ('39a82edc-fce3-4cb5-8ef7-be6b2f9a1122', 'Yomg‘ir sadolari ostidagi ertak 🌧️', 'Ovozingiz chiqmayapti, ertak o‘qishga kuchingiz yo‘qmi? Aqlli ertaklarda fon sifatida faqat yomg‘ir va o‘rmon tovushlarini yoqing. Tabiatning bu sokinligi ba’zan eng yaxshi ertakdan ham tezroq uyquga eltadi.'),
  ('69d7d720-ce5e-441e-ac6e-b3151e6557c4', 'Qo‘limdan ushlamang! 🚶‍♂️', 'Yo‘lda qo‘lingizni qo‘yib yuborib, mustaqil yurishni istayaptimi? Agar bu xavfsiz hudud bo‘lsa, o‘z mustaqilligini sinab ko‘rishiga imkon bering, siz esa shunchaki ikki qadam ortda g‘urur bilan uni kuzatib boring.'),
  ('1b495b8d-2c5f-47f5-aeda-e199006766ac', 'Tanam menga tegishli emas 🔋', 'Kun bo‘yi ustingizga tirmashaverishidan tanangiz uvishib qoldimi? Bolani 5 daqiqaga xonada yolg‘iz qoldiring, shunchaki eshikni yoping, ko‘zlaringizni yumib, chuqur nafas oling. Kuchingizni tiklashingiz kerak.'),
  ('81591bb3-d8f2-475d-b7fc-1bd47693b91f', 'Meni bola dema! 😤', '«Men katta bo‘lganman», deb xonada sizga o‘z qoidalarini o‘tkazyaptimi? U allaqachon ulg‘ayganini isbotlashga harakat qilyapti. Unda unga «yosh xonim» yoki «yosh janob» deb, kattalardek murojaat qiling va hurmatini qozoning.'),
  ('a65f1e7a-ca07-4462-bac0-1293b0e5896c', 'Raqamli terapiyam 🤫', 'Butun uy uyquda, ammo miyangiz hali ham shovqinga to‘lami? Shovqin o‘lchagichni yoqing. Xonadagi 0 detsibel yozuviga qarash sizni psixolog seansidan ham ko‘proq tinchlantiradi — sinab ko‘ring.'),
  ('25ef7ba4-1698-4dbc-9412-9bb568472d80', 'O‘yinchoqlarini uxlatish 🧸', 'O‘zi uxlamaydi-yu, ammo o‘yinchoqlarini birma-bir yotqizib, ustini yopadimi? Aslida bu rolli o‘yin uni asta-sekin, ruhiy jihatdan uyquga tayyorlaydi, aralashmang.'),
  ('7626d265-88f4-40f1-a79c-e9d0f1238d73', 'Nega eshikni siz ochdingiz? 🚪', 'Eshikni siz ochganingiz uchun yig‘lab, uni qayta yopdirib, o‘zi ochmoqchimi? Mayli, bunga 1 daqiqa ketsin, ammo uyda boshlanadigan 20 daqiqalik isyon va qichqiriqning oldini tinch yo‘l bilan oling.'),
  ('a5284401-af40-43a4-aa11-663792a88d21', 'Faqat yashil rang! 🥦', 'Likopchadan faqat yashil narsalarni qidiryaptimi? Ovqatlanish rejasini ko‘rib chiqing, ko‘katlardan qanday qilib yoqimli shakldagi yashil sabzavotli sharchalar tayyorlashni o‘rganing va uning bu g‘alati ishtiyoqini qondiring.'),
  ('27e63f29-b167-40b2-aa6b-8ed0d0329ca3', 'Nonning chetlari — dushman 🍞', 'Nonning faqat o‘rtasini yeb, chetlarini qat’iylik bilan tashlab yuboradimi? Qobig‘i bilan kurashmang. Hayvon shaklidagi qoliplar bilan kesib, qobiqsiz shakllar yarating — oshpazlikdagi bu dizayndan zavqlansin.'),
  ('7c97a838-1745-4335-a86c-2bf011bb9f3b', 'Uydan chiqishni istamaydi ⛅', 'To‘rt devor orasida siqilyapsiz, ammo u yig‘lab, tashqariga chiqishni istamayaptimi? Ob-havo va kiyim vositasiga ishonib, istamasa ham tashqariga olib chiqing. Toza havodan nafas olishi bilan uydagi barcha asabiyligi bir zumda tarqab ketadi.'),
  ('f3fa598e-4bec-4396-a5cb-220c0c856d23', 'Dadasi bilan pijamadagi kurash 🤼‍♂️', 'Uxlashni istamayaptimi? Dadasi u bilan devor yonida hazillashib kurashsin va uni yenggandek bo‘lsin. U terlab, qolgan barcha kuchini o‘sha yerda sarflaydi-da, yugurib borib yotog‘iga kiradi.'),
  ('2ab3a16c-8538-4df6-b8df-c031bc53d6c7', 'Hamjamiyatdan kuch olish 💬', 'Sabringiz tugaganda Anacan hamjamiyatiga kiring. U yerdagi onalar ham xuddi shunday tartibsizlikni boshdan kechirayotganini ko‘rsangiz, qalbingizda katta yengillik va «men yolg‘iz emasman» degan tuyg‘u paydo bo‘ladi.'),
  ('5a8f1d52-e3d3-4c7e-b491-d2552a236831', 'Buni ham uddaladik! 🚀', 'Uy ahli uxlab qoldi. Kelasi oyning yangi tartibsizliklariga tayyorsiz — siz bu ishning ustasisiz. Chiroqlarni o‘chiring va bugun yaratgan barcha kichik mo‘jizalaringiz uchun o‘zingizga minnatdorlik bildiring.'),
  ('83732257-57c8-43f0-99f6-cb1c1583874a', 'Bu soya meniki 👻', 'O‘z soyasini o‘ziniki deb, u bilan gaplashib, unga buyruqlar beryaptimi? Uning tasavvuri cheksiz.'),
  ('37af8066-a97d-4233-891d-9eb3a99e296b', 'Ro‘yxatga yashirin hujum 🛒', 'Do‘konga borishdan oldin ilovadagi Xaridlar ro‘yxatini ochib, unda 5 dona shokolad yozilganini ko‘rdingizmi? Ha, u telefoningizga kirishni va raqamli dunyoni ko‘chirishni allaqachon o‘rganib olgan.'),
  ('709311bc-b001-46b6-bc4d-6ad222fa6ef4', 'Butun olma dramasi 🍏', 'Olmani bo‘laklaganingiz uchun xonada dod-faryod boshlandimi? «Men uni butunligicha xohlagandim!» deb yig‘layapti. Mantiq izlamang. Bo‘laklarni bir-biriga yopishtirib, «Qara, yana tuzatdim», deng-da, bu bema’ni dramadan diplomatik yo‘l bilan chiqib keting.'),
  ('8b61be71-cfc2-42cd-ad4f-a58585ff674e', 'Dada o‘ylab topgan qahramon 🦸‍♂️', 'Gapirishga ham, kitob o‘qishga ham holingiz yo‘qmi? Navbatni dadasiga bering. Dadasi bosh qahramoni bolaning o‘zi bo‘lgan to‘qima va mantiqsiz bir hikoya aytib bersin. Siz esa shunchaki divanga cho‘zilib, xonadan kelayotgan qahqahalarni tinglang.'),
  ('167cc8b8-5aaf-4f2a-8be0-934651da76be', 'Teskari kiyilgan paypoq qaysarligi 🧦', 'Paypoqning tovon qismini oyog‘ining ustiga qaratib kiyib oldimi va aslo to‘g‘rilashga qo‘ymayaptimi? Mayli, shunday qolaversin. Uning «Buni o‘zim uddaladim» degan g‘ururi paypoqni to‘g‘ri kiyishdan million marta qadrliroq.'),
  ('4081d285-b739-4c34-a223-ae2922366de7', 'Yana bir qultum suv bahonasi 💧', 'Endi uxlab qolay deganingizda, «Juda chanqadim», deb yotoqdan sapchib turadimi? Maqsad suv emas, siz bilan yana biroz vaqt o‘tkazish. Karavoti yoniga oldindan suvi to‘kilmaydigan idish qo‘yib, bu mashhur nayrangning yo‘lini boshidanoq to‘sing.'),
  ('7b85f446-78f0-4be5-9cc1-c336a25ea658', 'Charchadim, ammo aytmayman 📝', 'Bugun qanchalik asabiylashganingizni hech kim ko‘rmayaptimi, hammaga kulib qarash esa sizni bo‘g‘yaptimi? Kayfiyat kundaligini oching. Ichingizdagi bor zahar va g‘azabni ekranga to‘kib soling. Ichingizdagilarni raqamli tarzda bo‘shatish sizni psixologdan ham tezroq yengillashtiradi.'),
  ('4c512e27-6d0e-434b-b3b6-e7db7541662c', 'Asfaltdagi chiziqlar — qonun 🛣️', 'Ko‘chada ketayotganda toshlar orasidagi chiziqlarni bosmaslik uchun g‘alati harakatlar qiladimi? Bunda yirik motorika va diqqat bir vaqtda ishlaydi. Uni shoshirmang, qo‘lidan tuting va siz ham o‘sha chiziqlar ustidan sakrab o‘ting.'),
  ('685cde5b-1133-4e8c-aa85-09d262ad4afb', 'Suv oqib ketadigan teshikdan qo‘rqish 🛁', 'Vannadan chiqayotganda suv oqib ketadigan teshikdan qo‘rqadimi? Uning tasavvuri kutilmagan tarzda ishlayapti. O‘sha joyga plastik o‘yinchoq kemani qo‘yib: «Qara, bu qo‘riqchi, u hech narsani tortib ketmaydi», deng. Shunda qo‘rquv o‘rnini o‘yin egallaydi.'),
  ('e7c8a731-9f6f-40fe-bb36-efba9869846f', 'Ertalab soat 6 da boshlanadigan konsert 🎤', 'Ko‘zini ochishi bilan bor ovozda o‘zi to‘qigan qo‘shiqni aytadimi? «Jim bo‘l, qo‘shnilar uyg‘onadi», deb uning jo‘shqin energiyasini so‘ndirmang. Siz ham qo‘shiling. Tongni qo‘shiq bilan boshlagan bola kun davomida kamroq tajovuzkor bo‘ladi.'),
  ('7dbcfeb4-6b0f-40e0-a421-e16781d15f4a', 'Sukunatning 0 detsibelli raqsi 🤫', 'Nihoyat, xona qorong‘i va u uxlab qoldi. Uyga shunday sukunat cho‘kkanki, hatto quloqlaringiz bitib qolgandek bo‘ladi. Ilovadagi Ovoz o‘lchagichni oching. Ekrandagi 0 detsibelgacha tushgan raqamni kuzatish shovqindan charchagan miyangiz uchun haqiqiy raqamli massajdir.'),
  ('80129e61-cd59-4c54-9d5e-e6507c3811da', 'Mening o‘yinchog‘im sizdan xafa bo‘ldi 🧸', 'Siz baqirganingiz uchun yoningizga kelib: «Ayiqcham sizdan xafa bo‘ldi», dedimi? U o‘z his-tuyg‘ularini buyumlarga ko‘chirib, shu orqali sizga yetkazyapti. Ayiqchadan jiddiy tarzda uzr so‘rang va uni quchoqlang. Bolangiz qanday yengil tortganini ko‘rasiz.'),
  ('e7d3487a-45d4-44a3-bf97-c34082190904', 'Choy nega bug‘lanadi? ☕', 'Piyolangizdan chiqayotgan bug‘ga qarab sizni savolga tutadimi yoki undan qo‘rqadimi? Ilmiy izoh bera olmayapsizmi? Anacan AI-dan 4 yoshli bola uchun falsafiy va yoqimli izoh oling: «U bulutlarga qo‘shilish uchun uchyapti».'),
  ('1bdc66c1-4583-42f2-a981-0ba814be491d', 'Kurtka jangi 🧥', 'Tashqarida quyosh charaqlab turibdi, ammo u kurtkasini kiyishni istamayapti. Derazadan qarab aldanmang, unga Ob-havo va kiyim vositasidagi haqiqiy haroratni va bir necha qavat kiyintirilgan bolaning rasmini ko‘rsating. Qoidani telefonga yuklab oling.'),
  ('8b4c98d1-27b9-49ae-b0a2-f93f650bdd45', 'Nega qush menga qaramadi? 🐦', 'Parkda bir kaptar uchib ketgani uchun ho‘ngrab yig‘ladimi? Bunda mantiq izlamang. Bu uning uchun chindan ham katta umidsizlik. «U ham sizni juda sog‘inadi», deb his-tuyg‘usini mehr bilan qabul qiling.'),
  ('cbcac766-bab8-4183-80ab-82267106b24d', 'Ertakda mening ismim bo‘lsin 🪄', 'Klassik kitoblardagi qahramonlardan zerikdimi? Aqlli ertaklarda qahramonning ismini uning ismiga almashtiring. O‘zining qanday jasorat bilan uxlaganini eshitgach, xonasida hech qanday e’tirozsiz uyquga ketadi.'),
  ('83683b1a-77a6-45bf-bf9e-6b7ae022a7e3', 'Men bugun mashinaman 🚗', 'Ertalab sizga «Men bola emasman, mashinaman», deyaptimi? Qoidalar qo‘ymang. «Unda kel, tez yugurishing uchun benziningni (bo‘tqangni) to‘ldiramiz», deng. Bunday kulgili rolli o‘yinlar baqirishdan ancha oson.'),
  ('87824b1c-6e01-4ebd-84b1-4bb784a464e0', 'Qumdan pishirilgan tort 🏖️', 'Parkda suv bilan tuproqni aralashtirib, ust-boshini loy qilib, sizga tort tayyorladimi? Tozalikni bir chetga qo‘ying. Bu mayda motorika va ijodkorlikni rivojlantiradi.'),
  ('bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99', 'Ko‘z yummaslik musobaqasi 👀', 'Uxlashni istamay, ataylab ko‘zlarini katta ochib sizga qarayaptimi? «Kim birinchi bo‘lib ko‘zini yumsa, yutqazadi» o‘yinini o‘ynang. Ko‘zlari yoshlanib, baribir charchaydi va 2 daqiqada o‘z-o‘zidan yumiladi. Sinab ko‘ring!'),
  ('20b06f39-a2df-4c97-aab5-39753c3a8a8f', 'To‘shakdagi yashirin o‘yinchoqlar 🧸', 'To‘shagiga yotganingizda tagidan 3 ta qattiq o‘yinchoq mashina chiqdimi? U ularni qo‘riqlab uxlaydi. Xavotir olmang, uxlab qolganidan 10 daqiqa o‘tgach, badaniga botayotgan o‘sha buyumlarni sezdirmay olib qo‘yib, uning bemalol uxlashini ta’minlaysiz.'),
  ('29e9913a-41eb-42ab-96c8-cc6c3af590fd', 'Hamjamiyatdagi sokin tasalli 💬', 'Juda charchadingiz va hatto hech kimga dardingizni aytishni istamayapsizmi? Anacan hamjamiyatiga kirib, shunchaki kuzatuvchi bo‘ling. Boshqa onalar xuddi shunday bema’ni injiqliklarni qanday yengayotganini ko‘rish siz uchun eng kuchli sokin tasalli bo‘ladi.'),
  ('bab27593-bee1-487c-a8d8-1d9f5c333dc2', 'Noto‘g‘ri qoshiq mojarosi 🥄', 'Sho‘rvani katta qoshiqda berganingiz uchun uyda deyarli inqilob ko‘tarildimi? 4 yoshga yaqin bolalar uchun ovqat bir xil bo‘lsa ham, buyumning o‘lchami uning tasavvurida taomning ta’mini o‘zgartiradi. Bahslashmang, qoshiqni darhol almashtiring va kuchingizni asrang.'),
  ('6072f87e-09eb-4773-9647-75d90ac37029', 'Indamay divanga cho‘kish 🥂', 'Bola uxladi, uy yig‘ishtirildi. Juftingiz bilan divanda yonma-yon o‘tiring, hatto televizorni ham yoqmang. Shunchaki bir-biringizga «buni ham uddaladik, omon qoldik» degan nigoh bilan qarang. Ishoning, ota-onalikning eng romantik va chinakam lahzasi aynan shu.'),
  ('a980ec72-f146-48fe-a3b4-28ba8f8a9398', 'Yashil rangga muhabbat 🥦', 'Likopchadan faqat yashil narsalarni izlab, boshqa rangdagilarni chetga suryaptimi? Foydali retseptlarni ko‘rib chiqing va ko‘katlardan shirin ko‘rinishdagi yashil sabzavotli sharchalarni qanday tayyorlashni o‘rganing.'),
  ('e2f4da77-db67-4ed8-9acb-d0a907894c73', 'Nega eshikni siz yopdingiz? 🚪', 'Uydan chiqayotganda eshikni siz yopganingiz uchun dod solib, uni qayta ochdirib oldimi? Vaziyatni nazorat qilayotganini his etish — uning eng katta ehtiyojlaridan biri. Mayli, bunga 1 daqiqa sarflang, ammo ko‘chada 30 daqiqa davom etadigan yig‘i va injiqlikning oldini oling.'),
  ('2feec242-97b8-4207-9200-a80856e8121d', 'Ko‘zgudagi bu bola kim? 🪞', 'Ko‘zgu qarshisida turib, o‘ziga o‘zi qoshlarini chimiryaptimi, jahldor va g‘alati yuz ifodalarini qilyaptimi? U his-tuyg‘ular yuzida qanday aks etishini o‘rganmoqda. Bu mitti teatr aktyorining mashqini chetdan ovoz chiqarmay, zavq bilan tomosha qiling.'),
  ('70b38ef9-bf37-4439-be26-d9a4e96ca1a7', 'Chiroqlarni o‘chiring, soyani toping 🔦', 'Qorong‘ilikdan qo‘rqib, uxlashga yotmayaptimi? Xonadagi chiroqlarni butunlay o‘chirib, kichik fonarni yoqing. Devorda qo‘llaringiz bilan kuchuk va qush soyalarini yarating. Qo‘rqinchli qorong‘ilikni uning uchun teatrga aylantiring — shunda uxlab qolishi osonlashadi.'),
  ('d5008830-7d32-4abc-8ae0-128b13041be3', 'Devorga chizilgan shoh asar 🖍️', 'Bir necha soniyalik jimlikdan so‘ng uni devorga flomaster bilan san’at asari chizayotganida topdingizmi? Chuqur nafas oling. Uning mayda motorikasi rivojlanmoqda, devorni esa baribir tozalash mumkin. Bu shoh asarni o‘chirishdan oldin, albatta, suratga oling.'),
  ('56af6282-7207-49e4-b888-b735c8e4f791', 'Dadaning yelkasida ot minish 🐴', 'U bor kuchini sarflay olmay, uxlashga yotishga qarshilik qilyaptimi? Dadasini yordamga chaqiring. Dadasi bolani yelkasiga mindirib, ot bo‘lib chopganida, xona qahqahaga to‘ladi va to‘planib qolgan jismoniy zo‘riqish ter bilan birga soniyalar ichida yo‘qoladi.'),
  ('65ce993d-a029-4b05-8c87-ec0d7b807a64', 'Hojatxonaga 5 daqiqalik qochish 🚪', 'Shovqin-surondan boshingiz yorilay deyaptimi, hamma narsaga baqirgingiz kelyaptimi? Uni xavfsiz joyga qo‘yib, hojatxonaga kiring va eshikni yoping. Shunchaki 5 daqiqa devorga qarab turing, hech narsa qilmang. Bu qisqa sukunat sizni yana o‘zingizga keltiradi.'),
  ('a5a3dc3f-2634-4d40-9509-dbe4066d8a5a', 'Bo‘tqa juda dumaloq 🥣', 'Ovqatning shaklidan jahli chiqib, uni yeyishdan bosh tortyaptimi? Mantiq izlamay, bo‘tqani qoshiq bilan shunchaki aralashtiring va «Qarang, tuzatdim», deng. Illyuziya san’ati onalikda sizga har doim asqatadi.'),
  ('9272ca67-0e34-4d81-b7cc-a00d43d2c52b', 'Mantiqsiz ko‘z yoshlar 😭', 'Parkdan qaytayotganda yo‘ldagi bir toshni tepa olmagani uchun qiyomat qoyim bo‘ldimi? Bunda mantiq yo‘q, u shunchaki charchagan. Bahslashmang, bag‘ringizga bosing, his-tuyg‘ularini tan olib, e’tiborini boshqa narsaga qarating.'),
  ('bf4ef479-e79f-4536-adc8-2a33fe4bb476', 'Pichirlab ertak aytish sirlari 🤫', 'Yotmaslik uchun bahonalar o‘ylab topyaptimi? Ovozingizni juda pasaytirib, faqat pichirlab gapira boshlang. Sizni tushunish uchun bor diqqatini jamlashiga to‘g‘ri keladi va miyasi tez orada uyquga ketadi.'),
  ('dd593bef-61fd-4b06-ae2c-84f70da4ad5c', 'Nega kuylashimga qo‘ymading? 🎶', 'Orqa fonda yangrayotgan bolalar qo‘shig‘iga jo‘r bo‘lib xirgoyi qildingiz-u, u darhol baqirdi: Siz kuylamang!? Xonadagi yagona solist — o‘zi, sizning vokalga urinishlaringiz esa uning sahnasini toraytiradi. Xafa bo‘lmang, sahnani shu mitti xudbinchaga qoldiring.'),
  ('0e5c772e-ad3b-4b0c-99e1-704d879eb64e', 'Kiyimlarini o‘zi tanlaydi 👗', 'Qizil shim, sport poyabzali va qishki qalpoq... Ustiga-ustak, parkka aynan shunday borishini qat’iy talab qilyapti. Odamlar nima deyishini o‘ylamang. O‘z tanlovi bilan ko‘chaga chiqishiga ruxsat bering, bu erkinlik uning uchun chiroyli ko‘rinishdan muhimroq.'),
  ('1c02e319-6351-4dbf-93b0-072c9cbcabab', 'Taymer bilan uyqu kelishuvi ⏱️', 'Uxlash vaqti kelganda birdan chanqab qoladimi yoki devor bilan xayrlasha boshlaydimi? Taymer o‘rnating. Qo‘ng‘iroq chalinganda hamma uxlaydi degan qoida kiriting. Tashqi bir avtoritetga bo‘ysunish ularga har doim osonroq.'),
  ('42320a1e-019f-4b03-8860-b2a7ebec874e', 'Oy nega hali ketmadi? 🌙', 'Ertalab osmonda oyni ko‘rib, Oy nega uxlamadi? deb so‘radimi? Ilmiy atamalar bilan boshini qotirmang. Anacan AI’ni oching, shu yoshga mos yoqimli astronomik ertakni topib, unga o‘qib bering va savollariga javob topishiga yordam bering.'),
  ('37e1f058-26f3-4681-8381-3414a60ed5c9', 'Nonning faqat cheti yeyiladi 🍞', 'Nonning faqat po‘stini yeb, yumshoq qismini tashlaydimi? Bolalarning ovqat borasidagi bunday teskari qarashlari sizga yaxshi tanish. Non po‘sti deb tortishmang. Ovqatlanish rejasida nonni qoliplar bilan kesib, unga turli shakllar berishni o‘rganing.'),
  ('d40bcca0-d355-4520-b51b-bece0b2b8663', 'Melatonin uchun qorong‘ilik 🌌', 'Tezroq uxlab qolishi uchun uyqudan 1 soat oldin xonadagi barcha televizor va telefon ekranlarini o‘chiring. Melatonin (uyqu gormoni) faqat qorong‘i muhitda tez ajraladi, tabiiy jarayonga ishoning.'),
  ('eb8ec98b-d143-483a-b14c-964f86bd6a10', 'O‘yinchoqlar nega uxlamaydi? 🧸', 'O‘zi uxlamay, barcha o‘yinchoqlarini birma-bir yotqizib, ustini yopib chiqadimi? Bu rolli o‘yin aslida uni asta-sekin ruhiy jihatdan o‘z uyqusiga tayyorlaydi, aslo aralashmang.'),
  ('22a3d2df-ec5e-47c6-9766-7dc689ce8423', 'Shunchaki hidini to‘yib ichingizga yuting 🫂', 'Bugun sizni rostdan ham aqldan ozdirib, bor kuchingizni so‘rib oldimi? Ammo karavotda shu qadar beg‘ubor uxlayaptiki... Chiroqlarni o‘chiring. Yoniga yotib, o‘sha musaffo bolalik hidini chuqur-chuqur ichingizga yuting va qorong‘ida unga mehringizni pichirlab ayting.'),
  ('48b463cd-d776-4db6-a471-4507d498dd54', 'Do‘kon o‘rtasida nima olishni unutib qolmang 🛒', 'Do‘konga kirib, nima olishingizni unutdingizmi? Xaridlar ro‘yxatini raqamli shaklda yuritmasangiz, o‘sha tartibsizlik ichida hammasini unutasiz. Uyga quruq qo‘l bilan qaytmaslik uchun ilovadagi raqamli xotirangizga doimo ishoning.'),
  ('9dc02f00-56a0-48da-87a7-8f742a42c374', 'Siz men bilan o‘ynamayapsiz! 😤', 'Siz ovqatni aralashtirayotganingizda yoningizga kelib, yuzingizni qo‘llari bilan o‘ziga buradi: Menga qarang!? U haq. Unga shunchaki yonida ekaningiz emas, butun diqqatingiz kerak. Ishni chetga qo‘yib, atigi 2 daqiqa davomida ko‘zlariga tik qaragan holda uni tinglang.'),
  ('a00b84e6-561e-4101-8d5d-a0f8a705abed', 'Yomg‘ir ovozli xona 🌧️', 'Ovozingiz chiqmayaptimi, ertak o‘qishga kuchingiz yo‘qmi? Aqlli ertaklarda fon sifatida faqat yomg‘ir va o‘rmon ovozlarini yoqing. Tabiatning bu bir maromdagi sokinligi ba’zan eng yaxshi ertakdan ham tezroq uyquga eltadi.'),
  ('a4fa9d13-3510-4b51-9dcb-583bfd5c19ad', 'O‘zi o‘ylab topgan ism bilan chaqirilish 🦇', 'Ertalab uyg‘onib, o‘z ismini rad etdimi va Meni Batman deb chaqir deb talab qildimi? Moslashing! 5 daqiqa davomida Marhamat, Batman, bo‘tqangni ye deb, xonadagi taranglikni bir zumda kulgiga aylantiring.'),
  ('e5dd03b1-7179-4527-8c52-f0958fe208e9', 'Instagram onalaridan charchash 📱', 'Instagramni ochishingiz bilan boshqalarning mukammal farzandlarini ko‘rib, tushkunlikka tushmang! Ilovani yoping-da, Anacan Hamjamiyatiga kiring. Boshqalarning uyi ham siznikidek ag‘dar-to‘ntar ekanini ko‘rib, chuqur nafas oling — siz yolg‘iz emassiz.'),
  ('17e2ffec-fd31-4ab8-8917-684e3ceaaff9', 'Barcha stressni suv bilan yuvish 🛀', 'Ba’zan hech narsa yordam bermaydi, u shunchaki hamma narsaga yig‘layveradi. Uni iliq suvli vannaga tushiring. Suvning o‘sha mo‘jizaviy, taranglikni o‘ziga tortuvchi ta’siri bir zumda butun xona va uning asab tizimiga chuqur xotirjamlik olib keladi.'),
  ('d1311034-b416-403f-a981-34577f22c978', 'Ket, sizni xohlamayman 💔', 'Istagi rad etilgani uchun sizga Yomon onasan, ket! dedimi? Yuragingiz og‘ridi. Ammo u hali g‘azabini so‘z bilan ifodalay olmaydi, aslida Hafsalam pir bo‘ldi demoqda. Buni ko‘nglingizga olmang, shunchaki mehr bilan quchoqlang.'),
  ('e3289711-a700-447f-9c8d-d0e1b469b80e', 'Ko‘rinmas do‘st bilan choy ichish 🫖', 'Xonaning burchagidagi bo‘shliqqa choy quyib, kulyaptimi? Xayoliy do‘stlar davri boshlandi!'),
  ('05726924-8563-423e-bd0f-f5be06f1d806', 'Dadasi ataylab noto‘g‘ri o‘qigan ertak 📖', 'Bugun kechqurun ertak kitobini dadasiga bering. Dadasi hikoyani ataylab noto‘g‘ri, kulgili va bema’ni tarzda aytib bersin. Farzandingiz uni tuzatishdan zavqlanib, qah-qah otib kulishini chetdan maroq bilan kuzating.'),
  ('1b87ed18-3cf6-4e93-88b1-58f24b42513f', 'Tong sahardagi quvlashmachoq 🏃‍♂️', 'Ertalab soat 7 da divanlar ustida yuguryaptimi? Baqirmang. Ishlaringizni 2 daqiqaga chetga qo‘yib, siz ham sakrab unga qo‘shiling. Bolaning xayolot olamiga sho‘ng‘ish aslida siz uchun ham stressdan xalos bo‘lishning o‘ziga xos usulidir.'),
  ('9c4135ea-bc1e-4450-aea1-64dfec877859', 'To‘satdan duduqlanish vahimasi 🤖', 'Farzandingizning to‘satdan duduqlana boshlashi sizni internetdan kasalliklar izlashga majbur qildimi? To‘xtang! Anacan AI orqali bu 4 yoshdagi rivojlanish sakrashi ekanini bilib, vahimangizni bosing.'),
  ('15bb2b6b-7a84-4331-86dd-6aee2aba5539', 'Sukunatning ekrandagi raqami 📉', 'Nihoyat uxlab qoldi. Uy shu qadar jimib qoldiki, quloqlaringiz shang‘illayaptimi? Ilovadagi Ovoz o‘lchagichni oching. Undagi 0 desibel yozuviga qarash charchagan, shovqindan toliqqan miyangiz uchun dunyodagi eng yaxshi vizual massaj bo‘ladi.'),
  ('21cfa5ea-471d-459d-a626-6d4be6cf6e4c', 'Bananni siz archganingiz uchun janjal 🍌', 'Bananni siz archganingiz uchun uyda inqilob boshlandimi? Bu yoshning oltin qoidasi: hamma narsani bolaning o‘zi hal qilishi kerak. Bananni qayta yopishtira olmaysiz, shuning uchun yangisini bering va uni o‘zi xohlaganidek archisin — mustaqillik tuyg‘usiga putur yetmasin.'),
  ('e6cc1e43-997c-46d7-a69b-a71076271387', 'Yo‘l chetidagi dorboz 🧱', 'Parkka ketayotganda tekis yo‘ldan emas, albatta yo‘lkaning eng tor chetidan yurishni xohlayaptimi? Xavfsizligi uchun qo‘lidan ushlang va bu kichik cho‘qqini zabt etishiga imkon bering. Muvozanat va o‘ziga ishonch bir vaqtning o‘zida ajoyib rivojlanadi.'),
  ('6daea202-5e39-49bd-9344-4fdbc59064e5', 'O‘zingizga vaqt ajratish ayb emas 🥗', 'Uni ovqatlantirish uchun turli menyular tuzdingiz, ammo o‘zingiz nima yedingiz? Sog‘lom retseptlar bo‘limidagi onalar uchun oson, 5 daqiqada tayyor bo‘ladigan salatni tayyorlang va nihoyat, o‘zingizga ham kuch-quvvat berishni unutmang.'),
  ('744c45ec-e43d-4be3-95b9-700cd56edef4', 'Bir-biringizga jimgina qarash 🥂', 'Bola uxlab qoldi. Siz va turmush o‘rtog‘ingiz divanda indamay bir-biringizga qarab o‘tiribsiz. Hech narsa demaysiz. Aslida bu sukunat «Buni ham uddaladik, biz ajoyib jamoamiz» deyishning eng romantik va samimiy usulidir.'),
  ('9632825c-5c1a-41f6-900b-2b6b7e88d644', 'Kurtka kiyishni rad etish 🧥', 'Tashqarida quyosh charaqlab turgani uchun qishki kurtkasini kiyishni istamayaptimi? Ob-havo va kiyim bo‘limini ochib, telefondagi qishki kiyim kiygan bola belgisini ko‘rsating. Qoidani raqamli ekranga topshiring, o‘zingiz chetga chiqing — u jimgina kiyinadi.'),
  ('6f53d579-a4b1-4e03-8f30-fcdd7a9084bf', 'Qorong‘ida pichirlab dardlashish 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Yoniga yotib, kun davomida sodir bo‘lgan voqealarni yoki uning fe’l-atvoridagi sizga eng yoqadigan jihatni juda past ovozda qulog‘iga pichirlab ayting. Pichirlash miyani uyquga tayyorlashning eng sirli usullaridan biridir.'),
  ('ba2db9df-7097-4890-b7eb-8938c592806f', '«Bu mening aybim emas» degan yolg‘on 🤥', 'Suvni ataylab polga to‘kdi-yu, keyin barmog‘i bilan o‘yinchoq mashinasini ko‘rsatib: «U itarib yubordi», dedimi? Bu yolg‘onchilik emas, balki himoyalanish mexanizmi. «Kel, bu mashinaga ham qanday tozalashni o‘rgatamiz», deb uning diqqatini ustalik bilan boshqa tomonga yo‘naltiring.'),
  ('ce02bfea-edc6-42ad-80fd-37f3c322993b', 'Maydonchadagi sirpanchiq siyosati 🤝', 'Sirpanchiqda boshqa bolani itarib, o‘zi uchmoqchi bo‘ldimi? Uyalganingizdan bolangizni urmang. «Hozir uning navbati, keyin seniki», deb qoidani muloyim, ammo qat’iy ohangda eslating. U ijtimoiy qoidalarni shu tarzda o‘rganadi.'),
  ('2128fd31-18d2-4020-9903-1e4bdb06a192', 'Tuxum yig''lamasin 🍳', 'Tuxumni chaqqaningizda unga rahmi kelib, yemayaptimi? Uning hamdardligi cheksiz. «U endi mushaklaringda yashab, seni kuchli qiladi», degan yoqimli uydirmalar bilan vaziyatni darhol qutqaring.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('2fbf236d-dcf9-462e-911e-87f8e16831b1'::uuid, 'Yostiqlarni joylashtirish qoidasi 🛏️', 'Yostig''i millimetrigacha tekis turishi uchun yig''layaptimi? Unda uyqu bilan bog''liq o''ziga xos odatlar paydo bo''lgan. Uning qoidalariga amal qiling, yostiqni xuddi chizg''ich bilan o''lchagandek tekislang va chiroqlarni qat''iylik bilan o''chirib, unga xotirjamlik bering.'),
  ('3b18406f-7fbc-4193-88c1-aa910648f2b5', 'Tashlab yuborgan chiqindimni qaytarib ber! 🗑️', 'U asrab yurgan eski shokolad o''ramini chiqindiga tashlaganingiz uchun qiyomat ko''tardimi? Siz uchun bu chiqindi, uning uchun esa xazina. Diqqatini boshqa yaltiroq o''yinchoqqa qarating.'),
  ('3d6e1c1c-6a73-4824-ae1e-d09852574023', 'Uy diktatori dasturxon boshida 👑', 'Nonushta paytida «U yerga emas, bu yerga o''tir», deb dasturxon boshida hammani boshqaryaptimi? Uning irodasini keskin sindirmasdan, «Yaxshi, sen aytgandek bo''lsin», deng va kichik tabassum bilan muvozanat hamda xonadagi osoyishtalikni saqlang.'),
  ('51ca75c5-97b8-4826-b323-ca25f125a567', 'Hech kimga hech narsani tushuntirmaslik 📝', 'Uyda qanchalik charchayotganingizni hech kim ko''rmayaptimi va bu sizni portlash darajasiga olib kelyaptimi? Kayfiyat kundaligini oching. Bugun sizni aqldan ozdirgan barcha narsani unga yozing. His-tuyg''ularingizni qabul qilib, ularni yozib borish sizga ko''proq yordam beradi.'),
  ('989e82d9-dbab-4ad4-8fb4-42a6025e0511', 'Jim o''qish vaqti 📖', 'Bugun kechqurun o''qish yo''q. Aqlli ertaklardan mayin fon musiqasini yoqing va faqat rasmlarni jimgina tomosha qiling. Uning miyasi tasvirlardan charchaydi va siz bir og''iz ham gapirmasdan, u uyquga taslim bo''ladi.'),
  ('6f490476-47fe-4d7a-adc6-bf02e33e53bc', 'Do‘kon kassasidagi sinov 🛒', 'Kassaning shundoq oldida shokolad deb baqiryaptimi? Orqadagilarning nigohlariga qaramay, yon bermang. Xaridlar ro‘yxatini ochib, Bu yerda yo‘q, kassa buni o‘qimaydi deng. Siz qat’iy tursangiz, u ham fikridan qaytadi.'),
  ('851d1060-8f2e-4d29-b181-eb135eec18ca', 'Qo‘llari bilan emas, og‘zi bilan yeyish 🐶', 'Likopchadan qo‘llarini ishlatmay, mushuk kabi ovqat yegisi kelyaptimi? Taqiqlamang. Oshxona baribir iflos bo‘ladi, mayli, 5 daqiqaga mushuk bo‘lsin. Bu kulgili rolli o‘yin ishtahasizlikni yengishning eng quvnoq usulidir.'),
  ('9555c57b-eea5-4d41-a55f-827af2218674', 'Dada yelka massaji qilsin 💆‍♂️', 'Bugun ko‘p vaqt oyoqda turdingiz, uning ortidan yugurib, yerdagi o‘yinchoqlarni yig‘ishdan belingiz og‘riyapti. Bola uxlashi bilan juftingizdan 10 daqiqalik yelka massajini so‘rang. Siz uyning dvigatelisiz, albatta kuchingizni tiklashingiz kerak.'),
  ('ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb', 'Xona qop-qorong‘i bo‘lishi 🌌', 'Yo‘lakdan tushayotgan yorug‘lik sababli uxlay olmayaptimi? Unga hammasi mukammal bo‘lishi kerak. Eshikni mahkam yoping, xonani qop-qorong‘i qiling, melatonin o‘z tabiiy vazifasini bajarib, uni tezda uxlatishiga imkon bering.'),
  ('e268e86b-b622-447e-800e-69d444728521', 'Bu meniki inqirozi 🧸', 'Uydagi pultni quchoqlab, Bu meniki! deyaptimi? U egalik chegaralarini sinab ko‘ryapti. Uni xudbin demang, Men uchun topib berganingga rahmat deb, e’tiborini boshqa o‘yinga qarating va pultni qaytarib oling.'),
  ('e71d30e6-0cdb-4938-b907-fc93e194b4d5', 'Tugallanmagan jumlalarning ma’nosi 🗣️', 'Biror so‘zni unutganida qo‘llari bilan ishora qilib, uni topishingizni kutadimi? Sabr bilan jumlasini tugatganingizda, uning yuzidagi yengillikni kuzating. U aynan sizning yordamingiz bilan shu tarzda lug‘at boyligini oshiradi va o‘ziga ishonchini mustahkamlaydi.'),
  ('0a86e24e-bf60-4b61-ae36-925c5211691c', 'Suvni quritish talabi 💧', 'Stakandagi suvni ichish o‘rniga «Bu juda ho‘l, uni qurit!» deb baqiryaptimi? Mantiq izlamang: suvni boshqa rangdagi stakanga quyib, «Quruq suv olib keldim», deng. Illyuziya san’ati — onalikdagi eng kuchli qurolingiz.'),
  ('b27687ec-9619-4dbe-be9c-054706708b62', 'Tabiat qo‘yniga chiqish shart ⛅', 'To‘rt devor orasida uning energiyasi tajovuzkorlikka aylanib, har bir gapi «yo‘q» bilan boshlanyaptimi? Ob-havoga mos kiyintirib, uni albatta tashqariga olib chiqing. Tuproqqa tegish uning asab tizimini darhol qayta muvozanatga keltiradi.'),
  ('eeca2adc-6712-4238-9603-30877865ed81', 'Qo‘ng‘iroq ovozi bilan avtomatik uyqu ⏱️', 'Uxlash vaqti kelishi bilan birdan hojatxonaga borgisi keladimi? Taymer o‘rnating. «Qo‘ng‘iroq chalinganda hamma chiroqlarni o‘chiradi» qoidasini joriy eting va bu cheksiz xayrlashuv hamda mohirona nayranglardan tortishuvsiz qutuling.'),
  ('4e140178-6301-4406-9f9f-fe623cbcfff7', 'Eshik ortidagi bekinmachoq 🙈', 'Bog‘chaga kechikyapsiz, u esa parda ortiga yashirinib, «Meni toping!» deyaptimi? Baqirish jarayonni yanada cho‘zadi. «Qani, mening bolajonim qayerda ekan?» deb, 2 daqiqalik o‘yinga qo‘shiling va uni u yerdan kuldirib olib chiqing.'),
  ('7964aed1-1770-40a2-a565-23bfdc9aea21', 'Aqlli ertakdagi turli ovoz effektlari 🪄', 'Aqlli ertaklarni yoqing. Hikoyani o‘qiyotganda eshik g‘ichirlashi, shamol ovozi va shivirlashni taqlid qilib, xonada ovozli teatr yarating. Bu noodatiy tovushlar uning diqqatini bir zumda ertak olamiga jalb qiladi.'),
  ('c87486c1-f5de-473b-8cd5-b9e2e2bd31c1', 'Ekran uchun o‘zingizni ayblamang 📺', 'Bugun ishlaringiz ko‘p bo‘lgani uchun u televizor qarshisida uzoq vaqt qoldimi? Vijdoningiz qiynalyaptimi? Har kuni mukammal bo‘la olmaysiz. Ba’zan ekranlar bizni katta tartibsizliklardan qutqaradigan eng bezarar enagadir, xotirjam bo‘ling.'),
  ('0c893825-691b-4509-9849-6369336b84d4', 'O‘z asarini yirtib tashlagan rassom 🖍️', 'Chizgan chizig‘i yoqmay, Yomon chiqdi deb qog‘ozni yirtib tashlayaptimi? Unda o‘zini tanqid qilish va mukammallikka intilish hissi paydo bo‘lmoqda! Kel, keyingi safar boshqa rangni sinab ko‘ramiz deb, uning hafsalasi pir bo‘lganini yangi kashfiyotga aylantiring.'),
  ('bcac5731-4815-4adc-beb4-861e3ff078b1', 'Mushukdek suykalish 🐾', 'Bugun ertalab u to‘rt oyoqlab yurib, oyog‘ingizga suykalib, faqat miyovlayaptimi? Unga turli qoidalarni tushuntirish o‘rniga, siz ham unga xayoliy sut idishini uzating. O‘ynash har doim koyishdan osonroq va zavqliroq.'),
  ('c6026760-e985-429a-b39f-d4d1786df630', 'Vannadagi mini laboratoriya 🛀', 'Suvga turli rangdagi sovunlarni qo‘shib, sehrli ichimlik tayyorlayaptimi? Hammom iflos bo‘ladi, albatta. Ammo u erituvchilarni o‘rganmoqda. Bunday ilmiy izlanish kechki charchoqni yengillashtirib, uni sokin uyquga tayyorlaydigan eng yaxshi vositadir.'),
  ('40e041b4-2484-475f-93b5-25cda3ee362e', 'Sen kimsan? tomoshasi 🎭', 'Sizga begona odamdek qarab, Sen kimsan? Onam qani? deyaptimi? Bu yangi rolli o‘yin. Men shifokor xolaman, yuragingni tinglash uchun keldim deng va uni qitiqlang. Tongda xona kulgiga to‘lsin.'),
  ('417e0bcc-cf3b-4a96-95e9-58a2f51764f6', 'Hojatxona qog‘ozi san’ati 🧻', 'Xonaga kirganingizda, hojatxona qog‘ozining hammasi yechilib, butun uyga yoyilganini ko‘rdingizmi? Jahlingiz chiqishi o‘rniga, qog‘ozlarni yig‘ib, birgalikda to‘p yasang. Tartibsizlikni baqiriq bilan emas, ijodkorlik va kulgi bilan yenging.'),
  ('4a1de341-603c-4aae-ab4d-439d7bb05d7c', 'Sukunat zavqi 🤫', 'Nihoyat uxlab qoldi. Uy shu qadar jimjit bo‘lib qoldiki, quloqlaringiz shang‘illayaptimi? Ilovadagi Ovoz o‘lchagichni oching. Undagi 0 desibel yozuviga qarash charchagan, shovqindan toliqqan miyangiz uchun dunyodagi eng yaxshi vizual massaj bo‘ladi.'),
  ('3d9dcc3e-1698-4fca-951e-a58aed0724d2', 'Stakanning rangi noto‘g‘ri 🥤', 'Suvni sariq stakanda berganingiz uchun uyda qiyomat qo‘pdimi? Buni ko‘nglingizga olmang, u shunchaki bugun ertalab sizning chegaralaringizni sinab ko‘ryapti. Suvni darhol ko‘k stakanga quying va uyda tinchlikni tiklab, kuchingizni asrang.'),
  ('522145b2-4826-4821-80c0-e0e180045415', 'Shunchaki bag‘ringizga bosish 🫂', 'Bugun u sizni rostdan ham aqldan ozdirib, bor kuchingizni so‘rib oldimi? Ammo yotoqda shunchalik beg‘ubor uxlayaptiki... Chiroqlarni o‘chiring, ertak o‘qimang. Yoniga yotib, bolangizning beg‘ubor hididan to‘yib-to‘yib nafas oling va shukr qiling.'),
  ('792e3525-032e-4662-ba49-1276a3b3ef78', 'Boshqa onalarning hikoyalari 💬', 'Instagramni ochishingiz bilan boshqalarning mukammal farzandlarini ko‘rib, tushkunlikka tushmang! Ilovani yoping-da, Anacan hamjamiyatiga kiring. Boshqalarning uyi ham siznikidek ostin-ustun ekanini ko‘rib, chuqur nafas oling.'),
  ('3e4bbd84-ef8f-45a2-b630-5aeadd95390e', '«Qo‘limni ushlamang!» mustaqilligi 🚶‍♂️', 'Yo‘lda qo‘lingizni qo‘yib yuborib, o‘zi mustaqil yurishni xohlayaptimi? Agar joy xavfsiz bo‘lsa, o‘z mustaqilligini sinab ko‘rishiga imkon bering. Siz esa bu mitti erkin isyonkorni ikki qadam ortidan faxr bilan kuzating.'),
  ('6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0', 'Oshxonada yordam berish falokati 🧑‍🍳', 'Siz xamir yoyayotganingizda stulini ko‘tarib kelib, unni albatta o‘zi solmoqchi bo‘ldimi? Ruxsat bermasangiz, yig‘laydi. Unga kichik plastik idish va ozgina un bering. Oshxona ostin-ustun bo‘ladi, ammo uning ko‘ngli to‘ladi.'),
  ('776040ef-af05-4430-a752-3b380b194dba', 'Oy biz bilan birga yuguryapti 🌕', 'Kechqurun mashinada qaytayotib, derazadan qarab Oy bizni kuzatyapti, deyaptimi? U butun koinot o‘z atrofida aylanadi deb o‘ylaydi. Uning bu tasavvurini buzmasdan, Qiziq, u biz bilan qayerga ketyapti ekan? deb o‘yinga qo‘shiling.'),
  ('58e2fe84-f6c5-40ff-93ab-26ea06ad9f14', 'Kir ko‘ylakka muhabbat 👕', '3 kundan beri bir xil ko‘ylakni kiyib, yuvishga ruxsat bermayaptimi? Bu yoshda ayrim buyumlar bolaga o‘zini xavfsiz his qilishiga yordam beradi. Bahslashmang, «Ko‘ylakni kir yuvish mashinasida sehrli sarguzashtga jo‘natdim, u kuchga to‘lib qaytadi», degan uydirma ertak bilan uni qo‘lidan oling. U bu xayoliy voqeaga ishonadi.'),
  ('b740d6be-007b-4aa6-9c46-6ffbce8b157e', 'Chumoli uchun motam marosimi 🐜', 'Bog‘da yotgan chumolini ko‘rib, joyidan jilmayaptimi va «U adashib qolibdi», deb yig‘layaptimi? Uning hamdardligi chegara bilmaydi. «Hozir onasi kelib, uni olib ketadi», deb ayting.'),
  ('fcc60573-09e9-4a7c-8399-55df532828cd', 'Botqoqdagi oq shovqin 🌊', 'Xonasida uxlash o‘rniga u yoqdan bu yoqqa sakrayaptimi? Ovoz o‘lchagichning fon tovushlaridan kuchli dengiz to‘lqini yoki oq shovqinni yoqing. Bir maromdagi bu tovush chastotasi miyasidagi jo‘shqin energiyani yuvib ketadi va 10 daqiqada ko‘zlari yumiladi.'),
  ('73abbd29-9b2f-4f48-8461-6482853b741f', 'Supurgi bilan halokatli yordam 🧹', 'Siz uyni yig‘ishtirayotganingizda kelib, «Men qilaman», deya chiqindilarni xona bo‘ylab yanada sochib yuboradimi? Ruxsat bermasangiz, qiyomat qo‘padi. Qo‘liga nam salfetka berib, «Sen faqat stolning mana bu burchagiga javobgarsan», deng. Shunda siz ham ishingizni qilasiz, u ham o‘zini muhim his qiladi.'),
  ('eacaec53-45d2-4b70-9f52-8b48878bd78c', 'Bo‘sh devorga tikilish vaqti 🛋️', 'Xonada o‘zi mustaqil o‘ynayaptimi? Jonim, bu fursatni idish yuvishga sarflamang! Divanga o‘tiring, choyingizni oling va shunchaki devorga qarang. Ha, hech narsa haqida o‘ylamasdan. Kayfiyat kundaligingizga 5 daqiqalik osoyishtalikni yozib qo‘ying. Bu sizga kerak.'),
  ('f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3', '«Sochim sinib ketdi!» dramasi 🪮', 'Taroqni ko‘rishi bilan «Sochim og‘riyapti», deb qochadimi? Sensor sezgirlik uni qo‘rqitadi. Diqqatini chalg‘iting. Qo‘liga ko‘zgu berib, «Qani, ko‘zguda kim tilini kulgiliroq chiqararkin?» deng va u chalg‘ib turganida sochlarini bir zumda tarab bo‘ling.'),
  ('a897741a-cd22-4371-a712-b1ae3911676e', 'O‘zi to‘qigan qo‘shiqlar 🎤', 'Hali quyosh chiqmagan, u esa sakrab, ma’nosiz so‘zlarni baland ovozda qo‘shiq qilib aytyaptimi? Baqirib, uni jim qilmang. Tongni qo‘shiq bilan boshlagan bola ichidagi tajovuzkorlikni chiqarib yuboradi. Siz ham 1 daqiqaga uning jo‘shqinligiga qo‘shiling — uyqungiz darhol qochadi.'),
  ('ad4460c3-33b8-4fdc-85b5-ca63eae32f6e', 'Instagramdagi bequsur onalar 📱', 'Instagramni ochishingiz bilan boshqalarning saranjom uyini, aqlli bolasini ko‘rib, tushkunlikka tushdingizmi? O‘sha ilovani o‘chirib tashlang! Anacan hamjamiyatiga qo‘shiling. Uyi siznikidek tartibsiz, bolasi esa qaysar bo‘lgan haqiqiy onalarning hikoyalarini o‘qing va yengil torting.'),
  ('b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4', 'Shivirlab chaqirilgan uyqu 🤫', 'To‘shakdan qochib, u yoqdan bu yoqqa sakrayaptimi? Birdan ovozingizni juda pasaytiring. Juda past ovozda, shivirlab gapira boshlang. Sizni tushunish uchun bor diqqatini jamlaydi va miyasi 5 daqiqada charchab, uyqu rejimiga o‘tadi. Sinab ko‘ring!'),
  ('1dcf070f-1d18-4228-b248-9ed1c6174aff', 'Muzlatkichdan topilgan o‘yinchoq 🧊', 'Muzlatkichni ochsangiz, ichidan rezina mashinacha chiqdimi? Bu xotirani va buyumni boshqa joyda sinab ko‘rish o‘yini. Jahlingiz chiqmasin, bunday bema’nidek tuyulgan ishlar uning rivojlanishining bir qismidir.'),
  ('ba708130-cef9-4b08-8a17-7c16cb66de0a', 'Uydan chiqishni istamaydi ⛅', 'Uy ag‘dar-to‘ntar, u esa divanda yig‘lab, bormayman deyaptimi? Ob-havo ilovasini ochib, tashqaridagi haqiqiy haroratni tekshiring, unga mos kiyim kiydiring va istamasa ham parkka olib boring. Toza havo yuziga tegishi bilan butun tajovuzkorligi tarqab ketadi.'),
  ('c3fe5fd9-dde9-47f5-b95c-98d26881d393', 'Ertak qahramoni uning o‘zi bo‘lsa 🪄', 'Tarbiyaviy ertaklarni oching. Undagi qahramon ismini bevosita farzandingizning ismiga almashtiring. Hikoya davomida o‘sha qahramon qanday qilib jasorat bilan, gapga quloq solib uxlaganini o‘qing. Hikoyada o‘zini eshitgach, hech qanday qarshiliksiz ko‘zlarini yumadi.'),
  ('4c96a8e1-971d-4b98-9e5c-faff2c2726a9', 'To‘satdan falsafa xuruji 🤔', 'To‘satdan Dengar tubi nega qora? deb ilmiy savol berdimi? Vahimaga tushmang! Anacan AI-ni oching, uning yoshiga mos, pediatr va psixologlar ma’qullagan eng yoqimli ertaknamo javobni oling va unga o‘qib bering. Siz doim hamma narsani biladigan onasiz!'),
  ('9f289ae7-fe30-4b1a-8ebd-63874521363d', 'Qorong‘i xonada quvlashmachoq 🔦', 'Uxlash vaqti bo‘ldi, ammo uning energiyasi hali ham tugamadimi? Xonadagi barcha chiroqlarni o‘chiring. Qo‘lingizga kichik fonar olib, Qani, yorug‘lik devorda kimni tutarkin? o‘yinini o‘ynang. Qorong‘ida o‘ynash melatonin ajralishini tezlashtiradi va uni charchatadi.'),
  ('d28d5d46-d2a6-4daa-b454-adbdf6be3f63', 'Ko‘rinmas yaraning azobi 🩹', 'Barmog‘ida hech narsa yo‘q, ammo qonadi deb yig‘layapti va yara plastiri so‘rayaptimi? Bu jismoniy og‘riq emas, unga sizning mehringiz kerak. O‘sha plastirni yopishtiring, o‘pib qo‘ying va sehrli bo‘sam bilan tuzatdim deng. Shunda kuningiz qutqariladi.'),
  ('19ac1700-7f02-47aa-b9e8-f8064c7e18d0', 'Eshikni yopish va shaxsiy hudud 🚪', 'O‘z xonasiga kirib, eshikni ortidan yopdi va kelmang dedimi? Xafa bo‘lmang. U shunchaki shovqin-suron va tartibsizlikdan chetlanib, dam olmoqchi. Agar xavfsizligi joyida bo‘lsa, shaxsiy hududidan bahramand bo‘lishiga imkon bering. U ulg‘ayayapti!'),
  ('2cb51eab-cbdc-48ba-8569-e245d61ad27e', 'Tunning tuganmas bahonalari 🚰', 'Ko‘zi yumilib ketyapti, ammo birdan Oyog‘im qichidi, Suv ichgim kelyapti deb sapchib turadimi? U uyquni kechiktirish bo‘yicha professor. Taymer qo‘ying. Telefon jiringlaganda barcha bahonalar ham uxlaydi deng. Vakolatni telefonga topshirib, o‘zingiz chetga chiqing.'),
  ('9240add5-52c7-45dc-8ae0-15dd7dadfa88', 'Bu mening ismim emas 📛', 'Meni ismim bilan chaqirmang, men O‘rgimchak odamman deyaptimi? Bu o‘zligini izlash jarayoni. Unga moslashing! Nonushtani Marhamat, janob O‘rgimchak deb bering. Xonadagi taranglikni bir zumda komediyaga aylantirish sizning qo‘lingizda.'),
  ('2127b5f4-7e9a-438e-9094-bd9d7f0d5237', 'Do‘konda ro‘yxat bilan murosa 🛒', 'Kassa oldida to‘satdan konfet talab qildimi? Atrofdagilarning sizga «qanday ona ekan» degandek qarashlariga aslo e’tibor bermang. Xaridlar ro‘yxatini ochib, «Bu ro‘yxatda yo‘q, kassa buni bizga sotmaydi», deng va qaroringizda qat’iy turing.'),
  ('73af2e7a-1bb5-4576-8888-801050bfada3', 'Bo‘yoqlar devorgacha yetib bordi 🖍️', 'Xonaga kirib, devorda yangi freskani ko‘rdingizmi? Chuqur nafas oling. U qog‘oz chegarasidan chiqib, motorikasini kattaroq ko‘lamda sinab ko‘rmoqda. Artib tashlashdan oldin, kelajakda unga ko‘rsatib birga kulish uchun bu shoh asarni albatta suratga oling.'),
  ('f6ed5025-5dc3-4f4a-8ce2-d48478e2666f', 'Sukunatning ekrandagi tasdig‘i 📉', 'Nihoyat uxlab qoldi. Qulog‘ingizda hali ham qichqiriqlar jaranglayaptimi? Shovqin o‘lchagichni oching. Xonadagi ovoz 0 desibelgacha tushganini ko‘rsatuvchi chiziqni tomosha qilish charchagan va shishib ketgandek bo‘lgan miyangiz uchun dunyodagi eng yoqimli vizual massaj bo‘ladi.'),
  ('48318bc7-c4f3-4717-9848-18bd10967e29', 'Dadaning to‘qima ertagi 🦸‍♂️', 'Gapirishga holingiz yo‘q, kitob o‘qishni istamayapsizmi? Ertak aytishni dadasiga topshiring. Dadasi bosh qahramoni bolaning o‘zi bo‘lgan to‘qima va g‘aroyib hikoya aytib bersin. Devor yonida cho‘zilib dam olgancha, bolaning dadasiga qarab qah-qah otib kulishini tomosha qiling.'),
  ('4ac93f87-372d-4d1a-a449-a2da763a8227', 'Bu taomning shakli noto‘g‘ri 🥒', 'Bodringni dumaloq emas, uzun qilib kesganingiz uchun likopchani itarib yubordimi? Uning taom estetikasi haqidagi tushunchasi endi shakllanmoqda. Xuddi shu sabzavotni qiziqarli shakllarga kiritib, qanday yashirishni o‘rganing. Bu dizayn o‘yinida siz g‘olib bo‘lasiz.'),
  ('61167ef0-dce7-4186-9b36-5aa8a00936ff', 'Yolg‘iz qolish uchun hammomga qochish 🛀', 'Kun bo‘yi oyog‘ingizga yopishib oldimi, tinimsiz teginishlardan tanangiz uvishib ketdimi? Teginishlardan bezib ketish — haqiqiy holat. Uni xonada qoldirib, 5 daqiqaga hammomga kiring, eshikni yoping va shunchaki nafas oling. Sizga kuchingizni tiklash kerak.'),
  ('139226ae-9370-42b4-954a-012623528599', 'Yarim tunda tushunarsiz yig‘i 😭', 'Yarim tunda ko‘zlari yumuq holda yig‘lab uyg‘ondi va sizni eshitmayaptimi? Yig‘i tahlili yordamida tekshirib ko‘ring; bu katta ehtimol bilan tungi vahimadir. Uni uyg‘otmaslikka harakat qiling, shunchaki yonida bo‘lib, qo‘lidan ushlang. U o‘z-o‘zidan tinchlanib, yana uxlab qoladi.'),
  ('a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1', 'Onaning yashirin shokolad vaqti 🍫', 'Shkaf ortida undan yashirincha shokolad yeyapsizmi? Yoqimli ishtaha! Uning tuganmas «nega»lariga, qichqiriqlariga bardosh berish va quvvatingizni tiklash uchun bu glyukoza — sizning eng tabiiy haqqingiz. Buning uchun hech qachon o‘zingizni ayblamang.'),
  ('a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe', 'Soya bilan quvlashmachoq 🏃‍♂️', 'Ko‘chada ketayotib, to‘satdan yugurib, o‘z soyasini tutishga harakat qiladimi? Uning tasavvuri mantiqidan ustun kelmoqda. Uni to‘xtatmang, siz ham o‘z soyangizni tutishga urinib, ko‘cha o‘rtasidagi bu telbanamo va quvnoq o‘yinga qo‘shiling. Hayot uni haddan tashqari jiddiy qabul qilish uchun yetarlicha uzun emas.'),
  ('4d4b704f-57d5-4f72-9df3-13398bb1f2e3', 'Oyoq kiyimni teskari kiyish sindromi 👟', 'O‘ng oyoq kiyimini chap oyog‘iga, chapini esa o‘ng oyog‘iga kiyib olib, to‘g‘rilashingizga yo‘l qo‘ymayaptimi? Mayli, shunday qolaversin! Uning «o‘zim kiydim» degan g‘ururi va mustaqillik hissi oyoq kiyimining to‘g‘ri kiyilganidan million karra qadrliroq.'),
  ('95ee8df4-a59a-42f4-b252-bf062304f70b', 'Ichimdagi g‘azabni raqamli sahifaga to‘kish 📝', 'Bugun qanchalik charchaganingizni hech kim ko‘rmayaptimi va jilmayish sizni bo‘g‘yaptimi? Kayfiyat kundaligini oching. Ichingizdagi bor alam va charchoqni ekranga to‘king. «Men holdan toydim» deb yozish sizni soxta mukammallikdan ko‘ra tezroq tiklaydi.'),
  ('ec907054-781c-4e3c-be06-6c97119a4864', 'Dadaning yelka massaji 💆‍♂️', 'Bugun ko‘p vaqt oyoqda qoldingiz, uning ortidan yugurish va yerdagi o‘yinchoqlarni yig‘ishdan belingiz uzilgudek bo‘lyapti. Bola uxlagach, juftingizdan 10 daqiqalik yelka massajini so‘rang. Siz bu uyning dvigatelisiz, dvigatel esa albatta dam olishi va tiklanishi kerak.'),
  ('486ad622-5eff-484f-8ea8-ea64a245ed91', 'Bananni nega siz archdingiz?! 🍌', 'Bananni siz archganingiz uchun xonada to‘polon ko‘tarildimi? Bu yoshning oltin qoidasi: hamma narsani uning o‘zi hal qilishi kerak. Bananni qayta yopishtira olmaysiz, shuning uchun darhol yangisini bering va uni o‘zi istaganidek archishiga qo‘yib bering. Qaysarlik qilish faqat vaqtingizni oladi.'),
  ('b59a06d3-66eb-4eef-8c37-b58f8b3331ca', 'Juftlik bo‘lib sukutda 🥂', 'Bola uxladi, uy yig‘ishtirildi. Turmush o‘rtog‘ingiz bilan divanda yonma-yon o‘tiring, hatto televizorni ham yoqmang. Shunchaki bir-biringizga «Buni ham uddaladik, omon qoldik», degandek qarab qo‘ying. Ota-onalikdagi eng romantik va chinakam jamoaviy lahza aynan shu.'),
  ('c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b', 'Stol ostidagi kichkina uy ⛺', 'U ovqat stolining tagiga kirib, o‘ziga uy qurib oldimi va tushlikni o‘sha yerda qilmoqchimi? Qoidalarni biroz yumshating. Sho‘rvani o‘sha qorong‘i joyga uzating. Joyni o‘zgartirish sarguzasht hissi bilan hatto ishtahasi yo‘q bolani ham ovqatlantirishga qodir.'),
  ('1f9be131-7868-4433-adc0-efe09d70723d', 'Siz men bilan o‘ynamayapsiz! 😠', 'Siz telefonga qarab turganingizda, u kelib yuzingizni qo‘llari bilan o‘ziga burdi: «Menga qarang!» Haqiqatan ham u haq. Unga shunchaki yonida ekaningiz emas, balki butun e’tiboringiz kerak. Telefonni chetga qo‘ying, 3 daqiqa davomida uning ko‘zlariga to‘liq e’tibor bilan qarang — u darhol tinchlanadi.'),
  ('86f2c2e9-f758-416c-a78d-b431eb3db53a', 'Yo‘lka chetidagi dorboz 🧱', 'Bog‘ga ketayotganda tekis yo‘ldan emas, albatta yo‘lkaning eng tor chetidan yurishni xohlayaptimi? Qo‘lidan ushlab, xavfsizligini ta’minlang va bu kichik cho‘qqini zabt etishiga imkon bering. Muvozanat va o‘ziga ishonch bir vaqtning o‘zida ajoyib rivojlanadi, unga xalaqit bermang.'),
  ('963db29c-a2ad-4233-bbc2-364a68692feb', 'Xonadagi ovoz effektlari 🪄', 'Bugun kechqurun o‘qishdan charchadingizmi? Aqlli ertaklarni yoqing. Hikoyani o‘qiyotganda shunchaki eshik g‘ichirlashi, shamol ovozi va shivirlash kabi tovushlarni chiqarib, xonada ovozli teatr yarating. Bu noodatiy tovushlar uning diqqatini bir zumda ertak olamiga olib kiradi.'),
  ('2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6', 'Bog‘dan chiqish uchun musobaqa usuli 🌳', 'Bog‘dan qaytish vaqti keldi-yu, yig‘i va injiqlik boshlandimi? Uni sudrab olib ketish yordam bermaydi. «Qani, mashinagacha kim quyondek sakrab tezroq yetib borarkin?» deb, diqqatini darhol kulgili musobaqaga qarating — u albatta bellashishga tushadi.'),
  ('42b47472-82e3-49e8-bb91-8de4938efbde', 'Shunchaki hidini ichingizga torting 🫂', 'Bugun u sizni rostdan ham aqldan ozdirib, butun quvvatingizni so‘rib oldimi? Ammo yotoqda shu qadar beg‘ubor uxlayaptiki... Chiroqlarni o‘chiring. Yoniga yotib, bolajoningizning musaffo hidini chuqur-chuqur ichingizga torting va u siz uchun qanchalik qadrli ekanini pichirlab ayting.'),
  ('67931668-7ad8-456d-8077-31b1756abd2c', 'Suvni boshqa stakanda bering! 🥤', 'Suvni sariq stakanda berganingiz uchun uyda qiyomat bo‘ldimi? «Men ko‘k stakanni xohlagandim!» deyaptimi? Buni murakkablashtirmang, u shunchaki chegaralaringizni sinayapti. Suvni darhol ko‘k stakanga quying, uyda tinchlikni tiklab, kuchingizni asrang.'),
  ('047715fd-ae66-4d00-8341-50e230c2b688', 'Dinozavrlar bo‘tqa yemaydi! 🦖', 'Ertalab hech bir savolga javob bermay, faqat o‘kiryaptimi? Demak, u bugun T-Rex. «Xo‘sh, T-Rex-lar nonushta qiladimi?» deb, u o‘ylab topgan obrazga qo‘shiling va uning ko‘z yoshlarisiz, xotirjamlik bilan stolga o‘tirishiga yordam bering.'),
  ('2da52e9b-b72c-461f-8480-276d6d5e47df', 'Do‘kon o‘rtasida qotib qolmang 🛒', 'Do‘konga kirib, nima olmoqchi ekaningizni unutdingizmi? Onalik tashvishlari miyani chindan ham band qilib yuboradi. Ilovadagi Xaridlar ro‘yxatini ochib, shu raqamli xotiraga tayanish sizni uyga quruq qo‘l bilan qaytishdan doim asraydi.'),
  ('2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4', 'Chiroqlarni o‘chiring, uyqu kelsin 🌙', 'Tezroq uxlab qolishi uchun yotishdan 1 soat oldin xonadagi barcha televizor va telefon ekranlarini o‘chiring. Melatonin qorong‘i muhitda tez ajraladi — tabiiy jarayon sizning o‘rningizga ishlasin.'),
  ('020f5f2c-bba3-4441-b9a0-518ce0263ac5', 'Axlat emas, san’at asari 🎨', 'Xonaning o‘rtasida quruq makaron va qog‘oz parchalaridan ulkan san’at asari yaratibdimi? Hamma joyni ozoda tutish istagini bir chetga suring. Bu — Rivojlanish kuzatuvchisiga kiritishga arziydigan ajoyib yirik motorika mashg‘uloti. Uy muzey emas.'),
  ('7231bd75-47cb-4255-ae64-144dcd8d314f', 'Sukunatning ekrandagi raqami 📉', 'Nihoyat uxlab qoldi. Uyga shunday sukunat cho‘kdiki, quloqlaringiz shang‘illayaptimi? Ilovadagi Ovoz o‘lchagichni oching. O‘sha 0 desibel yozuviga qarash shovqindan toliqqan miyangiz uchun dunyodagi eng yaxshi vizual massaj bo‘ladi.'),
  ('d3223299-be6e-4dfc-bfb7-c168e33bb866', 'Yarim qolgan gaplarni tugating 🗣️', 'Biror so‘zni unutib qolsa, qo‘li bilan ishora qilib, uni topishingizni kutadimi? So‘z boyligi oshib bormoqda, ammo miyasi tilidan tezroq ishlayapti. Gapini sabr bilan tugatganingizda, yuzida paydo bo‘ladigan «ha-a, aynan shuni aytmoqchi edim» degan yengillikni kuzating.'),
  ('3f9c24cf-68b9-4b5b-9e40-a3652b7d443e', 'Dadasi bilan divandagi kurash 🤼‍♂️', 'Uxlashga yotmaslik uchun qochib, yashirinib oldimi? Navbatni dadasiga bering. Divanda hazillashib kurashishsin. Shovqinli, terlatadigan bu ota-bola o‘yini bolaning qolgan so‘nggi qaysar energiyasini ham sarflab, osongina uyquga ketishiga yordam beradi.'),
  ('4d053e9f-b091-45c7-9c6a-66e7f1ab590e', 'Sabzavotlarni yashirish san’ati 🥦', 'Sho‘rva ichidagi bittagina sabzini topib, «Buni yemayman», dedimi? Sabzavotlarni pyure qilib, souslarga qo‘shing-chi, endi qanday topar ekan! Uning oshpazlik ziyrakligini ustalik bilan yengib o‘ting.'),
  ('db42b564-536c-485c-afff-dce099e8c451', 'Men uchishni xohlayman! 🕊️', 'Divandan sakrab, qo‘llarini qoqyaptimi va ucha olmagani uchun sizdan jahli chiqyaptimi? Unga fizika qonunlarini o‘rgatishga hali erta. «Sen uchmayapsan, chunki qanotlaring hali o‘smoqda», deb, e’tiborini yumshoq joyga sakrashga qarating.'),
  ('294ce10a-4fac-4bfb-8007-e2e3fea714ad', 'O‘z rasmini tanqid qilish 🖍️', 'Chizgan chizig‘i yoqmay, “Bu yomon chiqdi”, deb qog‘ozni yirtib tashlayaptimi? Unda o‘zini tanqid qilish va mukammallikka intilish hissi paydo bo‘lmoqda! “Kel, keyingi safar boshqa rangni sinab ko‘ramiz”, deb uning hafsalasi pir bo‘lganini qo‘llab-quvvatlovchi izlanishga aylantiring.'),
  ('76df67fe-b947-400d-8825-c8fd1637478f', 'Hamjamiyatdagi sokin tasalli 💬', 'Juda charchadingizmi, hatto birovga dardingizni aytgingiz ham kelmayaptimi? Anacan hamjamiyatiga kirib, shunchaki kuzatuvchi bo‘ling. Boshqa onalar xuddi shunday bema’ni injiqliklarni qanday yengayotganini ko‘rish siz uchun eng kuchli sokin tasalli bo‘ladi.'),
  ('882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2', 'Vannadagi okean bo‘roni 🌊', 'Cho‘milish bir bahona, aslida vannada okean yaratib, to‘lqinlar bilan o‘ynayaptimi? Mayli, o‘ynasin. Suvning shovqini va sachrashi uning ichidagi tuganmas, o‘jar energiyani yuvib ketadi. Kechqurun hech qanday qarshiliksiz yotog‘iga yotadi.'),
  ('3e4c8054-2b97-4968-a10f-267dccb5b8c0', 'Ertalabdan kutilmagan falsafa 🤔', '“Nega shamol ko‘rinmaydi?” deb to‘satdan ilmiy savol berdimi? Vahimaga tushmang! Anacan AI’ni oching va shu yoshdagi bola tushuna oladigan, pediatr hamda psixologlar ma’qullagan eng yoqimli, ertaknamo javobni olib, unga o‘qib bering. Siz doim hamma narsani biladigan onasiz!'),
  ('b7b7faa9-f807-43f1-bf54-6d7f963c5e32', 'Shunchaki tinchgina yotish 🛋️', 'U o‘zi mustaqil pazl yig‘yapti va uy birdan jimjit bo‘lib qoldimi? Iltimos, bu fursatni uy supurishga sarflamang! Divanga yotib oling. Kechgacha shu sur’atga bardosh berishingiz uchun sizning ham quvvatingiz to‘lishi kerak. Albatta dam oling.'),
  ('ccae9470-c321-4925-94c0-7408317b4c14', 'Cho‘ntakdan chiqqan xazinalar 🪨', 'Shimini yuvayotganda cho‘ntagidan qurigan barg yoki tosh chiqdimi? Bu ochko‘zlik emas, bolalarcha kashfiyotchilik. Uni jiddiy qiyofada axlatga tashlang, ammo ichingizda g‘amxo‘r jamg‘aruvchi bolakayga jilmayib qo‘ying — u dunyoni kashf etmoqda.'),
  ('76fc525d-97d8-486f-adde-6d0bdc417bbe', '“Bu meniki!” qiyomati 🧸', 'Uydagi pultni quchoqlab, “Bu meniki!” deyaptimi? U egalik chegaralarini sinab ko‘rmoqda. Uni xudbin deb atamang. “Men uchun topib berganingga rahmat”, deb e’tiborini boshqa o‘yinga qarating va pultni ohista qaytarib oling.'),
  ('ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b', 'Qo‘ng‘iroq chalinganda uxlaymiz ⏱️', 'Uxlash vaqti tobora cho‘zilmoqda. Suv ichish, hojatxonaga borish, devor bilan xayrlashish... Telefon taymerini sozlang. “Qo‘ng‘iroq ovozi eshitilganda hamma chiroqlarni o‘chiradi”, degan qoida kiriting. Tashqi bir avtoritetga bo‘ysunish bolalarga doim osonroq kechadi.'),
  ('f24ccc35-5845-4b4b-803c-db7a68218026', 'Hech kimga hisob berishingiz shart emas 🛑', 'Bugun sabringiz tugab, ovozingizni balandlatdingizmi? O‘zingizni jazolamang. Kayfiyat kundaligingizga “Men yaxshi onaman, shunchaki bugun juda charchadim”, deb yozing. O‘zingizga mehribon bo‘ling, hech kim sizdan mukammal bo‘lishni kutmaydi.'),
  ('3fdd99bb-9e81-4b54-a9b9-28997c15bd09', 'Onaning quvvat manbai 🥗', 'Uni ovqatlantirish uchun turli taomlar tayyorladingiz, ammo o‘zingiz nima yedingiz? Sog‘lom retseptlar orasidagi onalar uchun mo‘ljallangan, atigi 5 daqiqada tayyor bo‘ladigan oson salatni tayyorlang.'),
  ('8e09c446-7bb4-4213-903b-ca0d9d539235', 'Sukunatda ichilgan issiq choy ☕', 'Bola nihoyat uxlab qoldi. Xona o‘rtasida sochilib yotgan o‘yinchoqlarga qarab, chuqur nafas oling. Hozir ularni yig‘ishtirmang! O‘zingizga issiq choy quying, divanga o‘tiring va bu sukunat sizga baxsh etayotgan oromdan shunchaki zavqlaning.'),
  ('b85f6433-c512-4f2e-a5d4-b9023f0eb544', 'Jonsiz buyumlar bilan uzoq suhbatlar 🗣️', 'U bog‘dagi toshga yoki uydagi stulga jiddiy ohangda nimalarnidir gapiryaptimi? U o‘yin orqali qoidalarni va atrofdagi dunyoni anglab bormoqda.'),
  ('039b7451-67d0-43b6-9ed0-d4ec9bf47752', 'Kurtkani kiyishni rad etish 🧥', 'Tashqarida quyosh charaqlab turgani uchun qishki kurtkasini kiyishni istamayaptimi? Derazadan qarab aldanmang. Ob-havo va kiyim bo‘limini ochib, telefondagi qishki kiyim kiygan bola belgisini ko‘rsating. Qoidani raqamli ekranga topshiring, o‘zingiz esa chetga chiqing.'),
  ('1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c', 'Karavot ostidagi bekinmachoq 🛏️', 'Karavotida emas, albatta uning ostida uxlashni xohlayaptimi? Bunday yopiq va kichik joylar bolalarga ona qornidagidek xavfsizlik hissini beradi. Ruxsat bering, uxlab qolganidan keyin sekin karavotiga olib qo‘yasiz. Kuchingizni tejang.'),
  ('73a43849-8300-493d-9040-f05eaf01e5b6', 'Muzdek mantiqsizlik 🥶', 'Issiq choyni puflab ichish o‘rniga, ichiga albatta muz solishingizni talab qilyaptimi? U issiq va sovuq o‘rtasidagi farqni o‘rganmoqda. Muzni bering, erish jarayonini kuzatsin. Nonushta kechiksa ham, u o‘z ilmiy kashfiyotini amalga oshirgan bo‘ladi.'),
  ('1171703b-c644-4ad0-8298-a24063264467', 'Yomg‘ir sadoli ertaklar xonasi 🌧️', 'Ovozingiz chiqmayaptimi, ertak o‘qishga kuchingiz yo‘qmi? Aqlli ertaklarda fon sifatida faqat yomg‘ir va o‘rmon tovushlarini yoqing. Tabiatning mana shu bir maromdagi sokinligi ba’zan eng yaxshi va eng hayajonli hikoyadan ham tezroq allalab, uyquga eltadi.'),
  ('43e7fbfe-64bc-4627-85d6-4ddae59c6985', 'Ko‘zguda o‘ziga jahli chiqadi 🪞', 'Ko‘zgu qarshisiga turib, turli tovushlar chiqaryaptimi va yuz ifodalarini o‘zgartiryaptimi? Bu o‘zlikni anglash hissi kuchayayotganidan dalolat. U o‘z tanasi va his-tuyg‘ulari tashqaridan qanday ko‘rinishini sinab ko‘rmoqda. Indamay, chetdan kuzating.'),
  ('5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5', 'Teginishlar isyoni 🔋', 'Kun bo‘yi oyog‘ingizga yopishib olib, quchoqqa olishni so‘rayaptimi? Jismonan holdan toyibsiz. Teginishlardan charchagansiz. Uni o‘yinchoqlari bilan xonada qoldirib, 5 daqiqaga hammomga kirib oling va eshikni yoping. Shunchaki o‘sha yolg‘izlikni his qiling.'),
  ('2a662eb4-1c17-46f1-ad5d-c566286402e8', 'Parkdagi navbat janjali 🤝', 'Sirpanchiqda boshqa bolani itarib, o‘zi uchmoqchi bo‘ldimi? Hamma sizga qarayapti. Uyalganingizdan bolangizni urmang. «Hozir uning navbati, keyin biz uchamiz», deb qoidani muloyim, ammo qat’iy ohangda eslating. Tartib shunday ishlaydi.'),
  ('c0dcbfbe-b91a-462c-890d-a8770be19cf3', 'Ertalabdan quvlashmachoq 🏃‍♂️', 'Ertalab soat 7-da divanlar ustida yuguryaptimi? Baqirmang. Ishlaringizni 2 daqiqaga chetga surib, siz ham sakrab unga qo‘shiling. Bolaning xayolot olamiga kirish aslida siz uchun ham g‘alati, ammo juda samarali stressdan xalos bo‘lish usulidir.'),
  ('e41be904-7cb3-4dd6-8966-ea3b375783f6', 'Tungi qo‘rquvning ilmiy yechimi 🔦', 'Yotoqxonadagi soyalardan qo‘rqyaptimi? Xonani butunlay qorong‘i qilmang, iliq rangli kichik tungi chiroq qo‘ying. Bu melatonin ajralishini buzmaydi, shu bilan birga bolaga ko‘z bilan ko‘radigan xavfsizlik hissini berib, qo‘rquvini yo‘qotadi.'),
  ('b5588608-ef71-4787-b05e-09f4f4f2492a', 'Kutilmaganda «Sizni yaxshi ko‘raman» 💖', 'Xona o‘rtasida o‘ynab turib, birdan sizga qaraydi-da, yugurib kelib bo‘yningizdan quchoqlaydi. Barcha uyqusiz tunlar va charchoqlarga arziydi! Bu lahza olib kelgan chuqur, betakror xotirjamlikdan zavqlaning va atrofdagi tartibsizlikni unuting.'),
  ('e2ac4132-1e14-42d5-a828-9c40ffb00179', 'Pichirlashning sirli kuchi 🤫', 'Yotoqdan qochib, u yoqdan bu yoqqa sakrayaptimi? Birdan ovozingizni butunlay pasaytiring. Juda past ovozda pichirlab gapira boshlang. Sizni tushunish uchun bor diqqatini jamlaydi va miyasi 5 daqiqada charchab, uyqu rejimiga o‘tadi. Sinab ko‘ring!'),
  ('f5be8b0c-0a17-4790-b9b1-73d205d64a76', 'Instagram onalari illyuziyasi 📱', 'Instagramni ochishingiz bilan boshqalarning saranjom uyini, aqlli bolasini ko‘rib, tushkunlikka tushdingizmi? O‘sha ilovani o‘chirib tashlang! Anacan hamjamiyatiga kiring. Uyi siznikidek tartibsiz, bolasi qaysar bo‘lgan haqiqiy onalarning hikoyalarini o‘qing.'),
  ('14317db1-b6eb-40d2-8404-59bcea4acdf7', 'Dadaning uyqu keltiradigan ertagi 📖', 'Ovozingiz charchab, ertak o‘qishga kuchingiz qolmadimi? Bu ishni dadasiga topshiring. Dadasining o‘zgacha, yo‘g‘on ovozi va o‘zi to‘qib chiqargan bema’ni tafsilotlar bolaning miyasini sizning odatiy ovozingizdan ham tezroq gipnoz qilib, uyquga eltadi.'),
  ('5d28c236-3ed8-4900-b875-c6d0d9b2aa20', '«Sen kimsan?» tomoshasi 🎭', 'Ertalab sizga begonadek qarab: «Sen kimsan? Onam qani?» dedimi? Bu yangi rolli o‘yin. «Men qo‘shni xolangman, onang hozir keladi», deng. Mayli, ertalab xona kulgidan larzaga kelsin — bu qaysarlik bilan kurashishdan ko‘ra ancha kam kuch talab qiladi.'),
  ('8758179c-cc13-42d7-b2c1-4900aea35e3a', 'O‘z ovqatini sizga bermaydi 🍳', 'O‘z likopchasidagini sizga bermaydi-yu, ammo kelib, sizning likopchangizdan yeyishni qat’iy talab qiladimi? Bolalar ota-onasining tanloviga doim to‘liq ishonadi. Qarshilik qilmang, luqmani mehr bilan unga uzating va bu kulgili xudbinlikka shunchaki jilmaying.'),
  ('12a06ab8-bcee-4772-8e2b-6f509250a594', 'Men uchishni xohlayman! 🕊️', 'Divandan sakrab, qo‘llarini qanotdek qoqadi va ucha olmagani uchun sizdan jahli chiqadimi? Unga fizika qonunlarini o‘rgatishga hali erta. «Sen ucha olmayapsan, chunki qanotlaring hali o‘syapti», deb, e’tiborini yumshoq joyga sakrashga qarating.'),
  ('e80a8c85-c67a-45b2-8209-90553a33fb5f', 'Telefon o‘g‘risi 📱', 'O‘zingizga choy quyayotib, telefoningiz yo‘qolganini, u esa divan ortida xuddi sizdek «Alo» deyayotganini ko‘rdingizmi? U sizning raqamli odatlaringizni takrorlayapti. Qurilmani olayotganda: «Telefonim ham sen bilan gaplashmoqchi ekan», deb, kulib uning qo‘lidan oling.'),
  ('ebb45c07-d4c6-4504-ac39-3e83655d3e00', 'Juftlik bo‘lib sukutda 🥂', 'Bola uxladi, uy yig‘ishtirildi. Turmush o‘rtog‘ingiz bilan divanda yonma-yon o‘tiring, hatto televizorni ham yoqmang. Shunchaki bir-biringizga «Buni ham uddaladik, omon qoldik», degan nigoh bilan qarang. Ishoning, charchatadigan ota-onalik hayotidagi eng haqiqiy jamoaviy lahza aynan shu.'),
  ('add15a56-d6d1-4819-af57-b57688cec0f4', 'Ertak o‘qimasdan uxlatish 🪄', 'Bu oqshom ertak o‘qishga holingiz yo‘qmi? Aqlli ertaklarni yoqing. Fon uchun faqat shivirlovchi o‘rmon va shamol tovushlarini qo‘ying. Qorong‘ida tabiat tovushlarini tinglab, ikkovingiz ham shovqin-surondan dam oling. Ko‘zlaringizdagi charchoq bir zumda yo‘qoladi.'),
  ('b000be1e-116f-4403-b926-fe4428d04231', 'Ichimdagi g‘azabni yozish 📝', 'Uyda qanchalik charchayotganingizni hech kim ko‘rmayotgani sizni portlash darajasiga olib kelyaptimi? Kayfiyat kundaligini oching. Bugun jahlingizni chiqargan hamma narsani o‘sha yerga yozing. Soxta jilmayishdan ko‘ra, his-tuyg‘ularingizni qabul qilib, yozib chiqish sizga ko‘proq yordam beradi.'),
  ('f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8', 'Men bilaman, sizga ham o‘rgatay ☝️', 'Farzandingiz siz biladigan narsani juda jiddiy va dono qiyofada tushuntiryaptimi? U o‘z aqlini sinab ko‘ryapti. Kulib yubormaslik uchun labinggizni tishlang, ammo uni jiddiy tinglab: «Rostdanmi? Katta rahmat», deng. O‘ziga bo‘lgan ishonchini qo‘llab-quvvatlang.'),
  ('5b3e259a-f085-41f9-b9ba-e7ff8789e89c', 'Vannadagi suv toshqini 🌊', 'Cho‘milish bir bahona, aslida esa u vannada okean yaratib, to‘lqinlar bilan o‘ynayaptimi? Mayli, o‘ynasin. Suvning shovqini va sachrashi uning ichidagi tuganmas, jo‘shqin energiyani yuvib ketadi. Kechqurun hech qanday qarshiliksiz yotog‘iga yotadi.'),
  ('7c552cb2-0d81-4027-8eba-e235f8359b1d', 'Oshxonada sizga yordam beryapti 🧑‍🍳', 'Siz xamir yoyayotganingizda stulini olib kelib, unni albatta o‘zi sepmoqchi bo‘ldimi? Ruxsat bermasangiz, yig‘laydi. Unga kichik plastik idish va ozgina un bering. Oshxona rasvo bo‘ladi, ammo uning jiddiy oshpaz qiyofasi bunga arziydi.'),
  ('86e3829d-08da-4b37-867c-0faf0ab2fa1c', 'Do‘kon o‘rtasida qotib qolish 🛒', 'Do‘kon o‘rtasida to‘xtab: «Men nima olish uchun kelgandim?» deb o‘ylanib qoldingizmi? Onalik miyasi chindan ham juda band. Ilovadagi Xaridlar ro‘yxatini ochib, o‘sha raqamli xotiraga ishonish sizni bu tartibsizlikdan doim qutqaradi.'),
  ('202773be-9378-4cfa-915c-7cbc9e98cdc2', 'Ko‘ylak yorlig‘i botyapti! 🏷️', 'Orqasidagi kichkina yorliq unga ignadek botgani uchun kiymayaptimi? Bu yoshdagi sensor sezgirlik odamni aqldan ozdiradi. Hech tortishmang, qaychini oling-da, yorliqni tagidan kesib tashlab, bu kichik inqirozni bir zumda hal qiling.'),
  ('65b5e1a3-f9ad-4e00-a2af-7ae096f9121d', 'Mukammal sukunat lahzasi 🛋️', 'Pazllari bilan shu qadar berilib o‘ynayaptiki, uy birdan jimjit bo‘lib qoldimi? Shubhalanmang, darhol o‘zingizga qahva quyib oling. Bu noyob va oltinga teng daqiqalarni uy yig‘ishtirish yoki kir yuvishga emas, ruhingizni tinchlantirishga, shiftga termulib yotishga sarflang. Siz robot emassiz.'),
  ('a86a31ee-9e29-4f41-aa7c-1edc94992d88', 'Yarim tunda to‘satdan qichqirish 😭', 'Tunda ko‘zlari yumuq holda yig‘lab uyg‘ondi va sizni eshitmayaptimi? Bu oddiy yig‘i emas, tungi vahima. Uni uyg‘otishga urinmang, shunchaki yonida turing, qo‘lidan ushlab, silab qo‘ying. U o‘z-o‘zidan tinchlanib, yana chuqur uyquga ketadi.'),
  ('5430bad3-c2db-4b2e-bb46-e51168e8dd91', 'Anacan’dan sizga maktub bor 💌', 'Sog‘lom retseptlarga yashirilgan sabzavotlar, Kayfiyat kundaligiga to‘kilgan ko‘z yoshlar va holdan toygan lahzalar... Shu 4 yil ichida siz dunyodagi eng qiyin kasbni puxta egalladingiz. Endi siz hech qanday ilovaga muhtoj bo‘lmagan, o‘z sezgisi bilan tartibsizlikni boshqara oladigan qahramonsiz. Biz shunchaki orqa fondagi yo‘l-yo‘riq ko‘rsatuvchi edik, asosiy ishni esa siz bajardingiz!'),
  ('7c7b74a0-c6ab-409c-babd-0085e345da09', '1460-kun: Biz buni uddaladik! 🚀', 'Ertalab uyg‘onib, unga qaraysiz... U endi roppa-rosa 4 yoshda! Mana 1460 kundirki, uyqusizlik, injiqlik va o‘jarliklarga bardosh berib, bu kichkina insonni voyaga yetkazyapsiz. Shu yillar davomida siz nafaqat bir bolani, balki qalbingizda kuchli, yengilmas yangi bir onani ham yaratdingiz. Bugun hech qanday qoida yo‘q, shunchaki uni bag‘ringizga bosing va o‘zingiz yaratgan bu mo‘jizaga faxr bilan qarang.'),
  ('e37bc161-dfcf-4941-bac0-6c7cfe6f4ba2', 'So‘nggi bildirishnoma, so‘nggi sukunat 🌌', 'U uxlab qoldi. Chiroqlarni o‘chiring. Bu — ilovadan sizga kelayotgan so‘nggi bildirishnoma. 1460 kun davomida charchaganingizda, yig‘laganingizda va o‘zingizni chorasiz his qilganingizda sizni tushunishga, indamay yoningizda bo‘lishga harakat qildik. Endi telefonni chetga qo‘ying. Siz mukammalsiz, siz yetarlisiz. Bundan keyingi ajoyib hikoyani o‘zingiz, mustaqil ravishda yozasiz. Siz bilan birga bu yo‘lni bosib o‘tish biz uchun sharaf edi. Ko‘rishguncha, Onajon! ❤️'),
  ('bfa22ff0-d771-4756-a950-034bebcc6d6a', 'Multfilm ssenariynavisi 📺', 'Ko‘rgan multfilmini sizga shunchalik o‘zgacha syujet bilan, shu qadar ishonarli tarzda tushuntiradiki, deyarli ishonib qolasiz. Unda ajoyib tasavvur shakllanmoqda.')
) AS v(id, t, b)
WHERE x.id = v.id;

-- Yoxlama: hər ikisi ~0 olmalıdır (boş-mənbə sətirləri istisna olmaqla)
SELECT
  (SELECT count(*) FROM public.pregnancy_day_notifications WHERE title_uz IS NULL) AS preg_uz_bos,
  (SELECT count(*) FROM public.mommy_day_notifications WHERE title_uz IS NULL) AS mommy_uz_bos;
